INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('llama-farm/llamafarm/fix-ci', 'community', 'llama-farm', 'llamafarm', 'llama-farm/llamafarm', 'fix-ci', 0, 0, 60, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:03.031Z', '89979bcb7209ce5f004d35dc404d5355f537896c5e90ef82e480a5041948d80a', '{"id":"llama-farm/llamafarm/fix-ci","name":"fix-ci","description":{"en":"fix-ci automates CI troubleshooting by analyzing GitHub Actions failures and creating a fix plan. It benefits developers by reproducing issues locally and streamlining the debugging process.","zh":"Fix-CI 是一种自动化 CI 故障诊断的技术，通过 GitHub Actions 日志分析和本地问题重现来帮助开发者快速修复 CI 故障","ja":"Fix-CI は、GitHub Actions のログ分析とローカルでの問題の再現により、開発者が CI の障害を迅速に修復できるようにする自動化 CI トラブルシューティング技術です","ko":"Fix-CI는 GitHub Actions 로그 분석 및 로컬 문제 재현을 통해 개발자가 빠르게 CI 오류를 진단하고修复 할 수 있는 자동화 CI 트러블슈팅 기술입니다","es":"fix-ci es una herramienta que automatiza la solución de problemas de integración continua mediante la verificación de la CLI de GitHub y la reproducción de errores locales","fr":"fix-ci est un outil qui automatise la résolution des problèmes d''intégration continue en vérifiant la CLI de GitHub et en reproduisant les erreurs locales","de":"fix-ci ist ein Tool, das die Lösung von Continuous-Integration-Problemen automatisiert, indem es die GitHub-CLI überprüft und Fehler lokal reproduziert","pt":"O Fix-CI é uma ferramenta que automatiza a solução de problemas de integração contínua, permitindo que os desenvolvedores resolvam erros rapidamente e melhorem a eficiência do pipeline de desenvolvimento.","ru":"Fix-CI - это инструмент, который автоматизирует решение проблем интеграции, позволяя разработчикам быстро устранять ошибки и повышать эффективность конвейера разработки.","ar":"Fix-CI هو أداة تؤتمة تصحيح أخطاء التكامل المستمر، مما يسمح للمطورين بحل المشاكل بسرعة وتحسين كفاءة خط أنابيب التطوير."},"seo":{"title":{"en":"fix-ci: Automated CI Troubleshooting Setup Guide | AI Age...","zh":"Fix-CI 设置指南：自动化 CI 故障诊断","ja":"Fix-CI セットアップガイド：CI トラブルシューティングの自動化","ko":"Fix-CI 설정 가이드: CI 자동화 트러블슈팅","es":"Guía de Configuración de fix-ci: Automatización de Soluci...","fr":"Guide de Configuration de fix-ci: Automatisation de la Ré...","de":"Konfigurationsleitfaden für fix-ci: Automatisierung der L...","pt":"Guia de Configuração do Fix-CI: Automatize a Solução de P...","ru":"Настройка Fix-CI: Автоматизируйте Устранение Несоответств...","ar":"دليل إعداد Fix-CI: أتمتة تصحيح أخطاء التكامل المستمر"},"description":{"en":"Solve GitHub Actions failures in minutes with fix-ci. Learn how to automate CI troubleshooting and get a step-by-step setup guide.","zh":"Fix-CI 技术通过 GitHub Actions 日志分析和本地问题重现，帮助开发者快速诊断和修复 CI 故障","ja":"Fix-CI 技術により、GitHub Actions のログ分析とローカルでの問題の再現により、開発者は CI の障害を迅速に診断して修復できます","ko":"Fix-CI 기술을 통해 GitHub Actions 로그 분석 및 로컬 문제 재현으로 개발자가 빠르게 CI 오류를 진단하고修复 할 수 있습니다","es":"Aprende a configurar fix-ci para automatizar la solución de problemas de integración continua y mejorar la eficiencia de tu flujo de trabajo","fr":"Découvrez comment configurer fix-ci pour automatiser la résolution des problèmes d''intégration continue et améliorer l''efficacité de votre flux de travail","de":"Erfahren Sie, wie Sie fix-ci konfigurieren, um die Lösung von Continuous-Integration-Problemen zu automatisieren und die Effizienz Ihres Workflows zu verbessern","pt":"Aprenda a configurar o Fix-CI para automatizar a solução de problemas de integração contínua e melhorar a eficiência do seu pipeline de desenvolvimento","ru":"Узнайте, как настроить Fix-CI для автоматизации решения проблем интеграции и повышения эффективности вашего конвейера разработки","ar":"تعلم كيفية إعداد Fix-CI لتحسين كفاءة خط أنابيب التطوير وتأتمة تصحيح أخطاء التكامل المستمر"},"definition":{"en":"fix-ci is an AI agent skill that automates Continuous Integration troubleshooting by fetching GitHub Actions failures, analyzing logs, and creating a fix plan for user approval.","zh":"Fix-CI 是一种自动化 CI 故障诊断技术，用于帮助开发者快速修复 CI 故障","ja":"Fix-CI は、開発者が CI の障害を迅速に修復できるようにする自動化 CI トラブルシューティング技術です","ko":"Fix-CI는 개발자가 빠르게 CI 오류를 진단하고修复 할 수 있는 자동화 CI 트러블슈팅 기술입니다","es":"fix-ci es una herramienta de automatización de solución de problemas de integración continua que utiliza la CLI de GitHub","fr":"fix-ci est un outil d''automatisation de la résolution des problèmes d''intégration continue qui utilise la CLI de GitHub","de":"fix-ci ist ein Tool zur Automatisierung der Lösung von Continuous-Integration-Problemen, das die GitHub-CLI verwendet","pt":"O Fix-CI é uma ferramenta de automação de solução de problemas de integração contínua que utiliza o GitHub CLI para identificar e resolver erros.","ru":"Fix-CI - это инструмент автоматизации решения проблем интеграции, который использует GitHub CLI для выявления и устранения ошибок.","ar":"Fix-CI هو أداة تأتمة تصحيح أخطاء التكامل المستمر التي تستخدم GitHub CLI لتحديد ومعالجة الأخطاء."},"features":{"en":["Verifies GitHub CLI installation and authentication using `gh --version` and `gh auth status` commands","Analyzes GitHub Actions failures and reproduces issues locally for efficient debugging","Creates a fix plan for user approval based on log analysis","Exits gracefully if GitHub CLI is not installed, providing installation instructions with `brew install gh`","Handles authentication issues by informing users to authenticate with `gh auth status`"],"zh":["自动化 CI 故障诊断","GitHub Actions 日志分析","本地问题重现","快速修复 CI 故障","支持 GitHub CLI"],"ja":["自動化 CI トラブルシューティング","GitHub Actions のログ分析","ローカルでの問題の再現","迅速に CI の障害を修復","GitHub CLI をサポート"],"ko":["자동화 CI 트러블슈팅","GitHub Actions 로그 분석","로컬 문제 재현","빠르게 CI 오류를 진단하고修复","GitHub CLI 지원"],"es":["Verificación de la CLI de GitHub","Reproducción de errores locales","Creación de un plan de solución para la aprobación del usuario","Autenticación con la CLI de GitHub","Instalación de la CLI de GitHub si no está instalada"],"fr":["Vérification de la CLI de GitHub","Reproduction d''erreurs locales","Création d''un plan de résolution pour l''approbation de l''utilisateur","Authentification avec la CLI de GitHub","Installation de la CLI de GitHub si elle n''est pas installée"],"de":["Überprüfung der GitHub-CLI","Reproduktion von Fehlern im lokalen Bereich","Erstellung eines Lösungsplans für die Benutzerfreigabe","Authentifizierung mit der GitHub-CLI","Installation der GitHub-CLI, wenn sie nicht installiert ist"],"pt":["Verificação de pré-requisitos com GitHub CLI","Análise de logs de falhas do GitHub Actions","Reprodução de problemas locais para solução de erros","Criação de plano de solução para aprovação do usuário","Integração com pipelines de desenvolvimento"],"ru":["Проверка предварительных требований с помощью GitHub CLI","Анализ журналов неудач GitHub Actions","Воспроизведение проблем локально для решения ошибок","Создание плана решения для утверждения пользователя","Интеграция с конвейерами разработки"],"ar":["التحقق من متطلبات مسبقة باستخدام GitHub CLI","تحليل سجلات الفشل في GitHub Actions","إعادة إنتاج المشاكل محليًا لحل الأخطاء","إنشاء خطة حل للموافقة المستخدم","التكامل مع خطوط أنابيب التطوير"]},"keywords":{"en":["how to use fix-ci","fix-ci setup guide","github actions troubleshooting","ci troubleshooting automation","fix-ci vs traditional debugging methods","what is fix-ci","fix-ci install","automated ci troubleshooting","github cli authentication","fix-ci alternative"],"zh":["Fix-CI","自动化 CI 故障诊断","GitHub Actions","CI 故障修复","AIエージェント","自动化测试","CI/CD"],"ja":["Fix-CI","自動化 CI トラブルシューティング","GitHub Actions","CI の障害修復","AIエージェント","自動化テスト","CI/CD"],"ko":["Fix-CI","자동화 CI 트러블슈팅","GitHub Actions","CI 오류 진단","AI 에이전트","자동화 테스트","CI/CD"],"es":["herramientas de integración continua","solución de problemas de integración continua","automatización de solución de problemas","CLI de GitHub","fix-ci","integración continua","desarrollo de software","herramientas de desarrollo"],"fr":["outils d''intégration continue","résolution des problèmes d''intégration continue","automatisation de la résolution des problèmes","CLI de GitHub","fix-ci","intégration continue","développement de logiciels","outils de développement"],"de":["Continuous-Integration-Tools","Lösung von Continuous-Integration-Problemen","Automatisierung der Lösung von Problemen","GitHub-CLI","fix-ci","Continuous Integration","Software-Entwicklung","Entwicklungstools"],"pt":["Fix-CI","automação de solução de problemas","integração contínua","GitHub CLI","pipelines de desenvolvimento","solução de erros","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Fix-CI","автоматизация решения проблем","интеграция","GitHub CLI","конвейеры разработки","решение ошибок","разработка программного обеспечения","инструменты разработки"],"ar":["Fix-CI","تأتمة تصحيح أخطاء","التكامل المستمر","GitHub CLI","خطوط أنابيب التطوير","حل المشاكل","تطوير البرمجيات","أدوات التطوير"]}},"owner":"llama-farm","repo":"llamafarm","repoPath":"llama-farm/llamafarm","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"fix-ci","description":"Fetch GitHub CI failure information, analyze root causes, reproduce locally, and propose a fix plan. Use `/fix-ci` for current branch or `/fix-ci <run-id>` for a specific run.","bodyPreview":"# Fix CI Skill\n\nAutomates CI troubleshooting by fetching GitHub Actions failures, analyzing logs, reproducing issues locally, and creating a fix plan for user approval.\n\n---\n\n## Execution Workflow\n\n### Step 1: Prerequisites Check\n\nVerify the GitHub CLI is installed and authenticated:\n\n```bash\ngh --version && gh auth status\n```\n\n**If gh is not installed:**\n- Inform user: \"GitHub CLI is required. Install with: `brew install gh`\"\n- Exit gracefully\n\n**If not authenticated:**\n- Inform user: \"Please a","body":"# Fix CI Skill\n\nAutomates CI troubleshooting by fetching GitHub Actions failures, analyzing logs, reproducing issues locally, and creating a fix plan for user approval.\n\n---\n\n## Execution Workflow\n\n### Step 1: Prerequisites Check\n\nVerify the GitHub CLI is installed and authenticated:\n\n```bash\ngh --version && gh auth status\n```\n\n**If gh is not installed:**\n- Inform user: \"GitHub CLI is required. Install with: `brew install gh`\"\n- Exit gracefully\n\n**If not authenticated:**\n- Inform user: \"Please authenticate with: `gh auth login`\"\n- Exit gracefully\n\n### Step 2: Parse Arguments\n\nDetermine the mode based on arguments:\n\n- **No arguments** (`/fix-ci`): Fetch failures for the current branch only\n- **With run-id** (`/fix-ci <run-id>`): Fetch specific run (bypasses branch scoping)\n\n### Step 3: Fetch Failed Run\n\n**Default mode (current branch):**\n\n```bash\nBRANCH=$(git branch --show-current)\ngh run list --branch \"$BRANCH\" --status failure --limit 1 --json databaseId,name,headBranch,workflowName,createdAt\n```\n\n**Specific run mode:**\n\n```bash\ngh run view <run-id> --json databaseId,name,headBranch,workflowName,jobs,conclusion\n```\n\n**If no failures found:**\n- Report: \"No failed runs found for branch `$BRANCH`. CI is green!\"\n- Optionally show recent successful runs:\n```bash\ngh run list --branch \"$BRANCH\" --limit 3 --json databaseId,conclusion,workflowName,createdAt\n```\n- Exit gracefully\n\n### Step 4: Get Failure Details\n\nOnce a failed run is identified, gather comprehensive details:\n\n```bash\nRUN_ID=<the-run-id>\n\n# Get failed jobs with their steps\ngh run view $RUN_ID --json jobs --jq ''.jobs[] | select(.conclusion == \"failure\") | {name, conclusion, steps: [.steps[] | select(.conclusion == \"failure\")]}''\n\n# Get failed step logs (critical for debugging)\ngh run view $RUN_ID --log-failed 2>&1 | head -500\n\n# Get verbose run info\ngh run view $RUN_ID --verbose\n```\n\n**Log handling:**\n- Truncate logs to 500 lines to avoid context overflow\n- Note to user: \"Showing first 500 lines of failed logs. Full logs available on GitHub.\"\n\n### Step 5: Download Artifacts (if available)\n\nAttempt to download any debug artifacts:\n\n```bash\n# Try common artifact names - failures are OK (not all runs have artifacts)\ngh run download $RUN_ID -n \"coverage\" -D /tmp/ci-debug/ 2>/dev/null || true\ngh run download $RUN_ID -n \"test-results\" -D /tmp/ci-debug/ 2>/dev/null || true\ngh run download $RUN_ID -n \"logs\" -D /tmp/ci-debug/ 2>/dev/null || true\n```\n\nIf artifacts downloaded, read them for additional context.\n\n### Step 6: Analyze Failure Type\n\nCategorize the failure based on log patterns:\n\n| Pattern | Failure Type | Root Cause Area |\n|---------|--------------|-----------------|\n| `FAIL:`, `--- FAIL`, `FAILED` | Test Failure | Specific test case |\n| `ruff check`, `ruff format` | Lint Error | Code style/formatting |\n| `ModuleNotFoundError`, `ImportError` | Import Error | Missing dependency |\n| `TypeError`, `AttributeError` | Runtime Error | Type mismatch |\n| `SyntaxError` | Syntax Error | Invalid code |\n| `AssertionError` | Assertion Failure | Test expectation mismatch |\n| `TimeoutError`, `timed out` | Timeout | Performance/hang |\n| `PermissionError`, `EACCES` | Permission Error | File/resource access |\n| `ConnectionError`, `ECONNREFUSED` | Network Error | External service |\n\nExtract key information:\n- Failed test name/file (if applicable)\n- Error message\n- Stack trace location (file:line)\n- Environment variables or config issues\n\n### Step 7: Map to Local Test Commands\n\nDetermine the appropriate local command based on the CI job:\n\n| CI Workflow/Job | Local Command |\n|-----------------|---------------|\n| `test-cli` | `cd cli && go test ./...` |\n| `test-python` (server) | `cd server && uv run pytest -v` |\n| `test-python` (rag) | `cd rag && uv run pytest -v` |\n| `test-python` (config) | `cd config && uv run pytest -v` |\n| `test-python` (runtime) | `cd runtimes/universal && uv run pytest -v` |\n| `lint` (python) | `uv run ruff check .` |\n| `lint` (go) | `cd cli && golangci-lint run` |\n| `type-check` | `uv run mypy .` |\n| `build-cli` | `nx build cli` |\n| `build-designer` | `cd designer && npm run build` |\n\n**For specific test failures**, narrow down the command:\n- Python: `cd <dir> && uv run pytest -v <test_file>::<test_name>`\n- Go: `cd cli && go test -v -run <TestName> ./...`\n\n### Step 8: Reproduce Locally\n\nRun the mapped local command to confirm the failure reproduces:\n\n```bash\n# Example for Python test\ncd server && uv run pytest -v tests/test_api.py::test_health_check\n```\n\n**Outcome A - Failure reproduces locally:**\n- Good! Continue to fix plan\n- Report: \"Successfully reproduced failure locally\"\n\n**Outcome B - Failure does NOT reproduce locally:**\n- Note: \"Could not reproduce locally. Possible causes:\"\n  - Flaky test (timing-dependent)\n  - Environment difference (CI has different deps/config)\n  - Race condition\n- Suggest: \"Consider re-running CI with `gh run rerun $RUN_ID`\"\n- Ask user how to proceed (investigate further or skip)\n\n### Step 9: Analyze Root Cause\n\nBased on the failure type and logs, identify:\n\n1. **What failed**: Specific test, lint rule, or build step\n2. **Why it failed**: The actual error condition\n3. **Where to fix**: File(s) and line(s) that need changes\n4. **How to fix**: Proposed changes\n\nUse available tools to explore:\n- Read the failing test file\n- Read the code being tested\n- Search for related patterns in the codebase\n- Check recent changes that might have caused the failure\n\n### Step 10: Enter Plan Mode\n\nUse `EnterPlanMode` to create a formal fix plan. The plan should include:\n\n```markdown\n# CI Fix Plan\n\n## Problem Statement\n[Summary of the CI failure from logs]\n\n## Failure Details\n- **Run ID**: <run-id>\n- **Workflow**: <workflow-name>\n- **Job**: <job-name>\n- **Error Type**: <categorized-type>\n\n## Root Cause Analysis\n[Explanation of why the failure occurred]\n\n## Affected Files\n- `path/to/file1.py` (line X)\n- `path/to/file2.py` (line Y)\n\n## Proposed Changes\n\n### Change 1: [Brief description]\n[Specific edit to make]\n\n### Change 2: [Brief description]\n[Specific edit to make]\n\n## Verification Steps\n1. Run: `<local-test-command>`\n2. Expected: All tests pass\n3. Optional: Run full test suite with `<full-suite-command>`\n\n## Notes\n- [Any caveats or considerations]\n```\n\n### Step 11: User Approval Gate\n\nPresent the plan and wait for explicit user approval:\n- User approves: Proceed to execute fixes\n- User modifies: Incorporate feedback, update plan\n- User rejects: Exit gracefully without changes\n\n**CRITICAL**: Never make code changes without user approval.\n\n### Step 12: Execute Fix (after approval only)\n\n1. Make the proposed code changes using Edit tool\n2. Run local tests to verify the fix:\n```bash\n<local-test-command>\n```\n3. Report results:\n   - Success: \"Fix verified locally. Tests pass.\"\n   - Failure: \"Fix did not resolve the issue. [details]\"\n\n**IMPORTANT**: Do NOT auto-commit changes. Leave committing to the user or `/commit-push-pr` skill.\n\n---\n\n## Error Handling\n\n| Scenario | Action |\n|----------|--------|\n| gh CLI not installed | Direct user to install: `brew install gh` |\n| gh not authenticated | Direct user to: `gh auth login` |\n| No failures found | Report CI is green, exit gracefully |\n| Rate limit exceeded | Suggest waiting or using `gh auth refresh` |\n| Run not found | Verify run ID, suggest `gh run list` to find valid IDs |\n| Large logs (>500 lines) | Truncate, note full logs on GitHub |\n| Local reproduction fails | Note as flaky/env issue, offer re-run option |\n| Network errors | Suggest retry, check connection |\n\n---\n\n## Output Format\n\n**On finding a failure:**\n```\nCI Failure Found\nRun: #12345 (workflow-name)\nBranch: feature-branch\nFailed Job: test-python\nError Type: Test Failure\n\nAnalyzing logs...\n[Summary of failure]\n\nReproducing locally...\n[Result]\n\nEntering plan mode to propose fix...\n```\n\n**On success (after fix):**\n```\nFix Applied\n- Modified: path/to/file.py\n- Verification: Tests pass locally\n\nNext steps:\n- Review the changes\n- Run `/commit-push-pr` to commit and push\n- CI will re-run automatically on push\n```\n\n---\n\n## Notes for the Agent\n\n1. **Always scope to current branch by default** - Users expect `/fix-ci` to fix their current work, not random failures\n2. **Truncate logs wisely** - CI logs can be huge; extract the relevant error sections\n3. **Reproduce before fixing** - Don''t propose fixes for issues that can''t be reproduced\n4. **Plan mode is mandatory** - Always use EnterPlanMode before making changes\n5. **Never auto-commit** - The user controls when changes are committed\n6. **Be specific in analysis** - Generic advice isn''t helpful; identify exact files and lines\n7. **Handle flaky tests** - If reproduction fails, acknowledge it might be flaky\n"},"lastSynced":"2026-03-08T02:01:03.031Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub-centric AI Agents seeking to automate Continuous Integration troubleshooting and debugging workflows.","zh":"适用于以 GitHub 为中心的 AI 代理，旨在自动化持续集成故障排除和调试工作流。","ja":"GitHub を中心とした AI エージェントに適しており、継続的インテグレーションのトラブルシューティングとデバッグのワークフローを自動化する。","ko":"GitHub를 중심으로 하는 AI 에이전트에게 적합하며, 지속적인 통합 문제 해결 및 디버깅 워크플로를 자동화하는 데 사용된다.","es":"Ideal para agentes de IA centrados en GitHub que buscan automatizar flujos de trabajo de depuración y solución de problemas de Integración Continua.","fr":"Idéal pour les agents d''IA centrés sur GitHub qui cherchent à automatiser les flux de travail de débogage et de dépannage de l''intégration continue.","de":"Ideal für GitHub-zentrierte KI-Agenten, die die Automatisierung von Workflows zur Fehlersuche und Fehlerbehebung bei der kontinuierlichen Integration suchen.","pt":"Ideal para Agentes de IA centrados no GitHub que buscam automatizar fluxos de trabalho de depuração e solução de problemas de Integração Contínua.","ru":"Идеально для агентов ИИ, ориентированных на GitHub, стремящихся автоматизировать рабочие процессы устранения неполадок и отладки непрерывной интеграции.","ar":"مثالي لعميل الذكاء الاصطناعي المتمحور حول جيت هاب الذي يسعى إلى توفير عمليات عمل تصحيح وتحليل مشاكل التكامل المستمر."},"recommendation":{"en":"Empowers agents to analyze GitHub Actions failures, reproduce issues locally, and generate fix plans using GitHub CLI, streamlining the debugging process with automated log analysis and user-approved fix implementation.","zh":"赋予代理分析 GitHub Actions 故障、在本地复现问题并使用 GitHub CLI 生成修复计划的能力，通过自动化日志分析和用户批准的修复实施来简化调试过程。","ja":"エージェントに GitHub Actions の障害を分析し、ローカルで問題を再現し、GitHub CLI を使用して修正計画を生成する能力を与え、自動化されたログ分析とユーザー承認の修正実施によりデバッグ プロセスを簡素化する。","ko":"에이전트에게 GitHub Actions의 장애를 분석하고, 로컬에서 문제를 재현하며, GitHub CLI를 사용하여 수정 계획을 생성하는 능력을 부여하여, 자동화된 로그 분석과 사용자 승인된 수정 구현을 통해 디버깅 프로세스를 간소화한다.","es":"Habilita a los agentes a analizar los fallos de GitHub Actions, reproducir problemas de forma local y generar planes de solución utilizando GitHub CLI, simplificando el proceso de depuración con análisis de registros automatizado y implementación de soluciones aprobadas por el usuario.","fr":"Permet aux agents d''analyser les échecs de GitHub Actions, de reproduire les problèmes localement et de générer des plans de correction à l''aide de GitHub CLI, en simplifiant le processus de débogage avec une analyse de logs automatisée et une mise en œuvre de corrections approuvées par l''utilisateur.","de":"Ermächtigt die Agenten, GitHub-Actions-Fehler zu analysieren, Probleme lokal zu reproduzieren und mit GitHub CLI Lösungspläne zu generieren, wodurch der Fehlersuchprozess durch automatisierte Log-Analyse und benutzerfreundliche Lösungsumsetzung gestreamlined wird.","pt":"Habilita agentes a analisar falhas de GitHub Actions, reproduzir problemas localmente e gerar planos de correção usando GitHub CLI, racionalizando o processo de depuração com análise de log automatizada e implementação de correção aprovada pelo usuário.","ru":"Наделяет агентов возможностью анализировать неудачи GitHub Actions, воспроизводить проблемы локально и генерировать планы исправления с помощью GitHub CLI, оптимизируя процесс отладки с автоматическим анализом журналов и реализацией исправления, одобренного пользователем.","ar":"تمكين العميل من تحليل فشل إجراءات جيت هاب وإعادة إنتاج المشاكل محليا وتوليد خطط تصحيح باستخدام واجهة سطر الأوامر جيت هاب، وتبسيط عملية فحص الأخطاء مع تحليل سجل آلي وتطبيق تصحيح موافق عليه من قبل المستخدم."},"useCases":{"en":["Automating CI failure analysis","Reproducing GitHub Actions issues locally","Generating fix plans for user approval"],"zh":["自动化 CI 故障分析","在本地复现 GitHub Actions 问题","为用户批准生成修复计划"],"ja":["CI 故障分析の自動化","GitHub Actions の問題をローカルで再現","ユーザー承認のための修正計画の生成"],"ko":["CI 실패 분석 자동화","GitHub Actions 문제를 로컬에서 재현","사용자 승인 수정 계획 생성"],"es":["Automatización del análisis de fallos de CI","Reproducción de problemas de GitHub Actions de forma local","Generación de planes de solución para la aprobación del usuario"],"fr":["Automatisation de l''analyse des échecs de CI","Reproduction des problèmes de GitHub Actions localement","Génération de plans de correction pour l''approbation de l''utilisateur"],"de":["Automatisierung der Analyse von CI-Fehlern","Lokale Reproduktion von GitHub-Actions-Problemen","Generierung von Lösungsplänen zur Benutzerfreigabe"],"pt":["Automatizar análise de falha de CI","Reproduzir problemas de GitHub Actions localmente","Gerar planos de correção para aprovação do usuário"],"ru":["Автоматизировать анализ неудач CI","Воспроизводить проблемы GitHub Actions локально","Генерировать планы исправления для одобрения пользователя"],"ar":["توفير تحليل فشل التكامل المستمر","إعادة إنتاج مشاكل إجراءات جيت هاب محليا","توليد خطط تصحيح لموافقة المستخدم"]},"limitations":{"en":["Requires GitHub CLI installation and authentication","Limited to GitHub Actions failures"],"zh":["需要 GitHub CLI 安装和身份验证","仅限 GitHub Actions 故障"],"ja":["GitHub CLI のインストールと認証が必要","GitHub Actions の障害のみ"],"ko":["GitHub CLI 설치 및 인증이 필요","GitHub Actions의 장애만 해당"],"es":["Requiere instalación y autenticación de GitHub CLI","Limitado a fallos de GitHub Actions"],"fr":["Nécessite l''installation et l''authentification de GitHub CLI","Limité aux échecs de GitHub Actions"],"de":["Erfordert die Installation und Authentifizierung von GitHub CLI","Begrenzt auf GitHub-Actions-Fehler"],"pt":["Exige instalação e autenticação do GitHub CLI","Limitado a falhas de GitHub Actions"],"ru":["Требует установки и аутентификации GitHub CLI","Ограничен неудачами GitHub Actions"],"ar":["يتطلب تثبيت وتحقق من واجهة سطر الأوامر جيت هاب","محدود بفشل إجراءات جيت هاب"]},"version":4},"contentHash":"89979bcb7209ce5f004d35dc404d5355f537896c5e90ef82e480a5041948d80a","qualityScore":60}');
