INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('llama-farm/llamafarm/fix-ci', 'fix-ci', 'llama-farm', 'llamafarm', 'community', 'fix-ci llama-farm llamafarm community fix-ci automates CI troubleshooting by analyzing GitHub Actions failures and creating a fix plan. It benefits developers by reproducing issues locally and streamlining the debugging process. Fix-CI 是一种自动化 CI 故障诊断的技术，通过 GitHub Actions 日志分析和本地问题重现来帮助开发者快速修复 CI 故障 Fix-CI は、GitHub Actions のログ分析とローカルでの問題の再現により、開発者が CI の障害を迅速に修復できるようにする自動化 CI トラブルシューティング技術です Fix-CI는 GitHub Actions 로그 분석 및 로컬 문제 재현을 통해 개발자가 빠르게 CI 오류를 진단하고修复 할 수 있는 자동화 CI 트러블슈팅 기술입니다 fix-ci es una herramienta que automatiza la solución de problemas de integración continua mediante la verificación de la CLI de GitHub y la reproducción de errores locales fix-ci est un outil qui automatise la résolution des problèmes d''intégration continue en vérifiant la CLI de GitHub et en reproduisant les erreurs locales fix-ci ist ein Tool, das die Lösung von Continuous-Integration-Problemen automatisiert, indem es die GitHub-CLI überprüft und Fehler lokal reproduziert O Fix-CI é uma ferramenta que automatiza a solução de problemas de integração contínua, permitindo que os desenvolvedores resolvam erros rapidamente e melhorem a eficiência do pipeline de desenvolvimento. Fix-CI - это инструмент, который автоматизирует решение проблем интеграции, позволяя разработчикам быстро устранять ошибки и повышать эффективность конвейера разработки. Fix-CI هو أداة تؤتمة تصحيح أخطاء التكامل المستمر، مما يسمح للمطورين بحل المشاكل بسرعة وتحسين كفاءة خط أنابيب التطوير. how to use fix-ci fix-ci setup guide github actions troubleshooting ci troubleshooting automation fix-ci vs traditional debugging methods what is fix-ci fix-ci install automated ci troubleshooting github cli authentication fix-ci alternative Fix-CI 自动化 CI 故障诊断 GitHub Actions CI 故障修复 AIエージェント 自动化测试 CI/CD Verifies GitHub CLI installation and authentication using `gh --version` and `gh auth status` commands Analyzes GitHub Actions failures and reproduces issues locally for efficient debugging Creates a fix plan for user approval based on log analysis Exits gracefully if GitHub CLI is not installed, providing installation instructions with `brew install gh` Handles authentication issues by informing users to authenticate with `gh auth status` fix-ci is an AI agent skill that automates Continuous Integration troubleshooting by fetching GitHub Actions failures, analyzing logs, and creating a fix plan for user approval.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('commontoolsinc/labs/ct', 'community', 'commontoolsinc', 'labs', 'commontoolsinc/labs', 'ct', 0, 0, 60, '2026-03-08T01:57:15.292Z', '2026-03-08T02:01:04.790Z', 'a5289bd194b047822305a3f86692defc86da52a75725db3ef1867806f08b8c58', '{"id":"commontoolsinc/labs/ct","name":"ct","description":{"en":"The ct skill provides a command-line interface for CommonTools, enabling developers to perform type checking and piece operations. It benefits developers working with Deno and TypeScript.","zh":"CT CLI是CommonTools的命令行接口，提供piece操作、类型检查等功能。使用--help获取当前命令","ja":"CT CLIはCommonToolsのコマンドラインインターフェースで、piece操作、型チェックなどの機能を提供します。--helpを使用して現在のコマンドを取得","ko":"CT CLI는 CommonTools의 명령줄 인터페이스로서 피스 연산, 유형 검사 등의 기능을 제공합니다. --help를 사용하여 현재 명령을 가져옵니다","es":"ct es una herramienta de línea de comandos para CommonTools que ofrece operaciones de piezas y comprobación de tipos","fr":"ct est un outil de ligne de commande pour CommonTools qui propose des opérations de pièces et de vérification de types","de":"ct ist ein Befehlszeilen-Tool für CommonTools, das Pieze-Operationen und Typ-Prüfungen anbietet","pt":"O ct é uma ferramenta de linha de comando para CommonTools, que fornece operações de piece e verificação de tipo","ru":"ct - это командная строка для CommonTools, которая предоставляет операции с piece и проверкой типов","ar":"ct هو أداة سطر الأوامر للادوات المشتركة، توفر عمليات قطعة و تحقق من النوع"},"seo":{"title":{"en":"ct: CLI Setup Guide for AI Agents","zh":"CT CLI Setup Guide - AI工具命令行接口","ja":"CT CLI セットアップガイド - AIエージェントコマンドラインインターフェース","ko":"CT CLI 설정 가이드 - AI 에이전트 명령줄 인터페이스","es":"Guía de configuración de ct: Herramientas de línea de com...","fr":"Guide de configuration de ct : Outils de ligne de command...","de":"ct-Setup-Anleitung: Befehlszeilen-Tools für Entwickler","pt":"Guia de Configuração do ct: Ferramentas Comuns CLI","ru":"Настройка ct: Руководство по использованию ИИ Агентов","ar":"دليل إعداد ct: أدوات مشتركة واجهة سطر الأوامر"},"description":{"en":"Unlock the full potential of CommonTools with the ct CLI. Learn how to set up and use ct for efficient type checking and piece operations. Get started now!","zh":"了解CT CLI的命令和功能，包括piece操作、类型检查和环境设置。使用--help获取更多信息","ja":"CT CLIのコマンドと機能を学ぶ、piece操作、型チェック、環境設定など。--helpを使用して詳細を取得","ko":"CT CLI의 명령과 기능을 알아보세요. 피스 연산, 유형 검사, 환경 설정 등. --help를 사용하여 자세한 정보를 얻으십시오","es":"Aprende a configurar ct, la herramienta de línea de comandos para CommonTools, y descubre sus características clave para desarrolladores","fr":"Découvrez comment configurer ct, l''outil de ligne de commande pour CommonTools, et explorez ses fonctionnalités clés pour les développeurs","de":"Erfahren Sie, wie Sie ct, das Befehlszeilen-Tool für CommonTools, konfigurieren, und entdecken Sie seine wichtigsten Funktionen für Entwickler","pt":"Aprenda a configurar o ct, uma ferramenta de linha de comando para CommonTools, e explore seus recursos avançados","ru":"Узнайте, как настроить ct, командную строку для CommonTools, и откройте для себя ее расширенные возможности","ar":"تعلم كيفية إعداد ct، أداة سطر الأوامر للادوات المشتركة، واستكشف ميزاتها المتقدمة"},"definition":{"en":"ct is a command-line binary for CommonTools, providing a CLI interface for various operations, including type checking and piece management.","zh":"CT CLI是CommonTools的命令行工具，用于执行piece操作、类型检查和环境设置等任务","ja":"CT CLIはCommonToolsのコマンドラインツールで、piece操作、型チェック、環境設定などのタスクを実行する","ko":"CT CLI는 CommonTools의 명령줄 도구로서 피스 연산, 유형 검사, 환경 설정 등의 작업을 수행하는 데 사용됩니다","es":"ct es una herramienta de línea de comandos para CommonTools que proporciona funcionalidades de desarrollo","fr":"ct est un outil de ligne de commande pour CommonTools qui fournit des fonctionnalités de développement","de":"ct ist ein Befehlszeilen-Tool für CommonTools, das Entwicklungsfunktionen bietet","pt":"O ct é uma ferramenta de linha de comando para CommonTools, usada para operações de piece e verificação de tipo","ru":"ct - это командная строка для CommonTools, используемая для операций с piece и проверкой типов","ar":"ct هو أداة سطر الأوامر للادوات المشتركة، تستخدم لعمليات قطعة و تحقق من النوع"},"features":{"en":["Supports top-level commands via `deno task ct --help`","Enables piece operations with `deno task ct piece --help`","Performs type checking using `deno task ct check --help`","Requires an identity key for most operations, derivable with `deno run -A packages/cli/mod.ts id derive`","Utilizes Deno for task execution and TypeScript for development"],"zh":["支持piece操作","提供类型检查功能","环境设置和身份密钥管理","使用--help获取当前命令","Deno任务集成","CLI命令行接口"],"ja":["piece操作のサポート","型チェック機能の提供","環境設定とアイデンティティキー管理","--helpを使用して現在のコマンドを取得","Denoタスクの統合","CLIコマンドラインインターフェース"],"ko":["피스 연산 지원","유형 검사 기능 제공","환경 설정과 身分鍵 관리","--help를 사용하여 현재 명령을 가져옵니다","Deno 작업 통합","CLI 명령줄 인터페이스"],"es":["Operaciones de piezas con ct piece","Comprobación de tipos con ct check","Uso de la clave de identidad para operaciones","Derivación de claves de identidad con deno run","Compatibilidad con deno task","Opciones de ayuda con --help"],"fr":["Opérations de pièces avec ct piece","Vérification de types avec ct check","Utilisation de la clé d''identité pour les opérations","Déduction de clés d''identité avec deno run","Compatibilité avec deno task","Options d''aide avec --help"],"de":["Pieze-Operationen mit ct piece","Typ-Prüfungen mit ct check","Verwendung des Identitätsschlüssels für Operationen","Ableitung von Identitätsschlüsseln mit deno run","Kompatibilität mit deno task","Hilfe-Optionen mit --help"],"pt":["Suporte a operações de piece","Verificação de tipo avançada","Uso de identidade de chave para operações","Comando --help para visualizar comandos disponíveis","Derivação de chave de identidade para desenvolvimento local"],"ru":["Поддержка операций с piece","Расширенная проверка типов","Использование идентификатора ключа для операций","Команда --help для просмотра доступных команд","Получение идентификатора ключа для локального развития"],"ar":["دعم عمليات القطعة","تحقق متقدم من النوع","استخدام مفتاح الهوية للعمليات","الأمر --help لعرض الأوامر المتاحة","اشتقاق مفتاح الهوية لتطوير المحلي"]},"keywords":{"en":["how to use ct","ct setup guide","ct alternative","ct vs CommonTools","ct install","what is ct","ct CLI tutorial","ct for AI agents","ct Deno integration"],"zh":["CT CLI","AI工具","命令行接口","CommonTools","piece操作","类型检查","环境设置","Deno任务","CLI命令"],"ja":["CT CLI","AIエージェント","コマンドラインインターフェース","CommonTools","piece操作","型チェック","環境設定","Denoタスク","CLIコマンド"],"ko":["CT CLI","AI 에이전트","명령줄 인터페이스","CommonTools","피스 연산","유형 검사","환경 설정","Deno 작업","CLI 명령"],"es":["ct herramienta de línea de comandos","CommonTools desarrollo","operaciones de piezas","comprobación de tipos","deno task","identidad clave","desarrollo de software","herramientas de desarrollo","línea de comandos"],"fr":["ct outil de ligne de commande","CommonTools développement","opérations de pièces","vérification de types","deno task","clé d''identité","développement de logiciels","outils de développement","ligne de commande"],"de":["ct Befehlszeilen-Tool","CommonTools Entwicklung","Pieze-Operationen","Typ-Prüfungen","deno task","Identitätsschlüssel","Software-Entwicklung","Entwicklungstools","Befehlszeile"],"pt":["ct configuração","ferramentas comuns cli","operacoes de piece","verificação de tipo","identidade de chave","desenvolvimento local","comando --help"],"ru":["ct настройка","ИИ Агенты","операции с piece","проверка типов","идентификатор ключа","локальное развитие","команда --help"],"ar":["إعداد ct","أدوات مشتركة واجهة سطر الأوامر","عمليات القطعة","تحقق من النوع","مفتاح الهوية","تطوير المحلي","الأمر --help"]}},"owner":"commontoolsinc","repo":"labs","repoPath":"commontoolsinc/labs","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.292Z","topics":[],"category":"community","skillMd":{"name":"ct","description":"Guide for using the ct (CommonTools) binary to interact with pieces,","bodyPreview":"# CT CLI\n\nThe `ct` binary is the CLI for CommonTools. **Use `--help` for current commands:**\n\n```bash\ndeno task ct --help           # Top-level commands\ndeno task ct piece --help     # Piece operations\ndeno task ct check --help     # Type checking\n```\n\n## Environment Setup\n\n**Identity key** (required for most operations):\n```bash\nls -la claude.key              # Check for existing\n\n# For local dev: derive key matching toolshed''s \"implicit trust\" identity\ndeno run -A packages/cli/mod.ts id derive","body":"# CT CLI\n\nThe `ct` binary is the CLI for CommonTools. **Use `--help` for current commands:**\n\n```bash\ndeno task ct --help           # Top-level commands\ndeno task ct piece --help     # Piece operations\ndeno task ct check --help     # Type checking\n```\n\n## Environment Setup\n\n**Identity key** (required for most operations):\n```bash\nls -la claude.key              # Check for existing\n\n# For local dev: derive key matching toolshed''s \"implicit trust\" identity\ndeno run -A packages/cli/mod.ts id derive \"implicit trust\" > claude.key\n\n# For a fresh random key (e.g., against production):\ndeno run -A packages/cli/mod.ts id new > claude.key\n```\n\n**IMPORTANT:** Do NOT use `deno task ct id new > file` — the `deno task` wrapper\nprints ANSI-colored preamble to stdout, which pollutes the key file. Always use\n`deno run -A packages/cli/mod.ts` when redirecting output.\n\n**Environment variables** (avoid repeating flags):\n```bash\nexport CT_API_URL=http://localhost:8000  # or https://toolshed.saga-castor.ts.net/\nexport CT_IDENTITY=./claude.key\n```\n\n**Experimental flags** (must be set on both servers AND CLI commands):\n```bash\n# Pass experiment env vars to CLI commands:\nEXPERIMENTAL_CANONICAL_HASHING=true \\\nEXPERIMENTAL_RICH_STORABLE_VALUES=true \\\ndeno task ct piece new pattern.tsx ...\n```\n\nSee `docs/development/EXPERIMENTAL_OPTIONS.md` for all available flags.\n\n**Local servers**: See `docs/development/LOCAL_DEV_SERVERS.md`\n\n## Quick Command Reference\n\n| Operation | Command |\n|-----------|---------|\n| Type check | `deno task ct check pattern.tsx --no-run` |\n| Deploy new | `deno task ct piece new pattern.tsx -i key -a url -s space` |\n| Update existing | `deno task ct piece setsrc pattern.tsx --piece ID -i key -a url -s space` |\n| Inspect state | `deno task ct piece inspect --piece ID ...` |\n| Get field | `deno task ct piece get --piece ID fieldPath ...` |\n| Set field | `echo ''{\"data\":...}'' \\| deno task ct piece set --piece ID path ...` |\n| Call handler | `deno task ct piece call --piece ID handlerName ...` |\n| Trigger recompute | `deno task ct piece step --piece ID ...` |\n| List pieces | `deno task ct piece ls -i key -a url -s space` |\n| Visualize | `deno task ct piece map ...` |\n\n## Check Command Flags\n\n`deno task ct check` compiles and evaluates patterns. Key flags:\n\n| Flag | Purpose |\n|------|---------|\n| `--no-run` | Type check only, don''t execute |\n| `--no-check` | Execute without type checking |\n| `--show-transformed` | Show the transformed TypeScript after compilation |\n| `--verbose-errors` | Show original TS errors alongside simplified hints |\n| `--pattern-json` | Print the evaluated pattern export as JSON |\n| `--output <path>` | Store compiled JS to a file |\n| `--main-export <name>` | Select non-default export (default: `\"default\"`) |\n| `--filename <name>` | Override filename for source maps |\n\nCommon usage:\n```bash\ndeno task ct check pattern.tsx              # Compile + execute (quiet on success)\ndeno task ct check pattern.tsx --no-run     # Type check only (fast)\ndeno task ct check pattern.tsx --no-check   # Skip types, just execute\ndeno task ct check pattern.tsx --show-transformed  # Debug compiler transforms\ndeno task ct check pattern.tsx --verbose-errors     # Detailed error context\n```\n\n## Core Workflow: setsrc vs new\n\n**Critical pattern:** After initial deployment, use `setsrc` to iterate:\n\n```bash\n# First time only\ndeno task ct piece new pattern.tsx ...\n# Output: Created piece bafyreia... <- Save this ID!\n\n# ALL subsequent iterations\ndeno task ct piece setsrc pattern.tsx --piece bafyreia... ...\n```\n\n**Why:** `new` creates duplicate pieces. `setsrc` updates in-place.\n\n## JSON Input Format\n\nAll values to `set` and `call` must be valid JSON:\n\n```bash\n# Strings need nested quotes\necho ''\"hello world\"'' | deno task ct piece set ... title\n\n# Numbers are bare\necho ''42'' | deno task ct piece set ... count\n\n# Objects\necho ''{\"name\": \"John\"}'' | deno task ct piece set ... user\n```\n\n## Gotcha: Always `step` After `set` or `call`\n\nNeither `piece set` nor `piece call` triggers recomputation automatically.\nYou **must** run `piece step` after either one to get fresh computed values.\n\n```bash\n# After setting data:\necho ''[...]'' | deno task ct piece set --piece ID expenses ...\ndeno task ct piece step --piece ID ...  # Required!\ndeno task ct piece get --piece ID totalSpent ...\n\n# After calling a handler:\ndeno task ct piece call --piece ID addItem ''{\"title\": \"Test\"}''\ndeno task ct piece step --piece ID ...  # Required!\ndeno task ct piece inspect --piece ID ...\n```\n\n**Handler testing workflow** (deploy → call → step → inspect):\n```bash\n# 1. Deploy\ndeno task ct piece new pattern.tsx -i key -a url -s space\n# 2. Call a handler\ndeno task ct piece call --piece ID handlerName ''{\"arg\": \"value\"}'' ...\n# 3. Step to process\ndeno task ct piece step --piece ID ...\n# 4. Inspect result\ndeno task ct piece inspect --piece ID ...\n# 5. Repeat 2-4 for each handler\n```\n\nSee `docs/common/workflows/handlers-cli-testing.md` for the full workflow\nand `docs/development/debugging/cli-debugging.md` for debugging.\n\n## Troubleshooting\n\n| Issue | Fix |\n|-------|-----|\n| Commands hang | Check Tailnet connection for `*.ts.net` URLs |\n| Permission denied | `chmod 600 claude.key` |\n| JSON parse error | Check nested quotes, no trailing commas |\n| Local servers not responding | `./scripts/check-local-dev.sh` then `./scripts/restart-local-dev.sh --force` |\n\n## References\n\n- `packages/patterns/system/default-app.tsx` - System pieces (allCharms list lives here)\n- `docs/common/workflows/handlers-cli-testing.md` - Handler testing\n- `docs/development/debugging/cli-debugging.md` - CLI debugging\n"},"lastSynced":"2026-03-08T02:01:04.790Z","agentAnalysis":{"suitability":{"en":"Perfect for TypeScript Agents needing advanced type checking and piece operations","zh":"非常适合需要高级类型检查和块操作的TypeScript Agents","ja":"TypeScriptエージェントが高度な型チェックとピース操作を必要とする場合に最適","ko":"고급 타입 체크 및 조각 작업이 필요한 TypeScript 에이전트에 적합","es":"Perfecto para Agentes de TypeScript que necesitan verificación de tipo avanzada y operaciones de piezas","fr":"Parfait pour les agents TypeScript nécessitant une vérification de type avancée et des opérations de pièces","de":"Perfekt für TypeScript-Agents, die erweiterte Typprüfung und Teiloperationen benötigen","pt":"Perfeito para Agentes TypeScript que necessitam de verificação de tipo avançada e operações de peça","ru":"Идеально подходит для агентов TypeScript, требующих расширенной проверки типов и операций с фрагментами","ar":"مثالي للوكلاء TypeScript الذين يحتاجون إلى التحقق المتقدم من النوع وعمليات القطعة"},"recommendation":{"en":"Empowers agents to perform type checking and piece operations using the `ct` binary, leveraging Deno and TypeScript for robust development, with features like `--help` for top-level commands and support for identity keys","zh":"通过`ct`二进制文件实现类型检查和块操作，利用Deno和TypeScript进行强大的开发，具有诸如`--help`用于顶级命令和对身份密钥的支持等功能","ja":"`ct`バイナリを使用して型チェックとピース操作を実行し、DenoとTypeScriptを利用して堅牢な開発を行い、`--help`などのトップレベルコマンドとIDキーに対するサポートなどの機能を備える","ko":"`ct` 바이너리 파일을 사용하여 타입 체크 및 조각 작업을 수행하고 Deno 및 TypeScript를 사용하여 강력한 개발을 지원하며 `--help`와 같은 최상위 명령 및 ID 키에 대한 지원과 같은 기능을 제공","es":"Habilita a los agentes a realizar verificación de tipo y operaciones de piezas utilizando el binario `ct`, aprovechando Deno y TypeScript para un desarrollo robusto, con características como `--help` para comandos de nivel superior y soporte para claves de identidad","fr":"Permet aux agents d''exécuter des vérifications de type et des opérations de pièces en utilisant le binaire `ct`, en exploitant Deno et TypeScript pour un développement robuste, avec des fonctionnalités comme `--help` pour les commandes de niveau supérieur et la prise en charge des clés d''identité","de":"Ermöglicht es den Agents, Typprüfung und Teiloperationen mithilfe des `ct`-Binärs durchzuführen, indem Deno und TypeScript für eine robuste Entwicklung genutzt werden, mit Funktionen wie `--help` für Top-Level-Befehle und Unterstützung für Identitätsschlüssel","pt":"Habilita os agentes a realizar verificação de tipo e operações de peça usando o binário `ct`, aproveitando Deno e TypeScript para desenvolvimento robusto, com recursos como `--help` para comandos de nível superior e suporte a chaves de identidade","ru":"Позволяет агентам выполнять проверку типов и операции с фрагментами с помощью бинарного файла `ct`, используя Deno и TypeScript для надежной разработки, с функциями, такими как `--help` для команд верхнего уровня и поддержка идентификационных ключей","ar":"يمنح الوكلاء القدرة على إجراء التحقق من النوع وعمليات القطعة باستخدام ثنائي `ct` ، مع الاستفادة من Deno و TypeScript من أجل التطوير الموثوق ، مع ميزات مثل `--help` للأوامر من المستوى الأعلى ودعم مفاتيح الهوية"},"useCases":{"en":["Performing type checking with `deno task ct check`","Executing piece operations with `deno task ct piece`","Deriving identity keys for local development with `deno run -A packages/cli/mod.ts id derive`"],"zh":["使用`deno task ct check`执行类型检查","使用`deno task ct piece`执行块操作","使用`deno run -A packages/cli/mod.ts id derive`为本地开发派生身份密钥"],"ja":["`deno task ct check`を使用して型チェックを実行する","`deno task ct piece`を使用してピース操作を実行する","`deno run -A packages/cli/mod.ts id derive`を使用してローカル開発のためのIDキーを派生する"],"ko":["`deno task ct check`를 사용하여 타입 체크를 수행","`deno task ct piece`를 사용하여 조각 작업을 수행","`deno run -A packages/cli/mod.ts id derive`를 사용하여 로컬 개발을 위한 ID 키를 파생"],"es":["Realizar verificación de tipo con `deno task ct check`","Ejecutar operaciones de piezas con `deno task ct piece`","Derivar claves de identidad para desarrollo local con `deno run -A packages/cli/mod.ts id derive`"],"fr":["Exécuter une vérification de type avec `deno task ct check`","Exécuter des opérations de pièces avec `deno task ct piece`","Dériver des clés d''identité pour le développement local avec `deno run -A packages/cli/mod.ts id derive`"],"de":["Typprüfung mit `deno task ct check` durchführen","Teiloperationen mit `deno task ct piece` ausführen","Identitätsschlüssel für lokale Entwicklung mit `deno run -A packages/cli/mod.ts id derive` ableiten"],"pt":["Realizar verificação de tipo com `deno task ct check`","Executar operações de peça com `deno task ct piece`","Derivar chaves de identidade para desenvolvimento local com `deno run -A packages/cli/mod.ts id derive`"],"ru":["Выполнять проверку типов с помощью `deno task ct check`","Выполнять операции с фрагментами с помощью `deno task ct piece`","Получать идентификационные ключи для локальной разработки с помощью `deno run -A packages/cli/mod.ts id derive`"],"ar":["إجراء التحقق من النوع باستخدام `deno task ct check`","تنفيذ عمليات القطعة باستخدام `deno task ct piece`","استخراج مفاتيح الهوية للتنمية المحلية باستخدام `deno run -A packages/cli/mod.ts id derive`"]},"limitations":{"en":["Requires Deno and TypeScript environment","Needs an identity key for most operations"],"zh":["需要Deno和TypeScript环境","大多数操作需要身份密钥"],"ja":["DenoとTypeScriptの環境が必要","大多数の操作にはIDキーが必要"],"ko":["Deno 및 TypeScript 환경이 필요","대부분의 작업에는 ID 키가 필요"],"es":["Requiere un entorno Deno y TypeScript","Necesita una clave de identidad para la mayoría de las operaciones"],"fr":["Nécessite un environnement Deno et TypeScript","Nécessite une clé d''identité pour la plupart des opérations"],"de":["Benötigt eine Deno- und TypeScript-Umgebung","Benötigt einen Identitätsschlüssel für die meisten Operationen"],"pt":["Requer ambiente Deno e TypeScript","Necessita de uma chave de identidade para a maioria das operações"],"ru":["Требует среды Deno и TypeScript","Требует идентификационного ключа для большинства операций"],"ar":["يتطلب بيئة Deno و TypeScript","يحتاج إلى مفتاح الهوية لمعظم العمليات"]},"version":4},"contentHash":"a5289bd194b047822305a3f86692defc86da52a75725db3ef1867806f08b8c58","qualityScore":60}');
