INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('joa23/linear-cli/triage', 'triage', 'joa23', 'linear-cli', 'community', 'triage joa23 linear-cli community Triage is a CLI tool for analyzing and prioritizing software backlogs in Linear. It helps developers and teams cleanup and prioritize their backlog, making it easier to focus on high-priority issues. Triage 是一个 token-efficient 的 CLI，用于分析和优先级 Linear 的软件后台 Triage スキルは、Linear のバックログを分析し、優先順位を決定するためのエキスパートです Triage는 Linear의 소프트웨어 백로그를 분석하고 우선 순위를 결정하기 위한 전문가입니다 Triage es una herramienta de línea de comandos para analizar y priorizar backlogs de software de manera eficiente. Utilice Triage para limpiar y priorizar su backlog Triage est un outil en ligne de commande pour analyser et prioriser les backlogs de logiciels de manière efficace. Utilisez Triage pour nettoyer et prioriser votre backlog Triage ist ein Kommandozeilen-Tool zur Analyse und Priorisierung von Software-Backlogs. Verwenden Sie Triage, um Ihren Backlog zu bereinigen und zu priorisieren O Triage é uma ferramenta de linha de comando para análise de backlog que ajuda a priorizar e limpar a lista de tarefas ИИ Агент Triage - это инструмент командной строки для анализа бэклога, giúpающий с приоритизацией и очисткой списка задач مرشح التriage هو أداة سطر الأوامر لتحليل الباكلوج وتحديد الأولويات وتنظيف القائمة how to use triage triage setup guide linear cli alternative triage vs linear efficient backlog analysis token-efficient cli what is triage triage install linear backlog cleanup Triage 技术 Linear CLI 软件后台管理 开发效率 优先级排序 后台分析 AI エージェント CLIlinear 初始化 Fetches all backlog issues using the `linear issues` command Supports setup and initialization via the `linear init` command Utilizes the `.linear.yaml` file for team context configuration Identifies stale or blocked issues for efficient cleanup Prioritizes issues based on team context and backlog analysis Triage is a token-efficient CLI for Linear that enables efficient backlog analysis and prioritization, helping teams make informed decisions about their software development workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('enuno/unifi-mcp-server/FastMCP Development', 'community', 'enuno', 'unifi-mcp-server', 'enuno/unifi-mcp-server', 'FastMCP Development', 0, 0, 60, '2026-03-08T01:57:15.294Z', '2026-03-08T02:01:08.593Z', '329472f8b32978eda354bc40a7d92fd7c698c31908ddc45810ccbca4f6d4ab07', '{"id":"enuno/unifi-mcp-server/FastMCP Development","name":"FastMCP Development","description":{"en":"FastMCP Development is an MCP server that leverages the official UniFi API, providing functionality for developers to integrate with external systems. It benefits developers who need to create custom MCP servers.","zh":"FastMCP开发是一个利用官方UniFi API的MCP服务器，提供快速和可靠的开发环境","ja":"FastMCP開発は、Official UniFi APIを利用したMCPサーバーであり、迅速で信頼性の高い開発環境を提供する","ko":"FastMCP 개발은 공식 UniFi API를 활용한 MCP 서버로 빠르고 안정적인 개발 환경을 제공합니다","es":"FastMCP Development es un servidor MCP que utiliza la API oficial de UniFi para proporcionar funcionalidades de integración con sistemas externos","fr":"FastMCP Development est un serveur MCP qui utilise l''API officielle UniFi pour fournir des fonctionnalités d''intégration avec des systèmes externes","de":"FastMCP Development ist ein MCP-Server, der die offizielle UniFi-API verwendet, um Funktionalitäten für die Integration mit externen Systemen bereitzustellen","pt":"O FastMCP Development é um servidor MCP que utiliza a UniFi API oficial para fornecer funcionalidades personalizadas e integração com sistemas externos","ru":"FastMCP Development - это сервер MCP, использующий официальный UniFi API для предоставления индивидуальных функций и интеграции с внешними системами","ar":"FastMCP Development هو خادم MCP يستخدم واجهة برمجة UniFi لتقديم وظائف مخصصة ودمجها مع الأنظمة الخارجية"},"seo":{"title":{"en":"FastMCP Development: UniFi API Setup Guide | AI Agent Skill","zh":"FastMCP开发设置指南 - 使用官方UniFi API","ja":"FastMCP開発セットアップガイド - Official UniFi APIを使用","ko":"FastMCP 개발 설정 가이드 - 공식 UniFi API 활용","es":"Guía de configuración de FastMCP Development con UniFi API","fr":"Guide de mise en place de FastMCP Development avec l''API ...","de":"Einrichtungsleitfaden für FastMCP Development mit UniFi API","pt":"Guia de Configuração do FastMCP Development com UniFi API","ru":"ИИ Агенты: Настройка FastMCP Development с официальным Un...","ar":"دليل تنصيب FastMCP Development باستخدام واجهة برمجة UniFi"},"description":{"en":"Unlock the full potential of UniFi API with FastMCP Development - get started with our step-by-step setup guide and integrate with external systems today!","zh":"了解如何使用官方UniFi API构建FastMCP服务器，包括设置步骤和关键功能","ja":"Official UniFi APIを使用してFastMCPサーバーを構築する方法を学びます","ko":"공식 UniFi API를 사용하여 FastMCP 서버를 구축하는 방법에 대한 정보","es":"Aprende a configurar un servidor MCP rápido con la API oficial de UniFi y desarrolla herramientas para funciones ejecutables de LLM","fr":"Découvrez comment configurer un serveur MCP rapide avec l''API officielle UniFi et développez des outils pour les fonctions exécutables de LLM","de":"Erfahren Sie, wie Sie einen schnellen MCP-Server mit der offiziellen UniFi-API konfigurieren und entwickeln Sie Tools für LLM-ausführbare Funktionen","pt":"Aprenda a configurar o FastMCP Development com a UniFi API oficial para criar servidores MCP personalizados e escaláveis","ru":"Узнайте, как настроить FastMCP Development с официальным UniFi API для создания индивидуальных и масштабируемых серверов MCP","ar":"تعلم كيفية تثبيت FastMCP Development باستخدام واجهة برمجة UniFi لإنشاء خوادم MCP مخصصة وقابلة للتوسيع"},"definition":{"en":"FastMCP Development is a development framework for creating MCP servers using the UniFi API, allowing for custom integration and functionality.","zh":"FastMCP开发是指使用官方UniFi API构建MCP服务器的过程","ja":"FastMCP開発とは、Official UniFi APIを使用してMCPサーバーを構築すること","ko":"FastMCP 개발은 공식 UniFi API를 사용하여 MCP 서버를 구축하는 것을 의미합니다","es":"FastMCP Development es un servidor MCP que utiliza la API de UniFi para desarrollar herramientas y funciones personalizadas","fr":"FastMCP Development est un serveur MCP qui utilise l''API UniFi pour développer des outils et des fonctions personnalisées","de":"FastMCP Development ist ein MCP-Server, der die UniFi-API verwendet, um benutzerdefinierte Tools und Funktionen zu entwickeln","pt":"O que é FastMCP Development? Um servidor MCP personalizado que utiliza a UniFi API para fornecer funcionalidades específicas","ru":"Что такое FastMCP Development? Индивидуальный сервер MCP, использующий UniFi API для предоставления конкретных функций","ar":"ما هو FastMCP Development؟ خادم MCP مخصص يستخدم واجهة برمجة UniFi لتقديم وظائف محددة"},"features":{"en":["Creates FastMCP server files with basic structure using Quick Start template","Supports implementation of tools for LLM-executable functions","Allows determination of server purpose and required components using TodoWrite","Integrates with external systems using the official UniFi API","Supports development in Python or TypeScript based on project requirements","Includes type hints and annotations for LLM-executable functions"],"zh":["使用官方UniFi API","支持Python和TypeScript开发","提供快速和可靠的开发环境","支持LLM-executable函数","提供Quick Start模板"],"ja":["Official UniFi APIを使用","PythonとTypeScriptの開発をサポート","迅速で信頼性の高い開発環境を提供","LLM-executable関数をサポート","Quick Startテンプレートを提供"],"ko":["공식 UniFi API 사용","Python 및 TypeScript 개발 지원","빠르고 안정적인 개발 환경 제공","LLM-executable 함수 지원","Quick Start 템플릿 제공"],"es":["Utiliza la API oficial de UniFi para la integración con sistemas externos","Permite el desarrollo de herramientas para funciones ejecutables de LLM","Soporte para Python y TypeScript","Estructura de servidor básica con plantilla de inicio rápido","Implementación de herramientas para funciones de LLM","Integración con sistemas externos"],"fr":["Utilise l''API officielle UniFi pour l''intégration avec des systèmes externes","Permet le développement d''outils pour les fonctions exécutables de LLM","Prise en charge de Python et TypeScript","Structure de serveur de base avec modèle de démarrage rapide","Mise en œuvre d''outils pour les fonctions de LLM","Intégration avec des systèmes externes"],"de":["Verwendet die offizielle UniFi-API für die Integration mit externen Systemen","Ermöglicht die Entwicklung von Tools für LLM-ausführbare Funktionen","Unterstützung für Python und TypeScript","Basis-Server-Struktur mit Quick-Start-Vorlage","Implementierung von Tools für LLM-Funktionen","Integration mit externen Systemen"],"pt":["Utiliza a UniFi API oficial para integração com sistemas externos","Fornecer funcionalidades personalizadas com LLM-executable functions","Suporte a Python e TypeScript para desenvolvimento flexível","Integração com sistemas externos para expansão de funcionalidades","Estrutura básica de servidor com template de Quick Start"],"ru":["Использует официальный UniFi API для интеграции с внешними системами","Предоставляет индивидуальные функции с помощью LLM-executable functions","Поддержка Python и TypeScript для гибкого развития","Интеграция с внешними системами для расширения функциональности","Базовая структура сервера с шаблоном Quick Start"],"ar":["يستخدم واجهة برمجة UniFi لدمجها مع الأنظمة الخارجية","يقدم وظائف مخصصة مع وظائف LLM قابلة للتنفيذ","يدعم Python وTypeScript من أجل تطوير مرن","الدمج مع الأنظمة الخارجية لتوسيع الوظائف","هيكل خادم أساسي مع قالب Quick Start"]},"keywords":{"en":["FastMCP Development setup guide","how to use UniFi API with FastMCP","FastMCP Development vs other MCP servers","install FastMCP Development","what is FastMCP Development","FastMCP Development alternative","UniFi API integration with FastMCP","FastMCP Development tutorial","FastMCP Development documentation"],"zh":["FastMCP开发","UniFi API","MCP服务器","Python开发","TypeScript开发","LLM-executable函数","快速开发环境","AIエージェント开发"],"ja":["FastMCP開発","UniFi API","MCPサーバー","Python開発","TypeScript開発","LLM-executable関数","迅速開発環境","AIエージェント開発"],"ko":["FastMCP 개발","UniFi API","MCP 서버","Python 개발","TypeScript 개발","LLM-executable 함수","빠른 개발 환경","AI 에이전트 개발"],"es":["FastMCP Development","API de UniFi","Desarrollo de MCP","Herramientas de LLM","Integración con sistemas externos","Python","TypeScript","Servidor MCP","Desarrollo de herramientas","API oficial de UniFi"],"fr":["FastMCP Development","API UniFi","Développement de MCP","Outils de LLM","Intégration avec des systèmes externes","Python","TypeScript","Serveur MCP","Développement d''outils","API officielle UniFi"],"de":["FastMCP Development","UniFi-API","MCP-Entwicklung","LLM-Tools","Integration mit externen Systemen","Python","TypeScript","MCP-Server","Tool-Entwicklung","Offizielle UniFi-API"],"pt":["FastMCP Development","UniFi API","servidor MCP","LLM-executable functions","Python","TypeScript","desenvolvimento de servidor","integração com sistemas externos"],"ru":["FastMCP Development","ИИ Агенты","UniFi API","сервер MCP","LLM-executable functions","Python","TypeScript","разработка сервера","интеграция с внешними системами"],"ar":["FastMCP Development","واجهة برمجة UniFi","خادم MCP","وظائف LLM قابلة للتنفيذ","Python","TypeScript","تطوير الخادم","الدمج مع الأنظمة الخارجية"]}},"owner":"enuno","repo":"unifi-mcp-server","repoPath":"enuno/unifi-mcp-server","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.294Z","topics":[],"category":"community","skillMd":{"name":"FastMCP Development","description":"Use when creating or modifying Model Context Protocol (MCP) servers with FastMCP framework - guides through tools, resources, prompts, authentication, Claude Desktop integration, and production deployment with Python and TypeScript examples","bodyPreview":"<required>\n*CRITICAL* Add the following steps to your Todo list using TodoWrite:\n\n1. Determine server purpose and required components (tools, resources, prompts)\n\nAsk: What functionality does this MCP server provide? What external systems will it integrate with?\n\n2. Create FastMCP server file with basic structure\n\nUse Quick Start template below. Choose Python or TypeScript based on project requirements.\n\n3. Implement tools for LLM-executable functions\n\nFollow Tools section. Include type hints/an","body":"<required>\n*CRITICAL* Add the following steps to your Todo list using TodoWrite:\n\n1. Determine server purpose and required components (tools, resources, prompts)\n\nAsk: What functionality does this MCP server provide? What external systems will it integrate with?\n\n2. Create FastMCP server file with basic structure\n\nUse Quick Start template below. Choose Python or TypeScript based on project requirements.\n\n3. Implement tools for LLM-executable functions\n\nFollow Tools section. Include type hints/annotations, validation, error handling.\n\n4. Add resources if data access needed\n\nFollow Resources section. Use URI templates for dynamic resources. Include security validation.\n\n5. Add prompts if workflow guidance needed\n\nFollow Prompts section. Use for multi-step workflows, best practices, templates.\n\n6. Configure Claude Desktop integration\n\nFollow Claude Desktop Integration section. Use fastmcp CLI or manual config. Handle environment variables.\n\n7. Test server locally\n\nRun server in STDIO mode. Test with FastMCP client or Claude Desktop locally.\n\n8. Add authentication for production\n\nFollow Authentication section. Use OAuth for enterprise, token verification for custom auth.\n\n9. Deploy using appropriate transport\n\nSTDIO for local tools, HTTP/SSE for network access. Follow Deployment section.\n\n10. Verify integration end-to-end\n\nTest in Claude Desktop. Verify tools appear, resources load, prompts work.\n\n</required>\n\n# When to Use This Skill\n\n**Use this skill when:**\n\n- Creating new MCP servers with FastMCP\n- Adding tools, resources, or prompts to existing servers\n- Integrating MCP servers with Claude Desktop\n- Implementing authentication for production MCP servers\n- Deploying MCP servers via STDIO, HTTP, or SSE transports\n- Migrating from FastMCP v2 to v3\n- Creating custom domain-specific MCP integrations\n\n**Do NOT use this skill when:**\n\n- Building MCP servers in languages other than Python or TypeScript (use official SDK)\n- You need maximum control over MCP protocol implementation (use official SDK)\n- Creating simple command-line tools without LLM integration (FastMCP is overkill)\n\n# Quick Start\n\n## Minimal Python Example\n\n```python\nfrom fastmcp import FastMCP\n\nmcp = FastMCP(\"Demo Server 🚀\")\n\n@mcp.tool()\ndef add(a: int, b: int) -> int:\n    \"\"\"Add two numbers together\"\"\"\n    return a + b\n\n@mcp.resource(\"greeting://hello\")\ndef get_greeting() -> str:\n    \"\"\"Get a friendly greeting\"\"\"\n    return \"Hello from FastMCP!\"\n\nif __name__ == \"__main__\":\n    mcp.run()\n```\n\n**Run it:**\n\n```bash\npython server.py\n```\n\n## Minimal TypeScript Example\n\n```typescript\nimport { FastMCP } from \"@fastmcp/server\";\n\nconst mcp = new FastMCP(\"Demo Server 🚀\");\n\nmcp.tool({\n  name: \"add\",\n  description: \"Add two numbers together\",\n  parameters: {\n    a: { type: \"number\", description: \"First number\" },\n    b: { type: \"number\", description: \"Second number\" }\n  },\n  execute: async ({ a, b }) => a + b\n});\n\nmcp.resource({\n  uri: \"greeting://hello\",\n  name: \"Greeting\",\n  description: \"Get a friendly greeting\",\n  read: async () => \"Hello from FastMCP!\"\n});\n\nmcp.run();\n```\n\n**Run it:**\n\n```bash\nnpm install @fastmcp/server\nnode server.js\n```\n\n## Claude Desktop Installation\n\n**Using fastmcp CLI (Recommended):**\n\n```bash\nfastmcp install claude-desktop server.py\n```\n\n**Manual config** (`~/Library/Application Support/Claude/claude_desktop_config.json` on macOS):\n\n```json\n{\n  \"mcpServers\": {\n    \"my-server\": {\n      \"command\": \"uv\",\n      \"args\": [\"run\", \"--with\", \"fastmcp\", \"fastmcp\", \"run\", \"/absolute/path/to/server.py\"],\n      \"env\": {}\n    }\n  }\n}\n```\n\n**Verify**: Restart Claude Desktop, look for hammer icon (🔨) in input box.\n\n---\n\n# Core Concepts\n\n## Tools - LLM-Executable Functions\n\n**What are tools?** Python/TypeScript functions that LLMs can execute to interact with external systems, run code, and access data.\n\n### Python Tool Implementation\n\n```python\nfrom fastmcp import FastMCP, Context\nfrom typing import Annotated\nfrom pydantic import Field\n\nmcp = FastMCP(\"Data Server\")\n\n@mcp.tool(\n    description=\"Analyze dataset statistics\",\n    tags={\"analysis\", \"statistics\"},\n    timeout=60.0,\n    annotations={\"readOnlyHint\": True}  # Enables caching, skips confirmation\n)\nasync def analyze_dataset(\n    data: Annotated[list[float], Field(description=\"Numbers to analyze\")],\n    percentiles: Annotated[list[int], Field(ge=0, le=100)] = [25, 50, 75],\n    ctx: Context = None  # Injected automatically\n) -> dict:\n    \"\"\"Compute statistical analysis of numeric data.\"\"\"\n    await ctx.info(f\"Analyzing {len(data)} data points\")\n    await ctx.report_progress(progress=50, total=100)\n\n    import statistics\n    return {\n        \"mean\": statistics.mean(data),\n        \"median\": statistics.median(data),\n        \"stdev\": statistics.stdev(data) if len(data) > 1 else 0,\n        \"percentiles\": {p: sorted(data)[int(len(data) * p / 100)] for p in percentiles}\n    }\n```\n\n### TypeScript Tool Implementation\n\n```typescript\nimport { FastMCP, Context } from \"@fastmcp/server\";\n\nconst mcp = new FastMCP(\"Data Server\");\n\nmcp.tool({\n  name: \"analyze_dataset\",\n  description: \"Compute statistical analysis of numeric data\",\n  parameters: {\n    data: {\n      type: \"array\",\n      items: { type: \"number\" },\n      description: \"Numbers to analyze\"\n    },\n    percentiles: {\n      type: \"array\",\n      items: { type: \"number\", minimum: 0, maximum: 100 },\n      default: [25, 50, 75],\n      description: \"Percentiles to calculate\"\n    }\n  },\n  annotations: { readOnlyHint: true },\n  execute: async ({ data, percentiles }, ctx: Context) => {\n    await ctx.info(`Analyzing ${data.length} data points`);\n    await ctx.reportProgress(50, 100);\n\n    const sorted = [...data].sort((a, b) => a - b);\n    const mean = data.reduce((a, b) => a + b) / data.length;\n    const median = sorted[Math.floor(sorted.length / 2)];\n\n    return {\n      mean,\n      median,\n      stdev: calculateStdev(data, mean),\n      percentiles: Object.fromEntries(\n        percentiles.map(p => [p, sorted[Math.floor(sorted.length * p / 100)]])\n      )\n    };\n  }\n});\n```\n\n### Tool Annotations for Client Behavior\n\n```python\nannotations={\n    \"readOnlyHint\": True,      # Skip confirmation, enable caching\n    \"destructiveHint\": True,   # Warn users before execution\n    \"idempotentHint\": True,    # Safe to retry\n    \"openWorldHint\": True      # Accesses unpredictable external data\n}\n```\n\n### Tool Error Handling\n\n```python\nfrom fastmcp import ToolError\n\n@mcp.tool()\ndef query_database(sql: str) -> list[dict]:\n    \"\"\"Execute read-only SQL queries\"\"\"\n    if not sql.upper().startswith(\"SELECT\"):\n        raise ToolError(\"Only SELECT queries allowed\")\n\n    try:\n        return execute_query(sql)\n    except DatabaseError as e:\n        raise ToolError(f\"Query failed: {str(e)}\")\n```\n\n---\n\n## Resources - Read-Only Data Access\n\n**What are resources?** Data or files that MCP clients can read - like GET endpoints in REST APIs, providing data without side effects.\n\n### Static Python Resource\n\n```python\nfrom fastmcp.resources import TextResource\n\nmcp.add_resource(\n    TextResource(\n        uri=\"config://database\",\n        name=\"Database Config\",\n        description=\"Current database configuration\",\n        text=''{\"host\": \"localhost\", \"port\": 5432}''\n    )\n)\n```\n\n### Dynamic Python Resource with URI Templates\n\n```python\nfrom fastmcp.resources import ResourceResult, ResourceContent\n\n# Simple parameter (single path segment)\n@mcp.resource(\"weather://{city}/current\")\nasync def get_weather(city: str) -> str:\n    \"\"\"Get current weather for a city\"\"\"\n    if not is_valid_city(city):\n        raise ResourceError(f\"Invalid city: {city}\")\n\n    data = await fetch_weather(city)\n    return json.dumps({\"city\": city, \"temp\": data.temp, \"conditions\": data.conditions})\n\n# Wildcard parameter (multiple segments)\n@mcp.resource(\"path://{filepath*}\")\nasync def get_file_content(filepath: str, ctx: Context) -> str:\n    \"\"\"Read file contents with security validation\"\"\"\n    # Matches: path://docs/server/resources.mdx\n    full_path = os.path.abspath(filepath)\n\n    # Security: Prevent directory traversal\n    if not full_path.startswith(ALLOWED_BASE_PATH):\n        raise ResourceError(\"Access denied: path outside allowed directory\")\n\n    if not os.path.exists(full_path):\n        raise ResourceError(f\"File not found: {filepath}\")\n\n    await ctx.info(f\"Reading file: {filepath}\")\n\n    async with aiofiles.open(full_path, ''r'') as f:\n        content = await f.read()\n\n    return content\n\n# Query parameters (optional configuration)\n@mcp.resource(\"data://{id}{?format}\")\ndef get_data(id: str, format: str = \"json\") -> str:\n    \"\"\"Get data in specified format\"\"\"\n    # Matches: data://123?format=xml\n    data = fetch_data(id)\n    if format == \"xml\":\n        return convert_to_xml(data)\n    return json.dumps(data)\n```\n\n### TypeScript Resource with URI Templates\n\n```typescript\nmcp.resource({\n  uri: \"weather://{city}/current\",\n  name: \"Current Weather\",\n  description: \"Get current weather for a city\",\n  read: async ({ city }, ctx) => {\n    if (!isValidCity(city)) {\n      throw new ResourceError(`Invalid city: ${city}`);\n    }\n\n    const data = await fetchWeather(city);\n    return JSON.stringify({ city, temp: data.temp, conditions: data.conditions });\n  }\n});\n\n// File system resource with security\nmcp.resource({\n  uri: \"path://{filepath*}\",\n  name: \"File Content\",\n  description: \"Read file contents\",\n  read: async ({ filepath }, ctx) => {\n    const fullPath = path.resolve(filepath);\n\n    // Security: Prevent directory traversal\n    if (!fullPath.startsWith(ALLOWED_BASE_PATH)) {\n      throw new ResourceError(\"Access denied\");\n    }\n\n    await ctx.info(`Reading file: ${filepath}`);\n    return await fs.promises.readFile(fullPath, ''utf-8'');\n  }\n});\n```\n\n### Multiple Content Types\n\n```python\n@mcp.resource(\"data://users\")\ndef get_users() -> ResourceResult:\n    \"\"\"Get user data in multiple formats\"\"\"\n    return ResourceResult(\n        contents=[\n            ResourceContent(\n                content=''[{\"id\": 1, \"name\": \"Alice\"}]'',\n                mime_type=\"application/json\"\n            ),\n            ResourceContent(\n                content=\"# Users\\nTotal: 1 user\",\n                mime_type=\"text/markdown\"\n            ),\n        ],\n        meta={\"total\": 1, \"cached\": True}\n    )\n```\n\n---\n\n## Prompts - Reusable Message Templates\n\n**What are prompts?** Message templates that help LLMs generate structured, purposeful responses - \"best practices encoded into your server.\"\n\n### Basic Python Prompt\n\n```python\nfrom fastmcp import FastMCP\nfrom fastmcp.prompts import Message, PromptResult\n\nmcp = FastMCP(\"Prompt Server\")\n\n@mcp.prompt()\ndef ask_about_topic(topic: str) -> str:\n    \"\"\"Generate a user message asking for explanation\"\"\"\n    return f\"Can you please explain the concept of ''{topic}'' in simple terms?\"\n```\n\n### Advanced Python Prompt with Multi-Message Conversation\n\n```python\n@mcp.prompt(\n    name=\"code_review_workflow\",\n    description=\"Complete code review with security analysis\",\n    tags={\"security\", \"code-quality\"}\n)\ndef code_review(code: str, language: str = \"python\") -> PromptResult:\n    \"\"\"Security-focused code review workflow\"\"\"\n    return PromptResult(\n        messages=[\n            Message(\n                role=\"user\",\n                content=f\"Review this {language} code for security issues:\\n```{language}\\n{code}\\n```\"\n            ),\n            Message(\n                role=\"assistant\",\n                content=\"I''ll analyze this systematically for security vulnerabilities.\"\n            ),\n            Message(\n                role=\"user\",\n                content=\"Focus especially on SQL injection, XSS, and authentication bypass.\"\n            )\n        ],\n        description=\"Security-focused code review with systematic analysis\",\n        meta={\"priority\": \"high\", \"review_type\": \"security\"}\n    )\n```\n\n### TypeScript Prompt Implementation\n\n```typescript\nmcp.prompt({\n  name: \"code_review_workflow\",\n  description: \"Complete code review with security analysis\",\n  parameters: {\n    code: { type: \"string\", description: \"Code to review\" },\n    language: { type: \"string\", default: \"python\" }\n  },\n  execute: async ({ code, language }) => {\n    return {\n      messages: [\n        {\n          role: \"user\",\n          content: `Review this ${language} code for security issues:\\n\\`\\`\\`${language}\\n${code}\\n\\`\\`\\``\n        },\n        {\n          role: \"assistant\",\n          content: \"I''ll analyze this systematically for security vulnerabilities.\"\n        },\n        {\n          role: \"user\",\n          content: \"Focus especially on SQL injection, XSS, and authentication bypass.\"\n        }\n      ],\n      description: \"Security-focused code review\",\n      meta: { priority: \"high\", review_type: \"security\" }\n    };\n  }\n});\n```\n\n---\n\n## Context - MCP Capabilities Access\n\n**What is Context?** Dependency-injected object providing access to logging, progress tracking, resource/prompt management, LLM operations, and request metadata.\n\n### Context Capabilities\n\n| Category | Methods | Purpose |\n|----------|---------|---------|\n| **Logging** | `debug()`, `info()`, `warning()`, `error()` | Send log messages to clients |\n| **Progress** | `report_progress(progress, total)` | Update clients on long-running ops |\n| **Resources** | `list_resources()`, `read_resource(uri)` | Access other resources |\n| **Prompts** | `list_prompts()`, `get_prompt(name, args)` | Retrieve prompt templates |\n| **LLM** | `sample(prompt, temperature)` | Request client LLM generation |\n| **User Input** | `elicit(question, response_type)` | Request structured user input |\n| **State** | `set_state()`, `get_state()`, `delete_state()` | Persist data across requests |\n| **Metadata** | `request_id`, `client_id`, `session_id` | Request context information |\n\n### Python Context Example\n\n```python\nfrom fastmcp import FastMCP, Context\nfrom fastmcp.dependencies import CurrentContext\n\n@mcp.tool()\nasync def process_data(data_uri: str, ctx: Context = CurrentContext()) -> dict:\n    \"\"\"Process data with full context capabilities\"\"\"\n    await ctx.info(f\"Processing {data_uri}\")\n\n    # Read another resource\n    resources = await ctx.read_resource(data_uri)\n    content = resources[0].text\n\n    # Report progress\n    await ctx.report_progress(progress=25, total=100)\n\n    # Use LLM for analysis\n    summary = await ctx.sample(f\"Summarize this data concisely: {content[:500]}\")\n\n    await ctx.report_progress(progress=75, total=100)\n\n    # Store state for next request\n    await ctx.set_state(\"last_processed\", data_uri)\n\n    await ctx.report_progress(progress=100, total=100)\n\n    return {\n        \"result\": summary.text,\n        \"request_id\": ctx.request_id,\n        \"timestamp\": ctx.timestamp\n    }\n```\n\n### TypeScript Context Example\n\n```typescript\nmcp.tool({\n  name: \"process_data\",\n  description: \"Process data with full context capabilities\",\n  parameters: {\n    data_uri: { type: \"string\", description: \"URI of data to process\" }\n  },\n  execute: async ({ data_uri }, ctx) => {\n    await ctx.info(`Processing ${data_uri}`);\n\n    // Read resource\n    const resources = await ctx.readResource(data_uri);\n    const content = resources[0].text;\n\n    // Report progress\n    await ctx.reportProgress(25, 100);\n\n    // Use LLM\n    const summary = await ctx.sample(`Summarize this data: ${content.slice(0, 500)}`);\n\n    await ctx.reportProgress(75, 100);\n\n    // Store state\n    await ctx.setState(\"last_processed\", data_uri);\n\n    await ctx.reportProgress(100, 100);\n\n    return {\n      result: summary.text,\n      request_id: ctx.requestId,\n      timestamp: ctx.timestamp\n    };\n  }\n});\n```\n\n**Critical**: Context is scoped to a single request. State persists across requests, but context object itself is recreated per request.\n\n---\n\n# Claude Desktop Integration\n\n## Installation Methods\n\n### Method 1: FastMCP CLI (Recommended)\n\n```bash\n# Basic installation\nfastmcp install claude-desktop server.py\n\n# With dependencies\nfastmcp install claude-desktop server.py \\\n    --with pandas \\\n    --with requests \\\n    --env API_KEY=your_key\n\n# With requirements file\nfastmcp install claude-desktop server.py \\\n    --with-requirements requirements.txt \\\n    --env-file .env\n```\n\n### Method 2: Manual Configuration\n\n**macOS:** `~/Library/Application Support/Claude/claude_desktop_config.json`\n**Windows:** `%APPDATA%\\Claude\\claude_desktop_config.json`\n**Linux:** `~/.config/Claude/claude_desktop_config.json`\n\n```json\n{\n  \"mcpServers\": {\n    \"my-server\": {\n      \"command\": \"uv\",\n      \"args\": [\n        \"run\",\n        \"--with\", \"fastmcp\",\n        \"--with\", \"pandas\",\n        \"fastmcp\",\n        \"run\",\n        \"/absolute/path/to/server.py\"\n      ],\n      \"env\": {\n        \"API_KEY\": \"your_value\",\n        \"DATABASE_URL\": \"postgresql://localhost/mydb\"\n      }\n    }\n  }\n}\n```\n\n**TypeScript/Node.js config:**\n\n```json\n{\n  \"mcpServers\": {\n    \"my-server\": {\n      \"command\": \"node\",\n      \"args\": [\"/absolute/path/to/server.js\"],\n      \"env\": {\n        \"NODE_ENV\": \"production\"\n      }\n    }\n  }\n}\n```\n\n## Critical Requirements\n\n⚠️ **Environment Isolation**: Claude Desktop runs servers in completely isolated environment with **no access to your shell environment**\n\n⚠️ **Must explicitly pass environment variables** via `--env` or `--env-file`\n\n⚠️ **Absolute paths required** for server files (relative paths will fail)\n\n⚠️ **uv must be installed** and available in PATH for Python servers\n\n## Verification\n\n1. Save config file\n2. **Restart Claude Desktop completely** (quit and reopen)\n3. Look for hammer icon (🔨) in input box\n4. Type a message to see if tools appear in suggestions\n\n## Troubleshooting\n\n**No hammer icon appears:**\n\n- Check config file syntax (use JSON validator)\n- Verify absolute path to server file\n- Check `uv` is installed: `which uv`\n- Look at Claude Desktop logs (Help → View Logs)\n\n**Hammer icon appears but tools don''t work:**\n\n- Check environment variables are passed correctly\n- Verify dependencies are installed\n- Check server logs for errors\n- Test server standalone: `python server.py`\n\n**Environment variables not working:**\n\n- Don''t rely on shell environment (it won''t be loaded)\n- Pass ALL required env vars explicitly in config\n- Use `--env-file` to load from `.env` file\n\n---\n\n# Authentication and Security\n\n## Default is Insecure\n\n⚠️ **FastMCP defaults to HTTP with no authentication or encryption**\n\n🔒 **For production: ALWAYS use HTTPS/TLS and require authentication**\n\n## OAuth Authentication (Python)\n\n```python\nfrom fastmcp import FastMCP\nfrom fastmcp.auth import GoogleOAuth, GitHubOAuth, AzureOAuth\n\n# Google OAuth\nmcp = FastMCP(\n    name=\"Secure Server\",\n    auth=GoogleOAuth(\n        client_id=\"your-client-id.apps.googleusercontent.com\",\n        client_secret=\"your-client-secret\"\n    )\n)\n\n# GitHub OAuth\nmcp = FastMCP(\n    name=\"Secure Server\",\n    auth=GitHubOAuth(\n        client_id=\"your-client-id\",\n        client_secret=\"your-client-secret\"\n    )\n)\n\n# Azure OAuth\nmcp = FastMCP(\n    name=\"Secure Server\",\n    auth=AzureOAuth(\n        client_id=\"your-client-id\",\n        client_secret=\"your-client-secret\",\n        tenant_id=\"your-tenant-id\"\n    )\n)\n```\n\n## Token Verification (Python)\n\n```python\nfrom fastmcp.auth import TokenVerifier\n\ndef verify_jwt(token: str) -> bool:\n    \"\"\"Verify JWT token against your auth system\"\"\"\n    try:\n        payload = jwt.decode(token, SECRET_KEY, algorithms=[\"HS256\"])\n        return payload.get(\"authorized\") == True\n    except jwt.InvalidTokenError:\n        return False\n\nmcp = FastMCP(\n    name=\"Secure Server\",\n    auth=TokenVerifier(verify_token=verify_jwt)\n)\n```\n\n## TypeScript Authentication\n\n```typescript\nimport { FastMCP } from \"@fastmcp/server\";\nimport { GoogleOAuth } from \"@fastmcp/auth\";\n\nconst mcp = new FastMCP({\n  name: \"Secure Server\",\n  auth: new GoogleOAuth({\n    clientId: \"your-client-id\",\n    clientSecret: \"your-client-secret\"\n  })\n});\n```\n\n## Security Best Practices\n\n```python\nmcp = FastMCP(\n    name=\"Production Server\",\n    auth=GoogleOAuth(...),\n    mask_error_details=True,  # Don''t leak internal errors to clients\n    allowed_origins=[\"https://your-domain.com\"],  # CORS restrictions\n    rate_limit={\"requests_per_minute\": 100}  # Rate limiting\n)\n\n@mcp.tool()\ndef query_database(sql: str) -> list[dict]:\n    \"\"\"Secure database query with validation\"\"\"\n    # Input validation\n    if not sql.upper().startswith(\"SELECT\"):\n        raise ToolError(\"Only SELECT queries allowed\")\n\n    # SQL injection prevention\n    if any(keyword in sql.upper() for keyword in [\"DROP\", \"DELETE\", \"UPDATE\", \"INSERT\"]):\n        raise ToolError(\"Destructive SQL keywords not allowed\")\n\n    # Parameterized queries\n    return execute_query(sql, use_prepared=True)\n\n@mcp.resource(\"file://{path*}\")\ndef read_file(path: str) -> str:\n    \"\"\"Secure file access with path validation\"\"\"\n    # Prevent directory traversal\n    abs_path = os.path.abspath(path)\n    if not abs_path.startswith(ALLOWED_BASE_DIR):\n        raise ResourceError(\"Access denied: path outside allowed directory\")\n\n    # Check permissions\n    if not os.access(abs_path, os.R_OK):\n        raise ResourceError(\"Access denied: insufficient permissions\")\n\n    return open(abs_path).read()\n```\n\n---\n\n# Advanced Patterns\n\n## Dependency Injection\n\n```python\nfrom fastmcp.dependencies import Depends\n\ndef get_user_id() -> str:\n    \"\"\"Hidden from LLM schema, injected at runtime\"\"\"\n    return \"user_123\"\n\ndef get_db_connection():\n    \"\"\"Dependency injection for database\"\"\"\n    return DatabaseConnection()\n\n@mcp.tool()\ndef get_user_details(\n    user_id: str = Depends(get_user_id),\n    db = Depends(get_db_connection)\n) -> str:\n    \"\"\"Tool receives injected dependencies transparently\"\"\"\n    return db.fetch_user(user_id)\n```\n\n## Server Composition\n\n```python\nfrom fastmcp import FastMCP\n\n# Combine multiple servers\nweather_server = FastMCP(\"Weather\")\ndatabase_server = FastMCP(\"Database\")\n\nmain = FastMCP(\"Unified Server\")\nmain.add_server(weather_server, prefix=\"weather\")\nmain.add_server(database_server, prefix=\"db\")\n\n# Exposes: weather:get_forecast, db:query_users\nif __name__ == \"__main__\":\n    main.run()\n```\n\n## Remote Server Proxying\n\n```python\nfrom fastmcp.server import create_proxy\nfrom fastmcp.auth import BearerAuth\n\n# Create proxy to remote MCP server\nproxy = create_proxy(\n    \"https://api.example.com/mcp/sse\",\n    name=\"Remote Server Proxy\",\n    auth=BearerAuth(token=\"your-api-token\")\n)\n\nif __name__ == \"__main__\":\n    proxy.run()\n```\n\n## Dynamic Component Management\n\n```python\n# Add/remove components at runtime\nmcp.add_tool(my_function)\nmcp.remove_tool(\"tool_name\")\n\n# Control visibility\nmcp.disable(tags={\"admin\"})  # Hide admin tools\nmcp.enable(tags={\"public\"}, only=True)  # Allowlist mode\n\n# Clients automatically notified via notifications/tools/list_changed\n```\n\n## Testing with Client\n\n```python\nimport asyncio\nfrom fastmcp import FastMCP, Client\n\nmcp = FastMCP(\"Test Server\")\n\n@mcp.tool()\ndef add(a: int, b: int) -> int:\n    return a + b\n\n# Test your server\nasync def test_server():\n    async with Client(mcp) as client:\n        result = await client.call_tool(\"add\", {\"a\": 5, \"b\": 3})\n        assert result == 8\n        print(\"✅ Test passed\")\n\nasyncio.run(test_server())\n```\n\n---\n\n# Common Pitfalls\n\n## 1. Environment Isolation in Claude Desktop\n\n**Problem**: Server can''t find API keys or dependencies\n\n```python\n# ❌ BAD: Relies on shell environment\napi_key = os.getenv(\"API_KEY\")  # Will be None in Claude Desktop!\n```\n\n**Solution**: Explicitly pass environment variables in config\n\n```json\n{\n  \"mcpServers\": {\n    \"my-server\": {\n      \"command\": \"uv\",\n      \"args\": [\"run\", \"--with\", \"fastmcp\", \"fastmcp\", \"run\", \"server.py\"],\n      \"env\": {\n        \"API_KEY\": \"actual_value_here\"\n      }\n    }\n  }\n}\n```\n\n## 2. Relative Paths in Config\n\n**Problem**: Server file not found\n\n```json\n// ❌ BAD: Relative path\n\"args\": [\"fastmcp\", \"run\", \"./server.py\"]\n```\n\n**Solution**: Use absolute paths\n\n```json\n// ✅ GOOD: Absolute path\n\"args\": [\"fastmcp\", \"run\", \"/Users/alice/projects/mcp-server/server.py\"]\n```\n\n## 3. Functions with *args or **kwargs\n\n**Problem**: FastMCP can''t generate schema\n\n```python\n# ❌ BAD: Can''t extract parameter schema\n@mcp.tool()\ndef process(*args, **kwargs):\n    pass\n```\n\n**Solution**: Use explicit parameters\n\n```python\n# ✅ GOOD: Explicit parameters with types\n@mcp.tool()\ndef process(data: list[str], options: dict[str, any] = {}) -> dict:\n    pass\n```\n\n## 4. Context Scoped to Single Request\n\n**Problem**: Expecting context to persist\n\n```python\n# ❌ BAD: Context won''t persist across requests\n@mcp.tool()\nasync def step1(ctx: Context):\n    ctx.user_data = \"some value\"  # Lost after request ends\n\n@mcp.tool()\nasync def step2(ctx: Context):\n    return ctx.user_data  # Will fail - different context instance\n```\n\n**Solution**: Use context state methods\n\n```python\n# ✅ GOOD: Use state persistence\n@mcp.tool()\nasync def step1(ctx: Context):\n    await ctx.set_state(\"user_data\", \"some value\")\n\n@mcp.tool()\nasync def step2(ctx: Context):\n    return await ctx.get_state(\"user_data\")\n```\n\n## 5. Default Security is Insecure\n\n**Problem**: Production server with no authentication\n\n```python\n# ❌ BAD: No auth, HTTP only\nmcp = FastMCP(\"Production Server\")\nmcp.run(transport=\"http\", port=8000)\n```\n\n**Solution**: Always use auth and HTTPS\n\n```python\n# ✅ GOOD: OAuth with HTTPS\nmcp = FastMCP(\n    \"Production Server\",\n    auth=GoogleOAuth(client_id=\"...\", client_secret=\"...\")\n)\nmcp.run(transport=\"http\", port=8443, ssl_certfile=\"cert.pem\", ssl_keyfile=\"key.pem\")\n```\n\n## 6. Async/Sync Confusion\n\n**Problem**: Mixing async/sync incorrectly\n\n```python\n# ❌ BAD: Blocking I/O in async function\n@mcp.tool()\nasync def fetch_data(url: str) -> str:\n    return requests.get(url).text  # Blocks event loop!\n```\n\n**Solution**: Use async libraries or sync tools\n\n```python\n# ✅ GOOD: Async I/O\n@mcp.tool()\nasync def fetch_data(url: str) -> str:\n    async with aiohttp.ClientSession() as session:\n        async with session.get(url) as response:\n            return await response.text()\n\n# ✅ ALSO GOOD: Sync tool (FastMCP runs in thread pool)\n@mcp.tool()\ndef fetch_data_sync(url: str) -> str:\n    return requests.get(url).text  # FastMCP handles threading\n```\n\n## 7. Not Handling Tool Errors\n\n**Problem**: Unhandled exceptions leak to clients\n\n```python\n# ❌ BAD: Raw exception\n@mcp.tool()\ndef divide(a: int, b: int) -> float:\n    return a / b  # ZeroDivisionError leaks\n```\n\n**Solution**: Catch and raise ToolError\n\n```python\n# ✅ GOOD: Clean error handling\nfrom fastmcp import ToolError\n\n@mcp.tool()\ndef divide(a: int, b: int) -> float:\n    if b == 0:\n        raise ToolError(\"Cannot divide by zero\")\n    return a / b\n```\n\n---\n\n# Deployment\n\n## Transport Options\n\n### STDIO (Default) - For Claude Desktop and Local Tools\n\n```python\n# Python\nif __name__ == \"__main__\":\n    mcp.run()  # Defaults to STDIO\n```\n\n```bash\n# Run directly\npython server.py\n```\n\n**Use when:**\n\n- Integrating with Claude Desktop\n- Building local command-line tools\n- Single-user scenarios\n\n### HTTP - For Network Access\n\n```python\n# Python\nif __name__ == \"__main__\":\n    mcp.run(transport=\"http\", host=\"0.0.0.0\", port=8000)\n```\n\n```typescript\n// TypeScript\nmcp.run({ transport: \"http\", host: \"0.0.0.0\", port: 8000 });\n```\n\n**Use when:**\n\n- Multiple clients need access\n- Deploying to cloud services\n- Need RESTful interface\n\n### SSE (Server-Sent Events) - For Streaming\n\n```python\nif __name__ == \"__main__\":\n    mcp.run(transport=\"sse\", host=\"0.0.0.0\", port=8000)\n```\n\n**Use when:**\n\n- Need long-lived connections\n- Real-time updates/streaming\n- Better than HTTP for persistent connections\n\n## Production Deployment Checklist\n\n- [ ] **Authentication enabled** (OAuth or token verification)\n- [ ] **HTTPS/TLS configured** (SSL certificates)\n- [ ] **Error masking enabled** (`mask_error_details=True`)\n- [ ] **Input validation** on all tools and resources\n- [ ] **Rate limiting** configured\n- [ ] **Logging** configured to monitoring system\n- [ ] **Health check endpoint** implemented\n- [ ] **Environment variables** managed securely (not in code)\n- [ ] **Dependencies pinned** to specific versions\n- [ ] **CORS configured** if web clients will connect\n- [ ] **Resource limits** set (memory, CPU, timeout)\n- [ ] **Monitoring and alerting** configured\n\n## Production Server Template (Python)\n\n```python\nfrom fastmcp import FastMCP\nfrom fastmcp.auth import GoogleOAuth\nimport logging\n\n# Configure logging\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n# Production server with security\nmcp = FastMCP(\n    name=\"Production API Server\",\n    auth=GoogleOAuth(\n        client_id=os.getenv(\"GOOGLE_CLIENT_ID\"),\n        client_secret=os.getenv(\"GOOGLE_CLIENT_SECRET\")\n    ),\n    mask_error_details=True,\n    rate_limit={\"requests_per_minute\": 100},\n    allowed_origins=[\"https://app.example.com\"]\n)\n\n@mcp.tool(timeout=30.0)\nasync def secure_operation(data: str, ctx: Context) -> dict:\n    \"\"\"Production-ready tool with full security\"\"\"\n    try:\n        # Log request\n        logger.info(f\"Request {ctx.request_id}: processing {len(data)} bytes\")\n\n        # Validate input\n        if len(data) > 10000:\n            raise ToolError(\"Data too large (max 10KB)\")\n\n        # Process\n        result = await process_data(data)\n\n        # Log success\n        logger.info(f\"Request {ctx.request_id}: success\")\n\n        return {\"result\": result, \"request_id\": ctx.request_id}\n\n    except Exception as e:\n        logger.error(f\"Request {ctx.request_id}: error - {str(e)}\")\n        raise ToolError(\"Processing failed\")\n\nif __name__ == \"__main__\":\n    mcp.run(\n        transport=\"http\",\n        host=\"0.0.0.0\",\n        port=int(os.getenv(\"PORT\", 8443)),\n        ssl_certfile=os.getenv(\"SSL_CERT\"),\n        ssl_keyfile=os.getenv(\"SSL_KEY\")\n    )\n```\n\n## Production Server Template (TypeScript)\n\n```typescript\nimport { FastMCP } from \"@fastmcp/server\";\nimport { GoogleOAuth } from \"@fastmcp/auth\";\n\nconst mcp = new FastMCP({\n  name: \"Production API Server\",\n  auth: new GoogleOAuth({\n    clientId: process.env.GOOGLE_CLIENT_ID!,\n    clientSecret: process.env.GOOGLE_CLIENT_SECRET!\n  }),\n  maskErrorDetails: true,\n  rateLimit: { requestsPerMinute: 100 },\n  allowedOrigins: [\"https://app.example.com\"]\n});\n\nmcp.tool({\n  name: \"secure_operation\",\n  description: \"Production-ready tool\",\n  parameters: { data: { type: \"string\" } },\n  timeout: 30000,\n  execute: async ({ data }, ctx) => {\n    try {\n      console.log(`Request ${ctx.requestId}: processing ${data.length} bytes`);\n\n      if (data.length > 10000) {\n        throw new Error(\"Data too large\");\n      }\n\n      const result = await processData(data);\n\n      console.log(`Request ${ctx.requestId}: success`);\n\n      return { result, request_id: ctx.requestId };\n    } catch (e) {\n      console.error(`Request ${ctx.requestId}: error - ${e}`);\n      throw new Error(\"Processing failed\");\n    }\n  }\n});\n\nmcp.run({\n  transport: \"http\",\n  host: \"0.0.0.0\",\n  port: parseInt(process.env.PORT || \"8443\"),\n  sslCert: process.env.SSL_CERT,\n  sslKey: process.env.SSL_KEY\n});\n```\n\n---\n\n# FastMCP v3 Beta Features\n\n> **Note**: FastMCP v3 is in beta as of January 2026. For production systems, pin to v2.x.x stable release.\n\n## What''s New in v3\n\n### 1. Improved Type System\n\n```python\n# v3: Better type inference\nfrom fastmcp import FastMCP\nfrom typing import Literal\n\n@mcp.tool()\ndef process(mode: Literal[\"fast\", \"accurate\", \"balanced\"]) -> dict:\n    # v3 automatically generates enum schema\n    pass\n```\n\n### 2. Enhanced Context API\n\n```python\n# v3: New context methods\n@mcp.tool()\nasync def advanced_tool(ctx: Context) -> dict:\n    # Structured logging with levels\n    await ctx.log(level=\"INFO\", message=\"Starting\", tags={\"module\": \"processor\"})\n\n    # Batch operations\n    resources = await ctx.batch_read_resources([\"uri1\", \"uri2\", \"uri3\"])\n\n    # Enhanced state with TTL\n    await ctx.set_state(\"cache\", data, ttl=3600)  # Expire after 1 hour\n```\n\n### 3. Middleware Support\n\n```python\n# v3: Request/response middleware\nasync def auth_middleware(request, call_next):\n    if not validate_token(request.headers.get(\"Authorization\")):\n        raise UnauthorizedError()\n    return await call_next(request)\n\nmcp = FastMCP(\"Server\", middleware=[auth_middleware])\n```\n\n### 4. Plugin System\n\n```python\n# v3: Plugin architecture\nfrom fastmcp.plugins import MetricsPlugin, CachePlugin\n\nmcp = FastMCP(\n    \"Server\",\n    plugins=[\n        MetricsPlugin(export_to=\"prometheus\"),\n        CachePlugin(backend=\"redis\", ttl=300)\n    ]\n)\n```\n\n## Breaking Changes from v2\n\n| Feature | v2 | v3 |\n|---------|----|----|\n| **Import path** | `from fastmcp import FastMCP` | Same (no change) |\n| **Tool decorator** | `@mcp.tool()` | `@mcp.tool()` (signature changed) |\n| **Context injection** | `ctx: Context = None` | `ctx: Context` (required if used) |\n| **Error classes** | `ToolError`, `ResourceError` | Same + `UnauthorizedError` |\n| **Auth configuration** | `auth` parameter | `auth` + `authorization` |\n\n## Migration Guide: v2 → v3\n\n### Step 1: Update Dependencies\n\n```bash\n# Pin to v2 (stable)\npip install fastmcp~=2.11.0\n\n# Upgrade to v3 (beta)\npip install fastmcp~=3.0.0-beta\n```\n\n### Step 2: Update Tool Signatures\n\n```python\n# v2\n@mcp.tool()\ndef my_tool(param: str, ctx: Context = None) -> str:\n    pass\n\n# v3: Context must be explicitly typed (no default None)\n@mcp.tool()\ndef my_tool(param: str, ctx: Context) -> str:\n    pass\n```\n\n### Step 3: Update Context Method Calls\n\n```python\n# v2\nawait ctx.report_progress(50, 100)\n\n# v3: Same syntax (no change)\nawait ctx.report_progress(50, 100)\n```\n\n### Step 4: Update Authentication\n\n```python\n# v2\nfrom fastmcp.auth import GoogleOAuth\nmcp = FastMCP(\"Server\", auth=GoogleOAuth(...))\n\n# v3: Enhanced auth configuration\nfrom fastmcp.auth import GoogleOAuth, RoleBasedAuth\nmcp = FastMCP(\n    \"Server\",\n    auth=GoogleOAuth(...),\n    authorization=RoleBasedAuth(roles=[\"admin\", \"user\"])\n)\n```\n\n### Step 5: Test Thoroughly\n\n```python\n# Run full test suite before deploying v3\npytest tests/\n```\n\n## Version Compatibility Matrix\n\n| Feature | v2.11.x | v3.0.0-beta | Status |\n|---------|---------|-------------|--------|\n| Basic tools | ✅ | ✅ | Stable |\n| Resources | ✅ | ✅ | Stable |\n| Prompts | ✅ | ✅ | Stable |\n| Context API | ✅ | ✅ Enhanced | Enhanced in v3 |\n| OAuth | ✅ | ✅ Enhanced | Enhanced in v3 |\n| Middleware | ❌ | ✅ | New in v3 |\n| Plugins | ❌ | ✅ | New in v3 |\n| Batch operations | ❌ | ✅ | New in v3 |\n\n**Recommendation**: Use v2.11.x for production, evaluate v3 beta in staging environments.\n\n---\n\n# Integration with Creating-Skills Workflow\n\nThis FastMCP skill composes with the `creating-skills` workflow for creating custom domain-specific MCP skills.\n\n## When to Combine Both Skills\n\n**Use FastMCP skill alone when:**\n\n- Building one-off MCP servers\n- Integrating specific APIs or data sources\n- Quick prototyping\n\n**Use both skills together when:**\n\n- Creating reusable MCP patterns for your team\n- Building domain-specific skill templates (e.g., \"Database MCP Skill\", \"API Wrapper MCP Skill\")\n- Packaging MCP servers as distributable skills\n\n## Workflow: Creating Custom MCP-Based Skill\n\n1. **User requests custom skill**: \"Create a skill for working with our company''s API using MCP\"\n\n2. **Creating-skills skill activates**:\n   - Gathers requirements about the API\n   - Determines skill structure\n   - Creates skill directory\n\n3. **Creating-skills delegates to FastMCP skill**:\n   - FastMCP skill provides MCP server implementation\n   - Creates tools for API endpoints\n   - Creates resources for data access\n   - Adds authentication\n\n4. **Creating-skills wraps as reusable skill**:\n   - Packages MCP server as SKILL.md\n   - Adds checklist for using the skill\n   - Documents activation triggers\n   - Creates usage examples\n\n5. **Result**: Custom skill that other team members can use to work with the API via MCP\n\n## Example: Creating \"Company CRM MCP Skill\"\n\n```markdown\n# Input to creating-skills\n\"Create a skill for working with our Salesforce CRM using MCP\"\n\n# Creating-skills output (using FastMCP skill for implementation)\n.claude/skills/salesforce-crm/\n├── SKILL.md                    # Skill instructions\n├── server.py                   # FastMCP server (from this skill)\n└── config.json                 # Claude Desktop config\n\n# server.py (generated using FastMCP skill patterns)\nfrom fastmcp import FastMCP, Context\nfrom salesforce_api import SalesforceClient\n\nmcp = FastMCP(\"Salesforce CRM\")\n\n@mcp.tool()\nasync def search_contacts(query: str) -> list[dict]:\n    \"\"\"Search contacts in Salesforce\"\"\"\n    client = SalesforceClient(os.getenv(\"SALESFORCE_TOKEN\"))\n    return await client.search_contacts(query)\n\n@mcp.resource(\"crm://contacts/{contact_id}\")\nasync def get_contact(contact_id: str) -> str:\n    \"\"\"Get contact details\"\"\"\n    client = SalesforceClient(os.getenv(\"SALESFORCE_TOKEN\"))\n    contact = await client.get_contact(contact_id)\n    return json.dumps(contact)\n\nif __name__ == \"__main__\":\n    mcp.run()\n\n# SKILL.md (created by creating-skills, references FastMCP patterns)\n---\nname: Salesforce CRM\ndescription: Work with Salesforce CRM via MCP tools and resources\n---\n\n<required>\n1. Install FastMCP skill server in Claude Desktop\n2. Configure SALESFORCE_TOKEN environment variable\n3. Use tools: search_contacts, get_contact\n4. Use resources: crm://contacts/{id}\n</required>\n```\n\n## Reference Pattern\n\nWhen creating-skills needs MCP implementation, it should reference this skill:\n\n```markdown\n# In creating-skills SKILL.md\nFor MCP server implementation, follow patterns from FastMCP skill:\n- Tools: /home/elvis/.claude/skills/fastmcp/SKILL.md#tools\n- Resources: /home/elvis/.claude/skills/fastmcp/SKILL.md#resources\n- Authentication: /home/elvis/.claude/skills/fastmcp/SKILL.md#authentication\n```\n\n---\n\n# Complete Examples\n\n## Example 1: Database Integration Server (Python)\n\n```python\nfrom fastmcp import FastMCP, Context, ToolError\nfrom fastmcp.auth import GoogleOAuth\nimport asyncpg\nimport os\n\nmcp = FastMCP(\n    \"Database Server\",\n    auth=GoogleOAuth(\n        client_id=os.getenv(\"GOOGLE_CLIENT_ID\"),\n        client_secret=os.getenv(\"GOOGLE_CLIENT_SECRET\")\n    )\n)\n\nasync def get_db_pool():\n    \"\"\"Dependency: Database connection pool\"\"\"\n    return await asyncpg.create_pool(os.getenv(\"DATABASE_URL\"))\n\n@mcp.tool(\n    description=\"Execute read-only SQL queries\",\n    annotations={\"readOnlyHint\": True}\n)\nasync def query(sql: str, ctx: Context) -> list[dict]:\n    \"\"\"Execute SELECT queries with security validation\"\"\"\n    # Validate SQL\n    sql_upper = sql.upper().strip()\n    if not sql_upper.startswith(\"SELECT\"):\n        raise ToolError(\"Only SELECT queries allowed\")\n\n    if any(keyword in sql_upper for keyword in [\"DROP\", \"DELETE\", \"UPDATE\", \"INSERT\"]):\n        raise ToolError(\"Destructive SQL not allowed\")\n\n    await ctx.info(f\"Executing query: {sql[:50]}...\")\n\n    # Execute with connection pool\n    pool = await get_db_pool()\n    try:\n        async with pool.acquire() as conn:\n            rows = await conn.fetch(sql)\n            return [dict(row) for row in rows]\n    except Exception as e:\n        await ctx.error(f\"Query failed: {str(e)}\")\n        raise ToolError(f\"Query execution failed: {str(e)}\")\n\n@mcp.resource(\"db://tables\")\nasync def list_tables(ctx: Context) -> str:\n    \"\"\"List all database tables\"\"\"\n    pool = await get_db_pool()\n    async with pool.acquire() as conn:\n        rows = await conn.fetch(\"\"\"\n            SELECT table_name\n            FROM information_schema.tables\n            WHERE table_schema = ''public''\n            ORDER BY table_name\n        \"\"\")\n        tables = [row[\"table_name\"] for row in rows]\n        return json.dumps({\"tables\": tables})\n\n@mcp.resource(\"db://tables/{table_name}/schema\")\nasync def get_schema(table_name: str, ctx: Context) -> str:\n    \"\"\"Get table schema information\"\"\"\n    # Prevent SQL injection in table name\n    if not table_name.replace(\"_\", \"\").isalnum():\n        raise ResourceError(\"Invalid table name\")\n\n    pool = await get_db_pool()\n    async with pool.acquire() as conn:\n        rows = await conn.fetch(\"\"\"\n            SELECT column_name, data_type, is_nullable\n            FROM information_schema.columns\n            WHERE table_name = $1\n            ORDER BY ordinal_position\n        \"\"\", table_name)\n\n        schema = [\n            {\n                \"column\": row[\"column_name\"],\n                \"type\": row[\"data_type\"],\n                \"nullable\": row[\"is_nullable\"] == \"YES\"\n            }\n            for row in rows\n        ]\n        return json.dumps({\"table\": table_name, \"schema\": schema})\n\nif __name__ == \"__main__\":\n    mcp.run()\n```\n\n## Example 2: File System Server (TypeScript)\n\n```typescript\nimport { FastMCP, Context, ToolError, ResourceError } from \"@fastmcp/server\";\nimport { GoogleOAuth } from \"@fastmcp/auth\";\nimport * as fs from \"fs/promises\";\nimport * as path from \"path\";\n\nconst ALLOWED_BASE = process.env.ALLOWED_DIR || \"/home/user/documents\";\n\nconst mcp = new FastMCP({\n  name: \"File System Server\",\n  auth: new GoogleOAuth({\n    clientId: process.env.GOOGLE_CLIENT_ID!,\n    clientSecret: process.env.GOOGLE_CLIENT_SECRET!\n  })\n});\n\n// Tool: List directory\nmcp.tool({\n  name: \"list_directory\",\n  description: \"List files and directories\",\n  parameters: {\n    path: { type: \"string\", description: \"Directory path\", default: \".\" }\n  },\n  execute: async ({ path: dirPath }, ctx) => {\n    const fullPath = path.resolve(ALLOWED_BASE, dirPath);\n\n    // Security: Prevent directory traversal\n    if (!fullPath.startsWith(ALLOWED_BASE)) {\n      throw new ToolError(\"Access denied\");\n    }\n\n    await ctx.info(`Listing directory: ${dirPath}`);\n\n    const entries = await fs.readdir(fullPath, { withFileTypes: true });\n\n    return {\n      path: dirPath,\n      entries: entries.map(e => ({\n        name: e.name,\n        type: e.isDirectory() ? \"directory\" : \"file\"\n      }))\n    };\n  }\n});\n\n// Tool: Search files\nmcp.tool({\n  name: \"search_files\",\n  description: \"Search for files by name pattern\",\n  parameters: {\n    pattern: { type: \"string\", description: \"Glob pattern (e.g., *.txt)\" },\n    directory: { type: \"string\", default: \".\", description: \"Directory to search\" }\n  },\n  execute: async ({ pattern, directory }, ctx) => {\n    await ctx.info(`Searching for ${pattern} in ${directory}`);\n\n    const fullPath = path.resolve(ALLOWED_BASE, directory);\n\n    if (!fullPath.startsWith(ALLOWED_BASE)) {\n      throw new ToolError(\"Access denied\");\n    }\n\n    const results = await searchFiles(fullPath, pattern);\n\n    return {\n      pattern,\n      directory,\n      matches: results.length,\n      files: results\n    };\n  }\n});\n\n// Resource: Read file contents\nmcp.resource({\n  uri: \"file://{filepath*}\",\n  name: \"File Content\",\n  description: \"Read file contents\",\n  read: async ({ filepath }, ctx) => {\n    const fullPath = path.resolve(ALLOWED_BASE, filepath);\n\n    // Security validation\n    if (!fullPath.startsWith(ALLOWED_BASE)) {\n      throw new ResourceError(\"Access denied\");\n    }\n\n    try {\n      await ctx.info(`Reading file: ${filepath}`);\n      const content = await fs.readFile(fullPath, \"utf-8\");\n      return content;\n    } catch (e) {\n      throw new ResourceError(`Failed to read file: ${e.message}`);\n    }\n  }\n});\n\n// Prompt: File analysis workflow\nmcp.prompt({\n  name: \"analyze_file\",\n  description: \"Analyze file content and generate report\",\n  parameters: {\n    filepath: { type: \"string\", description: \"Path to file\" }\n  },\n  execute: async ({ filepath }) => {\n    return {\n      messages: [\n        {\n          role: \"user\",\n          content: `Analyze the file at ${filepath} and provide:`\n        },\n        {\n          role: \"user\",\n          content: `1. File size and format\\n2. Content summary\\n3. Key findings\\n4. Recommendations`\n        }\n      ]\n    };\n  }\n});\n\nmcp.run();\n```\n\n---\n\n# Templates\n\n## Basic Tool Template (Python)\n\n```python\nfrom fastmcp import FastMCP, Context, ToolError\n\n@mcp.tool(\n    description=\"[What this tool does]\",\n    annotations={\"readOnlyHint\": True}  # or destructiveHint, etc.\n)\nasync def tool_name(\n    param1: str,  # Required parameter\n    param2: int = 10,  # Optional with default\n    ctx: Context = None  # Context injection\n) -> dict:\n    \"\"\"[Detailed docstring for LLM]\"\"\"\n    try:\n        # 1. Validate inputs\n        if not param1:\n            raise ToolError(\"param1 is required\")\n\n        # 2. Log operation\n        await ctx.info(f\"Processing: {param1}\")\n\n        # 3. Report progress for long operations\n        await ctx.report_progress(50, 100)\n\n        # 4. Execute logic\n        result = do_something(param1, param2)\n\n        # 5. Return structured data\n        return {\"result\": result, \"param1\": param1}\n\n    except Exception as e:\n        await ctx.error(f\"Tool failed: {str(e)}\")\n        raise ToolError(f\"Operation failed: {str(e)}\")\n```\n\n## Basic Resource Template (Python)\n\n```python\nfrom fastmcp import ResourceError\n\n@mcp.resource(\"namespace://{param}/path\")\nasync def resource_name(param: str, ctx: Context) -> str:\n    \"\"\"[Docstring describing what data this returns]\"\"\"\n    try:\n        # 1. Validate parameters\n        if not is_valid(param):\n            raise ResourceError(f\"Invalid parameter: {param}\")\n\n        # 2. Security checks\n        if not has_permission(param):\n            raise ResourceError(\"Access denied\")\n\n        # 3. Fetch data\n        data = fetch_data(param)\n\n        # 4. Return as string (JSON for structured data)\n        return json.dumps(data)\n\n    except Exception as e:\n        raise ResourceError(f\"Failed to fetch data: {str(e)}\")\n```\n\n## Production Server Template (Python)\n\n```python\n#!/usr/bin/env python3\nfrom fastmcp import FastMCP, Context, ToolError\nfrom fastmcp.auth import GoogleOAuth\nimport logging\nimport os\n\n# Configure logging\nlogging.basicConfig(level=logging.INFO)\nlogger = logging.getLogger(__name__)\n\n# Create secure server\nmcp = FastMCP(\n    name=os.getenv(\"SERVER_NAME\", \"Production Server\"),\n    auth=GoogleOAuth(\n        client_id=os.getenv(\"GOOGLE_CLIENT_ID\"),\n        client_secret=os.getenv(\"GOOGLE_CLIENT_SECRET\")\n    ),\n    mask_error_details=True,\n    rate_limit={\"requests_per_minute\": int(os.getenv(\"RATE_LIMIT\", \"100\"))},\n)\n\n# Add your tools, resources, prompts here\n\nif __name__ == \"__main__\":\n    port = int(os.getenv(\"PORT\", \"8443\"))\n    transport = os.getenv(\"TRANSPORT\", \"http\")\n\n    logger.info(f\"Starting server on {transport}:{port}\")\n\n    mcp.run(\n        transport=transport,\n        host=\"0.0.0.0\",\n        port=port,\n        ssl_certfile=os.getenv(\"SSL_CERT\"),\n        ssl_keyfile=os.getenv(\"SSL_KEY\")\n    )\n```\n\n---\n\n# References\n\n## Official Documentation\n\n- [FastMCP Documentation](https://gofastmcp.com) - Complete guides and API reference\n- [FastMCP GitHub](https://github.com/jlowin/fastmcp) - Source code and examples\n- [Model Context Protocol Specification](https://modelcontextprotocol.io/specification/2025-11-25) - Official MCP spec\n\n## Integration Guides\n\n- [Claude Desktop Integration](https://gofastmcp.com/integrations/claude-desktop) - Integration guide\n- [FastMCP Cloud](https://fastmcp.cloud) - One-click deployment platform\n\n## Community\n\n- [FastMCP Discord](https://discord.gg/uu8dJCgttd) - Active support and discussions\n- [MCP Servers Repository](https://github.com/modelcontextprotocol/servers) - Example servers\n\n## Learning Resources\n\n- [Building MCP Servers with FastMCP - DataCamp](https://www.datacamp.com/tutorial/building-mcp-server-client-fastmcp)\n- [FastMCP Tutorial - MCPcat](https://mcpcat.io/guides/building-mcp-server-python-fastmcp/)\n\n---\n\n# Version Compatibility\n\n| Component | Minimum Version | Recommended |\n|-----------|----------------|-------------|\n| **Python** | 3.8+ | 3.11+ |\n| **Node.js** | 16+ | 20+ (LTS) |\n| **FastMCP (Python)** | 2.11.0 | 2.11.x (stable) |\n| **FastMCP (TypeScript)** | 2.0.0 | 2.x (stable) |\n| **uv** | 0.1.0+ | Latest |\n| **Claude Desktop** | Any | Latest |\n\n**Production Recommendation**: Pin FastMCP to specific minor version (e.g., `fastmcp~=2.11.0`) to avoid breaking changes.\n\n---\n\n# Skill Metadata\n\n**Created**: January 2026\n**FastMCP Version**: v2.11.0 / v3.0.0-beta\n**Languages**: Python, TypeScript\n**Integration**: Claude Desktop, FastMCP Cloud\n**Status**: Production Ready\n"},"lastSynced":"2026-03-08T02:01:08.593Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced AI Agents like AutoGPT and LangChain requiring customized MCP server integration with external systems via the UniFi API.","zh":"适用于像 AutoGPT 和 LangChain 这样的高级 AI Agent，需要自定义 MCP 服务器与外部系统通过 UniFi API 集成。","ja":"AutoGPTやLangChainのような高度なAIエージェントに適しています。MCPサーバーを外部システムとUniFi API経由でカスタマイズして統合する必要があります。","ko":"AutoGPT와 LangChain 같은 고급 AI 에이전트에 적합하며, UniFi API를 통해 외부 시스템과 MCP 서버를 사용자 지정하여 통합해야 합니다.","es":"Ideal para Agentes de IA Avanzados como AutoGPT y LangChain que requieren una integración personalizada del servidor MCP con sistemas externos a través de la API de UniFi.","fr":"Idéal pour les agents d''IA avancés comme AutoGPT et LangChain nécessitant une intégration personnalisée du serveur MCP avec des systèmes externes via l''API UniFi.","de":"Ideal für erweiterte KI-Agents wie AutoGPT und LangChain, die eine benutzerdefinierte MCP-Server-Integration mit externen Systemen über die UniFi-API erfordern.","pt":"Ideal para Agentes de IA Avançados como AutoGPT e LangChain que exigem integração personalizada do servidor MCP com sistemas externos via a UniFi API.","ru":"Идеально подходит для продвинутых агентов ИИ, таких как AutoGPT и LangChain, требующих настраиваемой интеграции сервера MCP с внешними системами через UniFi API.","ar":"مثالي للوكلاء الذكية المتقدمة مثل AutoGPT و LangChain التي تتطلب تكامل خادم MCP مخصص مع الأنظمة الخارجية من خلال واجهة برمجة تطبيقات UniFi API."},"recommendation":{"en":"Empowers agents to leverage the official UniFi API for seamless integration with external systems, enabling the creation of custom MCP servers with Python or TypeScript, and implementing tools for LLM-executable functions with type hints and annotations.","zh":"赋予代理使用官方 UniFi API 与外部系统实现无缝集成的能力，能够使用 Python 或 TypeScript 创建自定义的 MCP 服务器，并实现带有类型提示和注释的 LLM 可执行函数。","ja":"エージェントが公式のUniFi APIを使用して外部システムとシームレスに統合できる機能を提供します。PythonまたはTypeScriptを使用してカスタムのMCPサーバーを作成し、型ヒントと注釈を付けたLLM実行可能な関数を実装できます。","ko":"에이전트가 공식 UniFi API를 사용하여 외부 시스템과 무縫으로 통합할 수 있는 기능을 제공하여, Python 또는 TypeScript를 사용하여 사용자 지정 MCP 서버를 만들고, 타입 힌트와 주석이 있는 LLM 실행 가능한 함수를 구현할 수 있습니다.","es":"Habilita a los agentes a aprovechar la API oficial de UniFi para una integración perfecta con sistemas externos, lo que permite la creación de servidores MCP personalizados con Python o TypeScript, y la implementación de herramientas para funciones ejecutables de LLM con indicaciones de tipo y anotaciones.","fr":"Permet aux agents d''utiliser l''API officielle UniFi pour une intégration transparente avec des systèmes externes, ce qui permet de créer des serveurs MCP personnalisés avec Python ou TypeScript, et de mettre en œuvre des outils pour des fonctions exécutables LLM avec des repères de type et des annotations.","de":"Ermöglicht es Agents, die offizielle UniFi-API für eine nahtlose Integration mit externen Systemen zu nutzen, wodurch die Erstellung von benutzerdefinierten MCP-Servern mit Python oder TypeScript ermöglicht wird und Werkzeuge für LLM-ausführbare Funktionen mit Typ-Hinweisen und Annotationen implementiert werden.","pt":"Habilita os agentes a aproveitar a UniFi API oficial para integração sem interrupções com sistemas externos, permitindo a criação de servidores MCP personalizados com Python ou TypeScript e implementando ferramentas para funções executáveis LLM com dicas de tipo e anotações.","ru":"Наделяет агентов возможностью использовать официальный UniFi API для бесшовной интеграции с внешними системами, что позволяет создавать настраиваемые серверы MCP с помощью Python или TypeScript и реализовывать инструменты для функций LLM с подсказками типов и аннотациями.","ar":"تمكن الوكلاء من استخدام واجهة برمجة تطبيقات UniFi API الرسمية لتكامل بدون انقطاع مع الأنظمة الخارجية، مما يسمح بإنشاء خوادم MCP مخصصة باستخدام Python أو TypeScript وتنفيذ أدوات لتشغيل وظائف LLM مع تلميحات النوع والتعليقات."},"useCases":{"en":["Developing custom MCP servers with integrated UniFi API functionality","Implementing LLM-executable functions for advanced system automation","Integrating external systems with MCP servers using Python or TypeScript"],"zh":["开发集成了 UniFi API 功能的自定义 MCP 服务器","实现高级系统自动化的 LLM 可执行函数","使用 Python 或 TypeScript 将外部系统与 MCP 服务器集成"],"ja":["UniFi API機能を統合したカスタムMCPサーバーの開発","高度なシステム自動化のためのLLM実行可能な関数の実装","PythonまたはTypeScriptを使用した外部システムとMCPサーバーの統合"],"ko":["UniFi API 기능을 통합한 사용자 지정 MCP 서버 개발","고급 시스템 자동화를 위한 LLM 실행 가능한 함수 구현","Python 또는 TypeScript를 사용하여 외부 시스템과 MCP 서버 통합"],"es":["Desarrollar servidores MCP personalizados con funcionalidad de API de UniFi integrada","Implementar funciones ejecutables de LLM para una automatización avanzada del sistema","Integrar sistemas externos con servidores MCP utilizando Python o TypeScript"],"fr":["Développer des serveurs MCP personnalisés avec une fonctionnalité API UniFi intégrée","Mettre en œuvre des fonctions exécutables LLM pour une automatisation avancée du système","Intégrer des systèmes externes avec des serveurs MCP en utilisant Python ou TypeScript"],"de":["Entwicklung von benutzerdefinierten MCP-Servern mit integrierter UniFi-API-Funktionalität","Implementierung von LLM-ausführbaren Funktionen für eine erweiterte Systemautomatisierung","Integration externer Systeme mit MCP-Servern unter Verwendung von Python oder TypeScript"],"pt":["Desenvolver servidores MCP personalizados com funcionalidade da UniFi API integrada","Implementar funções executáveis LLM para automação avançada de sistemas","Integrar sistemas externos com servidores MCP usando Python ou TypeScript"],"ru":["Разработка настраиваемых серверов MCP с интегрированной функциональностью UniFi API","Реализация функций LLM для продвинутой автоматизации систем","Интеграция внешних систем с серверами MCP с помощью Python или TypeScript"],"ar":["تطوير خوادم MCP مخصصة مع وظيفة واجهة برمجة تطبيقات UniFi API المتكاملة","تنفيذ وظائف LLM القابلة للتشغيل لتأتمتة الأنظمة المتقدمة","دمج الأنظمة الخارجية مع خوادم MCP باستخدام Python أو TypeScript"]},"limitations":{"en":["Requires UniFi API access and knowledge of Python or TypeScript","Limited to developers familiar with MCP server development and external system integration"],"zh":["需要 UniFi API 访问权限和 Python 或 TypeScript 的知识","仅限于熟悉 MCP 服务器开发和外部系统集成的开发人员"],"ja":["UniFi APIへのアクセスとPythonまたはTypeScriptの知識が必要","MCPサーバーの開発と外部システムの統合に精通した開発者に限定される"],"ko":["UniFi API 접근 권한과 Python 또는 TypeScript에 대한 지식이 필요","MCP 서버 개발 및 외부 시스템 통합에 익숙한 개발자에게만 제한"],"es":["Requiere acceso a la API de UniFi y conocimiento de Python o TypeScript","Limitado a desarrolladores familiarizados con el desarrollo de servidores MCP y la integración de sistemas externos"],"fr":["Nécessite un accès à l''API UniFi et des connaissances en Python ou TypeScript","Limité aux développeurs familiarisés avec le développement de serveurs MCP et l''intégration de systèmes externes"],"de":["Erfordert Zugriff auf die UniFi-API und Kenntnisse in Python oder TypeScript","Begrenzt auf Entwickler, die mit der Entwicklung von MCP-Servern und der Integration externer Systeme vertraut sind"],"pt":["Exige acesso à UniFi API e conhecimento de Python ou TypeScript","Limitado a desenvolvedores familiarizados com o desenvolvimento de servidores MCP e integração de sistemas externos"],"ru":["Требует доступа к UniFi API и знания Python или TypeScript","Ограничен для разработчиков, знакомых с разработкой серверов MCP и интеграцией внешних систем"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات UniFi API ومعرفة Python أو TypeScript","محدود للمطورين المamiliarين بتطوير خوادم MCP ودمج الأنظمة الخارجية"]},"version":4},"contentHash":"329472f8b32978eda354bc40a7d92fd7c698c31908ddc45810ccbca4f6d4ab07","qualityScore":60}');
