INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('enuno/unifi-mcp-server/FastMCP Development', 'FastMCP Development', 'enuno', 'unifi-mcp-server', 'community', 'FastMCP Development enuno unifi-mcp-server community FastMCP Development is an MCP server that leverages the official UniFi API, providing functionality for developers to integrate with external systems. It benefits developers who need to create custom MCP servers. FastMCP开发是一个利用官方UniFi API的MCP服务器，提供快速和可靠的开发环境 FastMCP開発は、Official UniFi APIを利用したMCPサーバーであり、迅速で信頼性の高い開発環境を提供する FastMCP 개발은 공식 UniFi API를 활용한 MCP 서버로 빠르고 안정적인 개발 환경을 제공합니다 FastMCP Development es un servidor MCP que utiliza la API oficial de UniFi para proporcionar funcionalidades de integración con sistemas externos FastMCP Development est un serveur MCP qui utilise l''API officielle UniFi pour fournir des fonctionnalités d''intégration avec des systèmes externes FastMCP Development ist ein MCP-Server, der die offizielle UniFi-API verwendet, um Funktionalitäten für die Integration mit externen Systemen bereitzustellen O FastMCP Development é um servidor MCP que utiliza a UniFi API oficial para fornecer funcionalidades personalizadas e integração com sistemas externos FastMCP Development - это сервер MCP, использующий официальный UniFi API для предоставления индивидуальных функций и интеграции с внешними системами FastMCP Development هو خادم MCP يستخدم واجهة برمجة UniFi لتقديم وظائف مخصصة ودمجها مع الأنظمة الخارجية FastMCP Development setup guide how to use UniFi API with FastMCP FastMCP Development vs other MCP servers install FastMCP Development what is FastMCP Development FastMCP Development alternative UniFi API integration with FastMCP FastMCP Development tutorial FastMCP Development documentation FastMCP开发 UniFi API MCP服务器 Python开发 TypeScript开发 LLM-executable函数 快速开发环境 AIエージェント开发 Creates FastMCP server files with basic structure using Quick Start template Supports implementation of tools for LLM-executable functions Allows determination of server purpose and required components using TodoWrite Integrates with external systems using the official UniFi API Supports development in Python or TypeScript based on project requirements Includes type hints and annotations for LLM-executable functions FastMCP Development is a development framework for creating MCP servers using the UniFi API, allowing for custom integration and functionality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('manutej/categorical-meta-prompting/meta-self', 'community', 'manutej', 'categorical-meta-prompting', 'manutej/categorical-meta-prompting', 'meta-self', 0, 0, 60, '2026-03-08T01:57:15.294Z', '2026-03-08T02:01:09.035Z', '1f98417c0054c7606924c734d6cdd8587a9fe3c042fd368b7c03bb0ec3947ebe', '{"id":"manutej/categorical-meta-prompting/meta-self","name":"meta-self","description":{"en":"meta-self provides categorical foundations for AI meta-prompting, ensuring proven correctness and measurable quality improvements. It benefits developers seeking a unified syntax reference for AI agents.","zh":"meta-self是AI元提示框架的权威参考，提供了分类基础和测量质量改进的方法","ja":"meta-selfはAIエージェントのプロンプティングフレームワークの権威ある参考であり、カテゴリ的基礎と測定可能な品質改善の方法を提供する","ko":"meta-self는 AI 프롬프트링 프레임워크의 권위적인 참조이며, 분류적 기초와 측정 가능한 품질 개선 방법을 제공합니다","es":"Meta-Self es un marco de referencia catégorial para el prompts de meta de IA, que proporciona una base sólida para la creación de agentes de inteligencia artificial con comprobada corrección y mejoras de calidad medibles.","fr":"Meta-Self est un référentiel catégoriel pour les prompts de métadonnées d''IA, qui fournit une base solide pour la création d''outils d''intelligence artificielle avec correction prouvée et améliorations de qualité mesurables.","de":"Meta-Self ist ein kategoriales Referenzframework für Meta-Prompts von KI, das eine solide Grundlage für die Erstellung von KI-Tools mit nachgewiesener Korrektheit und messbaren Qualitätsverbesserungen bietet.","pt":"O Meta-Self é um framework de prompts de IA que utiliza funtores, monads e comonads para melhorar a qualidade dos prompts","ru":"Meta-Self - это фреймворк для промтов ИИ, использующий функторы, монады и комонады для улучшения качества промтов","ar":"متا-سيلف هو إطار عمل لتلميحات الذكاء الاصطناعي الذي يستخدم الفنكторات والمناد والكوموناد لتحسين جودة التلميحات"},"seo":{"title":{"en":"meta-self: Unified Categorical Syntax Reference for AI Ag...","zh":"meta-self Setup Guide: AI Prompting Framework","ja":"meta-self ベストプラクティス: AIエージェントのプロンプティングフレームワーク","ko":"meta-self 개발자 가이드: AI 프롬프트링 프레임워크","es":"Guía de Configuración de Meta-Self: Categorical Foundatio...","fr":"Guide de Mise en Place de Meta-Self: Fondements Catégorie...","de":"Einrichtungsleitfaden für Meta-Self: Kategoriale Grundlag...","pt":"Guia de Configuração do Meta-Self para Desenvolvedores","ru":"Настройка Meta-Self: Руководство для Разработчиков ИИ Аге...","ar":"دليل إعداد متا-سيلف لتنمية أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of AI meta-prompting with meta-self. Discover how to align commands and skills with this authoritative reference and improve qualit...","zh":"了解meta-self的技术细节和应用，实现AI提示框架的正确性和质量改进","ja":"meta-selfの技術的詳細と応用について学び、AIエージェントのプロンプティングフレームワークの正しさと品質の向上を実現する","ko":"meta-self의 기술적 세부 사항과 적용을 학습하고 AI 프롬프트링 프레임워크의 올바름과 품질 개선을 실현하세요","es":"Aprende a configurar Meta-Self, un marco de referencia catégorial para el prompts de meta de IA con comprobada corrección y mejoras de calidad medibles","fr":"Découvrez comment configurer Meta-Self, un référentiel catégoriel pour les prompts de métadonnées d''IA avec correction prouvée et améliorations de qualité me...","de":"Erfahren Sie, wie Sie Meta-Self einrichten, ein kategoriales Referenzframework für Meta-Prompts von KI mit nachgewiesener Korrektheit und messbaren Qualitäts...","pt":"Aprenda a configurar o Meta-Self para melhorar a qualidade dos prompts de IA com base em funtores, monads e comonads","ru":"Узнайте, как настроить Meta-Self для улучшения качества промтов ИИ с помощью функторов, монад и комонад","ar":"تعرف على كيفية إعداد متا-سيلف لتحسين جودة تلميحات الذكاء الاصطناعي باستخدام الفنكторات والمناد والكوموناد"},"definition":{"en":"meta-self is a categorical meta-prompting framework providing a structured approach to AI agent development using functors, monads, and comonads.","zh":"meta-self是AI元提示框架的分类基础，提供了结构保持变换、迭代改进和上下文提取的方法","ja":"meta-selfはAIエージェントのプロンプティングフレームワークのカテゴリ的基礎であり、構造保持変換、反復改善と文脈抽出の方法を提供する","ko":"meta-self는 AI 프롬프트링 프레임워크의 분류적 기초로서, 구조 보존 변환, 반복적 개선 및 문脈 추출 방법을 제공합니다","es":"Meta-Self es un marco de referencia catégorial para la creación de agentes de inteligencia artificial","fr":"Meta-Self est un référentiel catégoriel pour la création d''outils d''intelligence artificielle","de":"Meta-Self ist ein kategoriales Referenzframework für die Erstellung von KI-Tools","pt":"O que é Meta-Self? É um framework de prompts de IA baseado em funtores, monads e comonads","ru":"Что такое Meta-Self? Это фреймворк для промтов ИИ, основанный на функторах, монадах и комонадах","ar":"ما هو متا-سيلف? هو إطار عمل لتلميحات الذكاء الاصطناعي 기반 على الفنكторات والمناد والكوموناد"},"features":{"en":["Implements functor-based structure-preserving transformations (F: Task → Prompt)","Supports monad-based iterative refinement (M: Prompt →^n Prompt)","Utilizes comonad-based context extraction (W: History → Context)","Enables natural transformation-based strategy switching (α: F ⇒ G)","Provides a unified categorical syntax reference for AI meta-prompting"],"zh":["Functor（函数子）- 结构保持变换","Monad（单子）- 迭代改进","Comonad（共单子）- 上下文提取","Natural Transformation（自然变换）- 策略切换","测量质量改进的方法"],"ja":["Functor（ファンクタ）- 構造保持変換","Monad（モナド）- 反復改善","Comonad（コモナド）- 文脈抽出","Natural Transformation（自然変換）- 戦略切り替え","測定可能な品質改善の方法"],"ko":["Functor（함수자）- 구조 보존 변환","Monad（모나드）- 반복적 개선","Comonad（공모나드）- 문脈 추출","Natural Transformation（자연 변환）- 전략 교체","측정 가능한 품질 개선 방법"],"es":["Functor para transformaciones de estructura","Monad para refinamiento iterativo","Comonad para extracción de contexto","Transformación natural para conmutación de estrategias","Soporte para comprobada corrección y mejoras de calidad medibles"],"fr":["Functor pour les transformations de structure","Monad pour l''affinement itératif","Comonad pour l''extraction de contexte","Transformation naturelle pour la commutation de stratégies","Prise en charge de la correction prouvée et des améliorations de qualité mesurables"],"de":["Functor für Strukturtransformationen","Monad für iteratives Verfeinern","Comonad für Kontextextraktion","Natürliche Transformation für Strategiewechsel","Unterstützung für nachgewiesene Korrektheit und messbare Qualitätsverbesserungen"],"pt":["Utiliza funtores para transformações de estrutura","Emprega monads para refinamento iterativo","Utiliza comonads para extração de contexto","Suporta transformações naturais para mudanças de estratégia","Melhora a qualidade dos prompts com base em provas de correção"],"ru":["Использует функторы для трансформаций структуры","Применяет монады для итеративного уточнения","Использует комонады для извлечения контекста","Поддерживает естественные трансформации для смены стратегии","Улучшает качество промтов на основе доказательств корректности"],"ar":["يستخدم الفنكторات لتحويل الهياكل","يستخدم المناد لتحسين التكراري","يستخدم الكوموناد لاستخراج السياق","يدعم التحويلات الطبيعية لتغيير الاستراتيجية","يحسن جودة التلميحات بناءً على براهين الصحة"]},"keywords":{"en":["how to use meta-self","meta-self alternative","meta-self setup guide","what is meta-self","meta-self vs other AI frameworks","meta-self install for AI agents","categorical meta-prompting with meta-self","functor-based AI development","monad-based iterative refinement in AI"],"zh":["AI提示框架","元提示","分类基础","结构保持变换","迭代改进","上下文提取","自然变换","测量质量改进"],"ja":["AIエージェント","プロンプティングフレームワーク","カテゴリ的基礎","ファンクタ","モナド","コモナド","自然変換","測定可能な品質改善"],"ko":["AI 프롬프트링","프롬프트링 프레임워크","분류적 기초","함수자","모나드","공모나드","자연 변환","측정 가능한 품질 개선"],"es":["Agentes de Inteligencia Artificial","Meta-Self","Categorical Foundations","Functor","Monad","Comonad","Transformación natural","IA","Inteligencia Artificial"],"fr":["Outils d''Intelligence Artificielle","Meta-Self","Fondements Catégoriels","Functor","Monad","Comonad","Transformation naturelle","IA","Intelligence Artificielle"],"de":["KI-Tools","Meta-Self","Kategoriale Grundlagen","Functor","Monad","Comonad","Natürliche Transformation","KI","Künstliche Intelligenz"],"pt":["Meta-Self","IA","funtores","monads","comonads","transformações naturais","desenvolvimento de IA","framework de prompts de IA"],"ru":["Meta-Self","ИИ","функторы","монады","комонады","естественные трансформации","разработка ИИ","фреймворк для промтов ИИ"],"ar":["متا-سيلف","الذكاء الاصطناعي","الفنكторات","المناد","الكوموناد","التحويلات الطبيعية","تنمية الذكاء الاصطناعي","إطار عمل لتلميحات الذكاء الاصطناعي"]}},"owner":"manutej","repo":"categorical-meta-prompting","repoPath":"manutej/categorical-meta-prompting","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.294Z","topics":[],"category":"community","skillMd":{"name":"meta-self","description":"Master reference for categorical meta-prompting unified syntax. Contains all modifiers, operators, composition patterns, and execution protocols. Use this skill for self-reference when executing any prompt workflow, ensuring consistent syntax across all commands and skills.","bodyPreview":"# Meta-Self: Unified Categorical Syntax Reference\n\nThis skill serves as the authoritative reference for the categorical meta-prompting framework. All commands and skills should align with this specification.\n\n## Categorical Foundation\n\n```\nF: Task → Prompt        (Functor - structure-preserving transformation)\nM: Prompt →^n Prompt    (Monad - iterative refinement)\nW: History → Context    (Comonad - context extraction)\nα: F ⇒ G                (Natural Transformation - strategy switching)\nE: Eithe","body":"# Meta-Self: Unified Categorical Syntax Reference\n\nThis skill serves as the authoritative reference for the categorical meta-prompting framework. All commands and skills should align with this specification.\n\n## Categorical Foundation\n\n```\nF: Task → Prompt        (Functor - structure-preserving transformation)\nM: Prompt →^n Prompt    (Monad - iterative refinement)\nW: History → Context    (Comonad - context extraction)\nα: F ⇒ G                (Natural Transformation - strategy switching)\nE: Either Error A       (Exception Monad - error handling)\n[0,1]: Quality → Quality (Enriched - quality tracking)\n```\n\n### Categorical Laws (Must Be Satisfied)\n\n```\n1. Functor Identity:     F(id) = id\n2. Functor Composition:  F(g ∘ f) = F(g) ∘ F(f)\n3. Monad Left Identity:  return >=> f = f\n4. Monad Right Identity: f >=> return = f\n5. Monad Associativity:  (f >=> g) >=> h = f >=> (g >=> h)\n6. Comonad Left Id:      extract ∘ duplicate = id\n7. Comonad Associativity: duplicate ∘ duplicate = fmap duplicate ∘ duplicate\n8. Naturality Condition: α_B ∘ F(f) = G(f) ∘ α_A  for all f: A → B\n9. Exception Catch Id:   catch(Right(a), h) = Right(a)  (Phase 3)\n10. Exception Catch Err: catch(Left(e), h) = h(e)       (Phase 3)\n11. Exception Assoc:     Error handling preserves Kleisli associativity\n12. Quality Monotonicity: quality(A ⊗ B) ≤ min(quality(A), quality(B))\n```\n\n### Exception Monad E (Phase 3)\n\n**Type**: `Either<Error, A> = Left(Error) | Right(A)`\n\n**Operations**:\n1. **return**: `a → Right(a)` (pure success)\n2. **bind (>=>)**: Error-propagating composition\n   ```\n   m >>= f = case m of\n     Left(e) → Left(e)        -- error propagates\n     Right(a) → f(a)          -- continue on success\n   ```\n3. **catch**: Error recovery\n   ```\n   catch(m, handler) = case m of\n     Left(e) → handler(e)     -- recover from error\n     Right(a) → Right(a)      -- pass through success\n   ```\n\n**Laws**:\n- **Left Identity**: `return(a) >>= f = f(a)`\n- **Right Identity**: `m >>= return = m`\n- **Associativity**: `(m >>= f) >>= g = m >>= (λx. f(x) >>= g)`\n- **Catch Identity**: `catch(Right(a), h) = Right(a)`\n- **Catch Error**: `catch(Left(e), h) = h(e)`\n- **Catch Composition**: `catch(catch(m, h1), h2) = catch(m, λe. catch(h1(e), h2))`\n\n**In Framework**:\n- Used by `@catch:` modifier for error handling behaviors\n- Used by `@fallback:` modifier for recovery strategies\n- Integrates with `/chain` and `/rmp` commands\n- Preserves composition with existing operators (→, ||, >=>)\n\n---\n\n## Unified Modifiers\n\nAll commands support these modifiers. Place them before the task description.\n\n### @mode: - Execution Mode\n\n| Mode | Description | Effect |\n|------|-------------|--------|\n| `@mode:active` | Default execution | Execute with auto-detection |\n| `@mode:iterative` | RMP loop | Iterate until @quality: met |\n| `@mode:dry-run` | Preview only | Show plan, no execution |\n| `@mode:spec` | Generate spec | Output YAML specification |\n\n**Example**: `/meta @mode:iterative \"build auth system\"`\n\n### @quality: - Quality Threshold\n\n| Format | Description | Range |\n|--------|-------------|-------|\n| `@quality:0.85` | Target threshold | 0.0 - 1.0 |\n| `@quality:85%` | Percentage form | 0% - 100% |\n\n**Example**: `/rmp @quality:0.9 \"optimize algorithm\"`\n\n### @tier: - Complexity Tier\n\n| Tier | Tokens | Pattern | Strategy |\n|------|--------|---------|----------|\n| `@tier:L1` | 600-1200 | Single op | DIRECT |\n| `@tier:L2` | 1500-3000 | A → B | DIRECT |\n| `@tier:L3` | 2500-4500 | A → B → C | MULTI_APPROACH |\n| `@tier:L4` | 3000-6000 | A \\|\\| B \\|\\| C | MULTI_APPROACH |\n| `@tier:L5` | 5500-9000 | Hierarchical | AUTONOMOUS_EVOLUTION |\n| `@tier:L6` | 8000-12000 | Iterative | AUTONOMOUS_EVOLUTION |\n| `@tier:L7` | 12000-22000 | Ensemble | AUTONOMOUS_EVOLUTION |\n\n**Example**: `/meta @tier:L5 \"design microservices\"`\n\n### @budget: - Token Budget\n\n| Format | Description |\n|--------|-------------|\n| `@budget:20000` | Total tokens |\n| `@budget:[5K,4K,6K]` | Per-agent allocation |\n| `@budget:auto` | Automatic calculation |\n\n**Example**: `/task-relay @budget:[5000,4000,6000] [R→D→I]`\n\n### @variance: - Budget Variance Threshold\n\n| Format | Description | Action |\n|--------|-------------|--------|\n| `@variance:15%` | Acceptable variance | WARN if exceeded |\n| `@variance:20%` | Default | HALT if exceeded |\n\n**Example**: `/hekat @budget:18K @variance:15% [R→D→I]`\n\n### @max_iterations: - Iteration Limit\n\n| Format | Description |\n|--------|-------------|\n| `@max_iterations:5` | Maximum RMP iterations |\n| `@max_iterations:3` | Fewer iterations |\n\n**Example**: `/rmp @quality:0.9 @max_iterations:3 \"task\"`\n\n### @catch: - Error Handling Behavior (Phase 3)\n\n| Format | Description | Result |\n|--------|-------------|--------|\n| `@catch:halt` | Stop chain on error (default) | Left(error) |\n| `@catch:log` | Log error, continue chain | Left(error) logged |\n| `@catch:retry:N` | Retry command N times | Right(result) or Left(error) |\n| `@catch:skip` | Skip failed command | Right(empty) |\n| `@catch:substitute:/alt` | Use alternative command | Right(alt_result) |\n\n**Example**: `/chain @catch:retry:3 [/api→/process] \"fetch data\"`\n\n### @fallback: - Error Recovery Strategy (Phase 3)\n\n| Format | Description | When Used |\n|--------|-------------|-----------|\n| `@fallback:return-best` | Return highest quality result | Iterative refinement |\n| `@fallback:return-last` | Return last successful result | Prefer recency |\n| `@fallback:use-default:[val]` | Use specific default | Known safe value |\n| `@fallback:empty` | Return empty/neutral | Minimal context |\n\n**Example**: `/rmp @fallback:return-best @quality:0.9 \"complex task\"`\n\n### @quality:visualize - Quality Flow Visualization (Phase 5)\n\n| Format | Description | Output |\n|--------|-------------|--------|\n| `@quality:visualize` | Show quality flow (default: bar chart) | Visual quality tracking |\n| `@quality:visualize:bar` | Bar chart format | ASCII bar chart |\n| `@quality:visualize:flow` | Flow diagram format | Arrows with quality values |\n| `@quality:visualize:detailed` | Detailed breakdown | Full quality metrics |\n| `@quality:visualize:compact` | Compact summary | Single-line summary |\n\n**Categorical Foundation**: Uses [0,1]-enriched category structure where `Hom_Q(A, B) = [0,1]` and quality tensor follows `q1 ⊗ q2 = min(q1, q2)`\n\n**Example**: `/chain @quality:visualize [/analyze→/design→/implement] \"build feature\"`\n\n### @template: - Template Components\n\n| Format | Description |\n|--------|-------------|\n| `@template:{context:expert}` | Single component |\n| `@template:{context:X}+{mode:Y}+{format:Z}` | Combined |\n\n**Components**:\n- `{context:expert\\|teacher\\|reviewer\\|debugger}`\n- `{mode:direct\\|cot\\|multi\\|iterative}`\n- `{format:prose\\|structured\\|code\\|checklist}`\n\n**Example**: `/meta @template:{context:expert}+{mode:cot}+{format:code} \"implement\"`\n\n### @domain: - Force Domain Classification\n\n| Domain | Use Case |\n|--------|----------|\n| `@domain:ALGORITHM` | Algorithmic correctness |\n| `@domain:SECURITY` | Security review |\n| `@domain:API` | API design/review |\n| `@domain:DEBUG` | Debugging |\n| `@domain:TESTING` | Test generation |\n\n**Example**: `/meta @domain:SECURITY \"review auth code\"`\n\n### @skills: - Skill Discovery & Composition\n\n| Format | Description |\n|--------|-------------|\n| `@skills:discover(domain=X)` | Discover by domain |\n| `@skills:discover(relevance>0.7)` | Discover by quality |\n| `@skills:compose(A⊗B)` | Tensor composition |\n| `@skills:compose(A→B→C)` | Sequential |\n| `@skills:compose(A>=>B)` | Kleisli |\n| `@skills:skill1,skill2` | Explicit list |\n| `@skills:best(domain=X)` | Best for domain |\n\n**Example**: `/meta-command @skills:compose(api-testing⊗validation) \"create tests\"`\n\n---\n\n## Composition Operators\n\n### → (Sequence) - Kleisli Composition\n\n**Unicode**: U+2192\n**Meaning**: Output of A becomes input of B\n**Quality**: `quality(A → B) ≤ min(quality(A), quality(B))`\n\n```bash\n# Command syntax\n/chain [/debug→/review→/test] \"error in auth.py\"\n\n# Agent syntax\n[R→D→I→T] \"build feature\"\n\n# Skill syntax\n@skills:compose(research→design→implement)\n```\n\n### || (Parallel) - Concurrent Execution\n\n**Meaning**: Execute A, B, C concurrently, aggregate results\n**Quality**: `quality(A || B || C) = mean(quality(A), quality(B), quality(C))`\n\n```bash\n# Parallel commands\n/chain [/review-security || /review-performance] \"audit code\"\n\n# Parallel agents\n[R||D||A] \"evaluate options\"\n\n# Mixed\n[R→(D||F)→I] \"full-stack with parallel design\"\n```\n\n### ⊗ (Tensor) - Quality-Degrading Combination\n\n**Unicode**: U+2297\n**Meaning**: Combine capabilities, quality degrades to minimum\n**Quality**: `quality(A ⊗ B) = min(quality(A), quality(B))`\n\n```bash\n# Skill tensor\n@skills:compose(api-testing⊗jest-patterns⊗validation)\n\n# Agent tensor\n[debug-detective⊗test-engineer] \"fix and test\"\n```\n\n### >=> (Kleisli) - Monadic Refinement\n\n**Meaning**: Composition with quality-gated iteration at each stage\n**Quality**: `quality(A >=> B)` improves with each iteration\n\n```bash\n# RMP stages\n/rmp @quality:0.85 [analyze>=>design>=>implement] \"build feature\"\n\n# Each stage:\n# 1. Execute\n# 2. Assess quality\n# 3. If quality < threshold: refine\n# 4. Pass to next stage\n```\n\n---\n\n## Command Invocation Syntax\n\n### Standard Pattern\n\n```\n/<command> @modifier1:value @modifier2:value [composition] \"task description\"\n```\n\n### Examples\n\n```bash\n# Simple\n/meta \"implement rate limiter\"\n\n# With modifiers\n/meta @mode:iterative @quality:0.85 \"build API\"\n\n# With composition\n/chain [/debug→/fix→/test] \"TypeError in auth.py\"\n\n# Full syntax\n/hekat @mode:active @tier:L5 @budget:18K [R→D→(I||T)] \"build auth system\"\n\n# With skills\n/meta-command @skills:discover(domain=API) @mode:iterative \"create endpoint\"\n```\n\n---\n\n## Agent Hotkeys (HEKAT Compatible)\n\n### Tier 1 - Single Agent\n\n| Key | Agent | Domain |\n|-----|-------|--------|\n| `[R]` | deep-researcher | Research |\n| `[D]` | api-architect | Design |\n| `[I]` | practical-programmer | Implementation |\n| `[T]` | test-engineer | Testing |\n| `[B]` | build-engineer | Build |\n| `[F]` | frontend-specialist | Frontend |\n| `[A]` | analyzer | Analysis |\n\n### Tier 2 - Ctrl Modifiers\n\n| Key | Effect |\n|-----|--------|\n| `[Ctrl+P]` | L4 Parallel mode |\n| `[Ctrl+H]` | L5 Hierarchical mode |\n| `[Ctrl+I]` | L6 Iterative mode |\n\n### Tier 3 - Agent Chains\n\n```bash\n[R→D→I]        # Research → Design → Implement\n[R→D→I→T]      # Full pipeline with testing\n[P:R||D||A]    # Parallel: Research, Design, Analyze\n[R→(D||F)→I]   # Mixed: Research, parallel Design/Frontend, Implement\n```\n\n---\n\n## Quality Assessment Structure\n\n### Multi-Dimensional Quality Vector\n\n| Dimension | Weight | Description |\n|-----------|--------|-------------|\n| Correctness | 40% | Does it solve the problem? |\n| Clarity | 25% | Is it understandable? |\n| Completeness | 20% | Are edge cases handled? |\n| Efficiency | 15% | Is it well-designed? |\n\n### Aggregate Score\n\n```\naggregate = (0.40 × correctness) + (0.25 × clarity) +\n            (0.20 × completeness) + (0.15 × efficiency)\n```\n\n### Quality Thresholds\n\n| Score | Status | Action |\n|-------|--------|--------|\n| ≥0.9 | Excellent | Stop, success |\n| 0.8-0.9 | Good | Stop, success |\n| 0.7-0.8 | Acceptable | Continue if @mode:iterative |\n| 0.6-0.7 | Poor | Refine if iterations remain |\n| <0.6 | Failed | Abort or restructure |\n\n---\n\n## Checkpoint Format\n\nAll commands produce standardized checkpoints:\n\n```yaml\nCHECKPOINT_[type]_[n]:\n  command: /[command]\n  iteration: [n]\n  quality:\n    correctness: [0-1]\n    clarity: [0-1]\n    completeness: [0-1]\n    efficiency: [0-1]\n    aggregate: [0-1]\n  quality_delta: [+/- from previous]\n  budget:\n    used: [tokens]\n    remaining: [tokens]\n    variance: [%]\n  status: [CONTINUE | CONVERGED | MAX_ITERATIONS | HALT]\n  trend: [RAPID_IMPROVEMENT | STEADY_IMPROVEMENT | PLATEAU | DEGRADING]\n```\n\n---\n\n## Workflow Patterns\n\n### Pattern 1: Simple Task\n\n```bash\n/meta \"task\"\n```\n- Auto-detect domain, tier, template\n- Single-pass execution\n\n### Pattern 2: Quality-Gated Iteration\n\n```bash\n/rmp @quality:0.85 @max_iterations:5 \"task\"\n```\n- Iterate until quality threshold\n- Track quality improvement\n\n### Pattern 3: Multi-Stage Pipeline\n\n```bash\n/chain [/analyze→/design→/implement→/test] \"feature\"\n```\n- Sequential execution\n- Output → Input flow\n\n### Pattern 4: Parallel Exploration\n\n```bash\n/chain [/approach-a || /approach-b || /approach-c] \"evaluate options\"\n```\n- Concurrent execution\n- Aggregate results\n\n### Pattern 5: Hierarchical Orchestration\n\n```bash\n/hekat @tier:L5 [Lead→(Worker||Worker)→Synthesize] \"complex task\"\n```\n- Lead agent coordinates\n- Workers execute in parallel\n- Synthesizer combines results\n\n### Pattern 6: Skill-Driven Meta-Command\n\n```bash\n/meta-command @skills:discover(domain=API,relevance>0.7) \"create endpoint command\"\n```\n- Auto-discover relevant skills\n- Inject into command creation\n\n---\n\n## Mode Behaviors\n\n### @mode:active\n- Execute immediately\n- Auto-detect all parameters\n- Single-pass unless combined with @mode:iterative\n\n### @mode:iterative\n- Enable RMP loop\n- Iterate until @quality: threshold\n- Track quality across iterations\n\n### @mode:dry-run\n- Show execution plan\n- Do not execute\n- Exit after plan display\n\n### @mode:spec\n- Generate YAML specification\n- Do not execute\n- Exit after spec generation\n\n---\n\n## Error Handling\n\n### Budget Exceeded\n\n```yaml\nSTATUS: HALT\nreason: \"Budget variance exceeded @variance: threshold\"\naction: \"Review agent outputs, adjust budget allocation\"\n```\n\n### Quality Plateau\n\n```yaml\nSTATUS: NO_IMPROVEMENT\nreason: \"Quality improvement < 0.02 for 2 iterations\"\naction: \"Fixed-point reached, returning best result\"\n```\n\n### Max Iterations\n\n```yaml\nSTATUS: MAX_ITERATIONS\nreason: \"Reached @max_iterations: limit\"\naction: \"Return best result from iterations\"\n```\n\n---\n\n## Self-Reference Protocol\n\nWhen executing any command or skill:\n\n1. **Check modifiers**: Parse all @modifier: values\n2. **Apply defaults**: Use defaults for unspecified modifiers\n3. **Validate syntax**: Ensure operators match specification\n4. **Execute**: Follow categorical laws\n5. **Checkpoint**: Output standardized checkpoint\n6. **Quality assess**: Evaluate using multi-dimensional vector\n7. **Decide**: CONTINUE, CONVERGE, or HALT based on rules\n\n---\n\n## Command Reference Quick Look\n\n### Core Categorical Commands (F, M, W, α)\n\n| Command | Categorical Role | Key Modifiers |\n|---------|------------------|---------------|\n| `/meta` | **Functor F**: Task → Prompt | @mode:, @tier:, @template:, @domain: |\n| `/rmp` | **Monad M**: Prompt →ⁿ Prompt | @quality:, @max_iterations:, @mode: |\n| `/context` | **Comonad W**: History → Context | @mode:, @focus:, @depth:, @transform: |\n| `/transform` | **Nat. Trans. α**: F ⇒ G | @from:, @to:, @verify:, @mode: |\n\n### Natural Transformation Operations (/transform)\n\n| Mode | Description | Type Signature |\n|------|-------------|----------------|\n| `@mode:transform` | Strategy switch (default) | α_A: F(A) → G(A) |\n| `@mode:compare` | Compare strategies | Show F vs G side-by-side |\n| `@mode:analyze` | Recommend optimal | Suggest best α |\n\n**Strategy Registry (Functors)**:\n- `zero-shot` (F_ZS): Direct prompt, quality ~0.65\n- `few-shot` (F_FS): Exemplar prompt, quality ~0.78\n- `chain-of-thought` (F_CoT): Reasoning prompt, quality ~0.85\n- `tree-of-thought` (F_ToT): Branching prompt, quality ~0.88\n- `meta-prompting` (F_Meta): Adaptive prompt, quality ~0.90\n\n**Aliases**:\n- `/cot` = `/transform @to:chain-of-thought`\n- `/tot` = `/transform @to:tree-of-thought`\n\n### Comonad Operations (/context)\n\n| Mode | Operation | Type Signature |\n|------|-----------|----------------|\n| `@mode:extract` | Focus on current | ε: W(A) → A |\n| `@mode:duplicate` | Meta-observation | δ: W(A) → W(W(A)) |\n| `@mode:extend` | Context-aware transform | (W(A) → B) → W(A) → W(B) |\n\n**Aliases**:\n- `/extract` = `/context @mode:extract`\n- `/focus` = `/context @mode:extract @depth:1`\n\n### Composition & Routing Commands\n\n| Command | Purpose | Key Modifiers |\n|---------|---------|---------------|\n| `/chain` | Command composition | @mode:, @budget:, @quality:, @catch:, @fallback:, @quality:visualize |\n| `/route` | Dynamic routing | @domain: |\n| `/build-prompt` | Template assembly | @template: |\n\n### Domain Commands\n\n| Command | Purpose | Key Modifiers |\n|---------|---------|---------------|\n| `/review` | Domain-aware code review | @domain: |\n| `/debug` | Systematic debugging | @mode: |\n| `/hekat` | Agent orchestration DSL | @tier:, @budget:, @variance: |\n| `/meta-command` | Create new commands | @skills:, @mode: |\n| `/task-relay` | Multi-agent relay | @budget:, @pattern: |\n\n---\n\n## Skill Reference Quick Look\n\n| Skill | Purpose | Integration |\n|-------|---------|-------------|\n| `categorical-meta-prompting` | Core F, M, W framework | /meta, /rmp, /context |\n| `categorical-structure-builder` | Implement any categorical structure | {prompt:categorical-structure} |\n| `recursive-meta-prompting` | RMP implementation patterns | @mode:iterative |\n| `dynamic-prompt-registry` | Prompt lookup/composition | @skills:, {prompt:} |\n| `quality-enriched-prompting` | [0,1]-enriched quality | @quality: |\n| `atomic-blocks` | Composable atomic blocks | /blocks, @block: |\n| `meta-self` | This reference | Self-reference |\n\n---\n\n## Atomic Blocks (Layer 3 Access)\n\nFor power users who need fine-grained control, the framework exposes atomic blocks that underlie all commands.\n\n### Quick Reference\n\n```\nSkill: atomic-blocks\nCommand: /blocks [composition] \"task\"\n```\n\n### Available Blocks\n\n| Layer | Blocks | Purpose |\n|-------|--------|---------|\n| Assessment | assess_difficulty, assess_domain, assess_quality, select_tier | Analyze and classify |\n| Transformation | select_strategy, build_template, apply_transform, execute_prompt | Transform to outputs |\n| Refinement | evaluate_convergence, extract_improvement, apply_refinement | Monad M iteration |\n| Composition | sequence (→), parallel (\\|\\|), kleisli (>=>), tensor (⊗) | Combine blocks |\n\n### Progressive Disclosure\n\n| Layer | Users | Access |\n|-------|-------|--------|\n| 1 | 90% | `/meta \"task\"` - blocks hidden |\n| 2 | 9% | `/meta @block:assess_domain:SECURITY \"task\"` - override block |\n| 3 | 1% | `/blocks [assess_difficulty → select_tier] \"task\"` - compose |\n\n**Full specification**: `skill:atomic-blocks`\n\n---\n\n## Validation Checklist\n\nBefore executing any prompt:\n\n- [ ] All modifiers use `@name:value` syntax\n- [ ] Operators match: `→`, `||`, `⊗`, `>=>`\n- [ ] Quality thresholds in [0,1] range\n- [ ] Budget values are positive integers or \"auto\"\n- [ ] Tier values are L1-L7\n- [ ] Mode values are: active, iterative, dry-run, spec\n- [ ] Composition brackets match: `[...]`\n- [ ] Task description is quoted: `\"task\"`\n\n---\n\n## Version\n\n**Specification Version**: 2.5\n**Compatibility**: 100% backward compatible\n**Foundation**: Category Theory (F, M, W, α, E, [0,1]-enriched)\n**Last Updated**: 2025-12-01\n**New in 2.5**: Atomic blocks system with /blocks command, @block: overrides, progressive disclosure\n**New in 2.4**: Quality Visualization via @quality:visualize modifier (Phase 5)\n**New in 2.3**: Exception Monad E for error handling via @catch:/@fallback: modifiers\n**New in 2.2**: Natural Transformation α operations via /transform command\n**New in 2.1**: Comonad W operations via /context command\n"},"lastSynced":"2026-03-08T02:01:09.035Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced AI Agents needing unified categorical syntax references for meta-prompting and iterative refinement.","zh":"适用于需要统一分类语法参考的高级AI代理，用于元提示和迭代改进。","ja":"Meta-promptingとイテレーティブな改良のための統一されたカテゴリ的構文リファレンスを必要とする高度なAIエージェントに最適です。","ko":"메타 프롬프팅과 반복적인 개선을 위한 통일된 범주적 구문 참조가 필요한 고급 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de inteligencia artificial avanzados que necesitan referencias de sintaxis categórica unificada para meta-prompting y refinamiento iterativo.","fr":"Parfait pour les agents d''intelligence artificielle avancés ayant besoin de références de syntaxe catégorielle unifiée pour le meta-prompting et l''affinement itératif.","de":"Perfekt für fortgeschrittene KI-Agents, die vereinheitlichte kategorische Syntaxreferenzen für Meta-Prompting und iteratives Verfeinern benötigen.","pt":"Perfeito para Agentes de IA Avançados que necessitam de referências de sintaxe categórica unificada para meta-prompting e refinamento iterativo.","ru":"Идеально подходит для продвинутых агентов ИИ, которым требуются унифицированные ссылки на категориальную синтаксис для мета-пrompting и итеративного уточнения.","ar":"مثالي لعمليات الوكيل الذكي المتقدمة التي تحتاج إلى مراجع بنية موحدة لمتطلبات الإيهام والتحسين المتكرر."},"recommendation":{"en":"Empowers agents to leverage Functor, Monad, and Comonad structures for task-to-prompt transformations, iterative prompt refinement, and context extraction, utilizing natural transformations for strategy switching and ensuring proven correctness and measurable quality improvements.","zh":"赋予代理使用函子、单子和共单子结构进行任务到提示的转换、迭代提示改进和上下文提取，利用自然变换进行策略切换，确保正确性和可衡量的质量改进。","ja":"Functor、Monad、Comonad構造を使用してタスクからプロンプトへの変換、イテレーティブなプロンプト改良、コンテキスト抽出を行い、自然変換を使用して戦略の切り替えを行い、正しさと計量可能な品質の改善を確保します。","ko":"펑터, 모나드, 코모나드 구조를 사용하여 작업에서 프롬프트까지의 변환, 반복적인 프롬프트 개선 및 컨텍스트 추출을 수행하고, 자연적 변환을 사용하여 전략 전환을 수행하며, 올바름과 측정 가능한 품질 개선을 보장합니다.","es":"Habilita a los agentes a aprovechar estructuras de Functor, Monad y Comonad para transformaciones de tarea a prompt, refinamiento iterativo de prompts y extracción de contexto, utilizando transformaciones naturales para conmutación de estrategias y garantizando corrección probada y mejoras de calidad medibles.","fr":"Permet aux agents d''exploiter des structures de Functor, Monad et Comonad pour des transformations de tâche à prompt, un affinement itératif de prompts et une extraction de contexte, en utilisant des transformations naturelles pour un commutateur de stratégies et en garantissant une correction prouvée et des améliorations de qualité mesurables.","de":"Ermöglicht es Agents, Functor-, Monad- und Comonad-Strukturen für Task-to-Prompt-Transformationen, iteratives Prompt-Verfeinern und Kontextextraktion zu nutzen, wobei natürliche Transformationen für Strategiewechsel verwendet werden, um bewiesene Korrektheit und messbare Qualitätsverbesserungen sicherzustellen.","pt":"Habilita os agentes a utilizarem estruturas de Functor, Monad e Comonad para transformações de tarefa para prompt, refinamento iterativo de prompt e extração de contexto, utilizando transformações naturais para commutação de estratégias e garantindo correção comprovada e melhorias de qualidade mensuráveis.","ru":"Позволяет агентам использовать структуры Functor, Monad и Comonad для преобразования задач в подсказки, итеративного уточнения подсказок и извлечения контекста, используя естественные преобразования для переключения стратегий и обеспечения проверенной правильности и измеримых улучшений качества.","ar":"تمكّن الوكيل من استخدام هيكليات Functor و Monad و Comonad لتحويل المهام إلى إيهامات وتنقيحها بشكل متكرر واستخراج السياق، باستخدام التحويلات الطبيعية لتبديل الاستراتيجيات وضمان الصحة المثبتة وتحسين الجودة القابل للقياس."},"useCases":{"en":["Standardizing meta-prompting frameworks across multiple AI agents","Generating categorical foundations for task-specific prompt engineering","Refining prompts iteratively using Monad structures for improved quality"],"zh":["在多个AI代理中标准化元提示框架","为任务特定提示工程生成分类基础","使用Monad结构反复改进提示以提高质量"],"ja":["複数のAIエージェント全体でメタプロンプトフレームワークを標準化する","タスク固有のプロンプトエンジニアリングのためのカテゴリ的基礎を生成する","モナド構造を使用してプロンプトを反復的に改良し、品質を向上させる"],"ko":["여러 AI 에이전트에서 메타 프롬프팅 프레임워크를 표준화하는 것","작업 특정 프롬프트 엔지니어링을 위한 범주적 기반을 생성하는 것","모나드 구조를 사용하여 프롬프트를 반복적으로 개선하여 품질을 향상시키는 것"],"es":["Establecer estándares para frameworks de meta-prompting en múltiples agentes de inteligencia artificial","Generar fundamentos categóricos para ingeniería de prompts específicos de tareas","Refinar prompts de forma iterativa utilizando estructuras de Monad para una mayor calidad"],"fr":["Standardiser les frameworks de meta-prompting sur plusieurs agents d''intelligence artificielle","Générer des fondements catégoriels pour l''ingénierie de prompts spécifiques aux tâches","Affiner les prompts de manière itérative en utilisant des structures de Monad pour une meilleure qualité"],"de":["Standardisierung von Meta-Prompting-Frameworks über mehrere KI-Agents hinweg","Erzeugen kategorischer Grundlagen für task-spezifische Prompt-Engineering","Iteratives Verfeinern von Prompts unter Verwendung von Monad-Strukturen für verbesserte Qualität"],"pt":["Padronização de estruturas de meta-prompting em vários agentes de IA","Geração de fundamentos categóricos para engenharia de prompt específica de tarefa","Refinamento iterativo de prompts usando estruturas de Monad para melhorar a qualidade"],"ru":["Стандартизация фреймворков мета-пrompting для нескольких агентов ИИ","Генерация категориальных основ для задачно-специфической инженерии подсказок","Итеративное уточнение подсказок с использованием структур Monad для улучшения качества"],"ar":["توحيد إطارات الإيهام المتكرر عبر العديد من عمليات الوكيل الذكي","توليد الأسس الفئوية للهندسة المحددة للمهمة","تنقيح الإيهامات بشكل متكرر باستخدام هيكليات Monad لتحسين الجودة"]},"limitations":{"en":["Requires understanding of categorical foundations and meta-prompting concepts","Limited to AI agents capable of processing and applying categorical syntax references"],"zh":["需要了解分类基础和元提示概念","仅限于能够处理和应用分类语法引用的AI代理"],"ja":["カテゴリ的基礎とメタプロンプト概念の理解が必要","カテゴリ的構文リファレンスを処理して適用できるAIエージェントに限定される"],"ko":["범주적 기반과 메타 프롬프팅 개념에 대한 이해가 필요합니다","범주적 구문 참조를 처리하고 적용할 수 있는 AI 에이전트로 제한됩니다"],"es":["Requiere comprensión de fundamentos categóricos y conceptos de meta-prompting","Limitado a agentes de inteligencia artificial capaces de procesar y aplicar referencias de sintaxis categórica"],"fr":["Nécessite une compréhension des fondements catégoriels et des concepts de meta-prompting","Limité aux agents d''intelligence artificielle capables de traiter et d''appliquer des références de syntaxe catégorielle"],"de":["Benötigt Verständnis für kategorische Grundlagen und Meta-Prompting-Konzepte","Begrenzt auf KI-Agents, die in der Lage sind, kategorische Syntaxreferenzen zu verarbeiten und anzuwenden"],"pt":["Requer compreensão de conceitos de fundamentos categóricos e meta-prompting","Limitado a agentes de IA capazes de processar e aplicar referências de sintaxe categórica"],"ru":["Требует понимания концепций категориальных основ и мета-пrompting","Ограничен агентами ИИ, способными обрабатывать и применять ссылки на категориальную синтаксис"],"ar":["يتطلب فهم المفاهيم الأساسية الفئوية والإيهامات المتكررة","محدود بالوكلاء الذكية القادرة على معالجة وتطبيق المراجع النحوية الفئوية"]},"version":4},"contentHash":"1f98417c0054c7606924c734d6cdd8587a9fe3c042fd368b7c03bb0ec3947ebe","qualityScore":60}');
