INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('manutej/categorical-meta-prompting/meta-self', 'meta-self', 'manutej', 'categorical-meta-prompting', 'community', 'meta-self manutej categorical-meta-prompting community meta-self provides categorical foundations for AI meta-prompting, ensuring proven correctness and measurable quality improvements. It benefits developers seeking a unified syntax reference for AI agents. meta-self是AI元提示框架的权威参考，提供了分类基础和测量质量改进的方法 meta-selfはAIエージェントのプロンプティングフレームワークの権威ある参考であり、カテゴリ的基礎と測定可能な品質改善の方法を提供する meta-self는 AI 프롬프트링 프레임워크의 권위적인 참조이며, 분류적 기초와 측정 가능한 품질 개선 방법을 제공합니다 Meta-Self es un marco de referencia catégorial para el prompts de meta de IA, que proporciona una base sólida para la creación de agentes de inteligencia artificial con comprobada corrección y mejoras de calidad medibles. Meta-Self est un référentiel catégoriel pour les prompts de métadonnées d''IA, qui fournit une base solide pour la création d''outils d''intelligence artificielle avec correction prouvée et améliorations de qualité mesurables. Meta-Self ist ein kategoriales Referenzframework für Meta-Prompts von KI, das eine solide Grundlage für die Erstellung von KI-Tools mit nachgewiesener Korrektheit und messbaren Qualitätsverbesserungen bietet. O Meta-Self é um framework de prompts de IA que utiliza funtores, monads e comonads para melhorar a qualidade dos prompts Meta-Self - это фреймворк для промтов ИИ, использующий функторы, монады и комонады для улучшения качества промтов متا-سيلف هو إطار عمل لتلميحات الذكاء الاصطناعي الذي يستخدم الفنكторات والمناد والكوموناد لتحسين جودة التلميحات how to use meta-self meta-self alternative meta-self setup guide what is meta-self meta-self vs other AI frameworks meta-self install for AI agents categorical meta-prompting with meta-self functor-based AI development monad-based iterative refinement in AI AI提示框架 元提示 分类基础 结构保持变换 迭代改进 上下文提取 自然变换 测量质量改进 Implements functor-based structure-preserving transformations (F: Task → Prompt) Supports monad-based iterative refinement (M: Prompt →^n Prompt) Utilizes comonad-based context extraction (W: History → Context) Enables natural transformation-based strategy switching (α: F ⇒ G) Provides a unified categorical syntax reference for AI meta-prompting meta-self is a categorical meta-prompting framework providing a structured approach to AI agent development using functors, monads, and comonads.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alfredolopez80/multi-agent-ralph-loop/gates', 'community', 'alfredolopez80', 'multi-agent-ralph-loop', 'alfredolopez80/multi-agent-ralph-loop', 'gates', 0, 0, 60, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:12.024Z', '077990d7aba7c9c6bda44b48f4da8c257fcba4d2181d463e6491226b4bdfed3c', '{"id":"alfredolopez80/multi-agent-ralph-loop/gates","name":"gates","description":{"en":"Gates provides quality validation across 9 programming languages with TLDR-assisted analysis, supporting model-agnostic configurations. It benefits developers working with AI agents.","zh":"Gates提供多Agent AI编排和质量验证，支持9种编程语言和TLDR辅助分析","ja":"Gatesは多Agent AIオーケストレーションと品質検証を提供し、9つのプログラミング言語とTLDRアシスト分析をサポート","ko":"Gates는 다중 에이전트 AI 오케스트레이션과 품질 검증을 제공하며 9가지 프로그래밍 언어와 TLDR 보조 분석을 지원합니다","es":"Gates es una herramienta de validación de calidad para proyectos de AI que admite 9 lenguajes de programación con análisis asistido por TLDR","fr":"Gates est un outil de validation de qualité pour les projets d''IA qui prend en charge 9 langages de programmation avec analyse assistée par TLDR","de":"Gates ist ein Qualitätsvalidierungstool für KI-Projekte, das 9 Programmiersprachen mit TLDR-assistierter Analyse unterstützt","pt":"Gates é uma ferramenta de orquestração de agentes de IA que fornece validação de qualidade abrangente em 9 linguagens de programação.","ru":"Gates - это инструмент оркестровки ИИ Агентов, который обеспечивает всестороннюю проверку качества на 9 языках программирования.","ar":"Gates هي أداة لorchestration وكلاء الذكاء الاصطناعي التي توفر التحقق من جودة شامل في 9 لغات برمجة"},"seo":{"title":{"en":"Gates: Model-Agnostic Quality Validation Setup Guide | AI...","zh":"Gates Setup Guide - AIエージェント质量验证","ja":"Gates セットアップガイド - AIエージェントの品質検証","ko":"Gates 설정 가이드 - AI 에이전트 품질 검증","es":"Guía de configuración de Gates - Validación de calidad pa...","fr":"Guide de configuration de Gates - Validation de qualité p...","de":"Gates-Konfigurationsleitfaden - Qualitätsvalidierung für ...","pt":"Gates - Guia de Configuração para Validação de Qualidade ...","ru":"Gates - Настройка валидации качества для ИИ Агентов","ar":"Gates - دليل إعداد بوابات التحقق من جودة وكلاء الذكاء الا..."},"description":{"en":"Unlock comprehensive quality validation with Gates. Discover how to configure model-agnostic settings and tap into TLDR-assisted analysis for 9 programming l...","zh":"使用Gates进行多Agent AI编排，支持GLM-4.7 PRIMARY、Claude、Codex和Gemini，拥有67个钩子和TLDR辅助分析","ja":"Gatesを使用して多Agent AIオーケストレーションを実現する、GLM-4.7 PRIMARY、Claude、Codex、Geminiをサポート、67個のフックとTLDRアシスト分析を搭載","ko":"Gates를 사용하여 다중 에이전트 AI 오케스트레이션을 구현합니다. GLM-4.7 PRIMARY, Claude, Codex, Gemini를 지원하며 67개의 후크와 TLDR 보조 분석을 제공합니다","es":"Aprende a configurar Gates para validar la calidad de tus proyectos de AI con GLM-4.7, Claude, Codex y Gemini","fr":"Découvrez comment configurer Gates pour valider la qualité de vos projets d''IA avec GLM-4.7, Claude, Codex et Gemini","de":"Erfahren Sie, wie Sie Gates konfigurieren, um die Qualität Ihrer KI-Projekte mit GLM-4.7, Claude, Codex und Gemini zu validieren","pt":"Aprenda a configurar Gates para validação de qualidade de agentes de IA com GLM-4.7, Claude, Codex e Gemini. Descubra como melhorar a qualidade dos seus agen...","ru":"Узнайте, как настроить Gates для валидации качества ИИ Агентов с GLM-4.7, Claude, Codex и Gemini. Улучшите качество своих ИИ Агентов.","ar":"تعرف على كيفية 설정 بوابات Gates للتحقق من جودة وكلاء الذكاء الاصطناعي باستخدام GLM-4.7 و Claude و Codex و Gemini. تحسين جودة وكلائك"},"definition":{"en":"Gates is a multi-agent AI orchestration skill with quality gates, memory system, and 67 hooks, utilizing models like GLM-4.7 PRIMARY, Claude, Codex, and Gemini.","zh":"Gates是一种多Agent AI编排和质量验证工具，支持多种编程语言和AI模型","ja":"Gatesは多Agent AIオーケストレーションと品質検証ツールであり、多くのプログラミング言語とAIモデルをサポート","ko":"Gates는 다중 에이전트 AI 오케스트레이션과 품질 검증 도구로, 여러 프로그래밍 언어와 AI 모델을 지원합니다","es":"Gates es un sistema de validación de calidad para herramientas de AI que utiliza modelos como GLM-4.7 y Claude","fr":"Gates est un système de validation de qualité pour les outils d''IA qui utilise des modèles tels que GLM-4.7 et Claude","de":"Gates ist ein Qualitätsvalidierungssystem für KI-Tools, das Modelle wie GLM-4.7 und Claude verwendet","pt":"Gates é uma ferramenta de validação de qualidade de agentes de IA que utiliza GLM-4.7, Claude, Codex e Gemini.","ru":"Gates - это инструмент проверки качества ИИ Агентов, который использует GLM-4.7, Claude, Codex и Gemini.","ar":"Gates هي أداة للتحقق من جودة وكلاء الذكاء الاصطناعي التي تستخدم GLM-4.7 و Claude و Codex و Gemini"},"features":{"en":["Uses model configured in ~/.claude/settings.json or CLI/env vars","Supports model-agnostic configurations with GLM-5, Claude, and other models","Provides TLDR-assisted analysis for comprehensive quality validation","Works with 9 programming languages","Utilizes 67 hooks for flexible integration","Deprecates MiniMax for improved performance"],"zh":["支持GLM-4.7 PRIMARY、Claude、Codex和Gemini","拥有67个钩子和TLDR辅助分析","支持9种编程语言","模型无关，使用配置的默认模型","灵活，支持GLM-5、Claude、Minimax或任何配置模型"],"ja":["GLM-4.7 PRIMARY、Claude、Codex、Geminiをサポート","67個のフックとTLDRアシスト分析を搭載","9つのプログラミング言語をサポート","モデル非依存、設定されたデフォルトモデルを使用","柔軟、GLM-5、Claude、Minimaxまたは任意の設定モデルをサポート"],"ko":["GLM-4.7 PRIMARY, Claude, Codex, Gemini를 지원","67개의 후크와 TLDR 보조 분석을 제공","9가지 프로그래밍 언어를 지원","모델 비의존, 설정된 기본 모델 사용","유연하게 GLM-5, Claude, Minimax 또는 任意의 설정 모델을 지원"],"es":["Soporte para 9 lenguajes de programación","Análisis asistido por TLDR","Compatibilidad con GLM-4.7, Claude, Codex y Gemini","Configuración de modelo a través de variables de entorno","67 hooks para personalizar la validación","Compatibilidad con MiniMax (obsoleto)"],"fr":["Prise en charge de 9 langages de programmation","Analyse assistée par TLDR","Compatibilité avec GLM-4.7, Claude, Codex et Gemini","Sélection de modèle via des variables d''environnement","67 hooks pour personnaliser la validation","Compatibilité avec MiniMax (obsolète)"],"de":["Unterstützung für 9 Programmiersprachen","TLDR-assistierte Analyse","Kompatibilität mit GLM-4.7, Claude, Codex und Gemini","Modellauswahl über Umgebungsvariablen","67 Hooks zur Anpassung der Validierung","Kompatibilität mit MiniMax (veraltet)"],"pt":["Validação de qualidade abrangente em 9 linguagens de programação","Compatibilidade com GLM-4.7, Claude, Codex e Gemini","Sistema de memória com 67 hooks","Análise assistida por TLDR","Configuração flexível via arquivo de configuração ou variáveis de ambiente"],"ru":["Всесторонняя проверка качества на 9 языках программирования","Совместимость с GLM-4.7, Claude, Codex и Gemini","Система памяти с 67 крючками","Анализ с помощью TLDR","Гибкая настройка через файл конфигурации или переменные среды"],"ar":["التحقق من جودة شامل في 9 لغات برمجة","التوافق مع GLM-4.7 و Claude و Codex و Gemini","نظام الذاكرة مع 67 hooks","التحليل بمساعدة TLDR","الإعداد المرن عبر ملف الإعداد أو متغيرات البيئة"]},"keywords":{"en":["how to use gates","gates setup guide","gates alternative","gates vs claude","gates install","model-agnostic quality validation","TLDR-assisted analysis","gates for AI agents","gates configuration"],"zh":["AIエージェント","多Agent AI编排","质量验证","GLM-4.7 PRIMARY","Claude","Codex","Gemini","TLDR辅助分析","模型无关"],"ja":["AIエージェント","多Agent AIオーケストレーション","品質検証","GLM-4.7 PRIMARY","Claude","Codex","Gemini","TLDRアシスト分析","モデル非依存"],"ko":["AI 에이전트","다중 에이전트 AI 오케스트레이션","품질 검증","GLM-4.7 PRIMARY","Claude","Codex","Gemini","TLDR 보조 분석","모델 비의존"],"es":["herramientas de AI","validación de calidad","GLM-4.7","Claude","Codex","Gemini","TLDR","configuración de modelo","variables de entorno","desarrollo de AI"],"fr":["outils d''IA","validation de qualité","GLM-4.7","Claude","Codex","Gemini","TLDR","sélection de modèle","variables d''environnement","développement d''IA"],"de":["KI-Tools","Qualitätsvalidierung","GLM-4.7","Claude","Codex","Gemini","TLDR","Modellauswahl","Umgebungsvariablen","KI-Entwicklung"],"pt":["validação de qualidade de agentes de IA","orquestração de agentes de IA","GLM-4.7","Claude","Codex","Gemini","análise de código","desenvolvimento de software","IA"],"ru":["проверка качества ИИ Агентов","оркестровка ИИ Агентов","GLM-4.7","Claude","Codex","Gemini","анализ кода","разработка программного обеспечения","ИИ"],"ar":["التحقق من جودة وكلاء الذكاء الاصطناعي","orchestration وكلاء الذكاء الاصطناعي","GLM-4.7","Claude","Codex","Gemini","تحليل الكود","تطوير البرمجيات","الذكاء الاصطناعي"]}},"owner":"alfredolopez80","repo":"multi-agent-ralph-loop","repoPath":"alfredolopez80/multi-agent-ralph-loop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"gates","description":"9-language quality gate validation: linting, formatting, type checking, and test execution. Validates code changes meet quality standards before completion. Use when: (1) after code implementation, (2) before PR creation, (3) as part of /orchestrator Step 6, (4) manual quality check. Triggers: /gates, quality gates, run validation, check quality, validate code.","bodyPreview":"# Gates - Quality Validation (v2.37)\n\nComprehensive quality validation across 9 programming languages with **TLDR-assisted analysis**.\n\n## v2.88 Key Changes (MODEL-AGNOSTIC)\n\n- **Model-agnostic**: Uses model configured in `~/.claude/settings.json` or CLI/env vars\n- **No flags required**: Works with the configured default model\n- **Flexible**: Works with GLM-5, Claude, Minimax, or any configured model\n- **Settings-driven**: Model selection via `ANTHROPIC_DEFAULT_*_MODEL` env vars\n\n## Quick Start","body":"# Gates - Quality Validation (v2.37)\n\nComprehensive quality validation across 9 programming languages with **TLDR-assisted analysis**.\n\n## v2.88 Key Changes (MODEL-AGNOSTIC)\n\n- **Model-agnostic**: Uses model configured in `~/.claude/settings.json` or CLI/env vars\n- **No flags required**: Works with the configured default model\n- **Flexible**: Works with GLM-5, Claude, Minimax, or any configured model\n- **Settings-driven**: Model selection via `ANTHROPIC_DEFAULT_*_MODEL` env vars\n\n## Quick Start\n\n```bash\n/gates              # Run all quality gates\nralph gates         # Via CLI\nralph gates src/    # Specific directory\n```\n\n## LSP Usage for Type Checking\n\n**IMPORTANT**: Use LSP for efficient type checking instead of reading entire files.\n\n### When to Use LSP\n- Type checking TypeScript/JavaScript files\n- Finding type errors without running `tsc --noEmit`\n- Getting hover information for symbols\n- Finding references across the codebase\n\n### LSP Commands\n```yaml\n# Type check a specific file (TypeScript)\nLSP:\n  server: typescript-language-server\n  action: diagnostics\n  file: src/auth/login.ts\n\n# Get hover information for a symbol\nLSP:\n  server: typescript-language-server\n  action: hover\n  file: src/auth/login.ts\n  line: 42\n  character: 10\n\n# Find all references\nLSP:\n  server: typescript-language-server\n  action: references\n  file: src/auth/login.ts\n  line: 42\n  character: 10\n\n# Python type checking with pyright\nLSP:\n  server: pyright\n  action: diagnostics\n  file: src/auth/login.py\n```\n\n### LSP vs Traditional Type Checking\n| Method | Tokens Used | Speed | Use Case |\n|--------|-------------|-------|----------|\n| `tsc --noEmit` | HIGH (reads all files) | Slow | Full project check |\n| `LSP diagnostics` | LOW (indexed access) | Fast | Single file check |\n| `LSP hover` | MINIMAL | Instant | Quick type lookup |\n\n## Pre-Gates: TLDR Language Detection (v2.37)\n\n**AUTOMATIC** - Detect project languages efficiently:\n\n```bash\n# Get codebase structure to detect languages (95% token savings)\ntldr structure . > /tmp/project-structure.md\n\n# From structure, identify:\n# - Primary language(s)\n# - Config files present\n# - Test frameworks used\n```\n\n## Supported Languages\n\n| Language | Linter | Formatter | Types |\n|----------|--------|-----------|-------|\n| TypeScript | ESLint | Prettier | tsc |\n| JavaScript | ESLint | Prettier | - |\n| Python | Ruff | Black | mypy |\n| Rust | Clippy | rustfmt | cargo check |\n| Go | golint | gofmt | go vet |\n| Java | Checkstyle | google-java-format | - |\n| Ruby | RuboCop | - | Sorbet |\n| PHP | PHP_CodeSniffer | php-cs-fixer | PHPStan |\n| Solidity | Solhint | prettier-solidity | - |\n\n## Workflow\n\n### 1. Detect Languages\n```bash\n# Auto-detect based on file extensions and config files\n```\n\n### 2. Run Linters\n```bash\n# Per-language linting\nnpx eslint src/          # TypeScript/JavaScript\nruff check .             # Python\ncargo clippy             # Rust\ngolangci-lint run        # Go\n```\n\n### 3. Check Formatting\n```bash\nnpx prettier --check .   # JS/TS\nblack --check .          # Python\nrustfmt --check src/     # Rust\ngofmt -l .               # Go\n```\n\n### 4. Type Checking\n```bash\nnpx tsc --noEmit         # TypeScript\nmypy .                   # Python\ncargo check              # Rust\ngo vet ./...             # Go\n```\n\n### 5. Run Tests\n```bash\nnpm test                 # Node projects\npytest                   # Python\ncargo test               # Rust\ngo test ./...            # Go\n```\n\n## Exit Codes\n\n| Code | Meaning |\n|------|---------|\n| 0 | All gates passed |\n| 1 | Lint errors |\n| 2 | Format errors |\n| 3 | Type errors |\n| 4 | Test failures |\n\n## Gate Configuration\n\n### Minimal (fast)\n```bash\nralph gates --minimal    # Lint only\n```\n\n### Standard (default)\n```bash\nralph gates              # Lint + Format + Types\n```\n\n### Full (CI)\n```bash\nralph gates --full       # Lint + Format + Types + Tests\n```\n\n## Integration\n\n- Invoked by /orchestrator in Step 6\n- **Pre-step: tldr structure for language detection** (v2.37)\n- Must pass before VERIFIED_DONE\n- Hooks: `quality-gates.sh` (PostToolUse)\n\n## TLDR Integration (v2.37)\n\n| Phase | TLDR Command | Purpose |\n|-------|--------------|---------|\n| Language detection | `tldr structure .` | Identify languages |\n| Error context | `tldr context $FILE .` | Understand failing code |\n| Impact analysis | `tldr deps $FILE .` | Find related tests |\n\n## Agent Teams Integration (v2.88)\n\n**Optimal Scenario**: Integrated (Agent Teams + Custom Subagents)\n\nQuality gates use Agent Teams coordination with specialized ralph-tester agents for parallel quality validation.\n\n### Why Scenario C for Gates\n- Multiple quality checks require coordination (lint, format, type, test)\n- Quality gates are meta-validation (hooks validate the validators)\n- Language-specific specialization via ralph-tester\n- TeammateIdle/TaskCompleted hooks for quality enforcement\n\n### Subagent Roles\n\n| Subagent | Role in Gates |\n|----------|---------------|\n| `ralph-tester` | Execute test suites in parallel |\n| `ralph-reviewer` | Analyze code quality issues |\n| `ralph-coder` | Apply auto-fixes for linting/formatting |\n\n### Parallel Gates Execution\nWhen Agent Teams is active, gates run in parallel across subagents:\n1. **Team Lead** creates task list with gate phases\n2. **ralph-tester** runs tests concurrently\n3. **ralph-reviewer** reviews linter output\n4. **ralph-coder** applies fixes\n\n### Quality Gate Hooks\n- `TeammateIdle`: Triggers before agent goes idle\n- `TaskCompleted`: Validates gate completion\n\n## Action Reporting (v2.93.0)\n\n**Los resultados de `/gates` generan reportes automáticos completos**:\n\n### Reporte Automático\n\nCuando `/gates` completa, se genera automáticamente:\n\n1. **En la conversación de Claude**: Resultados visibles de todas las validaciones\n2. **En el repositorio**: `docs/actions/gates/{timestamp}.md`\n3. **Metadatos JSON**: `.claude/metadata/actions/gates/{timestamp}.json`\n\n### Contenido del Reporte\n\nCada reporte incluye:\n- ✅ **Summary**: Tipo de validación ejecutada\n- ✅ **Results**: Resultados de linters, formatters, type checkers, tests\n- ✅ **Errors**: Errores encontrados por categoría\n- ✅ **Recommendations**: Acciones correctivas sugeridas\n- ✅ **Next Steps**: Qué hacer según el resultado\n\n### Generación Manual (Opcional)\n\n```bash\n# Al inicio\nsource .claude/lib/action-report-lib.sh\nstart_action_report \"gates\" \"Running quality gates on src/\"\n\n# Ejecutar validaciones\nif ! npx tsc --noEmit; then\n    record_error \"TypeScript errors found\"\nfi\n\nif ! npx eslint .; then\n    record_error \"ESLint violations found\"\nfi\n\nif ! npm test; then\n    record_error \"Test failures found\"\nfi\n\n# Al completar\nif [[ ${#CURRENT_ACTION_ERRORS[@]} -eq 0 ]]; then\n    complete_action_report \\\n        \"success\" \\\n        \"All quality gates passed\" \\\n        \"Safe to commit: git commit -m ''chore: pass quality gates''\"\nelse\n    complete_action_report \\\n        \"failed\" \\\n        \"Quality gates failed\" \\\n        \"Fix errors and run /gates again\"\nfi\n```\n\n### Ver Reportes Anteriores\n\n```bash\n# Listar todos los reportes de gates\nls -lt docs/actions/gates/\n\n# Ver el reporte más reciente\ncat $(ls -t docs/actions/gates/*.md | head -1)\n\n# Buscar reportes fallidos\ngrep -l \"Status: FAILED\" docs/actions/gates/*.md\n\n# Ver tendencia de calidad\ngrep -c \"Status: COMPLETED\" docs/actions/gates/*.md\ngrep -c \"Status: FAILED\" docs/actions/gates/*.md\n```\n\n### Integración CI/CD\n\nLos metadatos JSON permiten integración con pipelines:\n\n```bash\n# En tu CI pipeline\nsource .claude/lib/action-report-generator.sh\n\n# Ejecutar gates\n/gates\n\n# Obtener resultado del último reporte\nlatest_report=$(find_latest_report \"gates\")\nstatus=$(grep \"Status:\" \"$latest_report\" | awk ''{print $2}'')\n\nif [[ \"$status\" != \"COMPLETED\" ]]; then\n    echo \"Quality gates failed - blocking commit\"\n    exit 1\nfi\n```\n\n### Referencias del Sistema de Reportes\n\n- [Action Reports System](docs/actions/README.md) - Documentación completa\n- [action-report-lib.sh](.claude/lib/action-report-lib.sh) - Librería helper\n- [action-report-generator.sh](.claude/lib/action-report-generator.sh) - Generador\n\n## Anti-Patterns\n\n- Never skip gates for \"quick fixes\"\n- Never ignore type errors\n- Never commit with lint warnings\n"},"lastSynced":"2026-03-08T02:01:12.024Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Language Support Agents needing advanced quality validation with TLDR-assisted analysis.","zh":"非常适合需要高级质量验证的多语言支持代理，具有TLDR辅助分析功能。","ja":"高度な品質の検証が必要なマルチ言語サポートエージェントに最適で、TLDRアシスト分析を備えています。","ko":"고급 품질 검증이 필요한 다중 언어 지원 에이전트에게 적합하며 TLDR 보조 분석을 제공합니다.","es":"Perfecto para agentes de soporte multilingüe que necesitan una validación de calidad avanzada con análisis asistido por TLDR.","fr":"Parfait pour les agents de support multilingue ayant besoin d''une validation de qualité avancée avec analyse assistée par TLDR.","de":"Perfekt für Multi-Language-Support-Agenten, die eine erweiterte Qualitätsvalidierung mit TLDR-assistierter Analyse benötigen.","pt":"Perfeito para Agentes de Suporte de Multilíngua que precisam de validação de qualidade avançada com análise assistida por TLDR.","ru":"Идеально подходит для агентов поддержки нескольких языков, которым требуется продвинутая проверка качества с помощью анализа, поддерживаемого TLDR.","ar":"مثالي للوكلاء الداعمين للمتعددة اللغات الذين يحتاجون إلى التحقق من الجودة المتقدمة مع التحليل المدعوم من TLDR."},"recommendation":{"en":"Empowers agents to perform comprehensive quality validation across 9 programming languages, leveraging model-agnostic configurations and TLDR-assisted analysis, with support for GLM-5, Claude, Minimax, or any configured model via settings-driven model selection.","zh":"使代理能够跨9种编程语言执行全面质量验证，利用模型无关配置和TLDR辅助分析，并支持GLM-5、Claude、Minimax或通过设置驱动的模型选择配置的任何模型。","ja":"エージェントが9つのプログラミング言語を横断して包括的な品質の検証を実行できるようにし、モデル非依存構成とTLDRアシスト分析を利用し、GLM-5、Claude、Minimax、または設定駆動のモデル選択構成によって構成されるモデルをサポートします。","ko":"에이전트가 9개의 프로그래밍 언어를横断하여 포괄적인 품질 검증을 수행할 수 있도록 하며, 모델 비의존 구성과 TLDR 보조 분석을 활용하며, GLM-5, Claude, Minimax 또는 설정 주도 모델 선택 구성에 의해 구성된 모델을 지원합니다.","es":"Habilita a los agentes a realizar una validación de calidad integral en 9 lenguajes de programación, aprovechando configuraciones agnósticas de modelo y análisis asistido por TLDR, con soporte para GLM-5, Claude, Minimax o cualquier modelo configurado a través de la selección de modelo basada en ajustes.","fr":"Permet aux agents d''effectuer une validation de qualité complète sur 9 langages de programmation, en exploitant des configurations agnostiques de modèle et une analyse assistée par TLDR, avec un support pour GLM-5, Claude, Minimax ou tout modèle configuré via une sélection de modèle basée sur les paramètres.","de":"Ermächtigt Agenten, eine umfassende Qualitätsvalidierung in 9 Programmiersprachen durchzuführen, indem es modellagnostische Konfigurationen und TLDR-assistierte Analyse nutzt, mit Unterstützung für GLM-5, Claude, Minimax oder jedes konfigurierte Modell über eine modellbasierte Auswahl basierend auf Einstellungen.","pt":"Habilita os agentes a realizar uma verificação de qualidade abrangente em 9 linguagens de programação, utilizando configurações independentes de modelo e análise assistida por TLDR, com suporte para GLM-5, Claude, Minimax ou qualquer modelo configurado por meio da seleção de modelo baseada em configurações.","ru":"Позволяет агентам выполнять всестороннюю проверку качества на 9 языках программирования, используя настройки, независимые от модели, и анализ, поддерживаемый TLDR, с поддержкой GLM-5, Claude, Minimax или любой настроенной модели через настройки, управляемые выбором модели.","ar":"تمكّن الوكلاء من أداء التحقق الشامل من الجودة عبر 9 لغات برمجة، مستفيدة من التكوينات المستقلة عن النموذج والتحليل المدعوم من TLDR، مع دعم GLM-5 و Claude و Minimax أو أي نموذج مضبوط عبر اختيار النموذج الموجه بالتكوين."},"useCases":{"en":["Validating code quality across multiple programming languages","Analyzing development projects with TLDR-assisted insights","Configuring model-agnostic settings for flexible quality validation"],"zh":["跨多种编程语言验证代码质量","使用TLDR辅助洞察分析开发项目","配置模型无关设置以进行灵活的质量验证"],"ja":["複数のプログラミング言語を横断してコードの品質を検証する","TLDRアシストの洞察を使用して開発プロジェクトを分析する","モデル非依存の設定を構成して柔軟な品質の検証を実行する"],"ko":["여러 프로그래밍 언어를横断하여 코드 품질을 검증하는 것","TLDR 보조洞察을 사용하여 개발 프로젝트를 분석하는 것","모델 비의존 설정을 구성하여 유연한 품질 검증을 수행하는 것"],"es":["Validar la calidad del código en varios lenguajes de programación","Analizar proyectos de desarrollo con información asistida por TLDR","Configurar ajustes agnósticos de modelo para una validación de calidad flexible"],"fr":["Valider la qualité du code sur plusieurs langages de programmation","Analyser les projets de développement avec des informations assistées par TLDR","Configurer des paramètres agnostiques de modèle pour une validation de qualité flexible"],"de":["Überprüfen der Codequalität in mehreren Programmiersprachen","Analysieren von Entwicklungsprojekten mit TLDR-assistierten Erkenntnissen","Konfigurieren modellagnostischer Einstellungen für eine flexible Qualitätsvalidierung"],"pt":["Validar a qualidade do código em várias linguagens de programação","Analizar projetos de desenvolvimento com informações assistidas por TLDR","Configurar configurações independentes de modelo para validação de qualidade flexível"],"ru":["Проверка качества кода на нескольких языках программирования","Анализ проектов разработки с помощью информации, поддерживаемой TLDR","Настройка настроек, независимых от модели, для гибкой проверки качества"],"ar":["التحقق من جودة الكود عبر عدة لغات برمجة","تحليل مشاريع التطوير باستخدام المعلومات المدعومة من TLDR","تكوين إعدادات مستقلة عن النموذج للتحقق المرن من الجودة"]},"limitations":{"en":["Requires configuration in ~/.claude/settings.json or CLI/env vars","Limited to 9 supported programming languages"],"zh":["需要在~/.claude/settings.json或CLI/env vars中进行配置","仅限9种支持的编程语言"],"ja":["~/.claude/settings.jsonまたはCLI/env varsで構成する必要がある","9つのサポートされているプログラミング言語に限定される"],"ko":["~/.claude/settings.json 또는 CLI/env vars에서 구성해야 함","9개의 지원되는 프로그래밍 언어로 제한됨"],"es":["Requiere configuración en ~/.claude/settings.json o variables de entorno de CLI","Limitado a 9 lenguajes de programación compatibles"],"fr":["Nécessite une configuration dans ~/.claude/settings.json ou des variables d''environnement CLI","Limité à 9 langages de programmation pris en charge"],"de":["Erfordert Konfiguration in ~/.claude/settings.json oder CLI-Umgebungsvariablen","Begrenzt auf 9 unterstützte Programmiersprachen"],"pt":["Requer configuração em ~/.claude/settings.json ou CLI/env vars","Limitado a 9 linguagens de programação suportadas"],"ru":["Требует настройки в ~/.claude/settings.json или CLI/env vars","Ограничен 9 поддерживаемыми языками программирования"],"ar":["يتطلب تكوينا في ~/.claude/settings.json أو CLI/env vars","محدود بـ 9 لغات برمجة مدعومة"]},"version":4},"contentHash":"077990d7aba7c9c6bda44b48f4da8c257fcba4d2181d463e6491226b4bdfed3c","qualityScore":60}');
