INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alfredolopez80/multi-agent-ralph-loop/gates', 'gates', 'alfredolopez80', 'multi-agent-ralph-loop', 'community', 'gates alfredolopez80 multi-agent-ralph-loop community Gates provides quality validation across 9 programming languages with TLDR-assisted analysis, supporting model-agnostic configurations. It benefits developers working with AI agents. Gates提供多Agent AI编排和质量验证，支持9种编程语言和TLDR辅助分析 Gatesは多Agent AIオーケストレーションと品質検証を提供し、9つのプログラミング言語とTLDRアシスト分析をサポート Gates는 다중 에이전트 AI 오케스트레이션과 품질 검증을 제공하며 9가지 프로그래밍 언어와 TLDR 보조 분석을 지원합니다 Gates es una herramienta de validación de calidad para proyectos de AI que admite 9 lenguajes de programación con análisis asistido por TLDR Gates est un outil de validation de qualité pour les projets d''IA qui prend en charge 9 langages de programmation avec analyse assistée par TLDR Gates ist ein Qualitätsvalidierungstool für KI-Projekte, das 9 Programmiersprachen mit TLDR-assistierter Analyse unterstützt Gates é uma ferramenta de orquestração de agentes de IA que fornece validação de qualidade abrangente em 9 linguagens de programação. Gates - это инструмент оркестровки ИИ Агентов, который обеспечивает всестороннюю проверку качества на 9 языках программирования. Gates هي أداة لorchestration وكلاء الذكاء الاصطناعي التي توفر التحقق من جودة شامل في 9 لغات برمجة how to use gates gates setup guide gates alternative gates vs claude gates install model-agnostic quality validation TLDR-assisted analysis gates for AI agents gates configuration AIエージェント 多Agent AI编排 质量验证 GLM-4.7 PRIMARY Claude Codex Gemini TLDR辅助分析 模型无关 Uses model configured in ~/.claude/settings.json or CLI/env vars Supports model-agnostic configurations with GLM-5, Claude, and other models Provides TLDR-assisted analysis for comprehensive quality validation Works with 9 programming languages Utilizes 67 hooks for flexible integration Deprecates MiniMax for improved performance Gates is a multi-agent AI orchestration skill with quality gates, memory system, and 67 hooks, utilizing models like GLM-4.7 PRIMARY, Claude, Codex, and Gemini.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AgentWorkforce/relay/creating-skills', 'community', 'AgentWorkforce', 'relay', 'AgentWorkforce/relay', 'creating-skills', 0, 0, 60, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:12.297Z', '2d5916eb2f7648cdb34fd17df7a5975a69eafd4f3265e96bc0f52b3b2d10df7a', '{"id":"AgentWorkforce/relay/creating-skills","name":"creating-skills","description":{"en":"Creating-Skills enables real-time agent-to-agent communication, providing reference guides for proven techniques and patterns. It benefits developers by offering a framework for creating effective approaches.","zh":"创建技能是实现AI智能代理实时通信和高效开发的关键，通过发现、扫描和执行的原则","ja":"スキルの作成はAIエージェント開発の重要なステップで、発見、スキャン、実行の原則を遵守","ko":"스킬 생성은 AI 에이전트 개발의 핵심으로서 발견, 스캔, 실행의 원칙을 따릅니다","es":"Las habilidades son guías de referencia para técnicas, patrones o herramientas comprobadas. Están diseñadas para ayudar a futuras instancias de Claude a encontrar y aplicar enfoques efectivos de manera rápida.","fr":"Les compétences sont des guides de référence pour des techniques, des modèles ou des outils éprouvés. Elles sont conçues pour aider les futures instances de Claude à trouver et à appliquer des approches efficaces rapidement.","de":"Fähigkeiten sind Referenzleitfäden für bewährte Techniken, Muster oder Tools. Sie sind dazu da, zukünftigen Claude-Instanzen zu helfen, effektive Ansätze schnell zu finden und anzuwenden.","pt":"Criar habilidades para comunicação em tempo real entre agentes é fundamental para melhorar a colaboração e a eficiência. Descubra como criar habilidades práticas e escaláveis","ru":"Создание навыков для реального взаимодействия ИИ Агентов является важным для улучшения сотрудничества и эффективности. Узнайте, как создать практические и масштабируемые навыки","ar":"إنشاء مهارات للتواصل في الوقت الفعلي بين وكلاء الذكاء الاصطناعي هو أمر أساسي لتحسين التعاون والكفاءة. تعلم كيفية إنشاء مهارات عملية ومتطورة"},"seo":{"title":{"en":"Creating-Skills: Real-Time Agent Communication Setup Guid...","zh":"创建技能 Setup Guide - AI智能代理技术","ja":"スキルの作成 Best Practices - AIエージェント開発","ko":"스킬 생성 튜토리얼 - AI 에이전트 개발 가이드","es":"Guía de Configuración para Crear Habilidades de Agentes d...","fr":"Guide de Configuration pour la Création de Compétences d''...","de":"Konfigurationsleitfaden für die Erstellung von Fähigkeite...","pt":"Guia de Criação de Habilidades para Comunicação em Tempo ...","ru":"Руководство по созданию навыков для реального взаимодейст...","ar":"دليل إنشاء مهارات للتواصل في الوقت الفعلي بين وكلاء الذكا..."},"description":{"en":"Unlock efficient agent-to-agent communication with Creating-Skills. Discover how to create discoverable, scannable, and actionable skills for future Claude i...","zh":"了解创建技能的技术细节，实现AI智能代理的实时通信和高效开发","ja":"AIエージェント開発を効率化するスキルの作成方法と技術を紹介","ko":"AI 에이전트 개발을 위한 스킬 생성의 핵심 원리와 기술적 내용을 확인하세요","es":"Aprende a crear habilidades para agentes de IA con nuestra guía paso a paso. Mejora la comunicación en tiempo real entre agentes.","fr":"Découvrez comment créer des compétences pour les agents d''IA avec notre guide étape par étape. Améliorez la communication en temps réel entre les agents.","de":"Erfahren Sie, wie Sie Fähigkeiten für KI-Agents erstellen, mit unserem Schritt-für-Schritt-Leitfaden. Verbessern Sie die Echtzeitkommunikation zwischen den A...","pt":"Aprenda a criar habilidades para comunicação em tempo real entre agentes com esse guia prático e descubra como melhorar a colaboração entre os agentes","ru":"Узнайте, как создать навыки для реального взаимодействия ИИ Агентов с помощью этого практического руководства и улучшите сотрудничество между агентами","ar":"تعلم كيفية إنشاء مهارات للتواصل في الوقت الفعلي بين وكلاء الذكاء الاصطناعي مع هذا الدليل العملي واكتشف كيفية تحسين التعاون بين الوكلاء"},"definition":{"en":"Creating-skills is a technical framework for developing reference guides that facilitate real-time agent communication, emphasizing discoverability, scannability, and actionability.","zh":"创建技能是指开发AI智能代理的参考指南，涵盖技术、模式和工具","ja":"スキルの作成はAIエージェント開発のための参考ガイドで、テクニック、パターン、ツールを含む","ko":"스킬 생성은 AI 에이전트 개발을 위한 참조 가이드로서 기술, 패턴, 툴을 포함합니다","es":"Una habilidad es una guía de referencia para técnicas y patrones comprobados que ayuda a los agentes de IA a encontrar y aplicar enfoques efectivos.","fr":"Une compétence est un guide de référence pour des techniques et des modèles éprouvés qui aide les agents d''IA à trouver et à appliquer des approches efficaces.","de":"Eine Fähigkeit ist ein Referenzleitfaden für bewährte Techniken und Muster, der KI-Agents hilft, effektive Ansätze zu finden und anzuwenden.","pt":"Habilidades são guias de referência para técnicas, padrões ou ferramentas comprovadas que ajudam os agentes a encontrar e aplicar abordagens eficazes","ru":"Навыки - это справочные руководства для проверенных техник, шаблонов или инструментов, которые помогают ИИ Агентам быстро найти и применить эффективные подходы","ar":"المهارات هي أدلة مرجعية لتقنيات أو أنماط أو أدوات مثبتة تساعد وكلاء الذكاء الاصطناعي على العثور على وتطبيق نهج فعال"},"features":{"en":["Enables discoverable skills for future Claude instances","Supports scannable skills for quick evaluation","Provides actionable examples for effective approaches","Follows core principle of assuming Claude''s existing intelligence","Allows creation of skills for proven techniques and patterns"],"zh":["实时通信技术","发现和扫描原则","执行和应用的清晰示例","默认假设AI智能代理已经很智能","只添加AI智能代理没有的上下文"],"ja":["リアルタイム通信技術","発見とスキャンの原則","実行と適用の明確な例","デフォルトの仮定はAIエージェントがすでに賢い","AIエージェントにないコンテキストのみを追加"],"ko":["실시간 통신 기술","발견과 스캔의 원칙","실행과 적용의 명확한 예","기본 가정은 AI 에이전트가 이미賢い","AI 에이전트에 없는 컨텍스트만 추가"],"es":["Comunicación en tiempo real entre agentes","Guías de referencia para técnicas comprobadas","Diseño para ser fácilmente descubribles y evaluable","Ejemplos claros para una implementación efectiva","Apoyo para el principio de que Claude ya es muy inteligente","Solo se agregan contextos que Claude no tenga"],"fr":["Communication en temps réel entre les agents","Guides de référence pour des techniques éprouvées","Conception pour être facilement découvrables et évaluables","Exemples clairs pour une mise en œuvre efficace","Support pour le principe que Claude est déjà très intelligent","Seuls les contextes que Claude n''a pas sont ajoutés"],"de":["Echtzeitkommunikation zwischen Agents","Referenzleitfäden für bewährte Techniken","Entwurf, um leicht auffindbar und bewertbar zu sein","Klare Beispiele für eine effektive Implementierung","Unterstützung für das Prinzip, dass Claude bereits sehr intelligent ist","Nur Kontexte, die Claude nicht hat, werden hinzugefügt"],"pt":["Comunicação em tempo real entre agentes","Criação de habilidades escaláveis e práticas","Integração com técnicas e padrões comprovados","Melhoria da colaboração e eficiência entre os agentes","Desenvolvimento de habilidades descobríveis e avaliáveis","Aplicação de exemplos claros e ação"],"ru":["Реальное взаимодействие ИИ Агентов","Создание масштабируемых и практических навыков","Интеграция с проверенными техниками и шаблонами","Улучшение сотрудничества и эффективности между агентами","Разработка навыков, обнаруживаемых и оцениваемых","Применение четких примеров и действий"],"ar":["التواصل في الوقت الفعلي بين وكلاء الذكاء الاصطناعي","إنشاء مهارات متطورة وعملية","التكامل مع تقنيات وأنماط مثبتة","تحسين التعاون والكفاءة بين الوكلاء","تطوير مهارات يمكن اكتشافها وتقييمها","تطبيق أمثلة واضحة وعمليات"]},"keywords":{"en":["how to use creating-skills","what is creating-skills","creating-skills alternative","creating-skills vs other AI skills","creating-skills install","creating-skills setup guide","real-time agent communication","Claude instance skills","actionable skill examples"],"zh":["AI智能代理","创建技能","实时通信","发现和扫描","执行和应用","AI开发","智能代理技术"],"ja":["AIエージェント","スキルの作成","リアルタイム通信","発見とスキャン","実行と適用","AI開発","エージェント技術"],"ko":["AI 에이전트","스킬 생성","실시간 통신","발견과 스캔","실행과 적용","AI 개발","에이전트 기술"],"es":["crear habilidades para agentes de IA","guía de configuración para agentes de inteligencia artificial","comunicación en tiempo real entre agentes","técnicas comprobadas para agentes de IA","desarrollo de habilidades para Claude","agentes de inteligencia artificial","IA Éagents","creación de competencias para IA"],"fr":["créer des compétences pour les agents d''IA","guide de configuration pour les agents d''intelligence artificielle","communication en temps réel entre les agents","techniques éprouvées pour les agents d''IA","développement de compétences pour Claude","agents d''intelligence artificielle","IA Agents","création de compétences pour l''IA"],"de":["Fähigkeiten für KI-Agents erstellen","Konfigurationsleitfaden für KI-Agents","Echtzeitkommunikation zwischen Agents","bewährte Techniken für KI-Agents","Entwicklung von Fähigkeiten für Claude","KI-Agents","Künstliche Intelligenz Agents","Erstellung von Fähigkeiten für KI"],"pt":["criação de habilidades","comunicação em tempo real","agentes de inteligência artificial","desenvolvimento de habilidades","colaboração entre agentes","eficiência e produtividade","técnicas e padrões comprovados","guias de referência para agentes"],"ru":["создание навыков","реальное взаимодействие ИИ Агентов","ИИ Агенты","разработка навыков","сотрудничество между агентами","эффективность и производительность","проверенные техники и шаблоны","справочные руководства для ИИ Агентов"],"ar":["إنشاء مهارات","التواصل في الوقت الفعلي بين وكلاء الذكاء الاصطناعي","وكلاء الذكاء الاصطناعي","تطوير مهارات","التعاون بين الوكلاء","الكفاءة والإنتاجية","تقنيات وأنماط مثبتة","دلائل مرجعية ل وكلاء الذكاء الاصطناعي"]}},"owner":"AgentWorkforce","repo":"relay","repoPath":"AgentWorkforce/relay","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.295Z","topics":[],"category":"community","skillMd":{"name":"creating-skills","description":"Use when creating new Claude Code skills or improving existing ones - ensures skills are discoverable, scannable, and effective through proper structure, CSO optimization, and real examples","bodyPreview":"# Creating Skills\n\n## Overview\n\n**Skills are reference guides for proven techniques, patterns, or tools.** Write them to help future Claude instances quickly find and apply effective approaches.\n\nSkills must be **discoverable** (Claude can find them), **scannable** (quick to evaluate), and **actionable** (clear examples).\n\n**Core principle**: Default assumption is Claude is already very smart. Only add context Claude doesn''t already have.\n\n## When to Use\n\n**Create a skill when:**\n- Technique was","body":"# Creating Skills\n\n## Overview\n\n**Skills are reference guides for proven techniques, patterns, or tools.** Write them to help future Claude instances quickly find and apply effective approaches.\n\nSkills must be **discoverable** (Claude can find them), **scannable** (quick to evaluate), and **actionable** (clear examples).\n\n**Core principle**: Default assumption is Claude is already very smart. Only add context Claude doesn''t already have.\n\n## When to Use\n\n**Create a skill when:**\n- Technique wasn''t intuitively obvious\n- Pattern applies broadly across projects\n- You''d reference this again\n- Others would benefit\n\n**Don''t create for:**\n- One-off solutions specific to single project\n- Standard practices well-documented elsewhere\n- Project conventions (put those in `.claude/CLAUDE.md`)\n\n## Required Structure\n\n### Frontmatter (YAML)\n\n```yaml\n---\nname: skill-name-with-hyphens\ndescription: Use when [triggers/symptoms] - [what it does and how it helps]\ntags: relevant-tags\n---\n```\n\n**Rules:**\n- Only `name` and `description` fields supported (max 1024 chars total)\n- Name: letters, numbers, hyphens only (max 64 chars). Use gerund form (verb + -ing)\n- Avoid reserved words: \"anthropic\", \"claude\" in names\n- Description: Third person, starts with \"Use when...\" (max 1024 chars)\n- Include BOTH triggering conditions AND what skill does\n- Match specificity to task complexity (degrees of freedom)\n\n### Document Structure\n\n```markdown\n# Skill Name\n\n## Overview\nCore principle in 1-2 sentences. What is this?\n\n## When to Use\n- Bullet list with symptoms and use cases\n- When NOT to use\n\n## Quick Reference\nTable or bullets for common operations\n\n## Implementation\nInline code for simple patterns\nLink to separate file for heavy reference (100+ lines)\n\n## Common Mistakes\nWhat goes wrong + how to fix\n\n## Real-World Impact (optional)\nConcrete results from using this technique\n```\n\n## Degrees of Freedom\n\n**Match specificity to task complexity:**\n\n- **High freedom**: Flexible tasks requiring judgment\n  - Use broad guidance, principles, examples\n  - Let Claude adapt approach to context\n  - Example: \"Use when designing APIs - provides REST principles and patterns\"\n\n- **Low freedom**: Fragile or critical operations\n  - Be explicit about exact steps\n  - Include validation checks\n  - Example: \"Use when deploying to production - follow exact deployment checklist with rollback procedures\"\n\n**Red flag**: If skill tries to constrain Claude too much on creative tasks, reduce specificity. If skill is too vague on critical operations, add explicit steps.\n\n## Claude Search Optimization (CSO)\n\n**Critical:** Future Claude reads the description to decide if skill is relevant. Optimize for discovery.\n\n### Description Best Practices\n\n```yaml\n# ❌ BAD - Too vague, doesn''t mention when to use\ndescription: For async testing\n\n# ❌ BAD - First person (injected into system prompt)\ndescription: I help you with flaky tests\n\n# ✅ GOOD - Triggers + what it does\ndescription: Use when tests have race conditions or pass/fail inconsistently - replaces arbitrary timeouts with condition polling for reliable async tests\n\n# ✅ GOOD - Technology-specific with explicit trigger\ndescription: Use when using React Router and handling auth redirects - provides patterns for protected routes and auth state management\n```\n\n### Keyword Coverage\n\nUse words Claude would search for:\n- **Error messages**: \"ENOENT\", \"Cannot read property\", \"Timeout\"\n- **Symptoms**: \"flaky\", \"hanging\", \"race condition\", \"memory leak\"\n- **Synonyms**: \"cleanup/teardown/afterEach\", \"timeout/hang/freeze\"\n- **Tools**: Actual command names, library names, file types\n\n### Naming Conventions\n\n**Use gerund form (verb + -ing):**\n- ✅ `creating-skills` not `skill-creation`\n- ✅ `testing-with-subagents` not `subagent-testing`\n- ✅ `debugging-memory-leaks` not `memory-leak-debugging`\n- ✅ `processing-pdfs` not `pdf-processor`\n- ✅ `analyzing-spreadsheets` not `spreadsheet-analysis`\n\n**Why gerunds work:**\n- Describes the action you''re taking\n- Active and clear\n- Consistent with Anthropic conventions\n\n**Avoid:**\n- ❌ Vague names like \"Helper\" or \"Utils\"\n- ❌ Passive voice constructions\n\n## Code Examples\n\n**One excellent example beats many mediocre ones.**\n\n### Choose Language by Use Case\n\n- Testing techniques → TypeScript/JavaScript\n- System debugging → Shell/Python\n- Data processing → Python\n- API calls → TypeScript/JavaScript\n\n### Good Example Checklist\n\n- [ ] Complete and runnable\n- [ ] Well-commented explaining **WHY** not just what\n- [ ] From real scenario (not contrived)\n- [ ] Shows pattern clearly\n- [ ] Ready to adapt (not generic template)\n- [ ] Shows both BAD (❌) and GOOD (✅) approaches\n- [ ] Includes realistic context/setup code\n\n### Example Template\n\n```typescript\n// ✅ GOOD - Clear, complete, ready to adapt\ninterface RetryOptions {\n  maxAttempts: number;\n  delayMs: number;\n  backoff?: ''linear'' | ''exponential'';\n}\n\nasync function retryOperation<T>(\n  operation: () => Promise<T>,\n  options: RetryOptions\n): Promise<T> {\n  const { maxAttempts, delayMs, backoff = ''linear'' } = options;\n\n  for (let attempt = 1; attempt <= maxAttempts; attempt++) {\n    try {\n      return await operation();\n    } catch (error) {\n      if (attempt === maxAttempts) throw error;\n\n      const delay = backoff === ''exponential''\n        ? delayMs * Math.pow(2, attempt - 1)\n        : delayMs * attempt;\n\n      await new Promise(resolve => setTimeout(resolve, delay));\n    }\n  }\n\n  throw new Error(''Unreachable'');\n}\n\n// Usage\nconst data = await retryOperation(\n  () => fetchUserData(userId),\n  { maxAttempts: 3, delayMs: 1000, backoff: ''exponential'' }\n);\n```\n\n### Don''t\n\n- ❌ Implement in 5+ languages (you''re good at porting)\n- ❌ Create fill-in-the-blank templates\n- ❌ Write contrived examples\n- ❌ Show only code without comments\n\n## File Organization\n\n### Self-Contained (Preferred)\n\n```\ntypescript-type-safety/\n  SKILL.md    # Everything inline\n```\n\n**When:** All content fits in ~500 words, no heavy reference needed\n\n### With Supporting Files\n\n```\napi-integration/\n  SKILL.md           # Overview + patterns\n  retry-helpers.ts   # Reusable code\n  examples/\n    auth-example.ts\n    pagination-example.ts\n```\n\n**When:** Reusable tools or multiple complete examples needed\n\n### With Heavy Reference\n\n```\naws-sdk/\n  SKILL.md       # Overview + workflows\n  s3-api.md      # 600 lines API reference\n  lambda-api.md  # 500 lines API reference\n```\n\n**When:** Reference material > 100 lines\n\n## Token Efficiency\n\nSkills load into every conversation. Keep them concise.\n\n### Target Limits\n\n- **SKILL.md**: Keep under 500 lines\n- Getting-started workflows: <150 words\n- Frequently-loaded skills: <200 words total\n- Other skills: <500 words\n- Files > 100 lines: Include table of contents\n\n**Challenge each piece of information**: \"Does Claude really need this explanation?\"\n\n### Compression Techniques\n\n```markdown\n# ❌ BAD - Verbose (42 words)\nYour human partner asks: \"How did we handle authentication errors in React Router before?\"\nYou should respond: \"I''ll search past conversations for React Router authentication patterns.\"\nThen dispatch a subagent with the search query: \"React Router authentication error handling 401\"\n\n# ✅ GOOD - Concise (20 words)\nPartner: \"How did we handle auth errors in React Router?\"\nYou: Searching...\n[Dispatch subagent → synthesis]\n```\n\n**Techniques:**\n- Reference tool `--help` instead of documenting all flags\n- Cross-reference other skills instead of repeating content\n- Show minimal example of pattern\n- Eliminate redundancy\n- Use progressive disclosure (reference additional files as needed)\n- Organize content by domain for focused context\n\n## Workflow Recommendations\n\nFor multi-step processes, include:\n\n1. **Clear sequential steps**: Break complex tasks into numbered operations\n2. **Feedback loops**: Build in verification/validation steps\n3. **Error handling**: What to check when things go wrong\n4. **Checklists**: For processes with many steps or easy-to-miss details\n\n**Example structure:**\n```markdown\n## Workflow\n\n1. **Preparation**\n   - Check prerequisites\n   - Validate environment\n\n2. **Execution**\n   - Step 1: [action + expected result]\n   - Step 2: [action + expected result]\n\n3. **Verification**\n   - [ ] Check 1 passes\n   - [ ] Check 2 passes\n\n4. **Rollback** (if needed)\n   - Steps to undo changes\n```\n\n## Common Mistakes\n\n| Mistake | Why It Fails | Fix |\n|---------|--------------|-----|\n| Narrative example | \"In session 2025-10-03...\" | Focus on reusable pattern |\n| Multi-language dilution | Same example in 5 languages | One excellent example |\n| Code in flowcharts | `step1 [label=\"import fs\"]` | Use markdown code blocks |\n| Generic labels | helper1, helper2, step3 | Use semantic names |\n| Missing description triggers | \"For testing\" | \"Use when tests are flaky...\" |\n| First-person description | \"I help you...\" | \"Use when... - provides...\" |\n| Deeply nested file references | Multiple @ symbols, complex paths | Keep references simple and direct |\n| Windows-style file paths | `C:\\path\\to\\file` | Use forward slashes |\n| Offering too many options | 10 different approaches | Focus on one proven approach |\n| Punting error handling | \"Claude figures it out\" | Include explicit error handling in scripts |\n| Time-sensitive information | \"As of 2025...\" | Keep content evergreen |\n| Inconsistent terminology | Mixing synonyms randomly | Use consistent terms throughout |\n\n## Flowchart Usage\n\n**Only use flowcharts for:**\n- Non-obvious decision points\n- Process loops where you might stop too early\n- \"When to use A vs B\" decisions\n\n**Never use for:**\n- Reference material → Use tables/lists\n- Code examples → Use markdown blocks\n- Linear instructions → Use numbered lists\n\n## Cross-Referencing Skills\n\n```markdown\n# ✅ GOOD - Name only with clear requirement\n**REQUIRED:** Use superpowers:test-driven-development before proceeding\n\n**RECOMMENDED:** See typescript-type-safety for proper type guards\n\n# ❌ BAD - Unclear if required\nSee skills/testing/test-driven-development\n\n# ❌ BAD - Force-loads file, wastes context\n@skills/testing/test-driven-development/SKILL.md\n```\n\n## Advanced Practices\n\n### Iterative Development\n\n**Best approach**: Develop skills iteratively with Claude\n1. Start with minimal viable skill\n2. Test with real use cases\n3. Refine based on what works\n4. Remove what doesn''t add value\n\n### Build Evaluations First\n\nBefore extensive documentation:\n1. Create test scenarios\n2. Identify what good looks like\n3. Document proven patterns\n4. Skip theoretical improvements\n\n### Utility Scripts\n\nFor reliability, provide:\n- Scripts with explicit error handling (don''t defer errors to Claude)\n- Exit codes for success/failure\n- Clear error messages\n- Examples of usage\n- List required dependencies explicitly\n\n**Example:**\n```bash\n#!/bin/bash\nset -e  # Exit on error\n\nif [ ! -f \"config.json\" ]; then\n  echo \"Error: config.json not found\" >&2\n  exit 1\nfi\n\n# Script logic here\necho \"Success\"\nexit 0\n```\n\n### Verifiable Intermediate Outputs\n\nFor complex operations, create validation checkpoints:\n1. Have Claude produce a structured plan file\n2. Validate the plan with a script\n3. Execute only after validation passes\n\nThis catches errors before they compound.\n\n### Templates for Structured Output\n\nWhen skills produce consistent formats:\n```markdown\n## Output Template\n\n\\`\\`\\`typescript\ninterface ExpectedOutput {\n  status: ''success'' | ''error'';\n  data: YourDataType;\n  errors?: string[];\n}\n\\`\\`\\`\n\n**Usage**: Copy and adapt for your context\n```\n\n## Skill Creation Checklist\n\n**Before writing:**\n- [ ] Technique isn''t obvious or well-documented elsewhere\n- [ ] Pattern applies broadly (not project-specific)\n- [ ] I would reference this across multiple projects\n\n**Frontmatter:**\n- [ ] Name uses only letters, numbers, hyphens\n- [ ] Description starts with \"Use when...\"\n- [ ] Description includes triggers AND what skill does\n- [ ] Description is third person\n- [ ] Total frontmatter < 1024 characters\n\n**Content:**\n- [ ] Overview states core principle (1-2 sentences)\n- [ ] \"When to Use\" section with symptoms\n- [ ] Quick reference table for common operations\n- [ ] One excellent code example (if technique skill)\n- [ ] Common mistakes section\n- [ ] Keywords throughout for searchability\n\n**Quality:**\n- [ ] Word count appropriate for frequency (see targets above)\n- [ ] SKILL.md under 500 lines\n- [ ] No narrative storytelling\n- [ ] Flowcharts only for non-obvious decisions\n- [ ] Supporting files only if needed (100+ lines reference)\n- [ ] Cross-references use skill name, not file paths\n- [ ] No time-sensitive information\n- [ ] Consistent terminology throughout\n- [ ] Concrete examples (not templates)\n- [ ] Degrees of freedom match task complexity\n\n**Testing:**\n- [ ] Tested with Claude Haiku, Sonnet, and Opus (instructions effective for Opus may need more detail for Haiku)\n- [ ] Tested with subagent scenarios (if discipline-enforcing skill)\n- [ ] Addresses common rationalizations\n- [ ] Includes red flags list\n\n## Directory Structure\n\n```\nskills/\n  skill-name/\n    SKILL.md              # Required\n    supporting-file.*     # Optional\n    examples/             # Optional\n      example1.ts\n    scripts/              # Optional\n      helper.py\n```\n\n**Flat namespace** - all skills in one searchable directory\n\n## Real-World Impact\n\n**Good skills:**\n- Future Claude finds them quickly (CSO optimization)\n- Can be scanned in seconds (quick reference)\n- Provide clear actionable examples\n- Prevent repeating same research\n- Stay under 500 lines (token efficient)\n- Match specificity to task needs (right degrees of freedom)\n\n**Bad skills:**\n- Get ignored (vague description)\n- Take too long to evaluate (no quick reference)\n- Leave gaps in understanding (no examples)\n- Waste token budget (verbose explanations of obvious things)\n- Over-constrain creative tasks or under-specify critical operations\n- Include time-sensitive or obsolete information\n\n---\n\n**Remember:** Skills are for future Claude, not current you. Optimize for discovery, scanning, and action.\n\n**Golden rule:** Default assumption is Claude is already very smart. Only add context Claude doesn''t already have."},"lastSynced":"2026-03-08T02:01:12.297Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced AI Agents like Claude, AutoGPT, and LangChain needing structured skill development for real-time agent-to-agent communication.","zh":"非常适合像 Claude、AutoGPT 和 LangChain 这样的高级 AI 代理，需要结构化的技能开发以实现代理之间的实时通信。","ja":"Claude、AutoGPT、LangChain などの高度な AI エージェントにとって最適であり、エージェント間のリアルタイム通信のための構造化されたスキル開発が必要です。","ko":"Claude, AutoGPT, LangChain 등의 고급 AI 에이전트에게 적합하며, 에이전트 간 실시간 통신을 위해 구조화된 기술 개발이 필요합니다.","es":"Perfecto para Agentes de IA Avanzados como Claude, AutoGPT y LangChain que necesitan un desarrollo de habilidades estructurado para la comunicación en tiempo real entre agentes.","fr":"Parfait pour les Agents d''IA Avancés comme Claude, AutoGPT et LangChain ayant besoin d''un développement de compétences structuré pour la communication en temps réel entre agents.","de":"Perfekt für fortschrittliche KI-Agents wie Claude, AutoGPT und LangChain, die ein strukturiertes Fähigkeitsentwicklung für Echtzeit-Kommunikation zwischen Agenten benötigen.","pt":"Perfeito para Agentes de IA Avançados como Claude, AutoGPT e LangChain que necessitam de desenvolvimento de habilidades estruturadas para comunicação em tempo real entre agentes.","ru":"Идеально подходит для продвинутых агентов ИИ, таких как Claude, AutoGPT и LangChain, которым требуется структурированное развитие навыков для реального взаимодействия агентов.","ar":"مثالي لعميل الذكاء الاصطناعي المتقدم مثل Claude و AutoGPT و LangChain الذين يحتاجون إلى تطوير مهارات منظم لاتصالات وكلاء الوقت الحقيقي."},"recommendation":{"en":"Empowers agents to create discoverable, scannable, and actionable reference guides for proven techniques and patterns using core principles that assume the agent is already very smart, providing context only where necessary, and leveraging real-time communication protocols.","zh":"使代理能够创建可发现、可扫描和可执行的参考指南，用于成熟的技术和模式，使用核心原则，假设代理已经非常智能，只在必要时提供上下文，并利用实时通信协议。","ja":"エージェントが、成熟したテクニックやパターンのための、検出可能、スキャナブル、かつ実行可能なリファレンスガイドを作成できるようにすることで、エージェントはすでに非常に賢いと仮定し、必要な場合にのみコンテキストを提供し、リアルタイム通信プロトコルを利用します。","ko":"에이전트가 검출 가능하고, 스캔 가능한 실행 가능한 참조 가이드를 만들 수 있도록 함으로써, 검증된 기술 및 패턴을 위한 코어 원칙을 사용하며, 에이전트가 이미 매우 지능적이라고 가정하고, 필요한 경우에만 컨텍스트를 제공하며, 실시간 통신 프로토콜을 활용합니다.","es":"Habilita a los agentes a crear guías de referencia descubribles, escaneables y accionables para técnicas y patrones comprobados utilizando principios básicos que asumen que el agente ya es muy inteligente, proporcionando contexto solo cuando sea necesario y aprovechando protocolos de comunicación en tiempo real.","fr":"Permet aux agents de créer des guides de référence découvrables, scannables et actionnables pour des techniques et des modèles éprouvés en utilisant des principes de base qui supposent que l''agent est déjà très intelligent, en fournissant un contexte uniquement lorsque nécessaire et en exploitant les protocoles de communication en temps réel.","de":"Ermächtigt Agents, handhabbare, scannbare und ausführbare Referenzhandbücher für bewährte Techniken und Muster zu erstellen, indem sie grundlegende Prinzipien verwenden, die davon ausgehen, dass der Agent bereits sehr intelligent ist, und nur dann Kontext bereitstellen, wenn dies erforderlich ist, und Echtzeit-Kommunikationsprotokolle nutzen.","pt":"Habilita os agentes a criar guias de referência descobríveis, analisáveis e ações comprovadas para técnicas e padrões comprovados usando princípios básicos que supõem que o agente já seja muito inteligente, fornecendo contexto apenas quando necessário e aproveitando protocolos de comunicação em tempo real.","ru":"Позволяет агентам создавать обнаруживаемые, сканируемые и действенные справочные материалы для проверенных методов и шаблонов, используя основные принципы, которые предполагают, что агент уже очень умён, предоставляя контекст только при необходимости и используя протоколы реального взаимодействия.","ar":"يتمكن العملاء من إنشاء أدلة مرجعية يمكن اكتشافها وقابلية المسح والإجراءات المثبته للتقنيات والأنماط المثبتة باستخدام المبادئ الأساسية التي تفترض أن العميل已经 ذكي للغاية ، وتوفير السياق فقط عند الحاجة واستخدام بروتوكولات التواصل في الوقت الفعلي."},"useCases":{"en":["Developing agent-to-agent communication frameworks","Creating reference guides for proven AI techniques","Enhancing agent discoverability and scannability"],"zh":["开发代理间通信框架","创建可发现和可扫描的参考指南用于成熟的 AI 技术","增强代理的可发现性和可扫描性"],"ja":["エージェント間通信フレームワークの開発","検出可能かつスキャナブルなリファレンスガイドの作成、成熟した AI テクニックのための","エージェントの検出可能性とスキャナビリティの強化"],"ko":["에이전트 간 통신 프레임워크 개발","검출 가능하고 스캔 가능한 참조 가이드 생성을 위한 검증된 AI 기술","에이전트의 검출 가능성 및 스캔 가능성 향상"],"es":["Desarrollar frameworks de comunicación entre agentes","Crear guías de referencia para técnicas de IA comprobadas","Mejorar la descubribilidad y escaneabilidad de los agentes"],"fr":["Développer des frameworks de communication entre agents","Créer des guides de référence pour des techniques d''IA éprouvées","Améliorer la découvrabilité et la scannabilité des agents"],"de":["Entwicklung von Kommunikationsframeworks zwischen Agenten","Erstellung von Referenzhandbüchern für bewährte KI-Techniken","Verbesserung der Auffindbarkeit und Scannierbarkeit von Agenten"],"pt":["Desenvolver estruturas de comunicação entre agentes","Criar guias de referência para técnicas de IA comprovadas","Melhorar a descobribilidade e a capacidade de varredura dos agentes"],"ru":["Разработка фреймворков для взаимодействия агентов","Создание справочных материалов для проверенных методов ИИ","Улучшение обнаруживаемости и сканируемости агентов"],"ar":["تنمية إطارات الاتصال بين العملاء","إنشاء أدلة مرجعية للتقنيات المثبته من الذكاء الاصطناعي","تحسين اكتشاف العملاء وقابلية المسح"]},"limitations":{"en":["Requires understanding of agent-to-agent communication principles","Assumes agent already possesses base intelligence"],"zh":["需要理解代理间通信原则","假设代理已经具备基础智能"],"ja":["エージェント間通信の原則を理解する必要がある","エージェントがすでに基本的な知能を持っていることを仮定する"],"ko":["에이전트 간 통신 원칙을 이해해야 함","에이전트가 이미 기본 지능을具备하고 있다고 가정"],"es":["Requiere comprensión de los principios de comunicación entre agentes","Supone que el agente ya posee inteligencia base"],"fr":["Nécessite une compréhension des principes de communication entre agents","Suppose que l''agent possède déjà une intelligence de base"],"de":["Benötigt das Verständnis von Kommunikationsprinzipien zwischen Agenten","Geht davon aus, dass der Agent bereits über eine Basisintelligenz verfügt"],"pt":["Exige compreensão dos princípios de comunicação entre agentes","Supõe que o agente já possua inteligência base"],"ru":["Требует понимания принципов взаимодействия агентов","Предполагает, что агент уже обладает базовым интеллектом"],"ar":["يتطلب فهم مبادئ اتصال العملاء","يفترض أن العميل يمتلك بالفعل ذكاء أساسي"]},"version":4},"contentHash":"2d5916eb2f7648cdb34fd17df7a5975a69eafd4f3265e96bc0f52b3b2d10df7a","qualityScore":60}');
