INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AgentWorkforce/relay/creating-skills', 'creating-skills', 'AgentWorkforce', 'relay', 'community', 'creating-skills AgentWorkforce relay community Creating-Skills enables real-time agent-to-agent communication, providing reference guides for proven techniques and patterns. It benefits developers by offering a framework for creating effective approaches. 创建技能是实现AI智能代理实时通信和高效开发的关键，通过发现、扫描和执行的原则 スキルの作成はAIエージェント開発の重要なステップで、発見、スキャン、実行の原則を遵守 스킬 생성은 AI 에이전트 개발의 핵심으로서 발견, 스캔, 실행의 원칙을 따릅니다 Las habilidades son guías de referencia para técnicas, patrones o herramientas comprobadas. Están diseñadas para ayudar a futuras instancias de Claude a encontrar y aplicar enfoques efectivos de manera rápida. Les compétences sont des guides de référence pour des techniques, des modèles ou des outils éprouvés. Elles sont conçues pour aider les futures instances de Claude à trouver et à appliquer des approches efficaces rapidement. Fähigkeiten sind Referenzleitfäden für bewährte Techniken, Muster oder Tools. Sie sind dazu da, zukünftigen Claude-Instanzen zu helfen, effektive Ansätze schnell zu finden und anzuwenden. Criar habilidades para comunicação em tempo real entre agentes é fundamental para melhorar a colaboração e a eficiência. Descubra como criar habilidades práticas e escaláveis Создание навыков для реального взаимодействия ИИ Агентов является важным для улучшения сотрудничества и эффективности. Узнайте, как создать практические и масштабируемые навыки إنشاء مهارات للتواصل في الوقت الفعلي بين وكلاء الذكاء الاصطناعي هو أمر أساسي لتحسين التعاون والكفاءة. تعلم كيفية إنشاء مهارات عملية ومتطورة how to use creating-skills what is creating-skills creating-skills alternative creating-skills vs other AI skills creating-skills install creating-skills setup guide real-time agent communication Claude instance skills actionable skill examples AI智能代理 创建技能 实时通信 发现和扫描 执行和应用 AI开发 智能代理技术 Enables discoverable skills for future Claude instances Supports scannable skills for quick evaluation Provides actionable examples for effective approaches Follows core principle of assuming Claude''s existing intelligence Allows creation of skills for proven techniques and patterns Creating-skills is a technical framework for developing reference guides that facilitate real-time agent communication, emphasizing discoverability, scannability, and actionability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zbruhnke/claude-code-starter/refresh-claude', 'community', 'zbruhnke', 'claude-code-starter', 'zbruhnke/claude-code-starter', 'refresh-claude', 0, 0, 60, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:14.509Z', '357a19d99d828cb14d5c26b06ece542c91c501b22eeb44b851879ca32ab868cf', '{"id":"zbruhnke/claude-code-starter/refresh-claude","name":"refresh-claude","description":{"en":"The refresh-claude skill updates the CLAUDE.md file to reflect the current state of the project, removing outdated information and adding new context. This benefits developers working with Claude Code.","zh":"refresh-claude 是一个生产就绪的 Claude Code 配置模板，具有栈预设、安全钩子和自动化工具，用于更新 CLAUDE.md 文件","ja":"refresh-claude は、CLAUDE.md ファイルを更新するために使用される、生産就緒の Claude Code 構成テンプレートであり、スタックのプリセット、セキュリティフック、および自動化ツールを備えています","ko":"refresh-claude는 CLAUDE.md 파일을 업데이트하는 데 사용되는 생산 준비가 된 Claude Code 구성 템플릿으로, 스택 프리셋, 보안 후크 및 자동화 도구가 포함되어 있습니다","es":"La habilidad refresh-claude actualiza tu archivo CLAUDE.md para mantenerlo relevante y útil para futuras sesiones de Claude Code, utilizando tecnologías como seguridad y automatización.","fr":"La compétence refresh-claude met à jour votre fichier CLAUDE.md pour le garder pertinent et utile pour les futures sessions de Claude Code, en utilisant des technologies telles que la sécurité et l''automatisation.","de":"Die Fähigkeit refresh-claude aktualisiert Ihre Datei CLAUDE.md, um sie für zukünftige Claude-Code-Sitzungen relevant und nützlich zu halten, unter Verwendung von Technologien wie Sicherheit und Automatisierung.","pt":"O Refresh Claude é um template de código de produção pronto para uso com stacks pré-definidos, hooks de segurança e ferramentas de automação","ru":"Refresh Claude - это шаблон кода для производства с предустановленными стеками, крючками безопасности и инструментами автоматизации","ar":"Refresh Claude هو قالب код جاهز للانتاج مع مكدس مسبق التعريف وأدوات أمان وآليّة"},"seo":{"title":{"en":"refresh-claude: CLAUDE.md Refresh Setup Guide | AI Agent ...","zh":"refresh-claude 设置指南：更新 CLAUDE.md 文件","ja":"refresh-claude セットアップガイド：CLAUDE.md ファイルの更新","ko":"refresh-claude 설정 가이드: CLAUDE.md 파일 업데이트","es":"Configuración de refresh-claude: Guía de Actualización de...","fr":"Mise à jour de refresh-claude: Guide de Configuration de ...","de":"Einrichtung von refresh-claude: Anleitung zur Aktualisier...","pt":"Guia de Configuração do Refresh Claude: Template de Códig...","ru":"Настройка Refresh Claude: шаблон кода для производства с ...","ar":"دليل إعداد Refresh Claude: قالب код جاهز للانتاج مع أدوات..."},"description":{"en":"Keep your CLAUDE.md file up-to-date with refresh-claude. Learn how to automate updates and ensure persistent context between sessions. Get started now!","zh":"使用 refresh-claude 更新 CLAUDE.md 文件，确保项目的持久性上下文保持相关性和实用性，AIエージェント","ja":"refresh-claude を使用して CLAUDE.md ファイルを更新し、プロジェクトの持続的なコンテキストを最新の状態に保ち、AIエージェント","ko":"refresh-claude를 사용하여 CLAUDE.md 파일을 업데이트하여 프로젝트의 지속적인 컨텍스트를 최신 상태로 유지하고, AI 툴","es":"Aprende a actualizar tu archivo CLAUDE.md con la habilidad refresh-claude, Herramientas de Inteligencia Artificial para desarrolladores","fr":"Découvrez comment mettre à jour votre fichier CLAUDE.md avec la compétence refresh-claude, Outils d''Intelligence Artificielle pour les développeurs","de":"Erfahren Sie, wie Sie Ihre Datei CLAUDE.md mit der Fähigkeit refresh-claude aktualisieren, KI-Tools für Entwickler","pt":"Aprenda a configurar o Refresh Claude, um template de código de produção pronto para uso com stacks pré-definidos, hooks de segurança e ferramentas de automação","ru":"Узнайте, как настроить Refresh Claude, шаблон кода для производства с предустановленными стеками, крючками безопасности и инструментами автоматизации с ИИ Аг...","ar":"تعرف على كيفية إعداد Refresh Claude، قالب код جاهز للانتاج مع مكدس مسبق التعريف وأدوات أمان وآليّة مع أدوات الذكاء الاصطناعي"},"definition":{"en":"refresh-claude is a production-ready Claude Code configuration template that reviews recent codebase changes, identifies new patterns, and updates CLAUDE.md accordingly.","zh":"refresh-claude 是一个更新 CLAUDE.md 文件的 AI 工具，用于保持项目的持久性上下文","ja":"refresh-claude は、プロジェクトの持続的なコンテキストを保持するために CLAUDE.md ファイルを更新する AI エージェントです","ko":"refresh-claude는 프로젝트의 지속적인 컨텍스트를 유지하기 위해 CLAUDE.md 파일을 업데이트하는 AI 툴입니다","es":"refresh-claude es una habilidad que actualiza el archivo CLAUDE.md para mantenerlo alineado con los cambios en el código","fr":"refresh-claude est une compétence qui met à jour le fichier CLAUDE.md pour le garder aligné avec les changements dans le code","de":"refresh-claude ist eine Fähigkeit, die die Datei CLAUDE.md aktualisiert, um sie mit den Änderungen im Code abzustimmen","pt":"O que é Refresh Claude? Um template de código de produção pronto para uso que atualiza o arquivo CLAUDE.md","ru":"Что такое Refresh Claude? Шаблон кода для производства, который обновляет файл CLAUDE.md с ИИ Агентами","ar":"ما هو Refresh Claude؟ قالب код جاهز للانتاج الذي يحدّث ملف CLAUDE.md مع أدوات الذكاء الاصطناعي"},"features":{"en":["Reviews recent changes to the codebase","Identifies new patterns, conventions, or important context","Updates CLAUDE.md to reflect current state","Removes outdated information","Analyzes codebase using stack presets and security hooks"],"zh":["更新 CLAUDE.md 文件以反映当前的代码库状态","识别新的模式、约定或重要的上下文","删除过时的信息","具有栈预设和安全钩子","自动化工具集成"],"ja":["CLAUDE.md ファイルを最新のコードベースの状態に更新する","新しいパターン、規約、または重要なコンテキストを識別する","古い情報を削除する","スタックのプリセットとセキュリティフックを備える","自動化ツールを統合する"],"ko":["CLAUDE.md 파일을 최신의 코드베이스 상태로 업데이트합니다","新的 패턴, 규약 또는 중요한 컨텍스트를 식별합니다","오래된 정보를 삭제합니다","스택 프리셋과 보안 후크를 제공합니다","자동화 도구를 통합합니다"],"es":["Revisión de cambios recientes en el código","Identificación de nuevos patrones y convenciones","Actualización de CLAUDE.md para reflejar el estado actual","Eliminación de información obsoleta","Seguridad y automatización integradas"],"fr":["Révision des changements récents dans le code","Identification de nouveaux modèles et conventions","Mise à jour de CLAUDE.md pour refléter l''état actuel","Élimination d''informations obsolètes","Sécurité et automatisation intégrées"],"de":["Überprüfung von aktuellen Änderungen im Code","Identifizierung neuer Muster und Konventionen","Aktualisierung von CLAUDE.md, um den aktuellen Zustand widerzuspiegeln","Entfernung veralteter Informationen","Sicherheit und Automatisierung integriert"],"pt":["Análise de alterações recentes no código","Identificação de novos padrões e convenções","Atualização do arquivo CLAUDE.md","Remoção de informações desatualizadas","Integração com stacks pré-definidos"],"ru":["Анализ недавних изменений в коде","Определение новых шаблонов и соглашений","Обновление файла CLAUDE.md","Удаление устаревшей информации","Интеграция с предустановленными стеками с ИИ Агентами"],"ar":["تحليل التغييرات الحديثة في الكود","تحديد الأنماط والاتفاقيات الجديدة","تحديث ملف CLAUDE.md","إزالة المعلومات القديمة","دمج المكدس المسبق التعريف مع أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use refresh-claude","what is refresh-claude","refresh-claude alternative","refresh-claude vs claude code","refresh-claude install","refresh-claude setup guide","claude code configuration template","automating CLAUDE.md updates"],"zh":["refresh-claude","CLAUDE.md 更新","AIエージェント","代码库管理","自动化工具","栈预设","安全钩子","持久性上下文"],"ja":["refresh-claude","CLAUDE.md 更新","AIエージェント","コードベース管理","自動化ツール","スタックのプリセット","セキュリティフック","持続的なコンテキスト"],"ko":["refresh-claude","CLAUDE.md 업데이트","AI 툴","코드베이스 관리","자동화 도구","스택 프리셋","보안 후크","지속적인 컨텍스트"],"es":["refresh-claude","CLAUDE.md","actualización de código","herramientas de inteligencia artificial","desarrollo de software","seguridad y automatización","configuración de CLAUDE.md","mejores prácticas para desarrolladores"],"fr":["refresh-claude","CLAUDE.md","mise à jour de code","outils d''intelligence artificielle","développement de logiciels","sécurité et automatisation","configuration de CLAUDE.md","meilleures pratiques pour les développeurs"],"de":["refresh-claude","CLAUDE.md","Code-Aktualisierung","KI-Tools","Software-Entwicklung","Sicherheit und Automatisierung","CLAUDE.md-Konfiguration","Best Practices für Entwickler"],"pt":["Refresh Claude","template de código de produção","CLAUDE.md","análise de código","identificação de padrões","atualização de arquivo","remoção de informações desatualizadas","integração com stacks"],"ru":["Refresh Claude","шаблон кода для производства","CLAUDE.md","анализ кода","определение шаблонов","обновление файла","удаление устаревшей информации","интеграция с предустановленными стеками","ИИ Агенты"],"ar":["Refresh Claude","قالب код جاهز للانتاج","CLAUDE.md","تحليل الكود","تحديد الأنماط","تحديث الملف","إزالة المعلومات القديمة","دمج المكدس المسبق التعريف","أدوات الذكاء الاصطناعي"]}},"owner":"zbruhnke","repo":"claude-code-starter","repoPath":"zbruhnke/claude-code-starter","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"refresh-claude","description":"Review recent changes and update CLAUDE.md to keep it relevant for future sessions. Use after significant changes or periodically to maintain context.","bodyPreview":"# Refresh CLAUDE.md\n\nYou are refreshing the project''s CLAUDE.md file to ensure it stays relevant and useful for future Claude Code sessions.\n\n## Purpose\n\nCLAUDE.md serves as persistent context between sessions. When a project evolves, CLAUDE.md should evolve too. This skill:\n\n1. Reviews recent changes to the codebase\n2. Identifies new patterns, conventions, or important context\n3. Updates CLAUDE.md to reflect current state\n4. Removes outdated information\n\n## Process\n\n### Step 1: Analyze Recent C","body":"# Refresh CLAUDE.md\n\nYou are refreshing the project''s CLAUDE.md file to ensure it stays relevant and useful for future Claude Code sessions.\n\n## Purpose\n\nCLAUDE.md serves as persistent context between sessions. When a project evolves, CLAUDE.md should evolve too. This skill:\n\n1. Reviews recent changes to the codebase\n2. Identifies new patterns, conventions, or important context\n3. Updates CLAUDE.md to reflect current state\n4. Removes outdated information\n\n## Process\n\n### Step 1: Analyze Recent Changes\n\n```bash\n# Recent commits\ngit log --oneline -20\n\n# Changed files\ngit diff --stat HEAD~10..HEAD\n\n# New files\ngit diff --name-status HEAD~10..HEAD | grep \"^A\"\n```\n\nLook for:\n- New features or modules\n- New dependencies or tools\n- Changed conventions or patterns\n- New commands or scripts\n- Architecture changes\n\n### Step 2: Review Current CLAUDE.md\n\nRead the existing CLAUDE.md and identify:\n- [ ] Outdated information\n- [ ] Missing new features/tools\n- [ ] Incorrect commands or paths\n- [ ] Stale conventions\n\n### Step 3: Scan the Codebase\n\nCheck for patterns not reflected in CLAUDE.md:\n\n```bash\n# Check for new test patterns\nls -la **/test* **/*test* **/*spec* 2>/dev/null | head -20\n\n# Check for new config files\nls -la *.config.* .* 2>/dev/null | head -20\n\n# Check package.json/pyproject.toml/etc for new scripts\ncat package.json 2>/dev/null | jq ''.scripts'' || true\n```\n\n### Step 4: Update CLAUDE.md\n\nMake targeted updates:\n\n**DO update:**\n- New commands (dev, test, build, lint)\n- New project structure (directories, key files)\n- New conventions discovered in code\n- Important architectural decisions\n- New dependencies that affect how to work with the code\n\n**DON''T add:**\n- Implementation details that change frequently\n- Obvious things (e.g., \"this is a JavaScript project\" for a .js repo)\n- Temporary workarounds\n- Personal preferences not enforced by tooling\n\n### Step 5: Verify Changes\n\nAfter updating, verify:\n- [ ] Commands still work\n- [ ] Paths are correct\n- [ ] No duplicate sections\n- [ ] Concise and scannable\n\n## Output Format\n\n```markdown\n## CLAUDE.md Refresh Summary\n\n### Changes Made\n- Added: [what was added]\n- Updated: [what was updated]\n- Removed: [what was removed]\n\n### Context Discovered\n- [New pattern or convention found]\n- [New tool or command found]\n\n### Recommendations\n- [Suggestions for project improvements]\n```\n\n## Guidelines\n\n### Keep It Concise\nCLAUDE.md should be scannable. Every line should earn its place.\n\n```\n❌ \"This project uses React, which is a JavaScript library for building user interfaces...\"\n✓ \"React 18 with TypeScript. See src/components/ for patterns.\"\n```\n\n### Focus on What''s Actionable\nInclude information Claude needs to work effectively:\n\n```\n✓ Commands to run\n✓ Key file locations\n✓ Conventions to follow\n✓ Things to avoid\n```\n\n### Avoid Duplication\nDon''t repeat what''s in:\n- README.md (user-facing docs)\n- Code comments (implementation details)\n- Config files (tooling handles it)\n\n### Keep It Fresh\nRemove information that''s:\n- No longer accurate\n- Covered by tooling (linters, formatters)\n- Too detailed for context\n\n## Example Updates\n\n### Adding a New Command\n```markdown\n## Commands\n+ npm run e2e        # Run end-to-end tests\n```\n\n### Adding a Convention\n```markdown\n## Conventions\n+ API routes follow REST conventions in `src/api/`\n+ Use `zod` for runtime validation at API boundaries\n```\n\n### Removing Outdated Info\n```markdown\n- ## Legacy\n- The old auth system in `src/auth-old/` is deprecated.\n```\n\n## When to Run\n\n- After adding major features\n- After significant refactoring\n- After adding new tools or dependencies\n- Periodically (weekly/monthly) on active projects\n- Before onboarding new team members\n"},"lastSynced":"2026-03-08T02:01:14.509Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents working with Claude Code, needing to maintain up-to-date project context.","zh":"适合与 Claude Code 合作的代码分析代理，需要保持项目上下文的最新状态。","ja":"Claude Code で作業するコード分析エージェントに最適で、プロジェクトのコンテキストを最新の状態に保つ必要があります。","ko":"클로드 코드와 협력하는 코드 분석 에이전트에게 적합하며, 프로젝트 컨텍스트를最新 상태로 유지해야 합니다.","es":"Ideal para Agentes de Análisis de Código que trabajan con Claude Code y necesitan mantener un contexto de proyecto actualizado.","fr":"Idéal pour les agents d''analyse de code travaillant avec Claude Code, ayant besoin de maintenir un contexte de projet à jour.","de":"Ideal für Code-Analyse-Agents, die mit Claude Code arbeiten und ein aktuelles Projekt-Kontext benötigen.","pt":"Ideal para Agentes de Análise de Código que trabalham com Claude Code, precisando manter o contexto do projeto atualizado.","ru":"Идеально подходит для Агентов анализа кода, работающих с Claude Code, необходимых для поддержания актуального контекста проекта.","ar":"مثالي لعميل تحليل الشفرة الذين يعملون مع Claude Code ، بحاجة إلى الحفاظ على سياق المشروع محدثًا."},"recommendation":{"en":"Empowers agents to keep CLAUDE.md files synchronized with the latest codebase changes, ensuring accurate context for future sessions by reviewing recent code modifications, identifying new patterns, and updating the CLAUDE.md file accordingly, utilizing Markdown format and file system access.","zh":"赋予代理保持 CLAUDE.md 文件与最新代码库更改同步的能力，通过审查最近的代码更改、识别新模式并相应地更新 CLAUDE.md 文件，以确保未来会话的准确上下文，利用 Markdown 格式和文件系统访问。","ja":"エージェントに、最新のコードベースの変更と同期された CLAUDE.md ファイルを維持する能力を付与し、最近のコード変更を確認し、新しいパターンを識別し、CLAUDE.md ファイルをそれに応じて更新し、将来のセッションの正確なコンテキストを確保するために、Markdown 形式とファイルシステムアクセスを使用します。","ko":"에이전트가 CLAUDE.md 파일을 최신 코드베이스 변경 사항과 동기화하여 유지할 수 있는 능력을 부여하고, 최근의 코드 변경을 검토하고, 새로운 패턴을 식별하고, CLAUDE.md 파일을 해당 패턴에 맞게 업데이트하여, 향후 세션의 정확한 컨텍스트를 보장하고, 마크다운 형식과 파일 시스템 액세스를 사용합니다.","es":"Permite a los agentes mantener los archivos CLAUDE.md sincronizados con los últimos cambios en el código, garantizando un contexto preciso para futuras sesiones al revisar las modificaciones recientes del código, identificar nuevos patrones y actualizar el archivo CLAUDE.md en consecuencia, utilizando el formato Markdown y el acceso al sistema de archivos.","fr":"Permet aux agents de maintenir les fichiers CLAUDE.md synchronisés avec les dernières modifications du codebase, assurant un contexte précis pour les futures sessions en révisant les modifications récentes du code, en identifiant de nouveaux modèles et en mettant à jour le fichier CLAUDE.md en conséquence, en utilisant le format Markdown et l''accès au système de fichiers.","de":"Ermöglicht es den Agenten, die CLAUDE.md-Dateien mit den neuesten Änderungen des Codebases zu synchronisieren, um so einen genauen Kontext für zukünftige Sitzungen sicherzustellen, indem die kürzlichen Code-Modifikationen überprüft, neue Muster identifiziert und die CLAUDE.md-Datei entsprechend aktualisiert werden, unter Verwendung des Markdown-Formats und des Dateisystemzugriffs.","pt":"Habilita os agentes a manterem os arquivos CLAUDE.md sincronizados com as últimas alterações no repositório de código, garantindo um contexto preciso para futuras sessões, revisando modificações recentes de código, identificando novos padrões e atualizando o arquivo CLAUDE.md de acordo, utilizando o formato Markdown e acesso ao sistema de arquivos.","ru":"Наделяет агентов возможностью поддерживать файлы CLAUDE.md в синхронизации с последними изменениями кодовой базы, обеспечивая точный контекст для будущих сессий, просматривая недавние изменения кода, выявляя новые закономерности и обновляя файл CLAUDE.md соответственно, используя формат Markdown и доступ к файловой системе.","ar":"تمكّن الوكيل من الحفاظ على ملفات CLAUDE.md متزامنة مع أحدث التغييرات في قاعدة الشفرة، مما يضمن سياقًا دقيقًا للجلسات المستقبلية من خلال xem التعديلات الأخيرة على الشفرة، وتحديد أنماط جديدة، وتحديث ملف CLAUDE.md وفقًا لذلك، باستخدام تنسيق Markdown ووصول نظام الملفات."},"useCases":{"en":["Updating CLAUDE.md after significant code refactorings","Maintaining project knowledge consistency across development sessions","Automating the removal of outdated information from CLAUDE.md files"],"zh":["在进行大量代码重构后更新 CLAUDE.md","在开发会话之间保持项目知识的一致性","自动从 CLAUDE.md 文件中删除过时的信息"],"ja":["大量なコードのリファクタリングを行った後、CLAUDE.md を更新する","開発セッション間でプロジェクトの知識の一貫性を維持する","CLAUDE.md ファイルから古い情報を自動的に削除する"],"ko":["대규모 코드 리팩토링 후 CLAUDE.md 업데이트","개발 세션 간 프로젝트 지식 일관성을 유지","CLAUDE.md 파일에서过时한 정보를 자동으로 제거"],"es":["Actualizar CLAUDE.md después de refactorizaciones de código significativas","Mantener la consistencia del conocimiento del proyecto en todas las sesiones de desarrollo","Automatizar la eliminación de información obsoleta de los archivos CLAUDE.md"],"fr":["Mettre à jour CLAUDE.md après des refactorisations de code significatives","Maintenir la cohérence des connaissances du projet au cours de toutes les sessions de développement","Automatiser la suppression d''informations obsolètes des fichiers CLAUDE.md"],"de":["CLAUDE.md nach bedeutenden Code-Refactorings aktualisieren","Die Konsistenz der Projektkenntnisse über alle Entwicklungs-Sitzungen hinweg aufrechterhalten","Die Entfernung veralteter Informationen aus den CLAUDE.md-Dateien automatisieren"],"pt":["Atualizar CLAUDE.md após refatorações significativas de código","Manter a consistência do conhecimento do projeto em todas as sessões de desenvolvimento","Automatizar a remoção de informações desatualizadas dos arquivos CLAUDE.md"],"ru":["Обновлять CLAUDE.md после значительных рефакторингов кода","Поддерживать согласованность знаний проекта на протяжении всех сессий разработки","Автоматизировать удаление устаревшей информации из файлов CLAUDE.md"],"ar":["تحديث CLAUDE.md بعد إعادة هيكلة الشفرة بشكل كبير","الحفاظ على tutaristency للمعرفة المشروع عبر جميع جلسات التطوير","تحديث تلقائي لمعلومات غير محدثة من ملفات CLAUDE.md"]},"limitations":{"en":["Requires access to the project''s filesystem to read and write CLAUDE.md files","Specifically designed for projects using Claude Code"],"zh":["需要访问项目的文件系统以读写 CLAUDE.md 文件","专门为使用 Claude Code 的项目设计"],"ja":["CLAUDE.md ファイルを読み書きするためにプロジェクトのファイルシステムにアクセスする必要がある","Claude Code を使用するプロジェクト専用に設計されている"],"ko":["CLAUDE.md 파일을 읽고 쓰기 위해 프로젝트 파일 시스템에 액세스해야 함","클로드 코드를 사용하는 프로젝트専用으로 설계"],"es":["Requiere acceso al sistema de archivos del proyecto para leer y escribir archivos CLAUDE.md","Diseñado específicamente para proyectos que utilizan Claude Code"],"fr":["Nécessite un accès au système de fichiers du projet pour lire et écrire des fichiers CLAUDE.md","Conçu spécifiquement pour les projets utilisant Claude Code"],"de":["Benötigt Zugriff auf das Dateisystem des Projekts, um CLAUDE.md-Dateien zu lesen und zu schreiben","Speziell für Projekte konzipiert, die Claude Code verwenden"],"pt":["Requer acesso ao sistema de arquivos do projeto para ler e gravar arquivos CLAUDE.md","Especificamente projetado para projetos que utilizam Claude Code"],"ru":["Требует доступа к файловой системе проекта для чтения и записи файлов CLAUDE.md","Специально разработан для проектов, использующих Claude Code"],"ar":["يتطلب الوصول إلى نظام ملفات المشروع لقراءة وكتابة ملفات CLAUDE.md","تم تصميمه خصيصًا لمشاريع التي تستخدم Claude Code"]},"version":4},"contentHash":"357a19d99d828cb14d5c26b06ece542c91c501b22eeb44b851879ca32ab868cf","qualityScore":60}');
