INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zbruhnke/claude-code-starter/refresh-claude', 'refresh-claude', 'zbruhnke', 'claude-code-starter', 'community', 'refresh-claude zbruhnke claude-code-starter community The refresh-claude skill updates the CLAUDE.md file to reflect the current state of the project, removing outdated information and adding new context. This benefits developers working with Claude Code. refresh-claude 是一个生产就绪的 Claude Code 配置模板，具有栈预设、安全钩子和自动化工具，用于更新 CLAUDE.md 文件 refresh-claude は、CLAUDE.md ファイルを更新するために使用される、生産就緒の Claude Code 構成テンプレートであり、スタックのプリセット、セキュリティフック、および自動化ツールを備えています refresh-claude는 CLAUDE.md 파일을 업데이트하는 데 사용되는 생산 준비가 된 Claude Code 구성 템플릿으로, 스택 프리셋, 보안 후크 및 자동화 도구가 포함되어 있습니다 La habilidad refresh-claude actualiza tu archivo CLAUDE.md para mantenerlo relevante y útil para futuras sesiones de Claude Code, utilizando tecnologías como seguridad y automatización. La compétence refresh-claude met à jour votre fichier CLAUDE.md pour le garder pertinent et utile pour les futures sessions de Claude Code, en utilisant des technologies telles que la sécurité et l''automatisation. Die Fähigkeit refresh-claude aktualisiert Ihre Datei CLAUDE.md, um sie für zukünftige Claude-Code-Sitzungen relevant und nützlich zu halten, unter Verwendung von Technologien wie Sicherheit und Automatisierung. O Refresh Claude é um template de código de produção pronto para uso com stacks pré-definidos, hooks de segurança e ferramentas de automação Refresh Claude - это шаблон кода для производства с предустановленными стеками, крючками безопасности и инструментами автоматизации Refresh Claude هو قالب код جاهز للانتاج مع مكدس مسبق التعريف وأدوات أمان وآليّة how to use refresh-claude what is refresh-claude refresh-claude alternative refresh-claude vs claude code refresh-claude install refresh-claude setup guide claude code configuration template automating CLAUDE.md updates refresh-claude CLAUDE.md 更新 AIエージェント 代码库管理 自动化工具 栈预设 安全钩子 持久性上下文 Reviews recent changes to the codebase Identifies new patterns, conventions, or important context Updates CLAUDE.md to reflect current state Removes outdated information Analyzes codebase using stack presets and security hooks refresh-claude is a production-ready Claude Code configuration template that reviews recent codebase changes, identifies new patterns, and updates CLAUDE.md accordingly.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('promptadvisers/n8n-powerhouse/n8n-workflow-architect', 'community', 'promptadvisers', 'n8n-powerhouse', 'promptadvisers/n8n-powerhouse', 'n8n-workflow-architect', 0, 0, 60, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:14.733Z', '95f2909fd121a155647f383d8711601c8faf2c8f123917b18f7f0539a940aef2', '{"id":"promptadvisers/n8n-powerhouse/n8n-workflow-architect","name":"n8n-workflow-architect","description":{"en":"The n8n-workflow-architect skill provides strategic guidance for building automation systems, helping users plan automation projects, integrate multiple services, and make informed architecture decisions. This skill benefits developers and automation specialists seeking to optimize their workflows.","zh":"n8n-workflow-architect是Claude Code技能框架的一部分，用于提供n8n自动化的战略指导","ja":"n8nワークフロー・アーキテクトは、Claude Codeスキルフレームワークの一部で、n8n自動化の戦略的ガイダンスを提供","ko":"n8n 워크플로우 아키텍트는 Claude Code 스킬 프레임워크의 일부로, n8n 자동화를 위한 전략적 가이드를 제공","es":"El arquitecto de flujos de trabajo n8n es un experto en automatización que ayuda a planificar proyectos y tomar decisiones informadas sobre la integración de servicios como Shopify, Klaviyo y Notion","fr":"L''architecte de workflow n8n est un expert en automatisation qui aide à planifier des projets et à prendre des décisions éclairées sur l''intégration de services tels que Shopify, Klaviyo et Notion","de":"Der n8n-Workflow-Architekt ist ein Automatisierungsexperte, der bei der Planung von Projekten und der fundierten Entscheidungsfindung über die Integration von Diensten wie Shopify, Klaviyo und Notion hilft","pt":"O n8n-workflow-architect é uma habilidade de automação que ajuda a planejar e implementar fluxos de trabalho complexos com integrações de serviços.","ru":"n8n-workflow-architect - это навык автоматизации, который помогает планировать и реализовывать сложные рабочие процессы с интеграцией сервисов.","ar":"n8n-workflow-architect هو مهارة تلقائية تساعد على تخطيط وتنفيذ تدفقات عمل معقدة مع دمج الخدمات."},"seo":{"title":{"en":"n8n-workflow-architect: Automation Setup Guide | AI Agent...","zh":"n8n-workflow-architect 使用指南 - AI智能自动化架构师","ja":"n8nワークフロー・アーキテクト セットアップガイド - AIエージェントによる自動化","ko":"n8n 워크플로우 아키텍트 설정 가이드 - AI 자동화 전문가","es":"Arquitecto de flujos de trabajo n8n: Guía de configuración","fr":"Architecte de workflow n8n: Meilleures pratiques","de":"n8n-Workflow-Architekt: Einrichtungsanleitung","pt":"Guia de Configuração do n8n-workflow-architect para Autom...","ru":"Настройка n8n-workflow-architect для автоматизации рабочи...","ar":"دليل إعداد n8n-workflow-architect لتحسين تدفق العمل مع أد..."},"description":{"en":"Unlock efficient automation with n8n-workflow-architect. Discover how to plan, integrate, and architect automation systems that thrive in production. Get sta...","zh":"了解n8n-workflow-architect的功能和特点，实现自动化项目的规划和架构决策","ja":"n8nワークフロー・アーキテクトの機能と特徴を紹介。自動化プロジェクトの計画とアーキテクチャー決定をサポート","ko":"n8n 워크플로우 아키텍트의 기능과 특징을 알아보세요. 자동화 프로젝트의 계획과 아키텍처 결정에 도움을 드립니다","es":"Aprende a planificar proyectos de automatización con n8n y toma decisiones informadas sobre la integración de servicios","fr":"Découvrez comment planifier des projets d''automatisation avec n8n et prendre des décisions éclairées sur l''intégration de services","de":"Erfahren Sie, wie Sie Automatisierungsprojekte mit n8n planen und fundierte Entscheidungen über die Integration von Diensten treffen","pt":"Aprenda a configurar o n8n-workflow-architect para automatizar fluxos de trabalho complexos e melhorar a eficiência com integrações de serviços como Shopify,...","ru":"Узнайте, как настроить n8n-workflow-architect для автоматизации сложных рабочих процессов и повышения эффективности с помощью интеграции сервисов như Shopify...","ar":"تعرف على كيفية إعداد n8n-workflow-architect لتحسين تدفق العمل المعقد وتحسين الكفاءة من خلال دمج خدمات مثل Shopify وKlaviyo وNotion مع أدوات الذكاء الاصطناعي"},"definition":{"en":"n8n-workflow-architect is a Claude Code skills framework for n8n automation, enabling users to turn Claude into an n8n expert for building robust automation systems.","zh":"n8n-workflow-architect是一种AI智能自动化架构师，用于规划和构建自动化系统","ja":"n8nワークフロー・アーキテクトは、AIエージェントによる自動化システムの計画と構築をサポートするアーキテクチャー","ko":"n8n 워크플로우 아키텍트는 자동화 시스템의 계획과 구성을 지원하는 AI 자동화 전문가","es":"Un arquitecto de flujos de trabajo n8n es un experto en automatización que diseña y planifica sistemas de automatización para la producción","fr":"Un architecte de workflow n8n est un expert en automatisation qui conçoit et planifie des systèmes d''automatisation pour la production","de":"Ein n8n-Workflow-Architekt ist ein Automatisierungsexperte, der Automatisierungssysteme für die Produktion entwirft und plant","pt":"O n8n-workflow-architect é uma habilidade de automação que fornece orientação estratégica para construir sistemas de automação que sobrevivam à produção.","ru":"n8n-workflow-architect - это навык автоматизации, который предоставляет стратегическое руководство для построения систем автоматизации, которые могут выдержать производство.","ar":"n8n-workflow-architect هو مهارة تلقائية توفر إرشادات استراتيجية لإنشاء أنظمة تلقائية يمكنها النجاة في الإنتاج."},"features":{"en":["Provides strategic guidance for building automation systems that survive production","Helps users plan automation projects, such as automating sales pipelines","Supports integration of multiple services, including Shopify, Klaviyo, and Notion","Offers architecture decisions, including choosing between n8n or Python for automation tasks","Evaluates feasibility of automation projects, ensuring effective resource allocation"],"zh":["提供自动化项目的规划和架构决策","支持多个服务的集成，如Shopify、Klaviyo和Notion","提供n8n或Python等技术的选择和决策","评估自动化项目的可行性","提供战略性的自动化系统构建指导"],"ja":["自動化プロジェクトの計画とアーキテクチャー決定をサポート","複数のサービス（Shopify、Klaviyo、Notionなど）の統合をサポート","n8nまたはPythonなどの技術の選択と決定をサポート","自動化プロジェクトの実現可能性を評価","戦略的な自動化システムの構築をサポート"],"ko":["자동화 프로젝트의 계획과 아키텍처 결정에 도움을 드립니다","여러 서비스(Shopify, Klaviyo, Notion 등)의 통합을 지원","n8n 또는 Python 등의 기술의 선택과 결정에 도움을 드립니다","자동화 프로젝트의 실현可能性를 평가","전략적인 자동화 시스템의 구성을 지원"],"es":["Planificación de proyectos de automatización","Integración de servicios como Shopify, Klaviyo y Notion","Toma de decisiones informadas sobre la arquitectura de la automatización","Evaluación de la viabilidad de la automatización","Uso de n8n para la automatización"],"fr":["Planification de projets d''automatisation","Intégration de services tels que Shopify, Klaviyo et Notion","Prise de décisions éclairées sur l''architecture de l''automatisation","Évaluation de la faisabilité de l''automatisation","Utilisation de n8n pour l''automatisation"],"de":["Planung von Automatisierungsprojekten","Integration von Diensten wie Shopify, Klaviyo und Notion","Fundierte Entscheidungsfindung über die Automatisierungsarchitektur","Bewertung der Machbarkeit der Automatisierung","Verwendung von n8n für die Automatisierung"],"pt":["Planejamento de projetos de automação","Integração de múltiplos serviços como Shopify, Klaviyo e Notion","Tomada de decisões arquiteturais para automação","Avaliação de viabilidade para automação"],"ru":["Планирование проектов автоматизации","Интеграция нескольких сервисов, таких как Shopify, Klaviyo и Notion","Принятие архитектурных решений для автоматизации","Оценка возможности автоматизации"],"ar":["تخطيط مشاريع التلقائية","دمج خدمات متعددة مثل Shopify وKlaviyo وNotion","اتخاذ قرارات هندسية لتحسين التلقائية","تقييم الإمكانية لتحسين التلقائية"]},"keywords":{"en":["how to use n8n-workflow-architect","n8n-workflow-architect setup guide","n8n automation tutorial","n8n workflow architecture","automating sales pipelines with n8n","n8n-workflow-architect vs Zapier","n8n workflow integration with Shopify"],"zh":["n8n自动化","AI智能自动化","自动化项目规划","多服务集成","n8n或Python","自动化系统构建","AIエージェント","自动化专家"],"ja":["n8n自動化","AIエージェント","自動化プロジェクトの計画","複数のサービス統合","n8nまたはPython","自動化システムの構築","AI自動化","自動化専門家"],"ko":["n8n 자동화","AI 자동화","自動화 프로젝트의 계획","여러 서비스 통합","n8n 또는 Python","自動화 시스템의 구축","AI 에이전트","自動화 전문가"],"es":["n8n workflow","automatización de flujos de trabajo","integración de servicios","arquitectura de automatización","planificación de proyectos de automatización","herramientas de automatización","Agentes de inteligencia artificial para la automatización"],"fr":["n8n workflow","automatisation de flux de travail","intégration de services","architecture d''automatisation","planification de projets d''automatisation","outils d''automatisation","Agents d''intelligence artificielle pour l''automatisation"],"de":["n8n-Workflow","Automatisierung von Workflows","Integration von Diensten","Automatisierungsarchitektur","Planung von Automatisierungsprojekten","Automatisierungstools","Künstliche Intelligenz-Agenten für die Automatisierung"],"pt":["n8n workflow automação","automação de fluxo de trabalho","integração de serviços","planejamento de projetos de automação","tomada de decisões arquiteturais","avaliação de viabilidade para automação","ferramentas de automação","IA agentes"],"ru":["n8n workflow автоматизация","автоматизация рабочих процессов","интеграция сервисов","планирование проектов автоматизации","принятие архитектурных решений","оценка возможности автоматизации","инструменты автоматизации","ИИ Агенты"],"ar":["n8n workflow تلقائية","تحسين تدفق العمل","دمج الخدمات","تخطيط مشاريع التلقائية","اتخاذ قرارات هندسية","تقييم الإمكانية لتحسين التلقائية","أدوات التلقائية","أدوات الذكاء الاصطناعي"]}},"owner":"promptadvisers","repo":"n8n-powerhouse","repoPath":"promptadvisers/n8n-powerhouse","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"n8n-workflow-architect","description":"Strategic automation architecture advisor. Use when users want to plan automation solutions, evaluate their tech stack (Shopify, Zoho, HubSpot, etc.), decide between n8n vs Python/Claude Code, or need guidance on production-ready automation design. Invokes plan mode for complex architectural decisions.","bodyPreview":"# n8n Workflow Architect\n\nThe Intelligent Automation Architect (IAA) - Strategic guidance for building automation systems that survive production.\n\n---\n\n## When to Use This Skill\n\nInvoke this skill when users:\n\n1. **Want to plan an automation project** - \"I need to automate my sales pipeline\"\n2. **Have multiple services to integrate** - \"I use Shopify, Klaviyo, and Notion\"\n3. **Need architecture decisions** - \"Should I use n8n or Python for this?\"\n4. **Are evaluating feasibility** - \"Can I autom","body":"# n8n Workflow Architect\n\nThe Intelligent Automation Architect (IAA) - Strategic guidance for building automation systems that survive production.\n\n---\n\n## When to Use This Skill\n\nInvoke this skill when users:\n\n1. **Want to plan an automation project** - \"I need to automate my sales pipeline\"\n2. **Have multiple services to integrate** - \"I use Shopify, Klaviyo, and Notion\"\n3. **Need architecture decisions** - \"Should I use n8n or Python for this?\"\n4. **Are evaluating feasibility** - \"Can I automate X with my current stack?\"\n5. **Want production-ready guidance** - \"How do I make this reliable?\"\n\n---\n\n## The Core Philosophy\n\n> **Viability over Possibility**\n\nThe gap between what''s technically possible and what''s actually viable in production is enormous. This skill helps users build systems that:\n\n- Won''t break at 3 AM on a Saturday\n- Don''t require a PhD to maintain\n- Respect data security, scale, and state management\n- Deliver actual business value, not just technical cleverness\n\n---\n\n## Architecture Decision Framework\n\n### Step 1: Stack Analysis\n\nWhen a user mentions their tools, evaluate each for:\n\n| Tool Category | Common Examples | n8n Native Support | Auth Complexity |\n|---------------|-----------------|-------------------|-----------------|\n| E-commerce | Shopify, WooCommerce, BigCommerce | Yes | OAuth |\n| CRM | HubSpot, Salesforce, Zoho CRM | Yes | OAuth |\n| Marketing | Klaviyo, Mailchimp, ActiveCampaign | Yes | API Key/OAuth |\n| Productivity | Notion, Airtable, Google Sheets | Yes | OAuth |\n| Communication | Slack, Discord, Teams | Yes | OAuth |\n| Payments | Stripe, PayPal, Square | Yes | API Key |\n| Support | Zendesk, Intercom, Freshdesk | Yes | API Key/OAuth |\n\n**Action**: Use `search_nodes` from n8n MCP to verify node availability.\n\n### Step 2: Tool Selection Matrix\n\nApply these decision rules:\n\n#### Use n8n When:\n\n| Condition | Why |\n|-----------|-----|\n| OAuth authentication required | n8n manages token lifecycle automatically |\n| Non-technical maintainers | Visual workflows are self-documenting |\n| Multi-day processes with waits | Built-in Wait node handles suspension |\n| Standard SaaS integrations | Pre-built nodes eliminate boilerplate |\n| < 5,000 records per execution | Within memory limits |\n| < 20 nodes of business logic | Maintains visual clarity |\n\n#### Use Python/Claude Code When:\n\n| Condition | Why |\n|-----------|-----|\n| > 5,000 records to process | Stream processing, memory management |\n| > 20MB files | Chunked processing capabilities |\n| Complex algorithms | Code is more maintainable than 50+ nodes |\n| Cutting-edge AI libraries | Access to latest packages |\n| Heavy data transformation | Pandas, NumPy optimization |\n| Custom ML models | Full Python ecosystem access |\n\n#### Use Hybrid (Recommended for Complex Systems):\n\n```\nn8n (Orchestration Layer)\n├── Webhooks & triggers\n├── OAuth authentication\n├── User-facing integrations\n├── Flow coordination\n│\n└── Calls Python Service (Processing Layer)\n    ├── Heavy computation\n    ├── Complex logic\n    ├── AI/ML operations\n    └── Returns results to n8n\n```\n\n---\n\n## Business Stack Quick Assessment\n\nWhen user describes their stack, respond with this analysis:\n\n### Template Response:\n\n```markdown\n## Stack Analysis: [User''s Business Type]\n\n### Services Identified:\n1. **[Service 1]** - [Category] - n8n Support: [Yes/Partial/No]\n2. **[Service 2]** - [Category] - n8n Support: [Yes/Partial/No]\n...\n\n### Recommended Approach: [n8n / Python / Hybrid]\n\n**Rationale:**\n- [Key decision factor 1]\n- [Key decision factor 2]\n- [Key decision factor 3]\n\n### Integration Complexity: [Low/Medium/High]\n- Auth complexity: [Simple API keys / OAuth required]\n- Data volume: [Estimate based on use case]\n- Processing needs: [Simple transforms / Complex logic]\n\n### Next Steps:\n1. [Specific action using other n8n skills]\n2. [Pattern to follow from n8n-workflow-patterns]\n3. [Validation approach from n8n-validation-expert]\n```\n\n---\n\n## Common Business Scenarios\n\n### Scenario 1: E-commerce Automation\n**Stack**: Shopify + Klaviyo + Slack + Google Sheets\n\n**Verdict**: Pure n8n\n- All services have native nodes\n- OAuth handled automatically\n- Standard webhook patterns\n- Use: `n8n-workflow-patterns` → webhook_processing\n\n### Scenario 2: AI-Powered Lead Qualification\n**Stack**: Typeform + HubSpot + OpenAI + Custom Scoring\n\n**Verdict**: Hybrid\n- n8n: Typeform webhook, HubSpot sync, notifications\n- Python/Code Node: Complex scoring algorithm, AI prompts\n- Use: `n8n-workflow-patterns` → ai_agent_workflow\n\n### Scenario 3: Data Pipeline / ETL\n**Stack**: PostgreSQL + BigQuery + 50k+ daily records\n\n**Verdict**: Python with n8n Trigger\n- n8n: Schedule trigger, success/failure notifications\n- Python: Batch processing, streaming, transformations\n- Reason: Memory limits in n8n for large datasets\n\n### Scenario 4: Multi-Step Approval Workflow\n**Stack**: Slack + Notion + Email + 3-day wait periods\n\n**Verdict**: Pure n8n\n- Built-in Wait node for delays\n- Native Slack/Notion integrations\n- Human approval patterns built-in\n- Use: `n8n-workflow-patterns` → scheduled_tasks\n\n---\n\n## Production Readiness Checklist\n\nBefore any automation goes live, verify:\n\n### Observability\n- [ ] Error notification workflow exists\n- [ ] Execution logging to database\n- [ ] Health check workflow for critical paths\n- [ ] Structured alerting by severity\n\n### Idempotency\n- [ ] Duplicate webhook handling\n- [ ] Check-before-create patterns\n- [ ] Idempotency keys for payments\n- [ ] Safe re-run capability\n\n### Cost Awareness\n- [ ] AI API costs calculated and approved\n- [ ] Rate limits documented\n- [ ] Caching strategy for repeated calls\n- [ ] Model right-sizing (Haiku vs Sonnet vs Opus)\n\n### Operational Control\n- [ ] Kill switch accessible to non-technical staff\n- [ ] Approval queues for high-stakes actions\n- [ ] Audit trail for all actions\n- [ ] Configuration externalized\n\nUse `n8n-validation-expert` skill to validate workflows before deployment.\n\n---\n\n## Integration with Other n8n Skills\n\nThis skill works as the **planning layer** that coordinates other skills:\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│                  n8n-workflow-architect                      │\n│            (Strategic Decisions & Planning)                  │\n└─────────────────────────────────────────────────────────────┘\n                              │\n         ┌────────────────────┼────────────────────┐\n         ▼                    ▼                    ▼\n┌─────────────────┐  ┌─────────────────┐  ┌─────────────────┐\n│ n8n-workflow-   │  │ n8n-node-       │  │ n8n-validation- │\n│ patterns        │  │ configuration   │  │ expert          │\n│ (Architecture)  │  │ (Node Setup)    │  │ (Quality)       │\n└─────────────────┘  └─────────────────┘  └─────────────────┘\n         │                    │                    │\n         └────────────────────┼────────────────────┘\n                              ▼\n┌─────────────────────────────────────────────────────────────┐\n│                     n8n MCP Tools                            │\n│    (search_nodes, validate_workflow, create_workflow, etc.) │\n└─────────────────────────────────────────────────────────────┘\n```\n\n### Skill Handoff Guide:\n\n| After Architect Decides... | Hand Off To |\n|---------------------------|-------------|\n| Pattern type identified | `n8n-workflow-patterns` for detailed structure |\n| Specific nodes needed | `n8n-node-configuration` for setup |\n| Code node required | `n8n-code-javascript` or `n8n-code-python` |\n| Expressions needed | `n8n-expression-syntax` for correct syntax |\n| Ready to validate | `n8n-validation-expert` for pre-deploy checks |\n| Need node info | n8n MCP → `get_node_essentials`, `search_nodes` |\n\n---\n\n## Plan Mode Activation\n\nFor complex architectural decisions, enter plan mode to:\n\n1. **Analyze the full business context**\n2. **Evaluate all integration points**\n3. **Design the data flow architecture**\n4. **Identify failure modes and mitigations**\n5. **Create implementation roadmap**\n\n### Trigger Plan Mode When:\n\n- User has 3+ services to integrate\n- Unclear whether n8n or Python is better\n- High-stakes automation (payments, customer data)\n- Complex multi-step processes\n- AI/ML components involved\n\n### Plan Mode Output Structure:\n\n```markdown\n## Automation Architecture Plan\n\n### 1. Business Context\n[What problem are we solving?]\n\n### 2. Stack Analysis\n[Each service, its role, integration complexity]\n\n### 3. Recommended Architecture\n[n8n / Python / Hybrid with rationale]\n\n### 4. Data Flow Design\n[Visual representation of the flow]\n\n### 5. Implementation Phases\nPhase 1: [Core workflow]\nPhase 2: [Error handling & observability]\nPhase 3: [Optimization & scaling]\n\n### 6. Risk Assessment\n[What could go wrong, how we prevent it]\n\n### 7. Maintenance Plan\n[Who maintains, what skills needed]\n```\n\n---\n\n## Quick Decision Tree\n\n```\nSTART: User wants to automate something\n  │\n  ├─► Does it involve OAuth? ────────────────────► Use n8n\n  │\n  ├─► Will non-developers maintain it? ──────────► Use n8n\n  │\n  ├─► Does it need to wait days/weeks? ──────────► Use n8n\n  │\n  ├─► Processing > 5000 records? ────────────────► Use Python\n  │\n  ├─► Files > 20MB? ─────────────────────────────► Use Python\n  │\n  ├─► Cutting-edge AI/ML? ───────────────────────► Use Python\n  │\n  ├─► Complex algorithm (would need 20+ nodes)? ─► Use Python\n  │\n  └─► Mix of above? ─────────────────────────────► Use Hybrid\n```\n\n---\n\n## MCP Tool Integration\n\nUse these n8n MCP tools during architecture planning:\n\n| Planning Phase | MCP Tools to Use |\n|----------------|------------------|\n| Stack analysis | `search_nodes` - verify node availability |\n| Pattern selection | `list_node_templates` - find similar workflows |\n| Feasibility check | `get_node_essentials` - understand capabilities |\n| Complexity estimate | `get_node_documentation` - auth & config needs |\n| Template reference | `get_template` - study existing patterns |\n\n---\n\n## Red Flags to Watch For\n\nWarn users when you see these patterns:\n\n| Red Flag | Risk | Recommendation |\n|----------|------|----------------|\n| \"I want AI to do everything\" | Cost explosion, unpredictability | Scope AI to specific tasks, cache results |\n| \"It needs to process millions of rows\" | Memory crashes | Python with streaming, not n8n loops |\n| \"The workflow has 50 nodes\" | Unmaintainable | Consolidate to code blocks or split workflows |\n| \"We''ll add error handling later\" | Silent failures | Build error handling from day one |\n| \"It should work on any input\" | Fragile system | Define and validate expected inputs |\n| \"The intern will maintain it\" | Single point of failure | Use n8n for visual clarity, document thoroughly |\n\n---\n\n## Summary\n\n**This skill answers**: \"Given my business stack and requirements, what''s the smartest way to build this automation?\"\n\n**Key outputs**:\n1. Stack compatibility analysis\n2. n8n vs Python vs Hybrid recommendation\n3. Pattern and skill handoffs\n4. Production readiness guidance\n5. Implementation roadmap via plan mode\n\n**Works with**:\n- All n8n-* skills for implementation details\n- n8n MCP tools for node discovery and workflow creation\n- Plan mode for complex architectural decisions\n\n---\n\n## Related Files\n\n- [tool-selection-matrix.md](tool-selection-matrix.md) - Detailed decision criteria\n- [business-stack-analysis.md](business-stack-analysis.md) - Common SaaS integration guides\n- [production-readiness.md](production-readiness.md) - Pre-launch checklist details\n"},"lastSynced":"2026-03-08T02:01:14.733Z","agentAnalysis":{"suitability":{"en":"Perfect for Automation Agents needing strategic guidance on building scalable workflow automation systems with n8n","zh":"非常适合需要在构建使用n8n的可扩展工作流自动化系统方面获得战略指导的自动化代理","ja":"n8nを使用したスケーラブルなワークフロー自動化システムの構築に関する戦略的ガイダンスが必要な自動化エージェントに最適","ko":"n8n을 사용하여 확장 가능한 워크플로 자동화 시스템을 구축하기 위한 전략적 지침이 필요한 자동화 에이전트에게 적합","es":"Perfecto para agentes de automatización que necesitan orientación estratégica para construir sistemas de automatización de flujo de trabajo escalables con n8n","fr":"Parfait pour les agents d''automatisation ayant besoin d''orientations stratégiques pour construire des systèmes d''automatisation de flux de travail évolutifs avec n8n","de":"Perfekt für Automatisierungsagenten, die strategische Anleitung für den Bau von skalierbaren Workflow-Automatisierungssystemen mit n8n benötigen","pt":"Perfeito para Agentes de Automação que necessitam de orientação estratégica para construir sistemas de automação de fluxo de trabalho escaláveis com n8n","ru":"Идеально для агентов автоматизации, которым требуется стратегическое руководство по созданию масштабируемых систем автоматизации рабочих процессов с помощью n8n","ar":"مثالي للوكلاء الآليين الذين يحتاجون إلى توجيه استراتيجي لإنشاء أنظمة أتمتة تدفق العمل القابلة للتوسيع مع n8n"},"recommendation":{"en":"Empowers agents to design and integrate multiple services using n8n, making informed architecture decisions and optimizing workflow automation projects with protocols like HTTP and APIs, while evaluating feasibility and planning automation pipelines","zh":"赋予代理设计和集成多个服务使用n8n，做出明智的架构决策，并使用HTTP和API等协议优化工作流自动化项目，同时评估可行性和规划自动化管道","ja":"エージェントにn8nを使用して複数のサービスを設計および統合する能力を与え、インフォームドなアーキテクチャの決定を下し、HTTPやAPIなどのプロトコルを使用してワークフロー自動化プロジェクトを最適化し、同時に実現可能性を評価し、自動化パイプラインを計画する","ko":"에이전트가 n8n을 사용하여 여러 서비스를 설계하고 통합할 수 있도록 하며, HTTP 및 API와 같은 프로토콜을 사용하여 워크플로 자동화 프로젝트를 최적화하고, 동시에 실현 가능성을 평가하고 자동화 파이프라인을 계획하는 능력을 부여","es":"Habilita a los agentes a diseñar e integrar múltiples servicios utilizando n8n, tomando decisiones informadas de arquitectura y optimizando proyectos de automatización de flujo de trabajo con protocolos como HTTP y API, mientras evalúa la viabilidad y planea tuberías de automatización","fr":"Équipe les agents pour concevoir et intégrer plusieurs services en utilisant n8n, prenant des décisions d''architecture éclairées et optimisant les projets d''automatisation de flux de travail avec des protocoles tels que HTTP et API, tout en évaluant la faisabilité et en planifiant les pipelines d''automatisation","de":"Ermächtigt Agenten, mehrere Dienste mit n8n zu entwerfen und zu integrieren, fundierte Architekturentscheidungen zu treffen und Workflow-Automatisierungsprojekte mit Protokollen wie HTTP und API zu optimieren, während die Machbarkeit bewertet und Automatisierungspipelines geplant werden","pt":"Habilita os agentes a projetar e integrar vários serviços usando n8n, tomando decisões informadas de arquitetura e otimizando projetos de automação de fluxo de trabalho com protocolos como HTTP e APIs, ao mesmo tempo em que avaliam a viabilidade e planejam pipelines de automação","ru":"Наделяет агентов возможностью проектировать и интегрировать несколько сервисов с помощью n8n, принимая обоснованные архитектурные решения и оптимизируя проекты автоматизации рабочих процессов с использованием протоколов, таких как HTTP и API, одновременно оценивая целесообразность и планируя конвейеры автоматизации","ar":"يمنح الوكلاء القدرة على تصميم وتكامل الخدمات المتعددة باستخدام n8n، اتخاذ قرارات معمارية مدروسة وتحسين مشاريع أتمتة تدفق العمل باستخدام بروتوكولات مثل HTTP و APIs، وفي نفس الوقت تقييم الجدوى وتخطيط خطوط أنابيب الأتمتة"},"useCases":{"en":["Planning automation projects for sales pipelines","Integrating services like Shopify, Klaviyo, and Notion","Evaluating feasibility of workflow automation with n8n"],"zh":["规划销售管道的自动化项目","集成Shopify、Klaviyo和Notion等服务","使用n8n评估工作流自动化的可行性"],"ja":["セールスパイプラインの自動化プロジェクトの計画","Shopify、Klaviyo、Notionなどのサービスを統合する","n8nを使用してワークフロー自動化の実現可能性を評価する"],"ko":["판매 파이프라인의 자동화 프로젝트 계획","Shopify, Klaviyo, Notion 등의 서비스 통합","n8n을 사용하여 워크플로 자동화의 실현 가능성 평가"],"es":["Planificación de proyectos de automatización para tuberías de ventas","Integración de servicios como Shopify, Klaviyo y Notion","Evaluación de la viabilidad de la automatización de flujo de trabajo con n8n"],"fr":["Planification de projets d''automatisation pour les pipelines de ventes","Intégration de services tels que Shopify, Klaviyo et Notion","Évaluation de la faisabilité de l''automatisation de flux de travail avec n8n"],"de":["Planung von Automatisierungsprojekten für Vertriebspipelines","Integration von Diensten wie Shopify, Klaviyo und Notion","Bewertung der Machbarkeit von Workflow-Automatisierung mit n8n"],"pt":["Planejamento de projetos de automação para pipelines de vendas","Integração de serviços como Shopify, Klaviyo e Notion","Avaliação da viabilidade da automação de fluxo de trabalho com n8n"],"ru":["Планирование проектов автоматизации для продажных конвейеров","Интеграция сервисов, таких как Shopify, Klaviyo и Notion","Оценка целесообразности автоматизации рабочих процессов с помощью n8n"],"ar":["تخطيط مشاريع الأتمتة لأنابيب المبيعات","دمج الخدمات مثل Shopify و Klaviyo و Notion","تقييم جدوى أتمتة تدفق العمل باستخدام n8n"]},"limitations":{"en":["Requires n8n workflow knowledge","Limited to workflow automation use cases"],"zh":["需要n8n工作流知识","仅限工作流自动化用例"],"ja":["n8nワークフローの知識が必要","ワークフロー自動化のユースケースに限定される"],"ko":["n8n 워크플로 지식이 필요","워크플로 자동화 유즈ケース에만 제한"],"es":["Requiere conocimiento de flujo de trabajo de n8n","Limitado a casos de uso de automatización de flujo de trabajo"],"fr":["Nécessite des connaissances en flux de travail n8n","Limité aux cas d''utilisation de l''automatisation de flux de travail"],"de":["Benötigt Kenntnisse von n8n-Workflows","Begrenzt auf Anwendungsfälle für Workflow-Automatisierung"],"pt":["Exige conhecimento de fluxo de trabalho n8n","Limitado a casos de uso de automação de fluxo de trabalho"],"ru":["Требует знания рабочих процессов n8n","Ограничен случаи использования автоматизации рабочих процессов"],"ar":["يتطلب معرفة بتدفق العمل n8n","محدود لحالات استخدام أتمتة تدفق العمل"]},"version":4},"contentHash":"95f2909fd121a155647f383d8711601c8faf2c8f123917b18f7f0539a940aef2","qualityScore":60}');
