INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('promptadvisers/n8n-powerhouse/n8n-workflow-architect', 'n8n-workflow-architect', 'promptadvisers', 'n8n-powerhouse', 'community', 'n8n-workflow-architect promptadvisers n8n-powerhouse community The n8n-workflow-architect skill provides strategic guidance for building automation systems, helping users plan automation projects, integrate multiple services, and make informed architecture decisions. This skill benefits developers and automation specialists seeking to optimize their workflows. n8n-workflow-architect是Claude Code技能框架的一部分，用于提供n8n自动化的战略指导 n8nワークフロー・アーキテクトは、Claude Codeスキルフレームワークの一部で、n8n自動化の戦略的ガイダンスを提供 n8n 워크플로우 아키텍트는 Claude Code 스킬 프레임워크의 일부로, n8n 자동화를 위한 전략적 가이드를 제공 El arquitecto de flujos de trabajo n8n es un experto en automatización que ayuda a planificar proyectos y tomar decisiones informadas sobre la integración de servicios como Shopify, Klaviyo y Notion L''architecte de workflow n8n est un expert en automatisation qui aide à planifier des projets et à prendre des décisions éclairées sur l''intégration de services tels que Shopify, Klaviyo et Notion Der n8n-Workflow-Architekt ist ein Automatisierungsexperte, der bei der Planung von Projekten und der fundierten Entscheidungsfindung über die Integration von Diensten wie Shopify, Klaviyo und Notion hilft O n8n-workflow-architect é uma habilidade de automação que ajuda a planejar e implementar fluxos de trabalho complexos com integrações de serviços. n8n-workflow-architect - это навык автоматизации, который помогает планировать и реализовывать сложные рабочие процессы с интеграцией сервисов. n8n-workflow-architect هو مهارة تلقائية تساعد على تخطيط وتنفيذ تدفقات عمل معقدة مع دمج الخدمات. how to use n8n-workflow-architect n8n-workflow-architect setup guide n8n automation tutorial n8n workflow architecture automating sales pipelines with n8n n8n-workflow-architect vs Zapier n8n workflow integration with Shopify n8n自动化 AI智能自动化 自动化项目规划 多服务集成 n8n或Python 自动化系统构建 AIエージェント 自动化专家 Provides strategic guidance for building automation systems that survive production Helps users plan automation projects, such as automating sales pipelines Supports integration of multiple services, including Shopify, Klaviyo, and Notion Offers architecture decisions, including choosing between n8n or Python for automation tasks Evaluates feasibility of automation projects, ensuring effective resource allocation n8n-workflow-architect is a Claude Code skills framework for n8n automation, enabling users to turn Claude into an n8n expert for building robust automation systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('reporails/rules/implement-rule', 'community', 'reporails', 'rules', 'reporails/rules', 'implement-rule', 0, 0, 60, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:16.435Z', 'af40151dd8a53c51e154623c33f114ccabbc68ec40a0435e4cf9bd6708abf03f', '{"id":"reporails/rules/implement-rule","name":"implement-rule","description":{"en":"The implement-rule skill provides a framework for validating AI coding agent instructions, benefiting developers who need to ensure structure, content, efficiency, governance, and maintenance in their AI projects.","zh":"Implement Rule 是一种用于验证 AI 代码代理指令的证据驱动规则，提供结构、内容、效率、治理和维护的核心规则","ja":"Implement Rule は、AI コードエージェントの指令を検証するためのエビデンス駆動型ルールであり、構造、コンテンツ、効率、ガバナンス、メンテナンスのためのコアルールを提供します","ko":"Implement Rule은 AI 코드 에이전트 지침을 검증하기 위한 증거 기반 규칙으로 구조, 내용, 효율, 治理 및 유지 보수의 핵심 규칙을 제공합니다","es":"Implement-rule es una habilidad que proporciona reglas de validación para instrucciones de agentes de codificación de IA, incluyendo estructura, contenido y eficiencia","fr":"Implement-rule est une compétence qui fournit des règles de validation pour les instructions des outils de codage d''IA, notamment la structure, le contenu et l''efficacité","de":"Implement-rule ist eine Fähigkeit, die Validierungsregeln für Anweisungen von KI-Coding-Agenten bereitstellt, einschließlich Struktur, Inhalt und Effizienz","pt":"O implement-rule é uma habilidade que fornece regras de validação para instruções de agentes de codificação de IA, garantindo estrutura, conteúdo e eficiência.","ru":"Implement-rule - навык, предоставляющий правила проверки для инструкций ИИ агентов, обеспечивающий структуру, содержание и эффективность.","ar":"implement-rule هو مهارة توفر قواعد التحقق من صحة لتعليمات وكلاء الذكاء الاصطناعي، مما يضمن الهيكل والمحتوى والكفاءة."},"seo":{"title":{"en":"implement-rule: Setup Guide for AI Agents | AI Agent Skill","zh":"AI Agent 实现规则设置指南 - Implement Rule","ja":"AIエージェントの実装ルール設定ガイド - Implement Rule","ko":"AI 에이전트 구현 규칙 설정 가이드 - Implement Rule","es":"Guía de configuración de implement-rule para agentes de IA","fr":"Guide de mise en œuvre de implement-rule pour les outils ...","de":"Implementierungshandbuch für implement-rule in KI-Agenten","pt":"Guia de Configuração do implement-rule para Ferramentas d...","ru":"Настройка implement-rule для ИИ Агентов: Лучшие Практики","ar":"دليل تثبيت implement-rule لأدوات الذكاء الاصطناعي"},"description":{"en":"Learn how to implement evidence-backed rules for validating AI coding agent instructions with our step-by-step guide and unlock efficient governance and main...","zh":"了解如何使用 Implement Rule 实现检查、正则表达式模式和测试 fixture，优化 AI 代码代理指令","ja":"Implement Rule を使用してチェック、正規表現パターン、テストフィクスチャを実装し、AI コードエージェントの指令を最適化する方法について学びます","ko":"Implement Rule을 사용하여 검사, 정규 표현식 패턴 및 테스트 픽스처를 구현하고 AI 코드 에이전트 지침을 최적화하는 방법에 대해 알아보세요","es":"Aprende a implementar reglas de validación para instrucciones de agentes de codificación de IA con implement-rule","fr":"Découvrez comment mettre en œuvre des règles de validation pour les instructions des outils de codage d''IA avec implement-rule","de":"Erfahren Sie, wie Sie Validierungsregeln für Anweisungen von KI-Coding-Agenten mit implement-rule implementieren","pt":"Aprenda a implementar regras de validação para instruções de agentes de codificação de IA com o implement-rule. Veja exemplos e uso.","ru":"Узнайте, как реализовать проверку правил для инструкций ИИ агентов с помощью implement-rule. Примеры и использование.","ar":"تعلم كيفية تنفيذ قواعد التحقق من صحة تعليمات وكلاء الذكاء الاصطناعي باستخدام implement-rule. انظر الأمثلة والاستخدام."},"definition":{"en":"implement-rule is a skill that provides evidence-backed rules for validating AI coding agent instructions, focusing on structure, content, efficiency, governance, and maintenance","zh":"Implement Rule 是一种用于实现检查、正则表达式模式和测试 fixture 的规则","ja":"Implement Rule は、チェック、正規表現パターン、テストフィクスチャを実装するためのルールです","ko":"Implement Rule은 검사, 정규 표현식 패턴 및 테스트 픽스처를 구현하기 위한 규칙입니다","es":"Implement-rule es una habilidad que implementa reglas de validación para instrucciones de agentes de codificación de IA","fr":"Implement-rule est une compétence qui met en œuvre des règles de validation pour les instructions des outils de codage d''IA","de":"Implement-rule ist eine Fähigkeit, die Validierungsregeln für Anweisungen von KI-Coding-Agenten implementiert","pt":"O implement-rule é uma habilidade de IA que implementa regras de validação para instruções de codificação.","ru":"Implement-rule - навык ИИ, реализующий правила проверки для инструкций кодирования.","ar":"implement-rule هو مهارة ذكاء اصطناعي تنفذ قواعد التحقق من صحة لتعليمات الترميز."},"features":{"en":["Generates checks, regex patterns, and test fixtures for existing rules","Supports template variable resolution using agents like Claude","Allows for dry-run mode to preview generated files without writing them","Utilizes rule coordinates like CORE:C:0001 and CLAUDE:S:0001 for organization","Enables customization with optional flags like --agent and --dry-run"],"zh":["实现检查、正则表达式模式和测试 fixture","支持 rule 坐标（例如 CORE:C:0001、CLAUDE:S:0001）","提供 --agent 选项用于模板变量解析","支持 --dry-run 选项用于显示生成内容而不写入文件"],"ja":["チェック、正規表現パターン、テストフィクスチャを実装する","ルール座標（例：CORE:C:0001、CLAUDE:S:0001）をサポートする","テンプレート変数解析用の --agent オプションを提供する","--dry-run オプションをサポートしてファイルを書き込まずに生成内容を表示する"],"ko":["검사, 정규 표현식 패턴 및 테스트 픽스처를 구현한다","규칙 좌표（예：CORE:C:0001、CLAUDE:S:0001）를 지원한다","템플릿 변수 해석을 위한 --agent 옵션을 제공한다","--dry-run 옵션을 지원하여 파일을 작성하지 않고 생성 내용을 표시한다"],"es":["Implementación de reglas de validación para instrucciones de agentes de codificación de IA","Soporte para estructura, contenido y eficiencia","Uso de expresiones regulares y fixtures de prueba","Compatibilidad con agentes como Claude","Opción de ejecución en seco para probar la generación de reglas"],"fr":["Mise en œuvre de règles de validation pour les instructions des outils de codage d''IA","Prise en charge de la structure, du contenu et de l''efficacité","Utilisation d''expressions régulières et de fixtures de test","Compatibilité avec des agents tels que Claude","Option d''exécution en mode sec pour tester la génération de règles"],"de":["Implementierung von Validierungsregeln für Anweisungen von KI-Coding-Agenten","Unterstützung für Struktur, Inhalt und Effizienz","Verwendung von regulären Ausdrücken und Test-Fixtures","Kompatibilität mit Agenten wie Claude","Option für Trockenausführung zur Erprobung der Regenerierung"],"pt":["Implementação de regras de validação para instruções de agentes de codificação de IA","Uso de expressões regulares e testes para garantir a eficiência","Suporte a agentes de codificação de IA, como Claude","Opção de execução seca para visualizar as alterações antes de aplicá-las","Coordenadas de regra personalizáveis para atender às necessidades específicas"],"ru":["Реализация правил проверки для инструкций ИИ агентов","Использование регулярных выражений и тестов для обеспечения эффективности","Поддержка ИИ агентов, таких как Claude","Вариант сухого запуска для просмотра изменений перед их применением","Настраиваемые координаты правил для удовлетворения конкретных потребностей"],"ar":["تنفيذ قواعد التحقق من صحة لتعليمات وكلاء الذكاء الاصطناعي","استخدام التعبيرات العادية والاختبارات لضمان الكفاءة","دعم وكلاء الترميز الذكاء الاصطناعي، مثل Claude","خيار التشغيل الجاف لمراجعة التعديلات قبل تطبيقها","تنسيق координات القواعد لتلبية الاحتياجات المحددة"]},"keywords":{"en":["how to use implement-rule","implement-rule setup guide","what is implement-rule","implement-rule alternative","implement-rule vs Claude","implement-rule install","AI coding agent validation","evidence-backed rules for AI","AI project governance and maintenance"],"zh":["AI Agent","Implement Rule","代码代理","规则实现","检查","正则表达式模式","测试 fixture","CLI"],"ja":["AIエージェント","Implement Rule","コードエージェント","ルール実装","チェック","正規表現パターン","テストフィクスチャ","CLI"],"ko":["AI 에이전트","Implement Rule","코드 에이전트","규칙 구현","검사","정규 표현식 패턴","테스트 픽스처","CLI"],"es":["implement-rule","agentes de IA","reglas de validación","codificación de IA","estructura de código","contenido de código","eficiencia de código","expresiones regulares","fixtures de prueba"],"fr":["implement-rule","outils d''IA","règles de validation","codage d''IA","structure de code","contenu de code","efficacité de code","expressions régulières","fixtures de test"],"de":["implement-rule","KI-Agenten","Validierungsregeln","KI-Coding","Code-Struktur","Code-Inhalt","Code-Effizienz","reguläre Ausdrücke","Test-Fixtures"],"pt":["implement-rule","ferramentas de IA","agentes de codificação de IA","regras de validação","expressões regulares","testes","Claude","desenvolvimento de software","IA"],"ru":["implement-rule","ИИ агенты","инструменты ИИ","правила проверки","регулярные выражения","тесты","Claude","разработка программного обеспечения","ИИ"],"ar":["implement-rule","أدوات الذكاء الاصطناعي","وكلاء الترميز الذكاء الاصطناعي","قواعد التحقق من صحة","التعبيرات العادية","الاختبارات","Claude","تطوير البرمجيات","الذكاء الاصطناعي"]}},"owner":"reporails","repo":"rules","repoPath":"reporails/rules","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"implement-rule","description":"Implement checks, patterns, and fixtures for an existing rule skeleton","bodyPreview":"# /implement-rule\n\nImplement checks, regex patterns, and test fixtures for an existing rule that has a skeleton but empty `checks: []`.\n\n## Usage\n\n```\n/implement-rule <coordinate> [--agent <name>] [--dry-run]\n```\n\n- `<coordinate>`: Rule coordinate (e.g., CORE:C:0001, CLAUDE:S:0001)\n- `--agent <name>`: Agent for template var resolution (default: `claude`)\n- `--dry-run`: Show what would be generated without writing files\n\n## Examples\n\n```\n/implement-rule CORE:S:0002\n/implement-rule CORE:M:0003 --a","body":"# /implement-rule\n\nImplement checks, regex patterns, and test fixtures for an existing rule that has a skeleton but empty `checks: []`.\n\n## Usage\n\n```\n/implement-rule <coordinate> [--agent <name>] [--dry-run]\n```\n\n- `<coordinate>`: Rule coordinate (e.g., CORE:C:0001, CLAUDE:S:0001)\n- `--agent <name>`: Agent for template var resolution (default: `claude`)\n- `--dry-run`: Show what would be generated without writing files\n\n## Examples\n\n```\n/implement-rule CORE:S:0002\n/implement-rule CORE:M:0003 --agent codex\n/implement-rule CLAUDE:S:0001 --dry-run\n```\n\n## Workflow\n\nFollow: [@.shared/workflows/rule-implementation.md](../../../.shared/workflows/rule-implementation.md)\n\n### 1. Locate\n\nResolve rule directory from coordinate:\n1. Look up slug in `registry/coordinate-map.yml` (backbone key: `registry.coordinate_map`)\n2. Determine category from coordinate letter: S=structure, C=content, E=efficiency, M=maintenance, G=governance\n3. For core rules: `{categories.{category}}/{slug}/`\n4. For agent rules: `{agent_rules.{agent}}/{slug}/`\n\n### 2. Read\n\nParse `rule.md` frontmatter and body:\n- Extract: `id`, `type`, `level`, `targets`, `question`, `criteria`, Pass/Fail examples from body\n- **Abort if `checks:` is already non-empty** — rule is already implemented\n- Identify the **violation class**: what structural or content pattern makes an instruction file FAIL this rule? The Pass/Fail examples are illustrations, not specifications.\n\n### 3. Analyze — Pattern Design\n\nThis is the critical step. The goal is to design a check that catches the **class of violation**, not a regex that discriminates between two fixture files.\n\n#### How to use frontmatter fields\n\n| Field | Design role |\n|-------|------------|\n| `title` | Names the concern — what property should instruction files have? |\n| `question` | Defines the evaluation question — what are we asking about the file? |\n| `criteria` | Lists observable properties of a PASSING file — invert each to get violation indicators |\n| Pass example | ONE illustration of a good file — extract the structural pattern that makes it good |\n| Fail example | ONE illustration of a bad file — extract the structural pattern that makes it bad |\n\n**Think in terms of violation structure, not fixture discrimination.**\n\n#### Mechanical rules\n\n- Select check function(s) from the 10 available: `file_exists`, `directory_exists`, `directory_contains`, `git_tracked`, `frontmatter_key`, `file_count`, `line_count`, `byte_size`, `path_resolves`, `extract_imports`\n- Derive `args` from rule description (e.g., `max: 300` for `line_count`)\n- No regex patterns needed\n\n#### Deterministic rules — violation detection\n\nDesign a pattern that matches the **structural signature of the violation**:\n\n1. Read the Fail example. Ask: what STRUCTURAL pattern makes this file bad? Not \"what text does it contain?\" but \"what is the shape of the problem?\"\n2. Read the `criteria` (if present). Each criterion describes a PASSING property. Invert: what does a file look like when it LACKS this property?\n3. Design a regex that matches the structural signature, not a specific keyword.\n\n**Two violation types:**\n\n| Type | Approach | Example |\n|------|----------|---------|\n| **Presence of bad content** | Pattern matches the violation directly | Secrets: `(?i)(api[_-]?key\\|secret)\\s*[=:]\\s*[''\"]?[A-Za-z0-9]{8,}` |\n| **Absence of good content** | Pattern matches the structural gap left by the missing content | Missing description: `^#\\s+[^\\n]+\\n\\s*\\n##` (title followed immediately by section heading, no prose between) |\n\n**NEVER use presence-then-negate as the primary strategy.** A pattern with `negate: true` that looks for \"does good content exist?\" is fragile — any incidental keyword match satisfies it. Instead, find the structural shape of the violation itself.\n\n`negate: true` is acceptable ONLY when:\n- The violation is purely about absence AND\n- No structural signature exists (the bad file is structurally identical to the good file, just missing a keyword) AND\n- You''ve confirmed there is no structural pattern to detect\n\nFor core rules: use `{{instruction_files}}` in paths (not `**/*.md`).\n\n#### Semantic rules — candidate surfacing\n\nSemantic rules have two phases: deterministic pre-check → semantic evaluation.\n\n**Pre-check purpose**: Find text that EXHIBITS the violation pattern — content that needs human/LLM judgment to determine if it''s actually a violation.\n\n**Pre-check design**:\n1. Read the `question` field. What kind of content needs to be EVALUATED?\n2. Read the `criteria` field. What observable text patterns MIGHT indicate a violation but need context to confirm?\n3. Design a pattern that matches these ambiguous indicators — not content matching the rule''s topic, but content matching the violation''s surface appearance.\n\nExample: Rule \"no-linter-enforceable-style\"\n- BAD pre-check: `(?i)(style|format|indent)` — matches the rule''s topic, not violation indicators\n- GOOD pre-check: `(?i)(indent|tab|space|bracket|semicolon|line.length|80.char|120.char)` — matches specific linter-enforceable patterns\n\nTerminal semantic check uses `prompt` derived from rule''s `question`/`criteria` fields.\n\n### 4. Generate checks\n\nWrite `checks:` array in `rule.md` frontmatter:\n- IDs follow `{NAMESPACE}.{CATEGORY}.{SLOT}.{descriptive-name}` format (e.g., `CORE.S.0005.file-exists`)\n- Check types must not exceed rule type ceiling:\n  - `mechanical` rule → only `mechanical` checks\n  - `deterministic` rule → `mechanical` + `deterministic` checks\n  - `semantic` rule → any types, semantic must be last\n- Severity from rule context: `critical` for L1, `high`/`medium` for L2+\n\n### 5. Generate patterns\n\nFor deterministic/semantic rules, write regex patterns in `rule.yml`:\n- `id` matches the check ID from frontmatter\n- `languages: [generic]` for markdown targets\n- `paths.include` uses template vars (`{{instruction_files}}`)\n- Pattern captures the violation, not the desired state\n- Severity mapping: critical→ERROR, high/medium/low→WARNING\n\nFor mechanical-only rules: leave `rule.yml` as `rules: []`.\n\n### 6. Generate fixtures\n\nFixtures simulate REAL instruction files, not minimal test content.\n\n**Pass fixture** (`tests/pass/`):\n- A realistic instruction file (30-80 lines) that a real project might have\n- Contains the structural patterns that satisfy the rule\n- Include realistic sections, commands, and project context — not just the minimum to pass\n- File names match resolved template vars (e.g., `CLAUDE.md` for claude agent)\n\n**Fail fixture** (`tests/fail/`):\n- A realistic instruction file that exhibits the specific violation\n- The violation should be the ONLY difference from a reasonable file — don''t make the fail fixture obviously broken in multiple ways\n- Must trigger the pattern''s structural signature, not just be \"bad in general\"\n\n**Fixture quality check**: After generating fixtures, re-read them and ask:\n- Does the pass fixture look like a real CLAUDE.md from a real project?\n- Does the fail fixture look like a plausible mistake someone would make?\n- Would the pattern catch the fail fixture for the RIGHT reason (structural violation match), not an incidental one?\n\nRemove `.gitkeep` from directories that now have real fixture content.\n\n### 7. Verify\n\nRun the test harness (`/test-rules`):\n```bash\ndocker compose -f runtime/docker-compose.yml -f runtime/docker-compose.dev.yml run --rm test --rule <coordinate> --verbose\n```\n- All checks must pass for both pass and fail fixtures\n- If test fails: re-examine the violation class analysis (step 3), not just the regex. The pattern may be structurally wrong, not just syntactically wrong.\n\n## Reference\n\n- Schema: `schemas/rule.schema.yml` — check field definitions, mechanical check names, severity enum\n- Patterns: `docs/pattern-guide.md` — pattern syntax, generic mode, combining patterns\n- Runtime: `runtime/` — test runner, fixture format, mechanical check implementations\n- Agent config: `agents/{agent}/config.yml` — template var values per agent\n- Path resolution: `.shared/knowledge/backbone-resolution.md`\n\n## Quick Reference\n\n| Rule type | Modifies rule.md | Modifies rule.yml | Fixture content |\n|-----------|-----------------|-------------------|-----------------|\n| mechanical | checks with `check` + `args` | No change (`rules: []`) | Files/dirs matching check function expectations |\n| deterministic | checks with `pattern` + `message` | Regex patterns | Content triggering/not triggering pattern |\n| semantic | pre-checks + terminal `prompt` | Regex patterns for pre-checks | Content producing/not producing candidates |\n\n## Severity Mapping\n\n| rule.md severity | rule.yml severity |\n|------------------|-------------------|\n| critical | ERROR |\n| high | WARNING |\n| medium | WARNING |\n| low | WARNING |\n\n## Pattern Design Examples\n\n### Good: Structural violation detection\n\nRule: \"has-project-description\" — file must open with a project description.\n\n**Violation structure**: Title exists, but next non-blank line is a section heading (no description prose between).\n\n```yaml\npattern-regex: \"^#\\\\s+[^\\\\n]+\\\\n\\\\s*\\\\n##\"\nmessage: \"Title followed immediately by section heading — no project description\"\n```\n\nThis catches the SHAPE of the problem: `# Title\\n\\n## Section` with nothing between.\n\n### Bad: Minimal fixture discrimination\n\nSame rule, but designed to discriminate fixtures:\n\n```yaml\npattern-regex: \"\\\\A## \"\nmessage: \"File opens with H2 instead of project description\"\n```\n\nThis only catches files starting with `##` — misses the primary failure mode (title present, description absent).\n\n### Good: Absence via structural gap\n\nRule: \"has-commands\" — file must document executable commands.\n\n**Violation structure**: File has sections but none contain backtick-wrapped commands.\n\n```yaml\n# Combined pattern: file has 2+ sections but zero backtick commands\npatterns:\n  - pattern-regex: \"^## \"\n  - pattern-not-regex: \"`[a-z]+ .+`\"\n```\n\nThis requires both conditions: structured file (has sections) AND no commands. A file with no structure at all fails a different rule.\n\n### Bad: Presence check with negate\n\nSame rule, but as a negated presence check:\n\n```yaml\npattern-regex: \"`[a-z]+ .+`\"\nnegate: true  # fragile — any backtick content satisfies this\n```\n\nA file containing `` `see above` `` or `` `my-var` `` passes this check despite having no actual commands.\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Pattern discriminates fixtures instead of catching violation class | Re-analyze: what is the STRUCTURAL SHAPE of the violation? |\n| Using `negate: true` as primary strategy | Find the structural gap pattern. Negate is last resort only. |\n| Pre-check matches rule topic instead of violation indicators | Pre-check should find text that NEEDS judgment, not text about the topic |\n| Fixture is minimal synthetic content | Write realistic 30-80 line instruction files |\n| Fail fixture is broken in multiple ways | One specific violation in an otherwise reasonable file |\n| Pattern matches desired state | Invert: pattern must match the violation |\n| Using `**/*.md` in paths | Use `{{instruction_files}}` template var |\n| Missing `cross_file: true` | Add when pattern operates across target set |\n| Semantic rule without pre-checks | Always add deterministic pre-check before semantic |\n| Fixture file named wrong | Must match resolved template var (e.g., `CLAUDE.md`) |\n| Leaving `.gitkeep` alongside real fixtures | Remove `.gitkeep` when adding content |"},"lastSynced":"2026-03-08T02:01:16.435Z","agentAnalysis":{"suitability":{"en":"Perfect for Coding Agents needing structured rule implementation and validation.","zh":"适合需要结构化规则实现和验证的编码代理。","ja":"コードエージェントが構造化されたルールの実装と検証を必要とする場合に適しています。","ko":"구조화된 규칙 구현 및 검증이 필요한 코딩 에이전트에 적합합니다.","es":"Perfecto para Agentes de Codificación que necesitan implementación y validación de reglas estructuradas.","fr":"Parfait pour les Agents de Codage nécessitant une mise en œuvre et une validation de règles structurées.","de":"Perfekt für Codierungsagenten, die eine strukturierte Regelimplementierung und -validierung benötigen.","pt":"Perfeito para Agentes de Codificação que necessitam de implementação e validação de regras estruturadas.","ru":"Идеально для Кодированных Агентов, требующих реализации и проверки структурированных правил.","ar":"مثالي لعميل التشفير الذين يحتاجون إلى تنفيذ وقواعد محكمة هيكلية."},"recommendation":{"en":"Empowers agents to implement checks, regex patterns, and test fixtures for existing rules, ensuring structure, content, efficiency, governance, and maintenance in AI projects using coordinate-based rule identification and template var resolution with agents like Claude.","zh":"赋予代理实现检查、正则表达式模式和测试固件用于现有规则，确保使用坐标基于规则识别和模板变量解析的AI项目中的结构、内容、效率、治理和维护，例如与Claude等代理一起使用。","ja":"エージェントが既存のルールに対してチェック、正規表現パターン、テストフィクスチャを実装し、座標ベースのルール識別とテンプレート変数解決を使用したAIプロジェクトで構造、コンテンツ、効率、ガバナンス、メンテナンスを確保することができます。例えば、Claudeなどのエージェントを使用する場合です。","ko":"에이전트가 기존 규칙에 대한 검사, 정규식 패턴 및 테스트 픽스를 구현하여 좌표 기반 규칙 식별 및 템플릿 변수 해결을 사용하는 AI 프로젝트에서 구조, 내용, 효율성, 거버넌스 및 유지 보수를 보장할 수 있습니다. 예를 들어 Claude와 같은 에이전트를 사용하는 경우에 적합합니다.","es":"Habilita a los agentes a implementar controles, patrones de regex y conjuntos de pruebas para reglas existentes, garantizando estructura, contenido, eficiencia, gobernanza y mantenimiento en proyectos de AI que utilizan la identificación de reglas basada en coordenadas y la resolución de variables de plantilla con agentes como Claude.","fr":"Permet aux agents de mettre en œuvre des contrôles, des modèles de regex et des jeux de tests pour les règles existantes, garantissant structure, contenu, efficacité, gouvernance et maintenance dans les projets d''IA utilisant l''identification de règles basée sur les coordonnées et la résolution de variables de modèle avec des agents comme Claude.","de":"Ermächtigt Agenten, Prüfungen, Regex-Muster und Testfixtures für bestehende Regeln zu implementieren, um Struktur, Inhalt, Effizienz, Governance und Wartung in KI-Projekten sicherzustellen, die die koordinatenbasierte Regelidentifizierung und die Vorlagenvariablenauflösung mit Agenten wie Claude verwenden.","pt":"Habilita agentes a implementar verificações, padrões regex e testes de fixture para regras existentes, garantindo estrutura, conteúdo, eficiência, governança e manutenção em projetos de IA que usam identificação de regras baseada em coordenadas e resolução de variáveis de modelo com agentes como Claude.","ru":"Наделяет агентов возможностью реализовать проверки, шаблоны regex и тестовые фикстуры для существующих правил, обеспечивая структуру, содержание, эффективность, управление и обслуживание в проектах ИИ, использующих координатную идентификацию правил и разрешение шаблонных переменных с помощью агентов, таких как Claude.","ar":"تمكن الوكيل من تنفيذ عمليات التحقق، وأنماط regex وإكسسوارات الاختبار للقواعد الحالية، مما يضمن الهيكل والمحتوى والكفاءة والحوكمة والصيانة في مشاريع الذكاء الاصطناعي التي تستخدم تحديد القواعد القائم على الإحداثيات وحل переменات القالب مع وكلاء مثل Claude."},"useCases":{"en":["Implementing custom validation logic for AI project rules","Generating test fixtures for rule-based AI systems","Validating regex patterns for data processing rules"],"zh":["为AI项目规则实现自定义验证逻辑","为基于规则的AI系统生成测试固件","验证数据处理规则的正则表达式模式"],"ja":["AIプロジェクトのルールに対してカスタムの検証ロジックを実装する","ルールベースのAIシステムに対してテストフィクスチャを生成する","データ処理ルールの正規表現パターンを検証する"],"ko":["AI 프로젝트 규칙에 대한 사용자 지정 검증 논리를 구현하는 것","규칙 기반 AI 시스템에 대한 테스트 픽스를 생성하는 것","데이터 처리 규칙의 정규식 패턴을 검증하는 것"],"es":["Implementar lógica de validación personalizada para reglas de proyectos de AI","Generar conjuntos de pruebas para sistemas de AI basados en reglas","Validar patrones de regex para reglas de procesamiento de datos"],"fr":["Mettre en œuvre une logique de validation personnalisée pour les règles de projets d''IA","Générer des jeux de tests pour les systèmes d''IA basés sur les règles","Valider des modèles de regex pour les règles de traitement de données"],"de":["Implementierung von benutzerdefinierter Validierungslogik für KI-Projektregeln","Generierung von Testfixtures für regelbasierte KI-Systeme","Validierung von Regex-Mustern für Datenverarbeitungsregeln"],"pt":["Implementar lógica de validação personalizada para regras de projeto de IA","Gerar testes de fixture para sistemas de IA baseados em regras","Validar padrões regex para regras de processamento de dados"],"ru":["Реализовать пользовательскую логику проверки для правил проекта ИИ","Генерировать тестовые фикстуры для систем ИИ на основе правил","Проверить шаблоны regex для правил обработки данных"],"ar":["تنفيذ منطق التحقق المخصص لقواعد مشروع الذكاء الاصطناعي","توليد إكسسوارات الاختبار لنظم الذكاء الاصطناعي القائمة على القواعد","التحقق من أنماط regex لقواعد معالجة البيانات"]},"limitations":{"en":["Requires existing rule skeleton with empty checks","Coordinate-based rule identification required","Template var resolution limited to specified agents like Claude"],"zh":["需要现有的规则骨架，且检查为空","需要坐标基于规则识别","模板变量解析仅限于指定的代理，如Claude"],"ja":["空のチェックを持つ既存のルールスケルトンが必要","座標ベースのルール識別が必要","テンプレート変数解決はClaudeなどの指定されたエージェントに限定される"],"ko":["비어 있는 확인을 갖는 기존 규칙 스켈레톤이 필요합니다.","좌표 기반 규칙 식별이 필요합니다.","템플릿 변수 해결은 Claude와 같은 지정된 에이전트로 제한됩니다."],"es":["Requiere esqueleto de regla existente con controles vacíos","Se requiere identificación de reglas basada en coordenadas","La resolución de variables de plantilla está limitada a agentes especificados como Claude"],"fr":["Nécessite un squelette de règle existant avec des contrôles vides","L''identification de règles basée sur les coordonnées est requise","La résolution de variables de modèle est limitée à des agents spécifiés comme Claude"],"de":["Benötigt vorhandenes Regelskelett mit leeren Prüfungen","Koordinatenbasierte Regelidentifizierung erforderlich","Die Vorlagenvariablenauflösung ist auf bestimmte Agenten wie Claude beschränkt"],"pt":["Requer esqueleto de regra existente com verificações vazias","Identificação de regra baseada em coordenadas necessária","Resolução de variável de modelo limitada a agentes especificados como Claude"],"ru":["Требуется существующий скелет правила с пустыми проверками","Координатная идентификация правила необходима","Разрешение шаблонной переменной ограничено агентами, такими как Claude"],"ar":["يتطلب هيكل قاعدة موجود مع عمليات تحقق فارغة","تحديد القاعدة القائم على الإحداثيات ضروري","حَلّ переменات القالب محدودة بالوكلاء المحددين مثل Claude"]},"version":4},"contentHash":"af40151dd8a53c51e154623c33f114ccabbc68ec40a0435e4cf9bd6708abf03f","qualityScore":60}');
