INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('reporails/rules/implement-rule', 'implement-rule', 'reporails', 'rules', 'community', 'implement-rule reporails rules community The implement-rule skill provides a framework for validating AI coding agent instructions, benefiting developers who need to ensure structure, content, efficiency, governance, and maintenance in their AI projects. Implement Rule 是一种用于验证 AI 代码代理指令的证据驱动规则，提供结构、内容、效率、治理和维护的核心规则 Implement Rule は、AI コードエージェントの指令を検証するためのエビデンス駆動型ルールであり、構造、コンテンツ、効率、ガバナンス、メンテナンスのためのコアルールを提供します Implement Rule은 AI 코드 에이전트 지침을 검증하기 위한 증거 기반 규칙으로 구조, 내용, 효율, 治理 및 유지 보수의 핵심 규칙을 제공합니다 Implement-rule es una habilidad que proporciona reglas de validación para instrucciones de agentes de codificación de IA, incluyendo estructura, contenido y eficiencia Implement-rule est une compétence qui fournit des règles de validation pour les instructions des outils de codage d''IA, notamment la structure, le contenu et l''efficacité Implement-rule ist eine Fähigkeit, die Validierungsregeln für Anweisungen von KI-Coding-Agenten bereitstellt, einschließlich Struktur, Inhalt und Effizienz O implement-rule é uma habilidade que fornece regras de validação para instruções de agentes de codificação de IA, garantindo estrutura, conteúdo e eficiência. Implement-rule - навык, предоставляющий правила проверки для инструкций ИИ агентов, обеспечивающий структуру, содержание и эффективность. implement-rule هو مهارة توفر قواعد التحقق من صحة لتعليمات وكلاء الذكاء الاصطناعي، مما يضمن الهيكل والمحتوى والكفاءة. how to use implement-rule implement-rule setup guide what is implement-rule implement-rule alternative implement-rule vs Claude implement-rule install AI coding agent validation evidence-backed rules for AI AI project governance and maintenance AI Agent Implement Rule 代码代理 规则实现 检查 正则表达式模式 测试 fixture CLI Generates checks, regex patterns, and test fixtures for existing rules Supports template variable resolution using agents like Claude Allows for dry-run mode to preview generated files without writing them Utilizes rule coordinates like CORE:C:0001 and CLAUDE:S:0001 for organization Enables customization with optional flags like --agent and --dry-run implement-rule is a skill that provides evidence-backed rules for validating AI coding agent instructions, focusing on structure, content, efficiency, governance, and maintenance');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chongdashu/cc-skills/seo-optimizer', 'community', 'chongdashu', 'cc-skills', 'chongdashu/cc-skills', 'seo-optimizer', 0, 0, 60, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:16.829Z', '59739e204c174d42c9346ce716cc0ffaf238946671700dfcbdfcdc9659790c78', '{"id":"chongdashu/cc-skills/seo-optimizer","name":"seo-optimizer","description":{"en":"The seo-optimizer skill transforms your web application by analyzing your codebase and implementing comprehensive SEO optimizations, helping search engines understand and surface your content.","zh":"SEO 优化器通过分析代码库并实施综合 SEO 优化，帮助搜索引擎和社交平台理解、索引和显示您的内容","ja":"SEO オプティマイザーはコードベースを分析し、包括的な SEO 最適化を実施して、検索エンジンとソーシャル プラットフォームがコンテンツを理解、索引、表示できるようにします","ko":"SEO 최적화器는 코드베이스를 분석하고 종합적인 SEO 최적화를 구현하여 검색 엔진과 소셜 플랫폼이 콘텐츠를 이해하고 색인하고 표시할 수 있도록 합니다","es":"El skill seo-optimizer analiza y optimiza tu código para mejorar la comprensión de los motores de búsqueda y plataformas sociales","fr":"Le skill seo-optimizer analyse et optimise votre code pour améliorer la compréhension des moteurs de recherche et des plateformes sociales","de":"Der seo-optimizer-Skill analysiert und optimiert Ihren Code, um die Verständlichkeit für Suchmaschinen und soziale Plattformen zu verbessern","pt":"O SEO Optimizer é uma ferramenta que analisa o seu código e aplica otimizações de SEO para melhorar a indexação e visibilidade do seu conteúdo","ru":"ИИ Агент SEO Optimizer - это инструмент, который анализирует ваш код и применяет оптимизации SEO для улучшения индексации и видимости вашего контента","ar":"مُحسّن SEO هو أداة تحليل شفرة المصدر وتطبيق تحسينات SEO لتحسين الفهرسة والرؤية لمحتوياتك"},"seo":{"title":{"en":"seo-optimizer: Comprehensive SEO Setup Guide | AI Agent S...","zh":"SEO 优化器设置指南 - 实现代码库优化","ja":"SEO オプティマイザーセットアップガイド - コードベースの最適化","ko":"SEO 최적화器 설정 가이드 - 코드베이스 최적화 구현","es":"Guía de Configuración de seo-optimizer para Desarrolladores","fr":"Configurer seo-optimizer : Guide pour les Développeurs","de":"seo-optimizer Einrichtung: Leitfaden für Entwickler","pt":"Guia de Configuração do SEO Optimizer: Otimização de Busc...","ru":"Настройка ИИ Агента SEO Optimizer: Руководство по оптимиз...","ar":"دليل إعداد مُحسّن SEO: تحسين محركات البحث المتقدم"},"description":{"en":"Unlock your web app''s discoverability with seo-optimizer. Learn how to implement semantic communication for search engines and social platforms. Get started ...","zh":"了解如何使用 SEO 优化器分析代码库并实施综合 SEO 优化，以帮助搜索引擎和社交平台理解、索引和显示您的内容","ja":"SEO オプティマイザーを使用してコードベースを分析し、包括的な SEO 最適化を実施して、検索エンジンとソーシャル プラットフォームがコンテンツを理解、索引、表示する方法について学びます","ko":"SEO 최적화器를 사용하여 코드베이스를 분석하고 종합적인 SEO 최적화를 구현하여 검색 엔진과 소셜 플랫폼이 콘텐츠를 이해하고 색인하고 표시하는 방법에 대해 알아보세요","es":"Aprende a configurar seo-optimizer para mejorar la visibilidad de tu aplicación web en los motores de búsqueda y plataformas sociales","fr":"Découvrez comment configurer seo-optimizer pour améliorer la visibilité de votre application web sur les moteurs de recherche et les plateformes sociales","de":"Erfahren Sie, wie Sie seo-optimizer einrichten, um die Sichtbarkeit Ihrer Webanwendung in Suchmaschinen und sozialen Plattformen zu verbessern","pt":"Aprenda a configurar o SEO Optimizer para melhorar a visibilidade do seu aplicativo web e aumentar o tráfego orgânico","ru":"Узнайте, как настроить ИИ Агент SEO Optimizer, чтобы повысить видимость вашего веб-приложения и увеличить органический трафик","ar":"تعرف على كيفية إعداد مُحسّن SEO لتحسين الرؤية لتطبيقك على الويب وزيادة Movement العضوي"},"definition":{"en":"seo-optimizer is a skill that analyzes and optimizes web applications for search engine discoverability through semantic communication.","zh":"SEO 优化器是一种分析代码库并实施综合 SEO 优化的工具，帮助搜索引擎和社交平台理解和索引内容","ja":"SEO オプティマイザーは、コードベースを分析し、包括的な SEO 最適化を実施するツールで、検索エンジンとソーシャル プラットフォームがコンテンツを理解、索引できるようにします","ko":"SEO 최적화器는 코드베이스를 분석하고 종합적인 SEO 최적화를 구현하는 도구로, 검색 엔진과 소셜 플랫폼이 콘텐츠를 이해하고 색인할 수 있도록 합니다","es":"seo-optimizer es un skill que transforma tu aplicación web en descubrible mediante la optimización semántica","fr":"seo-optimizer est un skill qui transforme votre application web en découvrable grâce à l''optimisation sémantique","de":"seo-optimizer ist ein Skill, der Ihre Webanwendung durch semantische Optimierung auffindbar macht","pt":"O SEO Optimizer é uma ferramenta de otimização de busca que ajuda a melhorar a visibilidade do seu aplicativo web","ru":"ИИ Агент SEO Optimizer - это инструмент оптимизации поиска, который помогает улучшить видимость вашего веб-приложения","ar":"مُحسّن SEO هو أداة لتحسين محركات البحث التي تساعد على تحسين الرؤية لتطبيقك على الويب"},"features":{"en":["Analyzes codebase for SEO optimization opportunities","Implements comprehensive SEO optimizations for search engines and social platforms","Enables semantic communication for machines to understand content","Helps search engines and social platforms index and surface content","Transforms web applications from invisible to discoverable"],"zh":["代码库分析","综合 SEO 优化","搜索引擎优化","社交平台优化","语义通信","AI 爬虫优化"],"ja":["コードベース分析","包括的な SEO 最適化","検索エンジン最適化","ソーシャル プラットフォーム最適化","セマンティック コミュニケーション","AI クローラー最適化"],"ko":["코드베이스 분석","종합적인 SEO 최적화","검색 엔진 최적화","소셜 플랫폼 최적화","语义 커뮤니케이션","AI 크롤러 최적화"],"es":["Análisis de código para optimización SEO","Implementación de optimizaciones semánticas para motores de búsqueda y plataformas sociales","Mejora de la comprensión de la estructura y el contenido de tu aplicación web","Indexación y superficie de contenido en motores de búsqueda y plataformas sociales","Integración con herramientas de desarrollo como CLI y frameworks como React y Python"],"fr":["Analyse de code pour l''optimisation SEO","Mise en œuvre d''optimisations sémantiques pour les moteurs de recherche et les plateformes sociales","Amélioration de la compréhension de la structure et du contenu de votre application web","Indexation et mise en surface de contenu dans les moteurs de recherche et les plateformes sociales","Intégration avec des outils de développement comme CLI et des frameworks comme React et Python"],"de":["Code-Analyse für SEO-Optimierung","Implementierung semantischer Optimierungen für Suchmaschinen und soziale Plattformen","Verbesserung der Verständlichkeit der Struktur und des Inhalts Ihrer Webanwendung","Indexierung und Oberflächenbildung von Inhalten in Suchmaschinen und sozialen Plattformen","Integration mit Entwicklungstools wie CLI und Frameworks wie React und Python"],"pt":["Análise de código para otimização de SEO","Implementação de otimizações de SEO para melhorar a indexação","Comunicação clara com máquinas para melhorar a visibilidade","Otimização para motores de busca e plataformas sociais","Melhoria da visibilidade do conteúdo com otimizações semânticas"],"ru":["Анализ кода для оптимизации SEO","Применение оптимизаций SEO для улучшения индексации","Ясная коммуникация с машинами для улучшения видимости","Оптимизация для поисковых систем и социальных платформ","Улучшение видимости контента с помощью семантических оптимизаций"],"ar":["تحليل شفرة المصدر لتحسين محركات البحث","تطبيق تحسينات محركات البحث لتحسين الفهرسة","تواصل واضح مع الآلات لتحسين الرؤية","تحسين محركات البحث والمنصات الاجتماعية","تحسين الرؤية للمحتويات باستخدام تحسينات семантиكية"]},"keywords":{"en":["how to use seo-optimizer","seo-optimizer setup guide","what is seo-optimizer","seo-optimizer alternative","seo-optimizer vs other SEO tools","seo-optimizer install","seo-optimizer for AI agents","semantic communication for search engines","seo optimization for web applications"],"zh":["SEO 优化器","代码库分析","综合 SEO 优化","搜索引擎优化","社交平台优化","AI 工具","语义通信","SEO 设置指南"],"ja":["SEO オプティマイザー","コードベース分析","包括的な SEO 最適化","検索エンジン最適化","ソーシャル プラットフォーム最適化","AI エージェント","セマンティック コミュニケーション","SEO セットアップガイド"],"ko":["SEO 최적화器","코드베이스 분석","종합적인 SEO 최적화","검색 엔진 최적화","소셜 플랫폼 최적화","AI 도구","语义 커뮤니케이션","SEO 설정 가이드"],"es":["seo-optimizer","optimización semántica","motores de búsqueda","plataformas sociales","desarrollo web","CLI","React","Python","herramientas de desarrollo","mejora de visibilidad"],"fr":["seo-optimizer","optimisation sémantique","moteurs de recherche","plateformes sociales","développement web","CLI","React","Python","outils de développement","amélioration de visibilité"],"de":["seo-optimizer","semantische Optimierung","Suchmaschinen","soziale Plattformen","Webentwicklung","CLI","React","Python","Entwicklungstools","Sichtbarkeitsverbesserung"],"pt":["otimização de busca","SEO","visibilidade do aplicativo web","índice de busca","otimização semântica","ferramentas de SEO","melhoria da visibilidade","análise de código","implementação de SEO"],"ru":["оптимизация поиска","SEO","видимость веб-приложения","индекс поиска","семантическая оптимизация","инструменты SEO","улучшение видимости","анализ кода","применение SEO"],"ar":["تحسين محركات البحث","SEO","رؤية تطبيق الويب","فهرس محركات البحث","تحسين محركات البحث الدلالي","أدوات تحسين محركات البحث","تحسين الرؤية","تحليل شفرة المصدر","تطبيق تحسين محركات البحث"]}},"owner":"chongdashu","repo":"cc-skills","repoPath":"chongdashu/cc-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"seo-optimizer","description":">","bodyPreview":"# SEO Optimizer\n\nTransform your web application from invisible to discoverable. This skill analyzes your codebase and implements comprehensive SEO optimizations that help search engines and social platforms understand, index, and surface your content.\n\n## Philosophy: SEO as Semantic Communication\n\nSEO is not about gaming algorithms—it''s about **clearly communicating what your content IS** to machines (search engines, social platforms, AI crawlers) so they can properly understand and surface it.","body":"# SEO Optimizer\n\nTransform your web application from invisible to discoverable. This skill analyzes your codebase and implements comprehensive SEO optimizations that help search engines and social platforms understand, index, and surface your content.\n\n## Philosophy: SEO as Semantic Communication\n\nSEO is not about gaming algorithms—it''s about **clearly communicating what your content IS** to machines (search engines, social platforms, AI crawlers) so they can properly understand and surface it.\n\n**Before optimizing, ask**:\n- What is this page actually about? (not what keywords we want to rank for)\n- Who is the intended audience and what are they searching for?\n- What unique value does this content provide?\n- How should machines categorize and understand this content?\n\n**Core Principles**:\n\n1. **Accuracy Over Optimization**: Describe what IS, not what you wish would rank\n2. **User Intent First**: Match content to what searchers actually want\n3. **Semantic Clarity**: Use structured data to make meaning machine-readable\n4. **Progressive Enhancement**: Basic SEO for all pages, rich optimization for key pages\n5. **Framework-Native**: Use each framework''s idioms, not generic hacks\n\n**The SEO Hierarchy** (prioritize in order):\n```\n1. Content Quality      ← Foundation: Valuable, accurate, unique content\n2. Technical Access     ← Can crawlers find and index your pages?\n3. Semantic Structure   ← Do machines understand your content''s meaning?\n4. Meta Optimization    ← Are your titles/descriptions compelling?\n5. Structured Data      ← JSON-LD for rich search results\n6. Performance          ← Core Web Vitals affect rankings\n```\n\n---\n\n## Codebase Analysis Workflow\n\n**ALWAYS analyze before implementing.** Different codebases need different approaches.\n\n### Step 1: Discover Framework and Structure\n\nIdentify the framework and routing pattern:\n- **Next.js**: Look for `next.config.js`, `app/` or `pages/` directory\n- **Astro**: Look for `astro.config.mjs`, `src/pages/`\n- **React Router**: Look for route configuration, `react-router-dom`\n- **Gatsby**: Look for `gatsby-config.js`, `gatsby-node.js`\n- **Static HTML**: Look for `.html` files in root or `public/`\n\n### Step 2: Audit Current SEO State\n\nCheck for existing implementations:\n- [ ] Meta tags in `<head>` (title, description, viewport)\n- [ ] Open Graph tags (`og:title`, `og:image`, etc.)\n- [ ] Twitter Card tags (`twitter:card`, `twitter:image`)\n- [ ] Structured data (`<script type=\"application/ld+json\">`)\n- [ ] Sitemap (`sitemap.xml` or generation config)\n- [ ] Robots.txt file\n- [ ] Canonical URLs\n- [ ] Alt text on images\n\n### Step 3: Identify Page Types\n\nDifferent pages need different SEO approaches:\n\n| Page Type | Priority | Key Optimizations |\n|-----------|----------|-------------------|\n| Landing/Home | Critical | Brand keywords, comprehensive structured data |\n| Product/Service | High | Product schema, reviews, pricing |\n| Blog/Article | High | Article schema, author, publish date |\n| Documentation | Medium | HowTo/FAQ schema, breadcrumbs |\n| About/Contact | Medium | Organization schema, local business |\n| Legal/Privacy | Low | Basic meta only, often noindex |\n\n### Step 4: Generate Implementation Plan\n\nBased on analysis, prioritize:\n1. **Quick wins**: Missing meta tags, viewport, basic structure\n2. **High impact**: Structured data for key pages, sitemap\n3. **Refinement**: Performance, advanced schema, social optimization\n\nSee `references/analysis-checklist.md` for detailed audit procedures.\n\n---\n\n## Meta Tags Implementation\n\n### Essential Meta Tags (Every Page)\n\n```html\n<!-- Required -->\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>{Page Title} | {Site Name}</title>\n<meta name=\"description\" content=\"{150-160 char description}\">\n\n<!-- Recommended -->\n<link rel=\"canonical\" href=\"{full canonical URL}\">\n<meta name=\"robots\" content=\"index, follow\">\n```\n\n### Title Tag Best Practices\n\n**Format**: `{Primary Content} | {Brand}` or `{Primary Content} - {Brand}`\n\n**Guidelines**:\n- 50-60 characters (Google truncates at ~60)\n- Front-load important keywords\n- Unique for every page\n- Accurately describe page content\n- Include brand for recognition (usually at end)\n\n**Title Patterns by Page Type**:\n```\nHomepage:     {Brand} - {Value Proposition}\nProduct:      {Product Name} - {Key Benefit} | {Brand}\nArticle:      {Article Title} | {Brand}\nCategory:     {Category} Products | {Brand}\nSearch:       Search Results for \"{Query}\" | {Brand}\n```\n\n### Meta Description Best Practices\n\n**Guidelines**:\n- 150-160 characters (Google may truncate at ~155)\n- Include a call to action when appropriate\n- Accurately summarize page content\n- Unique for every page\n- Include primary keyword naturally\n\n**DO NOT**:\n- Stuff keywords unnaturally\n- Use the same description across pages\n- Write descriptions that don''t match content\n- Start with \"Welcome to...\" or similar filler\n\n### Open Graph Tags (Social Sharing)\n\n```html\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:url\" content=\"{canonical URL}\">\n<meta property=\"og:title\" content=\"{title}\">\n<meta property=\"og:description\" content=\"{description}\">\n<meta property=\"og:image\" content=\"{1200x630 image URL}\">\n<meta property=\"og:site_name\" content=\"{Site Name}\">\n```\n\n### Twitter Card Tags\n\n```html\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:site\" content=\"@{handle}\">\n<meta name=\"twitter:title\" content=\"{title}\">\n<meta name=\"twitter:description\" content=\"{description}\">\n<meta name=\"twitter:image\" content=\"{image URL}\">\n```\n\nSee `references/meta-tags-complete.md` for comprehensive tag reference.\n\n---\n\n## Structured Data (JSON-LD)\n\nStructured data enables rich search results (star ratings, prices, FAQs, etc.).\n\n### When to Use Which Schema\n\n| Content Type | Schema | Rich Result |\n|--------------|--------|-------------|\n| Organization info | Organization | Knowledge panel |\n| Products | Product | Price, availability, reviews |\n| Articles/Blog | Article | Headline, image, date |\n| How-to guides | HowTo | Step-by-step in search |\n| FAQs | FAQPage | Expandable Q&A |\n| Events | Event | Date, location, tickets |\n| Recipes | Recipe | Image, time, ratings |\n| Local business | LocalBusiness | Maps, hours, contact |\n| Breadcrumbs | BreadcrumbList | Navigation path |\n\n### Implementation Pattern\n\n```html\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Organization\",\n  \"name\": \"Company Name\",\n  \"url\": \"https://example.com\",\n  \"logo\": \"https://example.com/logo.png\",\n  \"sameAs\": [\n    \"https://twitter.com/company\",\n    \"https://linkedin.com/company/company\"\n  ]\n}\n</script>\n```\n\n### Multiple Schemas Per Page\n\nUse `@graph` to combine schemas:\n\n```json\n{\n  \"@context\": \"https://schema.org\",\n  \"@graph\": [\n    { \"@type\": \"Organization\", ... },\n    { \"@type\": \"WebSite\", ... },\n    { \"@type\": \"BreadcrumbList\", ... }\n  ]\n}\n```\n\nSee `references/structured-data-schemas.md` for complete schema examples.\n\n---\n\n## Technical SEO\n\n### Sitemap Generation\n\n**XML Sitemap Requirements**:\n- Include all indexable pages\n- Exclude noindex pages, redirects, error pages\n- Update `<lastmod>` when content changes\n- Submit to Google Search Console\n\n**Framework implementations**: See `references/framework-implementations.md`\n\n### Robots.txt\n\n**Standard Template**:\n```txt\nUser-agent: *\nAllow: /\n\n# Block admin/private areas\nDisallow: /admin/\nDisallow: /api/\nDisallow: /private/\n\n# Point to sitemap\nSitemap: https://yourdomain.com/sitemap.xml\n```\n\n### Canonical URLs\n\n**Always set canonical URLs to**:\n- Prevent duplicate content issues\n- Consolidate link equity\n- Specify preferred URL version\n\n**Handle**:\n- www vs non-www\n- http vs https\n- Trailing slashes\n- Query parameters\n\n### Performance (Core Web Vitals)\n\nCore Web Vitals affect rankings. Monitor:\n\n| Metric | Target | What It Measures |\n|--------|--------|------------------|\n| LCP | < 2.5s | Largest Contentful Paint (loading) |\n| INP | < 200ms | Interaction to Next Paint (interactivity) |\n| CLS | < 0.1 | Cumulative Layout Shift (visual stability) |\n\n**Quick wins**:\n- Optimize images (WebP, lazy loading, proper sizing)\n- Minimize JavaScript bundles\n- Use efficient fonts (display: swap)\n- Implement proper caching\n\n---\n\n## Anti-Patterns to Avoid\n\n❌ **Keyword Stuffing**\n```html\n<!-- BAD -->\n<title>Best Shoes | Buy Shoes | Cheap Shoes | Shoes Online | Shoe Store</title>\n\n<!-- GOOD -->\n<title>Running Shoes for Marathon Training | SportShop</title>\n```\nWhy bad: Search engines penalize unnatural keyword repetition. Users don''t click spammy titles.\n\n❌ **Duplicate Descriptions**\nUsing the same meta description across multiple pages.\nWhy bad: Misses opportunity for page-specific relevance. Google may ignore and auto-generate.\n\n❌ **Description/Content Mismatch**\nWriting descriptions for keywords rather than actual content.\nWhy bad: High bounce rates signal low quality. Users feel deceived.\n\n❌ **Missing Alt Text**\n```html\n<!-- BAD -->\n<img src=\"product.jpg\">\n\n<!-- GOOD -->\n<img src=\"product.jpg\" alt=\"Blue Nike Air Max running shoe, side view\">\n```\nWhy bad: Accessibility violation. Missed image search opportunity.\n\n❌ **Blocking Crawlers Unintentionally**\n```txt\n# Accidentally blocking everything\nUser-agent: *\nDisallow: /\n```\nWhy bad: Complete deindexing. Check robots.txt carefully.\n\n❌ **Ignoring Mobile**\nNot having responsive design or mobile-specific considerations.\nWhy bad: Google uses mobile-first indexing. Most traffic is mobile.\n\n❌ **Over-Optimization**\nAdding structured data for content that doesn''t exist.\nWhy bad: Schema violations can result in penalties. Trust erosion.\n\n❌ **Generic Auto-Generated Content**\n```html\n<!-- BAD: Template without customization -->\n<meta name=\"description\" content=\"Welcome to our website. We offer great products and services.\">\n```\nWhy bad: Provides no value. Won''t rank. Won''t get clicks.\n\n---\n\n## Variation Guidance\n\n**IMPORTANT**: SEO implementation should vary based on context.\n\n**Vary based on**:\n- **Industry**: E-commerce needs Product schema; SaaS needs Software schema\n- **Content type**: Blog posts vs landing pages vs documentation\n- **Audience**: B2B vs B2C affects tone and keywords\n- **Competition**: Highly competitive niches need more sophisticated optimization\n- **Framework**: Use native patterns (Next.js metadata API vs manual tags)\n\n**Avoid converging on**:\n- Same title format for all page types\n- Generic descriptions that could apply to any site\n- Identical structured data without page-specific content\n- One-size-fits-all sitemap configuration\n\n---\n\n## Framework Quick Reference\n\n### Next.js (App Router)\n\n```typescript\n// app/page.tsx\nimport { Metadata } from ''next''\n\nexport const metadata: Metadata = {\n  title: ''Page Title | Brand'',\n  description: ''Page description'',\n  openGraph: {\n    title: ''Page Title'',\n    description: ''Page description'',\n    images: [''/og-image.png''],\n  },\n}\n```\n\n### Next.js (Pages Router)\n\n```typescript\n// pages/index.tsx\nimport Head from ''next/head''\n\nexport default function Page() {\n  return (\n    <Head>\n      <title>Page Title | Brand</title>\n      <meta name=\"description\" content=\"Page description\" />\n    </Head>\n  )\n}\n```\n\n### Astro\n\n```astro\n---\n// src/pages/index.astro\nimport Layout from ''../layouts/Layout.astro'';\n---\n<Layout\n  title=\"Page Title | Brand\"\n  description=\"Page description\"\n  ogImage=\"/og-image.png\"\n/>\n```\n\n### React (react-helmet)\n\n```jsx\nimport { Helmet } from ''react-helmet'';\n\nfunction Page() {\n  return (\n    <Helmet>\n      <title>Page Title | Brand</title>\n      <meta name=\"description\" content=\"Page description\" />\n    </Helmet>\n  );\n}\n```\n\nSee `references/framework-implementations.md` for complete guides.\n\n---\n\n## Scripts\n\n### analyze_seo.py\n\nAnalyzes a codebase for SEO issues and opportunities:\n\n```bash\npython scripts/analyze_seo.py <path-to-project>\n```\n\n**Output**:\n- Current SEO state (what''s implemented)\n- Missing elements by priority\n- Page-by-page recommendations\n- Structured data opportunities\n\n### generate_sitemap.py\n\nGenerates sitemap.xml from project routes:\n\n```bash\npython scripts/generate_sitemap.py <path-to-project> --domain https://example.com\n```\n\n---\n\n## Remember\n\n**SEO is semantic communication, not algorithm manipulation.**\n\nThe best SEO:\n- Accurately describes what content IS\n- Helps machines understand meaning through structured data\n- Prioritizes user value over keyword optimization\n- Uses framework-native patterns\n- Implements progressively based on page importance\n\nFocus on making your content findable and understandable. The rankings follow from genuine value clearly communicated.\n\n**Claude is capable of comprehensive SEO analysis and implementation. These guidelines illuminate the path—they don''t fence it.**\n"},"lastSynced":"2026-03-08T02:01:16.829Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing advanced SEO optimization capabilities to enhance content discoverability","zh":"非常适合需要高级SEO优化功能来增强内容发现的Web开发代理","ja":"Web開発エージェントが高度なSEO最適化機能を必要とする場合に最適","ko":"콘텐츠 발견을 향상시키기 위해 고급 SEO 최적화 기능이 필요한 웹 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo web que necesitan capacidades de optimización de SEO avanzadas para mejorar la capacidad de descubrimiento de contenido","fr":"Parfait pour les agents de développement Web nécessitant des capacités de optimisation de SEO avancées pour améliorer la découverte de contenu","de":"Perfekt für Webentwicklungsagenten, die erweiterte SEO-Optimierungsfunktionen benötigen, um die Auffindbarkeit von Inhalten zu verbessern","pt":"Perfeito para agentes de desenvolvimento web que precisam de capacidades avançadas de otimização de SEO para melhorar a descoberta de conteúdo","ru":"Идеально подходит для агентов веб-разработки, которым необходимы продвинутые возможности оптимизации SEO для улучшения обнаружения контента","ar":"مثالي للوكلاء التطوير الويب الذين يحتاجون إلى قدرات متقدمة لتحسين محركات البحث لتحسين اكتشاف المحتوى"},"recommendation":{"en":"Empowers agents to analyze codebases and implement comprehensive SEO optimizations, utilizing semantic communication to clearly convey content meaning to search engines and social platforms, leveraging protocols such as HTML and CSS to improve indexing and surfacing of content","zh":"赋予代理分析代码库并实施全面的SEO优化的能力，利用语义通信清晰地传达内容意义给搜索引擎和社交平台，利用HTML和CSS等协议来改善索引和内容的显示","ja":"エージェントにコードベースを分析し、包括的なSEO最適化を実装する能力を与え、語義的なコミュニケーションを使用してコンテンツの意味を検索エンジンやソーシャルプラットフォームに明確に伝達し、HTMLやCSSなどのプロトコルを使用してコンテンツのインデックス付けや表示を改善する","ko":"에이전트가 코드베이스를 분석하고 포괄적인 SEO 최적화를 구현할 수 있는 능력을 부여하며, 의미 있는 커뮤니케이션을 사용하여 콘텐츠 의미를 검색 엔진 및 소셜 플랫폼에 명확하게 전달하고, HTML 및 CSS와 같은 프로토콜을 사용하여 콘텐츠의 색인화 및 표시를 개선","es":"Habilita a los agentes a analizar bases de código y implementar optimizaciones de SEO integrales, utilizando la comunicación semántica para transmitir claramente el significado del contenido a los motores de búsqueda y plataformas sociales, aprovechando protocolos como HTML y CSS para mejorar el indexado y la visualización de contenido","fr":"Permet aux agents d''analyser les bases de code et de mettre en œuvre des optimisations de SEO complètes, en utilisant la communication sémantique pour transmettre clairement le sens du contenu aux moteurs de recherche et aux plateformes sociales, en exploitant des protocoles tels que HTML et CSS pour améliorer l''indexation et la mise en surface du contenu","de":"Ermächtigt Agenten, Codebasen zu analysieren und umfassende SEO-Optimierungen zu implementieren, indem sie semantische Kommunikation nutzen, um den Inhaltssinn klar an Suchmaschinen und soziale Plattformen zu übermitteln und Protokolle wie HTML und CSS nutzen, um die Indizierung und Darstellung von Inhalten zu verbessern","pt":"Habilita os agentes a analisar bases de código e implementar otimizações de SEO abrangentes, utilizando comunicação semântica para transmitir claramente o significado do conteúdo para mecanismos de busca e plataformas sociais, aproveitando protocolos como HTML e CSS para melhorar o indexamento e a exposição do conteúdo","ru":"Наделяет агентов возможностью анализировать кодовые базы и реализовывать всесторонние оптимизации SEO, используя семантическую коммуникацию для четкого передачи смысла контента поисковым системам и социальным платформам, используя протоколы such as HTML и CSS для улучшения индексирования и представления контента","ar":"يمكن الوكلاء من تحليل قواعد البيانات وتنفيذ تحسينات متكاملة لمحركات البحث، باستخدام التواصل الدلالي لنقل معنى المحتوى بوضوح إلى محركات البحث ومنصات التواصل الاجتماعي، واستخدام بروتوكولات مثل HTML و CSS لتحسين الفهرسة وعرض المحتوى"},"useCases":{"en":["Analyzing codebases for SEO optimization opportunities","Implementing semantic HTML structures to improve content understanding","Optimizing content for social platform indexing and sharing"],"zh":["分析代码库以查找SEO优化机会","实施语义HTML结构以改善内容理解","优化内容以适应社交平台的索引和共享"],"ja":["SEO最適化の機会を探すためのコードベースの分析","コンテンツの理解を改善するためのセマンティックHTML構造の実装","ソーシャルプラットフォームのインデックス付けや共有のためのコンテンツの最適化"],"ko":["SEO 최적화 기회를 찾기 위한 코드베이스 분석","콘텐츠 이해를 개선하기 위한 의미 있는 HTML 구조 구현","소셜 플랫폼의 색인화 및 공유를 위한 콘텐츠 최적화"],"es":["Analizar bases de código para oportunidades de optimización de SEO","Implementar estructuras de HTML semántico para mejorar la comprensión de contenido","Optimizar contenido para indexación y compartición en plataformas sociales"],"fr":["Analyser les bases de code pour les opportunités d''optimisation de SEO","Mettre en œuvre des structures HTML sémantiques pour améliorer la compréhension du contenu","Optimiser le contenu pour l''indexation et le partage sur les plateformes sociales"],"de":["Codebasen auf SEO-Optimierungschancen analysieren","Semantische HTML-Strukturen implementieren, um die Inhaltsverständlichkeit zu verbessern","Inhalte für die Indizierung und den Austausch auf sozialen Plattformen optimieren"],"pt":["Analisar bases de código para oportunidades de otimização de SEO","Implementar estruturas HTML semânticas para melhorar a compreensão do conteúdo","Otimizar conteúdo para indexação e compartilhamento em plataformas sociais"],"ru":["Анализ кодовых баз для выявления возможностей оптимизации SEO","Реализация семантических структур HTML для улучшения понимания контента","Оптимизация контента для индексирования и обмена в социальных платформах"],"ar":["تحليل قواعد البيانات لفرص تحسين محركات البحث","تنفيذ هياكل HTML الدلالية لتحسين فهم المحتوى","تحسين المحتوى لفهرسة ومنصة التواصل الاجتماعي للمشاركة"]},"limitations":{"en":["Requires access to codebase and content","Limited to web application optimization","Dependent on search engine and social platform algorithms"],"zh":["需要访问代码库和内容","仅限于Web应用程序的优化","依赖于搜索引擎和社交平台的算法"],"ja":["コードベースやコンテンツへのアクセスが必要","Webアプリケーションの最適化のみに限定される","検索エンジンやソーシャルプラットフォームのアルゴリズムに依存する"],"ko":["코드베이스 및 콘텐츠에 대한 액세스가 필요","웹 애플리케이션 최적화에만 제한","검색 엔진 및 소셜 플랫폼의 알고리즘에 의존"],"es":["Requiere acceso a la base de código y contenido","Limitado a la optimización de aplicaciones web","Dependiente de los algoritmos de los motores de búsqueda y plataformas sociales"],"fr":["Nécessite un accès à la base de code et au contenu","Limité à l''optimisation des applications Web","Dépendant des algorithmes des moteurs de recherche et des plateformes sociales"],"de":["Erfordert Zugriff auf Codebase und Inhalt","Begrenzt auf die Optimierung von Webanwendungen","Von den Algorithmen der Suchmaschinen und sozialen Plattformen abhängig"],"pt":["Requer acesso à base de código e conteúdo","Limitado à otimização de aplicativos web","Dependente de algoritmos de mecanismos de busca e plataformas sociais"],"ru":["Требует доступа к кодовой базе и контенту","Ограничен оптимизацией веб-приложений","Зависит от алгоритмов поисковых систем и социальных платформ"],"ar":["يتطلب الوصول إلى قاعدة البيانات والمحتوى","محدود لتحسين تطبيقات الويب","يعتمد على خوارزميات محركات البحث ومنصات التواصل الاجتماعي"]},"version":4},"contentHash":"59739e204c174d42c9346ce716cc0ffaf238946671700dfcbdfcdc9659790c78","qualityScore":60}');
