INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chongdashu/cc-skills/seo-optimizer', 'seo-optimizer', 'chongdashu', 'cc-skills', 'community', 'seo-optimizer chongdashu cc-skills community The seo-optimizer skill transforms your web application by analyzing your codebase and implementing comprehensive SEO optimizations, helping search engines understand and surface your content. SEO 优化器通过分析代码库并实施综合 SEO 优化，帮助搜索引擎和社交平台理解、索引和显示您的内容 SEO オプティマイザーはコードベースを分析し、包括的な SEO 最適化を実施して、検索エンジンとソーシャル プラットフォームがコンテンツを理解、索引、表示できるようにします SEO 최적화器는 코드베이스를 분석하고 종합적인 SEO 최적화를 구현하여 검색 엔진과 소셜 플랫폼이 콘텐츠를 이해하고 색인하고 표시할 수 있도록 합니다 El skill seo-optimizer analiza y optimiza tu código para mejorar la comprensión de los motores de búsqueda y plataformas sociales Le skill seo-optimizer analyse et optimise votre code pour améliorer la compréhension des moteurs de recherche et des plateformes sociales Der seo-optimizer-Skill analysiert und optimiert Ihren Code, um die Verständlichkeit für Suchmaschinen und soziale Plattformen zu verbessern O SEO Optimizer é uma ferramenta que analisa o seu código e aplica otimizações de SEO para melhorar a indexação e visibilidade do seu conteúdo ИИ Агент SEO Optimizer - это инструмент, который анализирует ваш код и применяет оптимизации SEO для улучшения индексации и видимости вашего контента مُحسّن SEO هو أداة تحليل شفرة المصدر وتطبيق تحسينات SEO لتحسين الفهرسة والرؤية لمحتوياتك how to use seo-optimizer seo-optimizer setup guide what is seo-optimizer seo-optimizer alternative seo-optimizer vs other SEO tools seo-optimizer install seo-optimizer for AI agents semantic communication for search engines seo optimization for web applications SEO 优化器 代码库分析 综合 SEO 优化 搜索引擎优化 社交平台优化 AI 工具 语义通信 SEO 设置指南 Analyzes codebase for SEO optimization opportunities Implements comprehensive SEO optimizations for search engines and social platforms Enables semantic communication for machines to understand content Helps search engines and social platforms index and surface content Transforms web applications from invisible to discoverable seo-optimizer is a skill that analyzes and optimizes web applications for search engine discoverability through semantic communication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DNYoussef/ai-chrome-extension/sop-code-review', 'community', 'DNYoussef', 'ai-chrome-extension', 'DNYoussef/ai-chrome-extension', 'sop-code-review', 0, 0, 60, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:19.730Z', 'f037ea7ac295f5df48a190878295331c7011390a263abfe6fa1d8fc50e47e8e1', '{"id":"DNYoussef/ai-chrome-extension/sop-code-review","name":"sop-code-review","description":{"en":"The sop-code-review skill provides a comprehensive code review workflow for developers, utilizing specialized reviewers for different quality aspects. This workflow is designed for AI agents and includes automated checks, specialized reviews, and integration reviews.","zh":"sop-code-review是一种代码审查工作流，使用自动化检查和专家代码审查来提高代码质量","ja":"sop-code-reviewは、自動化チェックと専門家によるコードレビューを使用してコード品質を向上させるコードレビューのワークフローです","ko":"sop-code-review는 자동화된 검토와 전문가 코드 검토를 사용하여 코드 품질을 향상시키는 코드 검토 워크플로우입니다","es":"La revisión de código es un proceso crucial para garantizar la calidad y seguridad del código. Con la herramienta de revisión de código, puedes automatizar las comprobaciones y revisar el código de manera especializada","fr":"La revue de code est un processus crucial pour garantir la qualité et la sécurité du code. Avec l''outil de revue de code, vous pouvez automatiser les vérifications et examiner le code de manière spécialisée","de":"Die Code-Review ist ein entscheidender Prozess, um die Qualität und Sicherheit des Codes zu gewährleisten. Mit dem Code-Review-Tool können Sie die Prüfungen automatisieren und den Code spezialisiert überprüfen","pt":"O SOP-Code-Review é um fluxo de revisão de código abrangente que utiliza revisores especializados para diferentes aspectos de qualidade","ru":"SOP-Code-Review - это комплексный обзор кода, использующий специализированных рецензентов для различных аспектов качества","ar":"SOP-Code-Review هو تدفق مراجعة الكود الشامل الذي يستخدم مراجعين متخصصين لجوانب الجودة المختلفة"},"seo":{"title":{"en":"sop-code-review: Comprehensive Code Review Workflow Setup...","zh":"代码审查工作流Setup Guide - sop-code-review","ja":"AIエージェントのコードレビューBest Practices - sop-code-review","ko":"코드 리뷰 워크플로우 설정 가이드 - sop-code-review","es":"Guía de Configuración de Revisión de Código con Herramien...","fr":"Guide de Configuration de la Revue de Code avec Outils d''...","de":"Einrichtungsleitfaden für Code-Review mit KI-Tools","pt":"Guia de Configuração do SOP-Code-Review: Fluxo de Revisão...","ru":"Настройка SOP-Code-Review: Комплексный Обзор Код","ar":"دليل إعداد SOP-Code-Review: تدفق مراجعة الكود"},"description":{"en":"Discover how to implement a 4-hour code review workflow with sop-code-review. Learn about automated checks, specialized reviews, and integration reviews. Get...","zh":"使用sop-code-review实现自动化代码审查和专家代码审查，提高代码质量和开发效率","ja":"AIエージェントを使用したコードレビューの自動化と専門家によるコードレビューでコード品質と開発効率を向上","ko":"sop-code-review를 사용하여 자동화된 코드 검토와 전문가 코드 검토로 코드 품질과 개발 효율성을 향상","es":"Aprende a configurar la revisión de código con herramientas de IA para mejorar la calidad y seguridad de tu código","fr":"Découvrez comment configurer la revue de code avec des outils d''IA pour améliorer la qualité et la sécurité de votre code","de":"Erfahren Sie, wie Sie die Code-Review mit KI-Tools konfigurieren, um die Qualität und Sicherheit Ihres Codes zu verbessern","pt":"Aprenda a configurar o SOP-Code-Review para melhorar a qualidade do seu código com revisões automatizadas e especializadas","ru":"Узнайте, как настроить SOP-Code-Review для улучшения качества кода с помощью автоматизированных и специализированных обзоров","ar":"تعلم كيفية إعداد SOP-Code-Review لتحسين جودة الكود الخاص بك من خلال المراجعات الآلية والتخصصية"},"definition":{"en":"sop-code-review is a code review workflow that utilizes parallel automated testing and specialized reviewers to ensure high-quality code, following a 4-phase process: automated checks, specialized reviews, integration review, and final approval.","zh":"sop-code-review是一种代码审查工作流，使用自动化检查和专家代码审查来确保代码质量","ja":"sop-code-reviewは、コード品質を確保するために自動化チェックと専門家によるコードレビューを使用するコードレビューのワークフローです","ko":"sop-code-review는 코드 품질을 보장하기 위해 자동화된 검토와 전문가 코드 검토를 사용하는 코드 검토 워크플로우입니다","es":"La revisión de código es un proceso que utiliza herramientas de IA para examinar y mejorar la calidad y seguridad del código","fr":"La revue de code est un processus qui utilise des outils d''IA pour examiner et améliorer la qualité et la sécurité du code","de":"Die Code-Review ist ein Prozess, der KI-Tools verwendet, um den Code zu überprüfen und die Qualität und Sicherheit zu verbessern","pt":"O que é SOP-Code-Review? É um fluxo de revisão de código que combina testes automatizados e revisões especializadas","ru":"Что такое SOP-Code-Review? Это комплексный обзор кода, сочетающий автоматизированные тесты и специализированные обзоры","ar":"ما هو SOP-Code-Review؟ إنه تدفق مراجعة الكود الذي يجمع بين الاختبارات الآلية والمراجعات التخصصية"},"features":{"en":["Utilizes parallel automated testing via JavaScript","Employs a coordinator pattern with a ''star'' topology for review swarm initialization","Includes a 30-minute automated checks phase for quick quality checks","Supports specialized reviews for different quality aspects","Conducts a 1-hour integration review for thorough code examination","Requires a final 30-minute approval phase for verified code"],"zh":["自动化代码检查","专家代码审查","并行自动化测试","集成审查","最终批准"],"ja":["自動化コードチェック","専門家によるコードレビュー","パラレル自動テスト","統合レビュー","最終承認"],"ko":["자동화된 코드 검토","전문가 코드 검토","병렬 자동화 테스트","통합 검토","최종 승인"],"es":["Comprobaciones automatizadas en paralelo con JavaScript","Revisión especializada con diferentes fases de revisión","Revisión de integración para garantizar la coherencia del código","Aprobación final para asegurar la calidad del código","Topología de coordinador para la revisión de código"],"fr":["Vérifications automatiques parallèles avec JavaScript","Examen spécialisé avec différentes phases de revue","Examen d''intégration pour garantir la cohérence du code","Approbation finale pour assurer la qualité du code","Topologie de coordinateur pour la revue de code"],"de":["Automatisierte Prüfungen in Parallelschaltung mit JavaScript","Spezialisierte Überprüfung mit verschiedenen Phasen der Überprüfung","Überprüfung der Integration, um die Konsistenz des Codes zu gewährleisten","Endgültige Genehmigung, um die Qualität des Codes zu sichern","Topologie des Koordinators für die Code-Review"],"pt":["Revisões automatizadas paralelas com topology de estrela","Revisões especializadas para diferentes aspectos de qualidade","Integração de revisões em 4 fases: verificação automática, revisão especializada, revisão de integração e aprovação final","Suporte à inicialização de enxame de revisão com mcp__ruv-swarm__swarm_init","Revisão de código em 4 horas com fases bem definidas"],"ru":["Параллельные автоматизированные обзоры с топологией звезды","Специализированные обзоры для различных аспектов качества","Интеграция обзоров в 4 фазы: автоматическая проверка, специализированный обзор, обзор интеграции и окончательное одобрение","Поддержка инициализации роя обзора с mcp__ruv-swarm__swarm_init","Обзор кода за 4 часа с четко определёнными фазами"],"ar":["المراجعات الآلية الموازية بトポロジا نجمية","المراجعات التخصصية لجوانب الجودة المختلفة","تكامل المراجعات في 4 مراحل: التحقق الآلي والمراجعة التخصصية ومراجعة التكامل والموافقة النهائية","دعم 초기ه سرب المراجعة مع mcp__ruv-swarm__swarm_init","مراجعة الكود في 4 ساعات مع مراحل محددة جيدًا"]},"keywords":{"en":["how to use sop-code-review","sop-code-review setup guide","what is sop-code-review","sop-code-review alternative","sop-code-review vs code review tools","sop-code-review install for AI agents","comprehensive code review workflow","parallel automated testing with JavaScript","code review workflow for developers"],"zh":["代码审查","自动化代码检查","专家代码审查","代码质量","开发效率","AI工具","代码审查工作流"],"ja":["コードレビュー","自動化コードチェック","専門家によるコードレビュー","コード品質","開発効率","AIエージェント","コードレビューのワークフロー"],"ko":["코드 리뷰","자동화된 코드 검토","전문가 코드 검토","코드 품질","개발 효율성","AIツール","코드 리뷰 워크플로우"],"es":["revisión de código","herramientas de IA","automatización de pruebas","revisión especializada","integración de código","aprobación final","desarrollo de software","calidad del código","seguridad del código"],"fr":["revue de code","outils d''IA","automatisation des tests","examen spécialisé","intégration de code","approbation finale","développement de logiciels","qualité du code","sécurité du code"],"de":["Code-Review","KI-Tools","Automatisierung von Prüfungen","spezialisierte Überprüfung","Integration von Code","endgültige Genehmigung","Software-Entwicklung","Code-Qualität","Code-Sicherheit"],"pt":["SOP-Code-Review","revisão de código","testes automatizados","revisores especializados","fluxo de revisão de código","topologia de estrela","mcp__ruv-swarm__swarm_init","desenvolvimento de software","qualidade de código"],"ru":["SOP-Code-Review","обзор кода","автоматизированные тесты","специализированные рецензенты","поток обзора кода","топология звезды","mcp__ruv-swarm__swarm_init","разработка программного обеспечения","качество кода"],"ar":["SOP-Code-Review","مراجعة الكود","الاختبارات الآلية","المراجعون التخصصيون","تدفق مراجعة الكود","トポロジا نجمية","mcp__ruv-swarm__swarm_init","تطوير البرمجيات","جودة الكود"]}},"owner":"DNYoussef","repo":"ai-chrome-extension","repoPath":"DNYoussef/ai-chrome-extension","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"sop-code-review","description":"Comprehensive code review workflow coordinating quality, security, performance, and documentation reviewers. 4-hour timeline for thorough multi-agent review.","bodyPreview":"# SOP: Code Review Workflow\n\nComprehensive code review using specialized reviewers for different quality aspects.\n\n## Timeline: 4 Hours\n\n**Phases**:\n1. Automated Checks (30 min)\n2. Specialized Reviews (2 hours)\n3. Integration Review (1 hour)\n4. Final Approval (30 min)\n\n---\n\n## Phase 1: Automated Checks (30 minutes)\n\n### Quick Quality Checks\n\n**Parallel Automated Testing**:\n\n```javascript\n// Initialize review swarm\nawait mcp__ruv-swarm__swarm_init({\n  topology: ''star'',  // Coordinator pattern for","body":"# SOP: Code Review Workflow\n\nComprehensive code review using specialized reviewers for different quality aspects.\n\n## Timeline: 4 Hours\n\n**Phases**:\n1. Automated Checks (30 min)\n2. Specialized Reviews (2 hours)\n3. Integration Review (1 hour)\n4. Final Approval (30 min)\n\n---\n\n## Phase 1: Automated Checks (30 minutes)\n\n### Quick Quality Checks\n\n**Parallel Automated Testing**:\n\n```javascript\n// Initialize review swarm\nawait mcp__ruv-swarm__swarm_init({\n  topology: ''star'',  // Coordinator pattern for reviews\n  maxAgents: 6,\n  strategy: ''specialized''\n});\n\n// Run all automated checks in parallel\nconst [lint, tests, coverage, build] = await Promise.all([\n  Task(\"Linter\", `\nRun linting checks:\n- ESLint for JavaScript/TypeScript\n- Pylint for Python\n- RuboCop for Ruby\n- Check for code style violations\n\nStore results: code-review/${prId}/lint-results\n`, \"reviewer\"),\n\n  Task(\"Test Runner\", `\nRun test suite:\n- Unit tests\n- Integration tests\n- E2E tests (if applicable)\n- All tests must pass\n\nStore results: code-review/${prId}/test-results\n`, \"tester\"),\n\n  Task(\"Coverage Analyzer\", `\nCheck code coverage:\n- Overall coverage > 80%\n- New code coverage > 90%\n- No critical paths uncovered\n\nGenerate coverage report\nStore: code-review/${prId}/coverage-report\n`, \"reviewer\"),\n\n  Task(\"Build Validator\", `\nValidate build:\n- Clean build (no warnings)\n- Type checking passes\n- No broken dependencies\n- Bundle size within limits\n\nStore build results: code-review/${prId}/build-status\n`, \"reviewer\")\n]);\n\n// If any automated check fails, stop and request fixes\nif (hasFailures([lint, tests, coverage, build])) {\n  await Task(\"Review Coordinator\", `\nAutomated checks failed. Request fixes from author:\n${summarizeFailures([lint, tests, coverage, build])}\n\nStore feedback: code-review/${prId}/automated-feedback\n`, \"pr-manager\");\n  return; // Stop review until fixed\n}\n```\n\n**Deliverables**:\n- All automated checks passing\n- Test results documented\n- Coverage report generated\n\n---\n\n## Phase 2: Specialized Reviews (2 hours)\n\n### Parallel Expert Reviews\n\n**Sequential coordination of parallel reviews**:\n\n```javascript\n// Spawn specialized reviewers in parallel\nconst [codeQuality, security, performance, architecture, docs] = await Promise.all([\n  Task(\"Code Quality Reviewer\", `\nReview for code quality:\n\n**Readability**:\n- Clear, descriptive names (variables, functions, classes)\n- Appropriate function/method length (< 50 lines)\n- Logical code organization\n- Minimal cognitive complexity\n\n**Maintainability**:\n- DRY principle (no code duplication)\n- SOLID principles followed\n- Clear separation of concerns\n- Proper error handling\n\n**Best Practices**:\n- Following language idioms\n- Proper use of design patterns\n- Appropriate comments (why, not what)\n- No code smells (magic numbers, long parameter lists)\n\nStore review: code-review/${prId}/quality-review\nRating: 1-5 stars\n`, \"code-analyzer\"),\n\n  Task(\"Security Reviewer\", `\nReview for security issues:\n\n**Authentication & Authorization**:\n- Proper authentication checks\n- Correct authorization rules\n- No privilege escalation risks\n- Secure session management\n\n**Data Security**:\n- Input validation (prevent injection attacks)\n- Output encoding (prevent XSS)\n- Sensitive data encryption\n- No hardcoded secrets or credentials\n\n**Common Vulnerabilities** (OWASP Top 10):\n- SQL Injection prevention\n- XSS prevention\n- CSRF protection\n- Secure dependencies (no known vulnerabilities)\n\nStore review: code-review/${prId}/security-review\nSeverity: Critical/High/Medium/Low for each finding\n`, \"security-manager\"),\n\n  Task(\"Performance Reviewer\", `\nReview for performance issues:\n\n**Algorithmic Efficiency**:\n- Appropriate time complexity (no unnecessary O(n²))\n- Efficient data structures chosen\n- No unnecessary iterations\n- Lazy loading where appropriate\n\n**Resource Usage**:\n- No memory leaks\n- Proper cleanup (connections, files, timers)\n- Efficient database queries (avoid N+1)\n- Batch operations where possible\n\n**Optimization Opportunities**:\n- Caching potential\n- Parallelization opportunities\n- Database index needs\n- API call optimization\n\nStore review: code-review/${prId}/performance-review\nImpact: High/Medium/Low for each finding\n`, \"perf-analyzer\"),\n\n  Task(\"Architecture Reviewer\", `\nReview for architectural consistency:\n\n**Design Patterns**:\n- Follows established patterns in codebase\n- Appropriate abstraction level\n- Proper dependency injection\n- Clean architecture principles\n\n**Integration**:\n- Fits well with existing code\n- No unexpected side effects\n- Backward compatibility maintained\n- API contracts respected\n\n**Scalability**:\n- Design supports future growth\n- No hardcoded limits\n- Stateless where possible\n- Horizontally scalable\n\nStore review: code-review/${prId}/architecture-review\nConcerns: Blocker/Major/Minor for each finding\n`, \"system-architect\"),\n\n  Task(\"Documentation Reviewer\", `\nReview documentation:\n\n**Code Documentation**:\n- Public APIs documented (JSDoc/docstring)\n- Complex logic explained\n- Non-obvious behavior noted\n- Examples provided where helpful\n\n**External Documentation**:\n- README updated (if needed)\n- API docs updated (if API changed)\n- Migration guide (if breaking changes)\n- Changelog updated\n\n**Tests as Documentation**:\n- Test names are descriptive\n- Test coverage demonstrates usage\n- Edge cases documented in tests\n\nStore review: code-review/${prId}/docs-review\nCompleteness: 0-100%\n`, \"api-docs\")\n]);\n\n// Aggregate all reviews\nawait Task(\"Review Aggregator\", `\nAggregate specialized reviews:\n- Quality: ${codeQuality}\n- Security: ${security}\n- Performance: ${performance}\n- Architecture: ${architecture}\n- Documentation: ${docs}\n\nIdentify:\n- Blocking issues (must fix before merge)\n- High-priority suggestions\n- Nice-to-have improvements\n\nGenerate summary\nStore: code-review/${prId}/aggregated-review\n`, \"reviewer\");\n```\n\n**Deliverables**:\n- 5 specialized reviews completed\n- Issues categorized by severity\n- Aggregated review summary\n\n---\n\n## Phase 3: Integration Review (1 hour)\n\n### End-to-End Impact Assessment\n\n**Sequential Analysis**:\n\n```javascript\n// Step 1: Integration Testing\nawait Task(\"Integration Tester\", `\nTest integration with existing system:\n- Does this change break any existing functionality?\n- Are all integration tests passing?\n- Does it play well with related modules?\n- Any unexpected side effects?\n\nRun integration test suite\nStore results: code-review/${prId}/integration-tests\n`, \"tester\");\n\n// Step 2: Deployment Impact\nawait Task(\"DevOps Reviewer\", `\nAssess deployment impact:\n- Infrastructure changes needed?\n- Database migrations required?\n- Configuration updates needed?\n- Backward compatibility maintained?\n- Rollback plan clear?\n\nStore assessment: code-review/${prId}/deployment-impact\n`, \"cicd-engineer\");\n\n// Step 3: User Impact\nawait Task(\"Product Reviewer\", `\nAssess user impact:\n- Does this change improve user experience?\n- Are there any user-facing changes?\n- Is UX/UI consistent with design system?\n- Are analytics/tracking updated?\n\nStore assessment: code-review/${prId}/user-impact\n`, \"planner\");\n\n// Step 4: Risk Assessment\nawait Task(\"Risk Analyzer\", `\nOverall risk assessment:\n- What''s the blast radius of this change?\n- What''s the worst-case failure scenario?\n- Do we have rollback procedures?\n- Should this be feature-flagged?\n- Monitoring and alerting adequate?\n\nStore risk assessment: code-review/${prId}/risk-analysis\nRecommendation: Approve/Conditional/Reject\n`, \"reviewer\");\n```\n\n**Deliverables**:\n- Integration test results\n- Deployment impact assessment\n- User impact assessment\n- Risk analysis\n\n---\n\n## Phase 4: Final Approval (30 minutes)\n\n### Review Summary & Decision\n\n**Sequential Finalization**:\n\n```javascript\n// Step 1: Generate Final Summary\nawait Task(\"Review Coordinator\", `\nGenerate final review summary:\n\n**Automated Checks**: ✅ All passing\n**Quality Review**: ${qualityScore}/5\n**Security Review**: ${securityIssues} issues (${criticalCount} critical)\n**Performance Review**: ${perfIssues} issues (${highImpactCount} high-impact)\n**Architecture Review**: ${archConcerns} concerns (${blockerCount} blockers)\n**Documentation Review**: ${docsCompleteness}% complete\n**Integration Tests**: ${integrationStatus}\n**Deployment Impact**: ${deploymentImpact}\n**User Impact**: ${userImpact}\n**Risk Level**: ${riskLevel}\n\n**Blocking Issues**:\n${listBlockingIssues()}\n\n**Recommendations**:\n${generateRecommendations()}\n\n**Overall Decision**: ${decision} (Approve/Request Changes/Reject)\n\nStore final summary: code-review/${prId}/final-summary\n`, \"pr-manager\");\n\n// Step 2: Author Notification\nawait Task(\"Notification Agent\", `\nNotify PR author:\n- Review complete\n- Summary of findings\n- Action items (if any)\n- Next steps\n\nSend notification\nStore: code-review/${prId}/author-notification\n`, \"pr-manager\");\n\n// Step 3: Decision Actions\nif (decision === ''Approve'') {\n  await Task(\"Merge Coordinator\", `\nApproved for merge:\n- Add \"approved\" label\n- Update PR status\n- Queue for merge (if auto-merge enabled)\n- Notify relevant teams\n\nStore: code-review/${prId}/merge-approval\n`, \"pr-manager\");\n} else if (decision === ''Request Changes'') {\n  await Task(\"Feedback Coordinator\", `\nRequest changes:\n- Create detailed feedback comment\n- Label as \"changes-requested\"\n- Assign back to author\n- Schedule follow-up review\n\nStore: code-review/${prId}/change-request\n`, \"pr-manager\");\n} else {\n  await Task(\"Rejection Handler\", `\nReject PR:\n- Create detailed explanation\n- Suggest alternative approaches\n- Label as \"rejected\"\n- Close PR (or request fundamental rework)\n\nStore: code-review/${prId}/rejection\n`, \"pr-manager\");\n}\n```\n\n**Deliverables**:\n- Final review summary\n- Author notification\n- Decision and next steps\n\n---\n\n## Success Criteria\n\n### Review Quality\n- **Coverage**: All aspects reviewed (quality, security, performance, architecture, docs)\n- **Consistency**: Reviews follow established guidelines\n- **Actionability**: All feedback is specific and actionable\n- **Timeliness**: Reviews completed within 4 hours\n\n### Code Quality Gates\n- **Automated Tests**: 100% passing\n- **Code Coverage**: > 80% overall, > 90% for new code\n- **Linting**: 0 violations\n- **Security**: 0 critical issues, 0 high-severity issues\n- **Performance**: No high-impact performance regressions\n- **Documentation**: 100% of public APIs documented\n\n### Process Metrics\n- **Review Turnaround**: < 4 hours (business hours)\n- **Author Satisfaction**: > 4/5 (feedback is helpful)\n- **Defect Escape Rate**: < 1% (issues found in production that should have been caught)\n\n---\n\n## Review Guidelines\n\n### What Reviewers Should Focus On\n\n**DO Review**:\n- Logic correctness\n- Edge case handling\n- Error handling robustness\n- Security vulnerabilities\n- Performance implications\n- Code clarity and maintainability\n- Test coverage and quality\n- API design and contracts\n- Documentation completeness\n\n**DON''T Nitpick**:\n- Personal style preferences (use automated linting)\n- Minor variable naming (unless truly confusing)\n- Trivial formatting (use automated formatting)\n- Subjective \"better\" ways (unless significantly better)\n\n### Giving Feedback\n\n**Effective Feedback**:\n- ✅ \"This function has O(n²) complexity. Consider using a hash map for O(n).\"\n- ✅ \"This input isn''t validated. Add validation to prevent SQL injection.\"\n- ✅ \"This error isn''t logged. Add error logging for debugging.\"\n\n**Ineffective Feedback**:\n- ❌ \"I don''t like this.\"\n- ❌ \"This could be better.\"\n- ❌ \"Change this.\" (without explanation)\n\n**Tone**:\n- Be respectful and constructive\n- Assume good intent\n- Ask questions rather than make demands\n- Suggest, don''t dictate (unless security/critical issue)\n\n---\n\n## Agent Coordination Summary\n\n**Total Agents Used**: 12-15\n**Execution Pattern**: Star topology (coordinator with specialists)\n**Timeline**: 4 hours\n**Memory Namespaces**: code-review/{pr-id}/*\n\n**Key Agents**:\n1. reviewer - Lint, build, coordination\n2. tester - Test execution, integration testing\n3. code-analyzer - Code quality review\n4. security-manager - Security review\n5. perf-analyzer - Performance review\n6. system-architect - Architecture review\n7. api-docs - Documentation review\n8. cicd-engineer - Deployment impact\n9. planner - Product/user impact\n10. pr-manager - Review coordination, notifications\n\n---\n\n## Usage\n\n```javascript\n// Invoke this SOP skill for a PR\nSkill(\"sop-code-review\")\n\n// Or execute with specific PR\nTask(\"Code Review Orchestrator\", `\nExecute comprehensive code review for PR #${prNumber}\nRepository: ${repoName}\nAuthor: ${authorName}\nChanges: ${changesSummary}\n`, \"pr-manager\")\n```\n\n---\n\n**Status**: Production-ready SOP\n**Complexity**: Medium (12-15 agents, 4 hours)\n**Pattern**: Star topology with specialized reviewers\n"},"lastSynced":"2026-03-08T02:01:19.730Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured code review workflows with automated checks and integration reviews.","zh":"适合需要结构化代码审查工作流程和自动化检查以及集成审查的开发代理。","ja":"構造化されたコードレビューのワークフローと自動化されたチェックおよび統合レビューが必要な開発エージェントに最適です。","ko":"구조화된 코드 리뷰 워크플로와 자동화된 체크 및 통합 리뷰가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan flujos de trabajo de revisión de código estructurados con comprobaciones automatizadas y revisiones de integración.","fr":"Parfait pour les agents de développement nécessitant des flux de travail de révision de code structurés avec des vérifications automatisées et des examens d''intégration.","de":"Perfekt für Entwicklungsspezialisten, die strukturierte Code-Review-Workflows mit automatisierten Prüfungen und Integrationsprüfungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de fluxos de trabalho de revisão de código estruturados com verificações automatizadas e revisões de integração.","ru":"Идеально подходит для агентов разработки, которым необходимы структурированные рабочие процессы проверки кода с автоматическими проверками и обзорами интеграции.","ar":"مثالي للوكلاء النموزجيين الذين يحتاجون إلى سير عمل مراجعة الكود المنظمة مع الفحوصات الآلية ومراجعات التكامل."},"recommendation":{"en":"Empowers agents to perform comprehensive code reviews using specialized reviewers for different quality aspects, leveraging parallel automated testing and integration reviews via JavaScript and coordinator patterns like ''star'' topology.","zh":"赋予代理执行全面代码审查的能力，利用专用审查者针对不同质量方面，利用JavaScript和协调器模式（如星形拓扑）进行并行自动化测试和集成审查。","ja":"エージェントに、JavaScriptやコーディネーターパターン（例：スター型トポロジー）を使用した並列自動テストと統合レビューを活用して、さまざまな品質の側面に対する専門のレビューアーを使用することで、包括的なコードレビューを実行する能力を与えます。","ko":"에이전트가 자바스크립트 및 코디네이터 패턴(예: 별형 토폴로지)을 사용한 병렬 자동 테스트 및 통합 리뷰를 활용하여 다양한 품질 측면에 대한 전문 리뷰어를 사용하여 포괄적인 코드 리뷰를 수행할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a realizar revisiones de código exhaustivas utilizando revisores especializados para diferentes aspectos de calidad, aprovechando pruebas automatizadas paralelas y revisiones de integración a través de JavaScript y patrones de coordinador como la topología ''estrella''.","fr":"Permet aux agents d''effectuer des examens de code exhaustifs en utilisant des relecteurs spécialisés pour différents aspects de qualité, en exploitant les tests automatisés parallèles et les examens d''intégration via JavaScript et des modèles de coordinateur comme la topologie ''étoile''.","de":"Ermächtigt die Agenten, umfassende Code-Reviews durchzuführen, indem sie spezialisierte Reviewer für verschiedene Qualitätsaspekte verwenden, und nutzt dabei parallele automatisierte Tests und Integrationsprüfungen über JavaScript und Koordinierungsmuster wie die ''Stern''-Topologie.","pt":"Habilita os agentes a realizar revisões de código abrangentes usando revisores especializados para diferentes aspectos de qualidade, aproveitando testes automatizados paralelos e revisões de integração via JavaScript e padrões de coordenador como a topologia ''estrela''.","ru":"Наделяет агентов возможностью проводить комплексные проверки кода с помощью специализированных проверяющих для различных аспектов качества, используя параллельное автоматизированное тестирование и обзоры интеграции через JavaScript и координаторские шаблоны, такие как топология ''звезда''.","ar":"يتمكن الوكلاء من أداء مراجعات شاملة للكود باستخدام مراجعين متخصصين لمختلف جوانب الجودة، واستغلال الاختبارات الآلية المتوازية ومراجعات التكامل عبر JavaScript وأنماط منسق مثل طوبولوجيا ''نجم''."},"useCases":{"en":["Automating code quality checks with parallel automated testing","Conducting specialized reviews for distinct quality aspects","Performing integration reviews for cohesive codebase validation"],"zh":["使用并行自动化测试自动执行代码质量检查","进行针对不同质量方面的专用审查","进行集成审查以验证协调的代码库"],"ja":["並列自動テストを使用してコード品質チェックを自動化する","さまざまな品質の側面に対する専門のレビューを実施する","統合レビューを実施して一貫性のあるコードベースを検証する"],"ko":["병렬 자동 테스트를 사용하여 코드 품질 체크를 자동화하는 것","다양한 품질 측면에 대한 전문 리뷰를 수행하는 것","통합 리뷰를 수행하여 일관된 코드베이스를 검증하는 것"],"es":["Automatizar las comprobaciones de calidad del código con pruebas automatizadas paralelas","Realizar revisiones especializadas para diferentes aspectos de calidad","Realizar revisiones de integración para la validación de la base de código cohesiva"],"fr":["Automatiser les vérifications de la qualité du code avec des tests automatisés parallèles","Effectuer des examens spécialisés pour différents aspects de qualité","Effectuer des examens d''intégration pour la validation de la base de code cohérente"],"de":["Automatisierung von Code-Qualitätsprüfungen mit parallelen automatisierten Tests","Durchführung spezialisierter Prüfungen für verschiedene Qualitätsaspekte","Durchführung von Integrationsprüfungen für die Validierung des kohärenten Codebestands"],"pt":["Automatizar verificações de qualidade de código com testes automatizados paralelos","Realizar revisões especializadas para aspectos de qualidade distintos","Realizar revisões de integração para validação de base de código coesa"],"ru":["Автоматизировать проверки качества кода с параллельным автоматизированным тестированием","Проводить специализированные обзоры для различных аспектов качества","Проводить обзоры интеграции для валидации сплоченной базы кода"],"ar":["أتمتة فحوصات جودة الكود مع الاختبارات الآلية المتوازية","إجراء مراجعات متخصصة لجوانب الجودة المتنوعة","أداء مراجعات التكامل لتحقق صحة قاعدة الكود المتجانسة"]},"limitations":{"en":["Requires 4 hours for complete workflow execution","Dependent on JavaScript for automated testing scripts","Limited to specific quality aspects defined by specialized reviewers"],"zh":["需要4小时才能完成工作流执行","依赖于JavaScript进行自动化测试脚本","仅限于专用审查者定义的特定质量方面"],"ja":["ワークフローの実行を完了するのに4時間かかる","自動テストスクリプトにJavaScriptに依存する","専門のレビューアーによって定義される特定の品質の側面に限定される"],"ko":["워크플로우 실행을 완료하는 데 4시간이 필요하다","자동 테스트 스크립트에 자바스크립트에 의존한다","전문 리뷰어에 의해 정의된 특정 품질 측면에만 제한된다"],"es":["Requiere 4 horas para la ejecución completa del flujo de trabajo","Dependiente de JavaScript para scripts de pruebas automatizadas","Limitado a aspectos de calidad específicos definidos por revisores especializados"],"fr":["Nécessite 4 heures pour l''exécution complète du flux de travail","Dépendant de JavaScript pour les scripts de test automatisés","Limité à des aspects de qualité spécifiques définis par des relecteurs spécialisés"],"de":["Benötigt 4 Stunden für die vollständige Ausführung des Workflows","Abhängig von JavaScript für automatisierte Testskripte","Eingeschränkt auf bestimmte Qualitätsaspekte, die durch spezialisierte Reviewer definiert sind"],"pt":["Requer 4 horas para execução completa do fluxo de trabalho","Dependente de JavaScript para scripts de teste automatizado","Limitado a aspectos de qualidade específicos definidos por revisores especializados"],"ru":["Требует 4 часов для полного выполнения рабочего процесса","Зависит от JavaScript для автоматизированных скриптов тестирования","Ограничен конкретными аспектами качества, определяемыми специализированными проверяющими"],"ar":["يتطلب 4 ساعات لتنفيذ كامل لسير العمل","يعتمد على JavaScript لسكريبتات الاختبار الآلي","محدود بجانب الجودة المحددة بواسطة المراجعين التخصصيين"]},"version":4},"contentHash":"f037ea7ac295f5df48a190878295331c7011390a263abfe6fa1d8fc50e47e8e1","qualityScore":60}');
