INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DNYoussef/ai-chrome-extension/sop-code-review', 'sop-code-review', 'DNYoussef', 'ai-chrome-extension', 'community', 'sop-code-review DNYoussef ai-chrome-extension community The sop-code-review skill provides a comprehensive code review workflow for developers, utilizing specialized reviewers for different quality aspects. This workflow is designed for AI agents and includes automated checks, specialized reviews, and integration reviews. sop-code-review是一种代码审查工作流，使用自动化检查和专家代码审查来提高代码质量 sop-code-reviewは、自動化チェックと専門家によるコードレビューを使用してコード品質を向上させるコードレビューのワークフローです sop-code-review는 자동화된 검토와 전문가 코드 검토를 사용하여 코드 품질을 향상시키는 코드 검토 워크플로우입니다 La revisión de código es un proceso crucial para garantizar la calidad y seguridad del código. Con la herramienta de revisión de código, puedes automatizar las comprobaciones y revisar el código de manera especializada La revue de code est un processus crucial pour garantir la qualité et la sécurité du code. Avec l''outil de revue de code, vous pouvez automatiser les vérifications et examiner le code de manière spécialisée Die Code-Review ist ein entscheidender Prozess, um die Qualität und Sicherheit des Codes zu gewährleisten. Mit dem Code-Review-Tool können Sie die Prüfungen automatisieren und den Code spezialisiert überprüfen O SOP-Code-Review é um fluxo de revisão de código abrangente que utiliza revisores especializados para diferentes aspectos de qualidade SOP-Code-Review - это комплексный обзор кода, использующий специализированных рецензентов для различных аспектов качества SOP-Code-Review هو تدفق مراجعة الكود الشامل الذي يستخدم مراجعين متخصصين لجوانب الجودة المختلفة how to use sop-code-review sop-code-review setup guide what is sop-code-review sop-code-review alternative sop-code-review vs code review tools sop-code-review install for AI agents comprehensive code review workflow parallel automated testing with JavaScript code review workflow for developers 代码审查 自动化代码检查 专家代码审查 代码质量 开发效率 AI工具 代码审查工作流 Utilizes parallel automated testing via JavaScript Employs a coordinator pattern with a ''star'' topology for review swarm initialization Includes a 30-minute automated checks phase for quick quality checks Supports specialized reviews for different quality aspects Conducts a 1-hour integration review for thorough code examination Requires a final 30-minute approval phase for verified code sop-code-review is a code review workflow that utilizes parallel automated testing and specialized reviewers to ensure high-quality code, following a 4-phase process: automated checks, specialized reviews, integration review, and final approval.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cristian-robert/autonomous-automation-tester/mcp-client', 'community', 'cristian-robert', 'autonomous-automation-tester', 'cristian-robert/autonomous-automation-tester', 'mcp-client', 0, 0, 60, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:31.159Z', '962acb3c5b14f34ba636d7da21fff240a588fce1a5cd37444ca563bf024a04e4', '{"id":"cristian-robert/autonomous-automation-tester/mcp-client","name":"mcp-client","description":{"en":"The mcp-client skill enables developers to connect to any MCP server without bloating context with tool definitions, ideal for AI agents and automated workflows.","zh":"MCP客户端允许您连接到任何MCP服务器，而无需为工具定义填充上下文。每次MCP调用都会创建新的浏览器会话","ja":"MCPクライアントは、ツール定義でコンテキストを膨張させることなく、任意のMCPサーバーに接続することを可能にします。各MCP呼び出しで新しいブラウザーセッションが作成されます","ko":"MCP 클라이언트는 도구 정의로 컨텍스트를膨張させる 것 없이 任意의 MCP 서버에 연결할 수 있습니다. 각 MCP 호출은 새로운 브라우저 세션을 생성합니다.","es":"mcp-client es un cliente universal que permite conectar con cualquier servidor MCP sin sobrecargar el contexto. Cada llamada a MCP crea una nueva sesión de navegador.","fr":"mcp-client est un client universel qui permet de se connecter à n''importe quel serveur MCP sans surcharger le contexte. Chaque appel à MCP crée une nouvelle session de navigateur.","de":"mcp-client ist ein universeller Client, der eine Verbindung zu jedem MCP-Server herstellt, ohne den Kontext zu überladen. Jeder MCP-Aufruf erstellt eine neue Browsersession.","pt":"O mcp-client é uma ferramenta que permite conectar-se a servidores MCP sem sobrecarregar o contexto. Ele cria uma nova sessão de navegador para cada chamada MCP","ru":"mcp-client - это инструмент, который позволяет подключаться к серверам MCP без лишних настроек. Он создает новую сессию браузера для каждого вызова MCP","ar":"mcp-client هو أداة تمكنك من الاتصال بخوادير MCP دون إضاعة السياق. وهو يخلق جلسة متصفح جديدة لكل مكالمة MCP"},"seo":{"title":{"en":"mcp-client: Universal MCP Server Connection Setup Guide |...","zh":"MCP 客户端_SETUP_指南 - 连接任何MCP服务器","ja":"MCPクライアントセットアップガイド - 任何MCPサーバーに接続","ko":"MCP 클라이언트 설정 가이드 - 任意 MCP 서버에 연결","es":"Guía de Configuración de mcp-client: Conexión Universal a...","fr":"Guide de Configuration de mcp-client: Connexion Universel...","de":"Einrichtungsleitfaden für mcp-client: Universelle Verbind...","pt":"Guia de Configuração do mcp-client: Conecte-se a Servidor...","ru":"Настройка mcp-client: Подключение к Серверам MCP с ИИ Аге...","ar":"دليل إعداد mcp-client: الاتصال بخوادير MCP مع أدوات الذكا..."},"description":{"en":"Discover how to connect to any MCP server with the mcp-client skill. Learn how to navigate browser sessions and optimize your workflow. Get started now!","zh":"了解MCP客户端的工作原理，包括每次MCP调用创建新的浏览器会话，并提供browser_run_code用于多步操作","ja":"MCPクライアントの仕組みを理解し、各MCP呼び出しで新しいブラウザーセッションが作成され、browser_run_codeが複数ステップ操作に使用されることを学ぶ","ko":"MCP 클라이언트의 작동 방식에 대해 알아보세요. 각 MCP 호출은 새 브라우저 세션을 생성하며 browser_run_code는 여러 단계의 작업에 사용됩니다.","es":"Aprende a conectar con cualquier servidor MCP sin sobrecargar el contexto con definiciones de herramientas. Descubre cómo funciona mcp-client.","fr":"Découvrez comment se connecter à n''importe quel serveur MCP sans surcharger le contexte avec des définitions d''outils. Apprenez à utiliser mcp-client.","de":"Erfahren Sie, wie Sie eine Verbindung zu jedem MCP-Server herstellen können, ohne den Kontext mit Tool-Definitionen zu überladen. Erfahren Sie, wie mcp-clien...","pt":"Aprenda a configurar o mcp-client para conectar-se a servidores MCP sem sobrecarregar o contexto com definições de ferramentas","ru":"Узнайте, как настроить mcp-client для подключения к серверам MCP без лишних настроек инструментов с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد mcp-client للاتصال بخوادير MCP دون إضاعة السياق مع تعريفات الأدوات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"mcp-client is a universal client for connecting to MCP servers, allowing for efficient browser session management and multi-step operations.","zh":"MCP客户端是一种连接到MCP服务器的工具，允许开发人员执行MCP调用而无需工具定义","ja":"MCPクライアントは、MCPサーバーに接続するツールであり、開発者がツール定義を必要とせずにMCP呼び出しを実行できるようにする","ko":"MCP 클라이언트는 MCP 서버에 연결하는 도구로, 개발자가 도구 정의 없이 MCP 호출을 실행할 수 있습니다.","es":"mcp-client es un cliente que permite conectar con servidores MCP sin requerir definiciones de herramientas adicionales.","fr":"mcp-client est un client qui permet de se connecter à des serveurs MCP sans nécessiter de définitions d''outils supplémentaires.","de":"mcp-client ist ein Client, der eine Verbindung zu MCP-Servern herstellt, ohne zusätzliche Tool-Definitionen zu erfordern.","pt":"O mcp-client é um cliente universal que permite conectar-se a servidores MCP","ru":"mcp-client - это универсальный клиент, который позволяет подключаться к серверам MCP","ar":"mcp-client هو عميل عالمي يسمح بالاتصال بخوادير MCP"},"features":{"en":["Connects to any MCP server without requiring tool definitions","Creates a new browser session for each MCP call","Closes the browser after each call for efficient resource management","Supports multi-step operations using the browser_run_code command","Requires redoing all steps from scratch to return to a previous state, such as a logged-in session"],"zh":["每次MCP调用创建新的浏览器会话","浏览器会话在每次调用后关闭","browser_run_code用于多步操作","必须重新执行所有步骤才能返回到之前的状态","支持Playwright浏览器会话","支持多步操作"],"ja":["各MCP呼び出しで新しいブラウザーセッションが作成される","ブラウザーセッションは各呼び出し後に閉じられる","browser_run_codeが複数ステップ操作に使用される","以前の状態に戻るにはすべてのステップを再実行する必要がある","Playwrightブラウザーセッションをサポート","複数ステップ操作をサポート"],"ko":["각 MCP 호출은 새로운 브라우저 세션을 생성합니다","브라우저 세션은 각 호출 후에 닫힙니다","browser_run_code는 여러 단계의 작업에 사용됩니다","이전 상태로 돌아가려면 모든 단계를 다시 실행해야 합니다","Playwright 브라우저 세션을 지원합니다","여러 단계의 작업을 지원합니다"],"es":["Conexión universal a servidores MCP","Cada llamada a MCP crea una nueva sesión de navegador","No requiere definiciones de herramientas adicionales","Permite operaciones de varios pasos con ''browser_run_code''","Soporte para navegadores con Playwright","Cierre automático de la sesión de navegador después de cada llamada"],"fr":["Connexion universelle aux serveurs MCP","Chaque appel à MCP crée une nouvelle session de navigateur","Nécessite pas de définitions d''outils supplémentaires","Permet des opérations à plusieurs étapes avec ''browser_run_code''","Prise en charge des navigateurs avec Playwright","Fermeture automatique de la session de navigateur après chaque appel"],"de":["Universelle Verbindung zu MCP-Servern","Jeder MCP-Aufruf erstellt eine neue Browsersession","Benötigt keine zusätzlichen Tool-Definitionen","Ermöglicht Mehrschrittoperationen mit ''browser_run_code''","Unterstützung für Browser mit Playwright","Automatisches Schließen der Browsersession nach jedem Aufruf"],"pt":["Cria uma nova sessão de navegador para cada chamada MCP","Permite conectar-se a servidores MCP sem sobrecarregar o contexto","Suporta operações multi-etapas com o comando browser_run_code","Reinicia a sessão de navegador após cada chamada MCP"],"ru":["Создает новую сессию браузера для каждого вызова MCP","Позволяет подключаться к серверам MCP без лишних настроек","Поддерживает многоэтапные операции с помощью команды browser_run_code","Перезапускает сессию браузера после каждого вызова MCP"],"ar":["يخلق جلسة متصفح جديدة لكل مكالمة MCP","يسمح بالاتصال بخوادير MCP دون إضاعة السياق","يدعم العمليات متعددة الخطوات باستخدام الأمر browser_run_code","يعيد تشغيل جلسة المتصفح بعد كل مكالمة MCP"]},"keywords":{"en":["how to use mcp-client","mcp-client setup guide","mcp-client alternative","mcp-client vs playwright","mcp-client install","mcp-client browser session management","universal mcp server connection","mcp-client multi-step operations","browser_run_code command"],"zh":["MCP客户端","MCP服务器","Playwright","浏览器会话","browser_run_code","多步操作","AI工具","AIエージェント","MCP客户端设置","MCP客户端教程"],"ja":["MCPクライアント","MCPサーバー","Playwright","ブラウザーセッション","browser_run_code","複数ステップ操作","AIエージェント","AIツール","MCPクライアント設定","MCPクライアントチュートリアル"],"ko":["MCP 클라이언트","MCP 서버","Playwright","브라우저 세션","browser_run_code","여러 단계의 작업","AI 에이전트","AI 도구","MCP 클라이언트 설정","MCP 클라이언트 튜토리얼"],"es":["mcp-client","conexión universal a servidores MCP","cliente MCP","Playwright","navegadores","sesión de navegador","operaciones de varios pasos","automatización de pruebas","herramientas de desarrollo","agentes de AI"],"fr":["mcp-client","connexion universelle aux serveurs MCP","client MCP","Playwright","navigateurs","session de navigateur","opérations à plusieurs étapes","automatisation des tests","outils de développement","agents d''IA"],"de":["mcp-client","universelle Verbindung zu MCP-Servern","MCP-Client","Playwright","Browser","Browsersession","Mehrschrittoperationen","Automatisierung von Tests","Entwicklungstools","KI-Agents"],"pt":["mcp-client","servidores MCP","conectar-se a servidores MCP","cliente universal MCP","Playwright","browser_run_code","sessão de navegador"],"ru":["mcp-client","серверы MCP","подключение к серверам MCP","универсальный клиент MCP","Playwright","browser_run_code","сессия браузера","ИИ Агенты"],"ar":["mcp-client","خوادير MCP","الاتصال بخوادير MCP","عميل عالمي MCP","Playwright","browser_run_code","جلسة المتصفح","أدوات الذكاء الاصطناعي"]}},"owner":"cristian-robert","repo":"autonomous-automation-tester","repoPath":"cristian-robert/autonomous-automation-tester","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"mcp-client","description":"Universal MCP client for connecting to any MCP server with progressive disclosure. Wraps MCP servers as skills to avoid context window bloat from tool definitions. Use when interacting with external MCP servers (Playwright, GitHub, filesystem, etc.), listing available tools, or executing MCP tool calls. Triggers on connect to MCP, list MCP tools, call MCP, use Playwright, browser navigate, browser snapshot.","bodyPreview":"# Universal MCP Client\n\nConnect to any MCP server without bloating context with tool definitions.\n\n> **⚠️ PLAYWRIGHT USERS: READ \"CRITICAL: Playwright Browser Session Behavior\" SECTION BELOW!**\n>\n> Each MCP call = new browser session. Browser CLOSES after each call.\n> You CANNOT navigate in one call and click in another.\n> Use `browser_run_code` for ANY multi-step operation.\n> If you need to return to a state (e.g., logged in), you MUST redo ALL steps from scratch.\n\n## How It Works\n\nInstead of l","body":"# Universal MCP Client\n\nConnect to any MCP server without bloating context with tool definitions.\n\n> **⚠️ PLAYWRIGHT USERS: READ \"CRITICAL: Playwright Browser Session Behavior\" SECTION BELOW!**\n>\n> Each MCP call = new browser session. Browser CLOSES after each call.\n> You CANNOT navigate in one call and click in another.\n> Use `browser_run_code` for ANY multi-step operation.\n> If you need to return to a state (e.g., logged in), you MUST redo ALL steps from scratch.\n\n## How It Works\n\nInstead of loading all MCP tool schemas into context, this client:\n1. Lists available servers from config\n2. Queries tool schemas on-demand\n3. Executes tools with JSON arguments\n\n## Configuration\n\nConfig location priority:\n1. `MCP_CONFIG_PATH` environment variable\n2. `.claude/skills/mcp-client/references/mcp-config.json`\n3. `.mcp.json` in current directory\n4. `~/.claude.json`\n\n## Commands\n\n```bash\n# List configured servers\npython scripts/mcp_client.py servers\n\n# List tools from a specific server\npython scripts/mcp_client.py tools playwright\n\n# Call a tool\npython scripts/mcp_client.py call playwright browser_navigate ''{\"url\": \"https://example.com\"}''\n```\n\n---\n\n# CRITICAL: Playwright Browser Session Behavior\n\n## ⚠️ The Session Problem\n\n**Each MCP call creates a NEW browser session. The browser CLOSES after each call.**\n\nThis means:\n```bash\n# ❌ WRONG - These run in SEPARATE browser sessions!\npython scripts/mcp_client.py call playwright browser_navigate ''{\"url\": \"https://example.com\"}''\npython scripts/mcp_client.py call playwright browser_click ''{\"element\": \"Accept cookies\"}''\npython scripts/mcp_client.py call playwright browser_snapshot ''{}''\n# ^ The snapshot captures a FRESH page, not the page after clicking!\n```\n\n## ✅ The Solution: `browser_run_code`\n\nUse `browser_run_code` to run **multiple Playwright steps in ONE browser session**:\n\n```bash\npython scripts/mcp_client.py call playwright browser_run_code ''{\n  \"code\": \"\n    await page.goto(\\\"https://example.com\\\");\n\n    // Wait for and click cookie banner\n    const acceptBtn = page.getByRole(\\\"button\\\", { name: /accept/i });\n    if (await acceptBtn.isVisible({ timeout: 3000 }).catch(() => false)) {\n      await acceptBtn.click();\n      await page.waitForTimeout(1000);\n    }\n\n    // Wait for page to stabilize\n    await page.waitForLoadState(\\\"networkidle\\\");\n\n    // Return snapshot data for analysis\n    const snapshot = await page.accessibility.snapshot();\n    return JSON.stringify(snapshot, null, 2);\n  \"\n}''\n```\n\n## When to Use Each Approach\n\n| Scenario | Tool | Why |\n|----------|------|-----|\n| Simple page load + snapshot | `browser_navigate` | Returns snapshot automatically |\n| Multi-step interaction | `browser_run_code` | Keeps session alive |\n| Click then observe result | `browser_run_code` | Session persists |\n| Fill form and submit | `browser_run_code` | Session persists |\n| Hover to reveal menu | `browser_run_code` | Session persists |\n\n---\n\n# Playwright Workflows for Test Discovery\n\n## 1. Basic Page Exploration (Single Step)\n\n`browser_navigate` returns **both** navigation result AND accessibility snapshot:\n\n```bash\npython scripts/mcp_client.py call playwright browser_navigate ''{\"url\": \"https://example.com\"}''\n```\n\nOutput includes:\n- Page URL and title\n- Full accessibility tree (all visible elements with roles, names, states)\n- Element references for further interaction\n\n**Use this when:** Simple page load without interactions\n\n## 2. Page with Cookie Banner (Multi-Step)\n\n```bash\npython scripts/mcp_client.py call playwright browser_run_code ''{\n  \"code\": \"\n    await page.goto(\\\"https://www.olx.ro\\\");\n\n    // Handle cookie consent\n    try {\n      const cookieBtn = page.getByRole(\\\"button\\\", { name: \\\"Accept\\\" });\n      await cookieBtn.click({ timeout: 5000 });\n      await page.waitForTimeout(1000);\n    } catch (e) {\n      // No cookie banner\n    }\n\n    // Get accessibility snapshot\n    const snapshot = await page.accessibility.snapshot({ interestingOnly: false });\n    return JSON.stringify(snapshot, null, 2);\n  \"\n}''\n```\n\n## 3. Navigate to Subpage (Multi-Step)\n\n```bash\npython scripts/mcp_client.py call playwright browser_run_code ''{\n  \"code\": \"\n    await page.goto(\\\"https://www.olx.ro\\\");\n\n    // Dismiss cookies\n    const acceptBtn = page.getByRole(\\\"button\\\", { name: \\\"Accept\\\" });\n    if (await acceptBtn.isVisible({ timeout: 3000 }).catch(() => false)) {\n      await acceptBtn.click();\n      await page.waitForTimeout(500);\n    }\n\n    // Navigate to login\n    await page.goto(\\\"https://www.olx.ro/cont/\\\");\n\n    // Wait for redirect to login domain\n    await page.waitForURL(/login\\\\.olx\\\\.ro/, { timeout: 10000 });\n\n    // Get form structure\n    const snapshot = await page.accessibility.snapshot();\n    return JSON.stringify({ url: page.url(), snapshot }, null, 2);\n  \"\n}''\n```\n\n## 4. Explore Element Interactions (Multi-Step)\n\nUse this to understand how menus/dropdowns behave:\n\n```bash\npython scripts/mcp_client.py call playwright browser_run_code ''{\n  \"code\": \"\n    await page.goto(\\\"https://www.olx.ro\\\");\n\n    // Dismiss cookies\n    const acceptBtn = page.getByRole(\\\"button\\\", { name: \\\"Accept\\\" });\n    if (await acceptBtn.isVisible({ timeout: 3000 }).catch(() => false)) {\n      await acceptBtn.click();\n    }\n\n    // Click on category to see what happens\n    const categoryLink = page.getByRole(\\\"link\\\", { name: /Auto, moto/i }).first();\n    await categoryLink.click();\n\n    // Wait to see result\n    await page.waitForTimeout(1500);\n\n    // Capture state after click\n    const snapshot = await page.accessibility.snapshot();\n    return JSON.stringify({\n      url: page.url(),\n      didNavigate: page.url().includes(\\\"auto\\\"),\n      snapshot: snapshot\n    }, null, 2);\n  \"\n}''\n```\n\n## 5. Fill Form and Capture State\n\n```bash\npython scripts/mcp_client.py call playwright browser_run_code ''{\n  \"code\": \"\n    await page.goto(\\\"https://login.olx.ro\\\");\n\n    // Fill login form\n    await page.locator(\\\"input[type=email]\\\").fill(\\\"test@example.com\\\");\n    await page.locator(\\\"input[type=password]\\\").fill(\\\"test123\\\");\n\n    // Click login button\n    await page.getByTestId(\\\"login-submit-button\\\").click();\n\n    // Wait for response\n    await page.waitForTimeout(3000);\n\n    // Capture any error messages\n    const errors = await page.locator(\\\"[class*=error], [role=alert]\\\").allTextContents();\n    const snapshot = await page.accessibility.snapshot();\n\n    return JSON.stringify({\n      url: page.url(),\n      errors: errors,\n      snapshot: snapshot\n    }, null, 2);\n  \"\n}''\n```\n\n---\n\n# Gathering Selectors for Page Objects\n\n## Best Practices\n\n### 1. Use Accessibility Tree First\n\nThe snapshot from `browser_navigate` or `browser_run_code` provides:\n- **Role**: button, link, textbox, combobox, etc.\n- **Name**: accessible name (from label, aria-label, text content)\n- **State**: disabled, checked, expanded, etc.\n\nMap these to Playwright locators:\n```typescript\n// From snapshot: { role: \"button\", name: \"Căutare\" }\npage.getByRole(''button'', { name: /Căutare/i })\n\n// From snapshot: { role: \"textbox\", name: \"Ce anume cauți?\" }\npage.getByRole(''textbox'', { name: /Ce anume cauți/i })\n\n// From snapshot: { role: \"link\", name: \"Auto, moto și ambarcațiuni\" }\npage.getByRole(''link'', { name: /Auto, moto/i })\n```\n\n### 2. Selector Priority\n\n| Priority | Method | Use When |\n|----------|--------|----------|\n| 1 | `getByRole()` | Element has semantic role + accessible name |\n| 2 | `getByTestId()` | Element has `data-testid` attribute |\n| 3 | `getByText()` | Unique text content |\n| 4 | `getByPlaceholder()` | Input with placeholder |\n| 5 | `locator(''[attr=\"value\"]'')` | CSS attribute selector |\n| 6 | `locator(''.class'')` | CSS class (fragile, avoid) |\n\n### 3. Handling Multiple Matches\n\n```typescript\n// Use .first() when multiple match\npage.getByRole(''link'', { name: ''Category'' }).first()\n\n// Use parent context\npage.locator(''nav'').getByRole(''link'', { name: ''Category'' })\n\n// Use filter\npage.getByRole(''button'').filter({ hasText: /submit/i })\n```\n\n### 4. Get Full DOM for Complex Cases\n\nWhen accessibility tree isn''t enough, get raw HTML:\n\n```bash\npython scripts/mcp_client.py call playwright browser_run_code ''{\n  \"code\": \"\n    await page.goto(\\\"https://example.com\\\");\n\n    // Get specific element HTML\n    const formHtml = await page.locator(\\\"form\\\").first().innerHTML();\n\n    // Or get all buttons with their attributes\n    const buttons = await page.locator(\\\"button\\\").evaluateAll(btns =>\n      btns.map(b => ({\n        text: b.textContent,\n        testid: b.dataset.testid,\n        class: b.className,\n        type: b.type\n      }))\n    );\n\n    return JSON.stringify({ formHtml, buttons }, null, 2);\n  \"\n}''\n```\n\n---\n\n# Quick Reference: Playwright MCP Tools\n\n| Tool | Session Behavior | Use Case |\n|------|-----------------|----------|\n| `browser_navigate` | New session, returns snapshot | Simple page load |\n| `browser_run_code` | **Single session, custom script** | Multi-step operations |\n| `browser_click` | New session | Single click (usually not useful alone) |\n| `browser_type` | New session | Single type (usually not useful alone) |\n| `browser_snapshot` | Reuses if session exists | Get current page state |\n| `browser_screenshot` | Reuses if session exists | Visual capture |\n\n## Tool Arguments\n\n### browser_navigate\n```json\n{\"url\": \"https://example.com\"}\n```\n\n### browser_run_code\n```json\n{\n  \"code\": \"await page.goto(''https://example.com''); return await page.title();\"\n}\n```\n\nThe `code` must be valid JavaScript that:\n- Uses `page` object (Playwright Page)\n- Uses `await` for async operations\n- Returns the data you want (use `JSON.stringify` for objects)\n\n### browser_click\n```json\n{\"element\": \"Submit button\", \"ref\": \"optional-element-ref\"}\n```\n\n### browser_type\n```json\n{\"element\": \"Email input\", \"text\": \"user@example.com\"}\n```\n\n---\n\n# Error Handling\n\n| Error | Cause | Fix |\n|-------|-------|-----|\n| \"No MCP config found\" | Missing config file | Create mcp-config.json |\n| \"Server not found\" | Server not in config | Add server to config |\n| \"Connection failed\" | Server not running | Start the MCP server |\n| \"Invalid JSON\" | Bad tool arguments | Check argument format |\n| \"Timeout\" | Page too slow | Increase timeout in code |\n| \"Element not found\" | Wrong selector | Check snapshot for actual names |\n\n---\n\n# Setup\n\n1. Copy the example config:\n   ```bash\n   cp .claude/skills/mcp-client/references/mcp-config.example.json \\\n      .claude/skills/mcp-client/references/mcp-config.json\n   ```\n\n2. The config should contain:\n   ```json\n   {\n     \"mcpServers\": {\n       \"playwright\": {\n         \"command\": \"npx\",\n         \"args\": [\"@playwright/mcp@latest\"]\n       }\n     }\n   }\n   ```\n\n3. Install dependencies:\n   ```bash\n   pip install mcp fastmcp\n   ```\n\n## Config Example\n\nSee [references/mcp-config.example.json](references/mcp-config.example.json)\n\n## Available Servers\n\nSee [references/mcp-servers.md](references/mcp-servers.md) for:\n- Playwright (browser automation)\n- GitHub (repository operations)\n- Filesystem (file access)\n- Sequential Thinking (reasoning)\n- And more...\n\n## Dependencies\n\n```bash\npip install mcp fastmcp\n```\n"},"lastSynced":"2026-03-08T02:01:31.159Z","agentAnalysis":{"suitability":{"en":"Perfect for Automated Workflow Agents needing seamless MCP server connections without context bloat.","zh":"非常适合需要与MCP服务器建立无缝连接而无上下文膨胀的自动化工作流代理。","ja":"MCPサーバーへのシームレスな接続が必要で、コンテキストの膨張がない自動化ワークフロー エージェントに最適です。","ko":"MCP 서버에 대한 시ーム리스 연결이 필요한 컨텍스트가 부풀리지 않는 자동화된 워크플로 에이전트에 적합합니다.","es":"Perfecto para Agentes de flujo de trabajo automatizados que necesitan conexiones de servidor MCP sin sobrecarga de contexto.","fr":"Parfait pour les agents de workflow automatisés ayant besoin de connexions de serveur MCP sans surcharge de contexte.","de":"Perfekt für automatisierte Workflow-Agents, die nahtlose MCP-Server-Verbindungen ohne Kontextüberlastung benötigen.","pt":"Perfeito para Agentes de Fluxo de Trabalho Automatizado que necessitam de conexões de servidor MCP sem inflação de contexto.","ru":"Идеально подходит для автоматических агентов рабочего процесса, которым необходимы бесперебойные соединения с сервером MCP без избыточного контекста.","ar":"مثالي لعميلين مساعدين آليين للعمل التلقائي الذين يحتاجون إلى اتصالات خادم MCP بدون انتفاخ السياق."},"recommendation":{"en":"Empowers agents to connect to any MCP server using Playwright, enabling multi-step operations via browser_run_code and handling browser sessions efficiently with each MCP call.","zh":"通过Playwright使代理能够连接到任何MCP服务器，实现通过browser_run_code进行的多步骤操作，并且能够高效地使用每个MCP调用处理浏览器会话。","ja":"Playwrightを使用して、エージェントが任意のMCPサーバーに接続できるようにし、browser_run_codeを介したマルチステップ操作を可能にし、各MCP呼び出しでブラウザーセッションを効率的に処理します。","ko":"Playwright를 사용하여 에이전트가 任意의 MCP 서버에 연결할 수 있도록 하여 browser_run_code를 통해 다단계 작업을 가능하게 하며, 각 MCP 호출에서 브라우저 세션을 효율적으로 처리합니다.","es":"Habilita a los agentes a conectarse a cualquier servidor MCP utilizando Playwright, permitiendo operaciones multipeso a través de browser_run_code y manejo eficiente de sesiones de navegador con cada llamada MCP.","fr":"Permet aux agents de se connecter à n''importe quel serveur MCP en utilisant Playwright, permettant des opérations multipeso via browser_run_code et gérant les sessions de navigateur de manière efficace avec chaque appel MCP.","de":"Ermächtigt Agents, sich mit jedem MCP-Server über Playwright zu verbinden, ermöglicht mehrschrittige Operationen über browser_run_code und effizientes Handling von Browsersitzungen mit jedem MCP-Aufruf.","pt":"Habilita os agentes a se conectarem a qualquer servidor MCP usando Playwright, permitindo operações em várias etapas via browser_run_code e tratando sessões de navegador de forma eficiente a cada chamada MCP.","ru":"Наделяет агентов возможностью подключаться к любому серверу MCP с помощью Playwright, что позволяет выполнять многоступенчатые операции через browser_run_code и эффективно обрабатывать сеансы браузера при каждом вызове MCP.","ar":"تمكّن الوكلاء من الاتصال بใด.server MCP باستخدام Playwright، مما يسمح بالعمليات متعددة الخطوات عبر browser_run_code ومعالجة جلسات المتصفح بفعالية مع كل مكالمة MCP."},"useCases":{"en":["Automating MCP server interactions","Generating browser sessions for testing","Debugging MCP call issues with browser_run_code"],"zh":["自动化MCP服务器交互","为测试生成浏览器会话","使用browser_run_code调试MCP调用问题"],"ja":["MCPサーバーの相互作用を自動化する","テスト用のブラウザーセッションを生成する","browser_run_codeを使用してMCP呼び出しに関する問題をデバッグする"],"ko":["MCP 서버 상호작용 자동화","테스트를 위한 브라우저 세션 생성","browser_run_code를 사용하여 MCP 호출 관련 문제 디버깅"],"es":["Automatización de interacciones con servidores MCP","Generación de sesiones de navegador para pruebas","Depuración de problemas con llamadas MCP con browser_run_code"],"fr":["Automatisation des interactions avec les serveurs MCP","Génération de sessions de navigateur pour les tests","Débogage des problèmes d''appel MCP avec browser_run_code"],"de":["Automatisierung von MCP-Server-Interaktionen","Generierung von Browsersitzungen für Tests","Fehlerbehebung bei MCP-Aufrufen mit browser_run_code"],"pt":["Automatizar interações do servidor MCP","Gerar sessões de navegador para testes","Depurar problemas de chamada MCP com browser_run_code"],"ru":["Автоматизация взаимодействия с сервером MCP","Генерация сеансов браузера для тестирования","Отладка проблем вызова MCP с помощью browser_run_code"],"ar":["أتمتة تفاعلات خادم MCP","إنشاء جلسات متصفح للاختبار","تصحيح أخطاء الاتصال MCP باستخدام browser_run_code"]},"limitations":{"en":["Each MCP call creates a new browser session","Browser closes after each call","Requires redoing all steps for returning to a previous state"],"zh":["每个MCP调用都会创建一个新的浏览器会话","浏览器在每次调用后都会关闭","需要重新执行所有步骤才能返回到之前的状态"],"ja":["各MCP呼び出しで新しいブラウザーセッションが作成される","各呼び出し後ブラウザーが閉じられる","前の状態に戻るにはすべての手順をやり直す必要がある"],"ko":["각 MCP 호출에서 새로운 브라우저 세션이 생성됩니다.","각 호출 후 브라우저가 닫힙니다.","이전 상태로 돌아가려면 모든 단계를 다시 실행해야 합니다."],"es":["Cada llamada MCP crea una nueva sesión de navegador","El navegador se cierra después de cada llamada","Requiere volver a realizar todos los pasos para regresar a un estado anterior"],"fr":["Chaque appel MCP crée une nouvelle session de navigateur","Le navigateur se ferme après chaque appel","Nécessite de répéter toutes les étapes pour revenir à un état antérieur"],"de":["Jeder MCP-Aufruf erstellt eine neue Browsersitzung","Der Browser schließt sich nach jedem Aufruf","Erfordert das erneute Ausführen aller Schritte, um zu einem vorherigen Zustand zurückzukehren"],"pt":["Cada chamada MCP cria uma nova sessão de navegador","O navegador fecha após cada chamada","Requer refazer todos os passos para retornar a um estado anterior"],"ru":["Каждый вызов MCP создает новую сессию браузера","Браузер закрывается после каждого вызова","Требуется повторить все шаги, чтобы вернуться к предыдущему состоянию"],"ar":["تُنشئ كل مكالمة MCP جلسة متصفح جديدة","ينغلق المتصفح بعد كل مكالمة","يتطلب إعادة جميع الخطوات للعودة إلى حالة سابقة"]},"version":4},"contentHash":"962acb3c5b14f34ba636d7da21fff240a588fce1a5cd37444ca563bf024a04e4","qualityScore":60}');
DELETE FROM skills_fts WHERE id = 'cristian-robert/autonomous-automation-tester/mcp-client';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cristian-robert/autonomous-automation-tester/mcp-client', 'mcp-client', 'cristian-robert', 'autonomous-automation-tester', 'community', 'mcp-client cristian-robert autonomous-automation-tester community The mcp-client skill enables developers to connect to any MCP server without bloating context with tool definitions, ideal for AI agents and automated workflows. MCP客户端允许您连接到任何MCP服务器，而无需为工具定义填充上下文。每次MCP调用都会创建新的浏览器会话 MCPクライアントは、ツール定義でコンテキストを膨張させることなく、任意のMCPサーバーに接続することを可能にします。各MCP呼び出しで新しいブラウザーセッションが作成されます MCP 클라이언트는 도구 정의로 컨텍스트를膨張させる 것 없이 任意의 MCP 서버에 연결할 수 있습니다. 각 MCP 호출은 새로운 브라우저 세션을 생성합니다. mcp-client es un cliente universal que permite conectar con cualquier servidor MCP sin sobrecargar el contexto. Cada llamada a MCP crea una nueva sesión de navegador. mcp-client est un client universel qui permet de se connecter à n''importe quel serveur MCP sans surcharger le contexte. Chaque appel à MCP crée une nouvelle session de navigateur. mcp-client ist ein universeller Client, der eine Verbindung zu jedem MCP-Server herstellt, ohne den Kontext zu überladen. Jeder MCP-Aufruf erstellt eine neue Browsersession. O mcp-client é uma ferramenta que permite conectar-se a servidores MCP sem sobrecarregar o contexto. Ele cria uma nova sessão de navegador para cada chamada MCP mcp-client - это инструмент, который позволяет подключаться к серверам MCP без лишних настроек. Он создает новую сессию браузера для каждого вызова MCP mcp-client هو أداة تمكنك من الاتصال بخوادير MCP دون إضاعة السياق. وهو يخلق جلسة متصفح جديدة لكل مكالمة MCP how to use mcp-client mcp-client setup guide mcp-client alternative mcp-client vs playwright mcp-client install mcp-client browser session management universal mcp server connection mcp-client multi-step operations browser_run_code command MCP客户端 MCP服务器 Playwright 浏览器会话 browser_run_code 多步操作 AI工具 AIエージェント MCP客户端设置 MCP客户端教程 Connects to any MCP server without requiring tool definitions Creates a new browser session for each MCP call Closes the browser after each call for efficient resource management Supports multi-step operations using the browser_run_code command Requires redoing all steps from scratch to return to a previous state, such as a logged-in session mcp-client is a universal client for connecting to MCP servers, allowing for efficient browser session management and multi-step operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AWolf81/memory-lane/memorylane', 'community', 'AWolf81', 'memory-lane', 'AWolf81/memory-lane', 'memorylane', 0, 0, 60, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:33.227Z', 'eb1f296f783857fd4eab00f38f702446bd3d48df2fe8e10c8d2c9ba166767d39', '{"id":"AWolf81/memory-lane/memorylane","name":"memorylane","description":{"en":"memorylane provides Claude Code with durable project memory, extracting knowledge locally and injecting relevant information. It benefits developers by offering persistent memory across sessions.","zh":"MemoryLane 为 Claude 提供持久内存，支持 4 个类别的信息存储，并实现了 6.4 倍的平均压缩比","ja":"MemoryLane は Claude に永続メモリを提供し、4 種類のカテゴリの情報を保存し、平均 6.4 倍の圧縮比を実現します","ko":"MemoryLane는 Claude에 영속적 메모리를 제공하며 4가지 카테고리의 정보를 저장하며 평균 6.4배의 압축 비율을 실현합니다","es":"MemoryLane proporciona memoria persistente para Claude, reduciendo los costos en un 84,3% con compresión de contexto y seguimiento de costos en tiempo real","fr":"MemoryLane fournit une mémoire persistante pour Claude, réduisant les coûts de 84,3% avec la compression de contexte et le suivi des coûts en temps réel","de":"MemoryLane bietet persistente Speicherung für Claude, senkt die Kosten um 84,3% durch Kontextkomprimierung und Echtzeit-Kostenverfolgung","pt":"O MemoryLane fornece memória persistente para projetos, com compressão de contexto e acompanhamento de custos em tempo real","ru":"MemoryLane обеспечивает постоянную память для проектов, сжатие контекста и отслеживание затрат в режиме реального времени","ar":"يوفّر MemoryLane ذاكرة متواصلة للمشاريع، مع ضغط السياق وتتبع التكاليف في الوقت الفعلي"},"seo":{"title":{"en":"memorylane: Persistent Project Memory for AI Agents | Set...","zh":"MemoryLane 设置指南：持久内存和上下文压缩","ja":"MemoryLane 導入ガイド：永続メモリとコンテキスト圧縮","ko":"MemoryLane 설정 가이드: 영속적 메모리와 컨텍스트 압축","es":"Guía de Configuración de MemoryLane para Ahorro de Costos","fr":"Guide de Mise en Place de MemoryLane pour Économiser les ...","de":"MemoryLane-Setup-Anleitung für Kosteneinsparungen","pt":"Guia de Configuração do MemoryLane para Ferramentas de IA","ru":"Настройка ИИ Агентов с помощью MemoryLane","ar":"دليل إعداد MemoryLane لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how memorylane reduces API costs by 84.3% with context compression and passive learning. Get started with our setup guide today!","zh":"MemoryLane 为 Claude 提供持久内存，实现 84.3% 的成本节约，包括上下文压缩和被动学习等功能","ja":"MemoryLane は Claude に永続メモリを提供し、84.3% のコスト削減を実現します。コンテキスト圧縮やパッシブラーニングなど","ko":"MemoryLane는 Claude에 영속적 메모리를 제공하며 84.3%의 비용 절감을 실현합니다. 컨텍스트 압축 및 수동 학습 등","es":"Descubre cómo MemoryLane reduce los costos en un 84,3% con su memoria persistente y compresión de contexto","fr":"Découvrez comment MemoryLane réduit les coûts de 84,3% avec sa mémoire persistante et la compression de contexte","de":"Erfahren Sie, wie MemoryLane die Kosten um 84,3% senkt durch persistente Speicherung und Kontextkomprimierung","pt":"Aprenda a configurar o MemoryLane para melhorar a memória dos projetos com 84,3% de economia de custos","ru":"Узнайте, как настроить MemoryLane для улучшения памяти проектов с экономией 84,3% затрат","ar":"تعرف على كيفية إعداد MemoryLane لتحسين ذاكرة المشاريع بتوفير 84,3% من التكاليف"},"definition":{"en":"memorylane is a skill that enables persistent memory for Claude, allowing it to remember information across sessions in categories like patterns, insights, and context.","zh":"MemoryLane 是一种为 Claude 提供持久内存的 AI 工具","ja":"MemoryLane は Claude に永続メモリを提供する AI エージェントです","ko":"MemoryLane는 Claude에 영속적 메모리를 제공하는 AI 에이전트입니다","es":"MemoryLane es una habilidad que proporciona memoria persistente para Claude, permitiendo la compresión de contexto y el seguimiento de costos","fr":"MemoryLane est une compétence qui fournit une mémoire persistante pour Claude, permettant la compression de contexte et le suivi des coûts","de":"MemoryLane ist eine Fähigkeit, die persistente Speicherung für Claude bietet, ermöglicht die Kontextkomprimierung und die Kostenverfolgung","pt":"O que é MemoryLane? Uma ferramenta de IA que fornece memória persistente para projetos","ru":"Что такое MemoryLane? Инструмент ИИ, обеспечивающий постоянную память для проектов","ar":"ما هو MemoryLane؟ أداة ذكاء اصطناعي توفر ذاكرة متواصلة للمشاريع"},"features":{"en":["Persistent Memory: remembers information across sessions in 4 categories","Context Compression: achieves 6.4x average compression ratio","Cost Tracking: monitors API cost savings in real-time","Passive Learning: automatically learns from git commits and file changes","Zero Configuration: works out of the box with no setup required"],"zh":["持久内存：支持 4 个类别的信息存储","上下文压缩：平均 6.4 倍的压缩比","成本跟踪：实时 API 成本节约监控","被动学习：自动从 Git 提交和文件更改中学习","零配置：无需配置即可使用"],"ja":["永続メモリ：4 種類のカテゴリの情報を保存","コンテキスト圧縮：平均 6.4 倍の圧縮比","コストトラッキング：リアルタイム API コスト削減モニタリング","パッシブラーニング：Git コミットとファイル変更から自動的に学習","ゼロコンフィギュレーション：設定不要"],"ko":["영속적 메모리：4가지 카테고리의 정보를 저장","컨텍스트 압축：평균 6.4배의 압축 비율","비용 추적：실시간 API 비용 절감 모니터링","수동 학습：Git 커밋 및 파일 변경에서 자동으로 학습","제로 구성：설정 필요 없음"],"es":["Memoria persistente para Claude","Compresión de contexto con una relación de compresión promedio de 6,4x","Seguimiento de costos en tiempo real","Aprendizaje pasivo a través de commits de git y cambios de archivos","Configuración cero"],"fr":["Mémoire persistante pour Claude","Compression de contexte avec un ratio de compression moyen de 6,4x","Suivi des coûts en temps réel","Apprentissage passif via les commits de git et les modifications de fichiers","Configuration zéro"],"de":["Persistente Speicherung für Claude","Kontextkomprimierung mit einem durchschnittlichen Komprimierungsverhältnis von 6,4x","Echtzeit-Kostenverfolgung","Passives Lernen durch git-Commits und Dateiänderungen","Null-Konfiguration"],"pt":["Memória persistente em 4 categorias","Compressão de contexto com razão de compressão de 6,4x","Acompanhamento de custos em tempo real","Aprendizado passivo com commits e alterações de arquivos","Zero configuração necessária"],"ru":["Постоянная память в 4 категориях","Сжатие контекста с коэффициентом сжатия 6,4x","Отслеживание затрат в режиме реального времени","Пассивное обучение с помощью коммитов и изменений файлов","Нет необходимости в конфигурации"],"ar":["ذاكرة متواصلة في 4 فئات","ضغط السياق بنسبة ضغط 6,4x","تتبع التكاليف في الوقت الفعلي","تعلم سلبي باستخدام التعديلات والملفات","لا يوجد حاجة إلى إعداد"]},"keywords":{"en":["how to use memorylane","memorylane setup guide","memorylane alternative","memorylane vs competitors","memorylane install","what is memorylane","memorylane cost savings","persistent project memory","context compression techniques"],"zh":["MemoryLane","AI 工具","持久内存","上下文压缩","成本节约","被动学习","零配置","Claude","AI 에이전트"],"ja":["MemoryLane","AI エージェント","永続メモリ","コンテキスト圧縮","コスト削減","パッシブラーニング","ゼロコンフィギュレーション","Claude","AI ツール"],"ko":["MemoryLane","AI 에이전트","영속적 메모리","컨텍스트 압축","비용 절감","수동 학습","제로 구성","Claude","AI 도구"],"es":["MemoryLane","Claude","memoria persistente","compresión de contexto","seguimiento de costos","aprendizaje pasivo","configuración cero","herramientas de AI","agentes de AI"],"fr":["MemoryLane","Claude","mémoire persistante","compression de contexte","suivi des coûts","apprentissage passif","configuration zéro","outils d''IA","agents d''IA"],"de":["MemoryLane","Claude","persistente Speicherung","Kontextkomprimierung","Kostenverfolgung","passives Lernen","Null-Konfiguration","KI-Tools","KI-Agenten"],"pt":["ferramentas de ia","memória persistente","compressão de contexto","acompanhamento de custos","aprendizado passivo","zero configuração","guias de configuração","melhores práticas de ia"],"ru":["ИИ агенты","постоянная память","сжатие контекста","отслеживание затрат","пассивное обучение","нет конфигурации","руководства по настройке","лучшие практики ИИ"],"ar":["أدوات الذكاء الاصطناعي","ذاكرة متواصلة","ضغط السياق","تتبع التكاليف","تعلم سلبي","لا إعداد","دليل الإعداد","أفضل ممارسات الذكاء الاصطناعي"]}},"owner":"AWolf81","repo":"memory-lane","repoPath":"AWolf81/memory-lane","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"memorylane","description":"Zero-config persistent memory for Claude with automatic cost savings. Use when you need to remember project context, reduce API token costs, track learned patterns, manage memories across sessions, or curate/clean up memories. Automatically compresses context 6x and saves 84% on API costs. Keywords: memory, remember, recall, context, cost savings, reduce tokens, learn, patterns, insights, curate, clean up memories, review memories.","bodyPreview":"# MemoryLane Skill\n\n## What This Skill Does\n\nMemoryLane provides persistent memory for Claude with proven 84.3% cost savings:\n\n- **Persistent Memory**: Remember information across sessions in 4 categories (patterns, insights, learnings, context)\n- **Context Compression**: 6.4x average compression ratio (20K → 3K tokens)\n- **Cost Tracking**: Real-time API cost savings monitoring\n- **Passive Learning**: Automatically learns from git commits and file changes\n- **Zero Configuration**: Works out of t","body":"# MemoryLane Skill\n\n## What This Skill Does\n\nMemoryLane provides persistent memory for Claude with proven 84.3% cost savings:\n\n- **Persistent Memory**: Remember information across sessions in 4 categories (patterns, insights, learnings, context)\n- **Context Compression**: 6.4x average compression ratio (20K → 3K tokens)\n- **Cost Tracking**: Real-time API cost savings monitoring\n- **Passive Learning**: Automatically learns from git commits and file changes\n- **Zero Configuration**: Works out of the box with smart defaults\n\n## When to Use This Skill\n\nActivate MemoryLane when the user:\n- Asks to \"remember\" something about the project\n- Wants to know \"what you remember\" or \"what you know\"\n- Mentions \"API costs\", \"token usage\", or \"reduce costs\"\n- Asks about \"project patterns\" or \"insights\"\n- Wants to see \"learned\" information\n- Requests \"context compression\" or \"optimize context\"\n- Asks to \"curate memories\", \"clean up memories\", or \"review memory quality\"\n- Mentions memories seem low quality, self-referential, or not useful\n\n## Core Commands\n\n### Check Status\n```bash\npython3 src/cli.py status\n```\nShows memory statistics, category breakdown, and cost savings.\n\n### Recall Memories\n```bash\npython3 src/cli.py recall \"<query>\"\n```\nSearch memories by keyword. Example:\n```bash\npython3 src/cli.py recall \"authentication\"\n```\n\n### View Insights\n```bash\npython3 src/cli.py insights\n```\nDisplay learned project insights (high-value patterns).\n\n### View Cost Savings\n```bash\npython3 src/cli.py costs\n```\nDetailed breakdown of token savings and cost reduction.\n\n### Configure Settings\n```bash\n# Get a setting\npython3 src/cli.py config get memory.max_context_tokens\n\n# Set a setting\npython3 src/cli.py config set memory.max_context_tokens 3000\n\n# List all settings\npython3 src/cli.py config list\n```\n\n### Export Memories as Markdown\n```bash\npython3 src/cli.py export-markdown --category patterns --output context.md\n```\n\n### Backup/Restore\n```bash\n# Create backup\npython3 src/cli.py backup --output backup.json\n\n# Restore from backup\npython3 src/cli.py restore backup.json\n```\n\n### Reset Memories\n```bash\npython3 src/cli.py reset --force\n```\n\n## Individual Memory Management\n\n### Get a Memory\n```bash\npython3 src/cli.py memory get <id>\n```\nExample: `python3 src/cli.py memory get lear-009`\n\n### Delete a Memory\n```bash\npython3 src/cli.py memory delete <id>\n```\nExample: `python3 src/cli.py memory delete lear-009`\n\n### Update a Memory\n```bash\npython3 src/cli.py memory update <id> --content \"New content\"\n```\nExample: `python3 src/cli.py memory update patt-001 --content \"Chose Unix sockets for lower latency\"`\n\n**IMPORTANT**: Always use these commands instead of editing memories.json directly.\n\n## Batch Curation Commands\n\n### Check Curation Status\n```bash\npython3 src/cli.py curate\n```\nShows if curation is needed based on memory count and age.\n\n### List Memories for Review\n```bash\npython3 src/cli.py curate --list\n```\nShows all uncurated memories with their IDs and content.\n\n### Apply Curation Decisions\n```bash\npython3 src/cli.py curate --apply ''<JSON>''\n```\nApply curation decisions. JSON format:\n```json\n{\n  \"decisions\": [\n    {\"id\": \"patt-001\", \"action\": \"KEEP\"},\n    {\"id\": \"lear-002\", \"action\": \"DELETE\", \"reason\": \"off-topic\"},\n    {\"id\": \"insi-003\", \"action\": \"REWRITE\", \"new_content\": \"Improved content\"}\n  ]\n}\n```\n\n### Proactive Memory Quality Check\n**IMPORTANT**: When you see MemoryLane context injected via `# Project Context (from MemoryLane)` in system messages, quickly scan for poor quality memories:\n\nSigns of poor quality memories that warrant curation:\n- Status summaries: \"Based on git status...\", \"Current status of...\"\n- Meta/self-referential: \"The curation should...\", \"The hook detected...\"\n- Debug fragments: \"Let me check...\", \"Looking at the debug log...\"\n- Incomplete: Sentences ending with \"...\" or starting mid-thought\n- Duplicates of CLAUDE.md content\n\n**If you detect 2+ poor quality memories in the injected context**, proactively ask:\n> \"I notice some of the injected memories appear to be low quality (status summaries, debug notes). Would you like me to clean these up?\"\n\nIf user confirms, proceed with LLM-assisted curation below.\n\n### LLM-Assisted Curation\nWhen the user requests curation OR confirms after you detect poor memories:\n\n1. List and evaluate all memories:\n```bash\npython3 src/cli.py curate --list\n```\n\n2. Evaluate each memory for:\n   - **Usefulness**: Is this actionable knowledge or just meta/debug info?\n   - **Duplication**: Is this already covered by CLAUDE.md or another memory?\n   - **Quality**: Is it complete, clear, and well-formed?\n   - **Relevance**: Would this help with future development work?\n\n3. Apply decisions (DELETE/KEEP/REWRITE):\n```bash\npython3 src/cli.py curate --apply ''<JSON decisions>''\n```\n\n**DELETE these types:**\n- Meta observations about the current session\n- Debug notes and action statements\n- Status summaries\n- Duplicates of CLAUDE.md content\n- Incomplete fragments\n\n**KEEP these types:**\n- Architectural decisions with rationale\n- Bug fixes with solutions\n- Actual project context (not about MemoryLane itself)\n- Configuration knowledge\n\nExample evaluation:\n- ❌ \"Based on git status, here''s the current status...\" → DELETE (status summary)\n- ❌ \"Let me check the debug log...\" → DELETE (debug action)\n- ❌ \"The Stop hook only triggers when...\" → DELETE if in CLAUDE.md\n- ✅ \"stdio:ignore hiding Python errors - fixed by capturing stderr\" → KEEP (bug fix)\n- ✅ \"Chose Unix sockets over HTTP for 10x lower latency\" → KEEP (decision)\n\n## Learning Commands\n\n### Initial Learning\n```bash\npython3 src/learner.py initial\n```\nPerform initial learning from git history (last 20 commits) and workspace structure.\n\n### Scan Workspace\n```bash\npython3 src/learner.py scan\n```\nScan and index all Python/JS/TS files in the workspace.\n\n### Analyze Git History\n```bash\npython3 src/learner.py git\n```\nExtract patterns from recent git commits.\n\n### Continuous Learning (Background)\n```bash\npython3 src/learner.py watch\n```\nWatch for file changes and git commits continuously (runs until stopped).\n\n## Server Commands\n\n### Start Sidecar Server\n```bash\npython3 src/server.py start\n```\nStart background server with Unix socket IPC (for low-latency memory operations).\n\n### Check Server Status\n```bash\npython3 src/server.py status\n```\n\n### Stop Server\n```bash\npython3 src/server.py stop\n```\n\n## Testing Commands\n\n### Run All Tests\n```bash\npytest\n```\n\n### Validate Cost Savings\n```bash\npytest tests/test_cost_savings.py -v -s\n```\nRuns comprehensive cost validation tests (shows 84.3% savings proof).\n\n### Test Memory Store\n```bash\npytest tests/test_memory_store.py -v\n```\n\n## Usage Patterns\n\n### Pattern 1: Remember Important Information\nWhen the user says: \"Remember that this project uses PostgreSQL with SSL mode required\"\n\n```bash\n# (You would typically use the Python API, but for CLI:)\npython3 -c \"\nimport sys; sys.path.insert(0, ''src'')\nfrom memory_store import MemoryStore\nstore = MemoryStore(''.memorylane/memories.json'')\nstore.add_memory(''context'', ''Project uses PostgreSQL with SSL mode required'', ''manual'', 0.9)\nprint(''✓ Remembered'')\n\"\n```\n\n### Pattern 2: Recall Project Knowledge\nWhen the user asks: \"What do you know about our database setup?\"\n\n```bash\npython3 src/cli.py recall \"database\"\n```\n\n### Pattern 3: Show Cost Savings\nWhen the user asks: \"How much money has MemoryLane saved me?\"\n\n```bash\npython3 src/cli.py costs\n```\n\n### Pattern 4: Learn from Project History\nWhen starting work on a project:\n\n```bash\npython3 src/learner.py initial\npython3 src/cli.py insights\n```\n\n## Integration with Workflows\n\n### Daily Development Workflow\n```bash\n# Morning: Start server and check status\npython3 src/server.py start\npython3 src/cli.py status\n\n# During work: MemoryLane learns passively\n# (no action needed - watches git commits and file changes)\n\n# Evening: Check what was learned\npython3 src/cli.py insights\npython3 src/cli.py costs\n```\n\n### Project Onboarding Workflow\n```bash\n# Step 1: Initial learning\npython3 src/learner.py initial\n\n# Step 2: Review learned patterns\npython3 src/cli.py recall \"primary language\"\npython3 src/cli.py insights\n\n# Step 3: Export context for sharing\npython3 src/cli.py export-markdown --output project-context.md\n```\n\n## Configuration Options\n\nKey settings in `.memorylane/config.json`:\n\n- `memory.max_context_tokens`: Target token count for compression (default: 2000)\n- `memory.compression_ratio_target`: Target compression ratio (default: 7.0x)\n- `context_rot.model_context_tokens`: Advertised model window for context rot guard (default: 200000)\n- `context_rot.safe_fraction`: Fraction of model window allowed for prompt + injected context (default: 0.5)\n- `context_rot.reserve_tokens`: Buffer reserved for assistant response (default: 1200)\n- `learning.watch_file_changes`: Enable file watching (default: true)\n- `learning.watch_git_commits`: Learn from commits (default: true)\n- `privacy.exclude_patterns`: Files to ignore (default: *.env, secrets/, etc.)\n\n## Performance Metrics\n\nValidated through comprehensive testing:\n\n- **Cost Savings**: 84.3% (baseline $17.25/week → $2.70/week)\n- **Compression Ratio**: 6.4x average (2.3M tokens → 360K tokens)\n- **Retrieval Latency**: <100ms (target, server not benchmarked yet)\n- **Memory Quality**: Relevance scoring with automatic pruning\n\n## Important Notes\n\n1. **Privacy**: All data stored locally in `.memorylane/` directory\n2. **No Dependencies**: Pure Python 3.8+ (no external packages needed for production)\n3. **Automatic Exclusions**: Respects `.env`, `secrets/`, and other sensitive patterns\n4. **Backup Before Reset**: Always creates backup before destructive operations\n5. **Server Optional**: CLI works standalone; server adds performance for frequent operations\n\n## Example Conversation Flow\n\n**User**: \"Remember that our API uses JWT tokens with 24-hour expiration\"\n\n**You**: Let me store that in MemoryLane''s context.\n```bash\npython3 -c \"...\"  # Add to memory\n```\n✓ Remembered in context category with 0.9 relevance.\n\n**User**: \"What do you know about our authentication?\"\n\n**You**: Let me recall what I know about authentication.\n```bash\npython3 src/cli.py recall \"authentication\"\n```\nFound 2 memories:\n1. [context] API uses JWT tokens with 24-hour expiration ⭐⭐⭐⭐⭐\n2. [patterns] Project uses authentication middleware ⭐⭐⭐⭐\n\nBased on what I''ve learned, your project uses JWT tokens for authentication with 24-hour expiration...\n\n## Troubleshooting\n\n**Server won''t start**: Check if already running with `python3 src/server.py status`\n\n**No memories found**: Run initial learning with `python3 src/learner.py initial`\n\n**Cost tracking shows $0**: Metrics file not initialized yet (will populate after server usage)\n\n**Tests failing**: Install dev dependencies with `pip install -r requirements-dev.txt`\n"},"lastSynced":"2026-03-08T02:01:33.227Z","agentAnalysis":{"suitability":{"en":"Ideal for Claude Code Agents requiring persistent project memory and cost-effective knowledge extraction across sessions.","zh":"适用于 Claude Code Agents 需要持久项目内存和跨会话成本有效的知识提取的场景。","ja":"Claude Code Agents が永続的なプロジェクトメモリとセッション間のコスト効率の良い知識抽出を必要とする場合に最適です。","ko":"클라우드 코드 에이전트에서 지속적인 프로젝트 메모리와 세션 간에 비용 효율적인 지식 추출이 필요한 경우에 적합합니다.","es":"Ideal para los agentes de Claude Code que requieren memoria de proyecto persistente y extracción de conocimiento rentable en varias sesiones.","fr":"Idéal pour les agents Claude Code nécessitant une mémoire de projet persistante et une extraction de connaissances rentable à travers les sessions.","de":"Ideal für Claude Code-Agents, die eine persistente Projektmemorie und eine kostengünstige Wissensextraktion über Sitzungen hinweg erfordern.","pt":"Ideal para Agentes de Código Claude que requerem memória de projeto persistente e extração de conhecimento rentável em várias sessões.","ru":"Идеально для агентов Claude Code, требующих постоянной памяти проекта и экономически эффективного извлечения знаний на разных сессиях.","ar":"مثالي للوكلاء Claude Code الذين يتطلبون ذاكرة مشروع مستدامة واستخراج معرفة فعال من حيث التكلفة عبر الجلسات."},"recommendation":{"en":"Empowers agents with durable project memory, leveraging context compression for an average 6.4x compression ratio and real-time API cost savings monitoring through passive learning from git commits and file changes, utilizing protocols for efficient data handling.","zh":"赋予代理人持久的项目内存，利用上下文压缩实现平均 6.4 倍的压缩比，并通过 git 提交和文件更改的被动学习实现实时 API 成本节省监控，利用协议进行高效的数据处理。","ja":"エージェントに耐久性のあるプロジェクトメモリを提供し、コンテキスト圧縮を利用して平均 6.4 倍の圧縮率を実現し、git コミットとファイル変更からの受動的学習を通じてリアルタイムの API コスト節約監視を実現し、プロトコルを使用して効率的なデータ処理を実現します。","ko":"에이전트에 영속적인 프로젝트 메모리를 제공하고, 컨텍스트 압축을 활용하여 평균 6.4배의 압축 비율을 달성하며, 깃 커밋 및 파일 변경의 수동 학습을 통해 실시간 API 비용 절감 모니터링을 구현하고, 프로토콜을 사용하여 효율적인 데이터 처리를 구현합니다.","es":"Habilita a los agentes con una memoria de proyecto duradera, aprovechando la compresión de contexto para una relación de compresión promedio de 6,4x y un seguimiento de ahorros de costos de API en tiempo real a través del aprendizaje pasivo de confirmaciones de git y cambios de archivos, utilizando protocolos para un manejo de datos eficiente.","fr":"Équipe les agents d''une mémoire de projet durable, en exploitant la compression de contexte pour un rapport de compression moyen de 6,4x et une surveillance en temps réel des économies de coûts d''API grâce à un apprentissage passif à partir de validations git et de modifications de fichiers, en utilisant des protocoles pour une gestion de données efficace.","de":"Ermöglicht es den Agenten, eine dauerhafte Projektmemorie zu nutzen, indem es die Kontextkomprimierung für ein durchschnittliches Komprimierungsverhältnis von 6,4x und eine Echtzeitüberwachung der API-Kostenersparnisse durch passives Lernen aus git-Commits und Dateiänderungen nutzt, wobei Protokolle für eine effiziente Datenverwaltung verwendet werden.","pt":"Habilita agentes com memória de projeto durável, aproveitando a compressão de contexto para uma média de 6,4x de razão de compressão e monitoramento de economia de custos da API em tempo real por meio do aprendizado passivo a partir de commits e alterações de arquivos do git, utilizando protocolos para tratamento eficiente de dados.","ru":"Наделяет агентов прочной памятью проекта, используя сжатие контекста для среднего показателя 6,4x сжатия и мониторинга экономии затрат API в реальном времени посредством пассивного обучения на основе коммитов и изменений файлов git, используя протоколы для эффективной обработки данных.","ar":"تمكين الوكلاء بذاكرة مشروع متينة، واستغلال ضغط السياق لتحقيق متوسط 6.4x نسبة الضغط ومراقبة توفير التكاليف في واجهة برمجة التطبيقات في الوقت الفعلي من خلال التعلم السلبي من التعديلات والتحديثات الموجودة في نظام التحكم في الإصدارات git، واستخدام بروتوكولات لمعالجة البيانات بكفاءة."},"useCases":{"en":["Automating knowledge extraction across sessions","Generating insights with 84.3% cost savings","Compressing context for efficient memory usage"],"zh":["跨会话自动化知识提取","使用 84.3% 的成本节约生成见解","压缩上下文以实现高效的内存使用"],"ja":["セッション間の知識抽出の自動化","84.3% のコスト節約を使用したインサイトの生成","コンテキストの圧縮による効率的なメモリ使用"],"ko":["세션 간 지식 추출 자동화","84.3%의 비용 절감을 사용한 인사이트 생성","컨텍스트 압축을 통한 효율적인 메모리 사용"],"es":["Automatizar la extracción de conocimiento a través de sesiones","Generar información con un ahorro de costos del 84,3%","Comprimir el contexto para un uso de memoria eficiente"],"fr":["Automatiser l''extraction de connaissances à travers les sessions","Générer des informations avec une économie de coûts de 84,3%","Compresser le contexte pour une utilisation de mémoire efficace"],"de":["Automatisieren der Wissensextraktion über Sitzungen hinweg","Erzeugen von Erkenntnissen mit 84,3% Kosteneinsparung","Komprimieren des Kontexts für einen effizienten Speicherbedarf"],"pt":["Automatizar a extração de conhecimento em várias sessões","Gerar insights com economia de 84,3%","Comprimir contexto para uso eficiente de memória"],"ru":["Автоматизировать извлечение знаний на разных сессиях","Генерировать идеи с экономией 84,3%","Сжимать контекст для эффективного использования памяти"],"ar":["تحسين استخراج المعرفة عبر الجلسات","توليد رؤى بتوفير 84.3%","ضغط السياق لاستخدام ذاكرة فعال"]},"limitations":{"en":["Requires integration with Claude Code","Dependent on git commits and file changes for passive learning"],"zh":["需要与 Claude Code 集成","依赖于 git 提交和文件更改以进行被动学习"],"ja":["Claude Code との統合が必要","受動的学習のために git コミットとファイル変更に依存"],"ko":["클라우드 코드와의 통합이 필요","수동 학습을 위해 깃 커밋 및 파일 변경에 의존"],"es":["Requiere integración con Claude Code","Dependiente de confirmaciones de git y cambios de archivos para el aprendizaje pasivo"],"fr":["Nécessite une intégration avec Claude Code","Dépendante des validations git et des modifications de fichiers pour l''apprentissage passif"],"de":["Erfordert Integration mit Claude Code","Abhängig von git-Commits und Dateiänderungen für das passive Lernen"],"pt":["Requer integração com Claude Code","Depende de commits e alterações de arquivos do git para aprendizado passivo"],"ru":["Требует интеграции с Claude Code","Зависит от коммитов и изменений файлов git для пассивного обучения"],"ar":["يتطلب دمجًا مع Claude Code","يعتمد على التعديلات والتحديثات الموجودة في نظام التحكم في الإصدارات git للتعلم السلبي"]},"version":4},"contentHash":"eb1f296f783857fd4eab00f38f702446bd3d48df2fe8e10c8d2c9ba166767d39","qualityScore":60}');
