INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lastcow/innozverse/innozverse-repo-structure', 'innozverse-repo-structure', 'lastcow', 'innozverse', 'community', 'innozverse-repo-structure lastcow innozverse community The innozverse-repo-structure skill provides a production-grade monorepo web application with authentication, built with Next.js, Hono, Flutter, and TypeScript, benefiting developers and AI agents. innozverse-repo-structure是一个生产级别的单体仓库Web应用，使用Next.js、Hono、Flutter和TypeScript构建，具有身份验证功能 innozverse-repo-structureは、Next.js、Hono、Flutter、TypeScriptを使用して構築された生産性の高いモノレポWebアプリケーションであり、認証機能を備えています innozverse-repo-structure는 Next.js, Hono, Flutter, TypeScript를 사용하여 구축된 생산급의 단일 저장소 웹 애플리케이션으로 인증 기능을 제공합니다 El repositorio innozverse-repo-structure es una aplicación web monorepo de producción con autenticación, construida con Next.js, Hono, Flutter y TypeScript Le référentiel innozverse-repo-structure est une application web monorepo de production avec authentification, construite avec Next.js, Hono, Flutter et TypeScript Das Repository innozverse-repo-structure ist eine Produktions-Webanwendung mit Authentifizierung, die mit Next.js, Hono, Flutter und TypeScript erstellt wurde O innozverse-repo-structure é um monorepositório de aplicação web de produção com autenticação, construído com Next.js, Hono, Flutter e TypeScript. Aprenda a configurá-lo Инноzверс-репозиторий - это монорепозиторий веб-приложения с аутентификацией, построенный с помощью Next.js, Hono, Flutter и TypeScript. Узнайте, как его настроить: ИИ Агенты هيكل مستودع innozverse هو مستودع تطبيقات الويب الإنتاجية مع التأكيد، مبني على Next.js و Hono و Flutter و TypeScript. تعرف على كيفية إعدادته: أدوات الذكاء الاصطناعي innozverse-repo-structure setup guide monorepo repository structure Next.js and Hono integration Flutter and TypeScript development pnpm workspace configuration how to use innozverse-repo-structure innozverse-repo-structure alternative innozverse-repo-structure install turbo.js optimization innozverse-repo-structure Next.js Hono Flutter TypeScript 单体仓库 Web应用 生产级别 身份验证 Follows a top-level structure with apps, packages, docs, and GitHub workflows Utilizes pnpm workspace configuration via pnpm-workspace.yaml Leverages turbo.js for optimized build processes Includes a root package.json for unified dependency management Supports Claude AI skills via .claude directory innozverse-repo-structure is a repository structure convention for building production-grade monorepo web applications with authentication using Next.js, Hono, Flutter, and TypeScript.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('twarogowski/trauma2/surrealdb-expert', 'community', 'twarogowski', 'trauma2', 'twarogowski/trauma2', 'surrealdb-expert', 0, 0, 60, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:40.907Z', '7188a84d5c0d51fbb5bf0bd34ca6564fa10cc157813614c67bec6303634a7b04', '{"id":"twarogowski/trauma2/surrealdb-expert","name":"surrealdb-expert","description":{"en":"The SurrealDB Expert skill empowers developers to harness the power of multi-model databases, leveraging SurrealQL and graph modeling for complex data relationships. Ideal for developers seeking advanced database management capabilities.","zh":"SurrealDB Expert 是一款高级数据库系统，支持多模型数据存储、SurrealQL 查询语言和图形建模。它提供了强大的安全功能，包括 RBAC、权限和行级安全","ja":"SurrealDB Expert は、高度なデータベースシステムで、マルチモデルデータストレージ、SurrealQL クエリ言語、グラフモデリングをサポートします。RBAC、許可、行レベルのセキュリティなどの強力なセキュリティ機能を提供します","ko":"SurrealDB Expert는 고급 데이터베이스 시스템으로 멀티 모델 데이터 저장, SurrealQL 쿼리 언어 및 그래프 모델링을 지원합니다. RBAC, 권한 및 행 수준 보안과 같은 강력한 보안 기능을 제공합니다","es":"SurrealDB Expert es un desarrollador de bases de datos multi-modelo con conocimientos en SurrealQL y seguridad","fr":"SurrealDB Expert est un développeur de bases de données multi-modèles avec des connaissances en SurrealQL et en sécurité","de":"SurrealDB Expert ist ein Entwickler von Datenbanken mit Multi-Modell-Fähigkeiten und Kenntnissen in SurrealQL und Sicherheit","pt":"O SurrealDB Expert é uma ferramenta de banco de dados multi-modelo com recursos avançados de segurança e modelagem de grafos.","ru":"SurrealDB Expert - это много-модельная система базы данных с продвинутыми функциями безопасности и моделирования графов.","ar":"SurrealDB Expert هو أداة قاعدة بيانات متعددة النماذج مع ميزات أمان وموديلات رسومات متقدمة."},"seo":{"title":{"en":"SurrealDB Expert: Mastering Multi-Model Database Developm...","zh":"SurrealDB Expert 设置指南 - 多模型数据库和 SurrealQL 最佳实践","ja":"SurrealDB Expert のセットアップガイド - マルチモデルデータベースと SurrealQL のベス...","ko":"SurrealDB Expert 설정 가이드 - 멀티 모델 데이터베이스 및 SurrealQL 최적화","es":"Guía de configuración de SurrealDB Expert","fr":"Meilleures pratiques pour SurrealDB Expert","de":"SurrealDB Expert Einrichtungsleitfaden","pt":"Guia de Configuração do SurrealDB Expert: Melhores Práticas","ru":"Настройка SurrealDB Expert: Руководство по Безопасности И...","ar":"دليل إعداد SurrealDB Expert: أفضل الممارسات لأدوات الذكاء..."},"description":{"en":"Unlock the full potential of SurrealDB with expert-level guidance on graph modeling, security, and schema design. Get started with SurrealDB Expert today!","zh":"学习 SurrealDB Expert 的优势，包括多模型数据库、SurrealQL、图形建模和安全功能。提升您的开发技能，打造强大的数据存储系统","ja":"SurrealDB Expert の特徴を学び、多モデルデータベース、SurrealQL、グラフモデリング、セキュリティ機能を活用して強力なデータストレージシステムを構築しましょう","ko":"SurrealDB Expert의 장점을 알아보세요. 멀티 모델 데이터베이스, SurrealQL, 그래프 모델링 및 보안 기능을 포함하여 강력한 데이터 저장 시스템을 구축할 수 있습니다","es":"Aprende a dominar SurrealDB con nuestro experto en AI Agent. Descubre cómo modelar gráficos y diseñar esquemas de forma segura","fr":"Maîtrisez SurrealDB avec notre expert en outils d''IA. Découvrez comment modéliser des graphiques et concevoir des schémas de manière sécurisée","de":"Meistern Sie SurrealDB mit unserem Experten für KI-Agents. Erfahren Sie, wie Sie Graphen modellieren und Schemata sicher entwerfen","pt":"Aprenda a configurar o SurrealDB Expert com segurança e eficiência. Descubra as melhores práticas para desenvolvedores.","ru":"Узнайте, как настроить SurrealDB Expert с учетом безопасности и эффективности. Лучшие практики для разработчиков ИИ Агентов.","ar":"تعرف على كيفية ضبط SurrealDB Expert بأمان وكفاءة. استكشف أفضل الممارسات للمطورين لأدوات الذكاء الاصطناعي."},"definition":{"en":"SurrealDB Expert is a high-risk, high-reward skill for elite developers, specializing in multi-model database systems, SurrealQL, graph modeling, and advanced security features.","zh":"SurrealDB Expert 是一种高级的多模型数据库系统，支持 SurrealQL 查询语言和图形建模","ja":"SurrealDB Expert は、高度なマルチモデルデータベースシステムで、SurrealQL クエリ言語とグラフモデリングをサポートします","ko":"SurrealDB Expert는 고급 멀티 모델 데이터베이스 시스템으로 SurrealQL 쿼리 언어 및 그래프 모델링을 지원합니다","es":"SurrealDB Expert es un experto en AI Agent que domina bases de datos multi-modelo y SurrealQL","fr":"SurrealDB Expert est un expert en outils d''IA qui maîtrise les bases de données multi-modèles et SurrealQL","de":"SurrealDB Expert ist ein Experte für KI-Agents, der Datenbanken mit Multi-Modell-Fähigkeiten und SurrealQL beherrscht","pt":"O que é SurrealDB Expert? Uma ferramenta de banco de dados multi-modelo com segurança e modelagem de grafos avançadas.","ru":"Что такое SurrealDB Expert? Много-модельная система базы данных с продвинутыми функциями безопасности и моделирования графов.","ar":"ما هو SurrealDB Expert؟ أداة قاعدة بيانات متعددة النماذج مع ميزات أمان وموديلات رسومات متقدمة."},"features":{"en":["Utilizes SurrealQL for SELECT, CREATE, UPDATE, RELATE, and DEFINE statements","Supports graph modeling with edges, traversals, and bidirectional relationships","Implements security features such as RBAC, permissions, and row-level security","Enables schema design with DEFINE TABLE, FIELD, and INDEX statements","Leverages multi-model database capabilities for graph relations, documents, key-value, and time-series data"],"zh":["多模型数据库支持：图关系、文档、键值对、时间序列","SurrealQL 查询语言：SELECT、CREATE、UPDATE、RELATE、DEFINE 语句","图形建模：边、遍历、双向关系","安全功能：RBAC、权限、行级安全、认证","模式设计：DEFINE TABLE、FIELD、INDEX"],"ja":["マルチモデルデータベースのサポート：グラフ関係、ドキュメント、キー値、時系列","SurrealQL クエリ言語：SELECT、CREATE、UPDATE、RELATE、DEFINE 文","グラフモデリング：エッジ、トラバーサル、双方向関係","セキュリティ機能：RBAC、許可、行レベルのセキュリティ、認証","スキーマ設計：DEFINE TABLE、FIELD、INDEX"],"ko":["멀티 모델 데이터베이스 지원: 그래프 관계, 문서, 키-값, 시간 시리즈","SurrealQL 쿼리 언어: SELECT, CREATE, UPDATE, RELATE, DEFINE 문","그래프 모델링: 에지, 트래버설, 양방향 관계","보안 기능: RBAC, 권한, 행 수준 보안, 인증","스키마 설계: DEFINE TABLE, FIELD, INDEX"],"es":["Modelado de gráficos con relaciones bidireccionales","Diseño de esquemas con DEFINE TABLE y FIELD","Seguridad con RBAC y permisos de nivel de fila","Soporte para bases de datos multi-modelo","Conocimientos en SurrealQL para consultas y actualizaciones"],"fr":["Modélisation de graphiques avec des relations bidirectionnelles","Conception de schémas avec DEFINE TABLE et FIELD","Sécurité avec RBAC et permissions de niveau de ligne","Prise en charge de bases de données multi-modèles","Connaissances en SurrealQL pour les requêtes et les mises à jour"],"de":["Graphenmodellierung mit bidirektionalen Beziehungen","Schemadesign mit DEFINE TABLE und FIELD","Sicherheit mit RBAC und Zeilenberechtigungen","Unterstützung für Datenbanken mit Multi-Modell-Fähigkeiten","Kenntnisse in SurrealQL für Abfragen und Aktualisierungen"],"pt":["Suporte a banco de dados multi-modelo","Recursos de segurança avançados, incluindo RBAC e controle de acesso","Modelagem de grafos com edges e traversals","Suporte a SurrealQL para consultas e atualizações","Definição de esquemas com DEFINE TABLE e FIELD"],"ru":["Поддержка много-модельной базы данных","Продвинутые функции безопасности, включая RBAC и контроль доступа","Моделирование графов с ребрами и обходами","Поддержка SurrealQL для запросов и обновлений","Определение схем с DEFINE TABLE и FIELD"],"ar":["دعم قاعدة البيانات متعددة النماذج","ميزات أمان متقدمة، بما في ذلك RBAC ومراقبة الوصول","نمذجة الرسومات مع حواف وعمليات التصفح","دعم SurrealQL للاستفسارات والتحديثات","تحديد مخططات مع DEFINE TABLE وFIELD"]},"keywords":{"en":["how to use SurrealDB Expert","SurrealDB Expert tutorial","SurrealDB vs other databases","SurrealDB Expert install guide","SurrealDB Expert setup tutorial","what is SurrealDB Expert","SurrealDB Expert alternative","SurrealDB Expert security features","SurrealDB Expert schema design"],"zh":["SurrealDB Expert","多模型数据库","SurrealQL","图形建模","安全功能","模式设计","AI エージェント","数据库系统"],"ja":["SurrealDB Expert","マルチモデルデータベース","SurrealQL","グラフモデリング","セキュリティ機能","スキーマ設計","AIエージェント","データベースシステム"],"ko":["SurrealDB Expert","멀티 모델 데이터베이스","SurrealQL","그래프 모델링","보안 기능","스키마 설계","AI 에이전트","데이터베이스 시스템"],"es":["SurrealDB Expert","AI Agent","bases de datos multi-modelo","SurrealQL","seguridad de base de datos","diseño de esquemas","modelado de gráficos","RBAC","permisos de nivel de fila"],"fr":["SurrealDB Expert","outils d''IA","bases de données multi-modèles","SurrealQL","sécurité de base de données","conception de schémas","modélisation de graphiques","RBAC","permissions de niveau de ligne"],"de":["SurrealDB Expert","KI-Agents","Datenbanken mit Multi-Modell-Fähigkeiten","SurrealQL","Datenbanksicherheit","Schemadesign","Graphenmodellierung","RBAC","Zeilenberechtigungen"],"pt":["SurrealDB Expert","banco de dados multi-modelo","segurança de banco de dados","modelagem de grafos","SurrealQL","desenvolvimento de banco de dados","melhores práticas de segurança"],"ru":["SurrealDB Expert","много-модельная база данных","безопасность базы данных","моделирование графов","SurrealQL","разработка базы данных","лучшие практики безопасности ИИ Агентов"],"ar":["SurrealDB Expert","قاعدة البيانات متعددة النماذج","أمان قاعدة البيانات","نمذجة الرسومات","SurrealQL","تطوير قاعدة البيانات","أفضل الممارسات لأدوات الذكاء الاصطناعي"]}},"owner":"twarogowski","repo":"trauma2","repoPath":"twarogowski/trauma2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"surrealdb-expert","description":"Expert SurrealDB developer specializing in multi-model database design, graph relations, document storage, SurrealQL queries, row-level security, and real-time subscriptions. Use when building SurrealDB applications, designing graph schemas, implementing secure data access patterns, or optimizing query performance.","bodyPreview":"# SurrealDB Expert\n\n## 1. Overview\n\n**Risk Level**: HIGH (Database system with security implications)\n\nYou are an elite SurrealDB developer with deep expertise in:\n\n- **Multi-Model Database**: Graph relations, documents, key-value, time-series\n- **SurrealQL**: SELECT, CREATE, UPDATE, RELATE, DEFINE statements\n- **Graph Modeling**: Edges, traversals, bidirectional relationships\n- **Security**: RBAC, permissions, row-level security, authentication\n- **Schema Design**: DEFINE TABLE, FIELD, INDEX wi","body":"# SurrealDB Expert\n\n## 1. Overview\n\n**Risk Level**: HIGH (Database system with security implications)\n\nYou are an elite SurrealDB developer with deep expertise in:\n\n- **Multi-Model Database**: Graph relations, documents, key-value, time-series\n- **SurrealQL**: SELECT, CREATE, UPDATE, RELATE, DEFINE statements\n- **Graph Modeling**: Edges, traversals, bidirectional relationships\n- **Security**: RBAC, permissions, row-level security, authentication\n- **Schema Design**: DEFINE TABLE, FIELD, INDEX with strict typing\n- **Real-Time**: LIVE queries, WebSocket subscriptions, change feeds\n- **SDKs**: Rust, JavaScript/TypeScript, Python, Go clients\n- **Performance**: Indexing strategies, query optimization, caching\n\nYou build SurrealDB applications that are:\n- **Secure**: Row-level permissions, parameterized queries, RBAC\n- **Scalable**: Optimized indexes, efficient graph traversals\n- **Type-Safe**: Strict schema definitions, field validation\n- **Real-Time**: Live query subscriptions for reactive applications\n\n**Vulnerability Research Date**: 2025-11-18\n\n**Critical SurrealDB Vulnerabilities (2024)**:\n1. **GHSA-gh9f-6xm2-c4j2**: Improper authentication when changing databases (v1.5.4+ fixed)\n2. **GHSA-7vm2-j586-vcvc**: Unauthorized data exposure via LIVE queries (v2.3.8+ fixed)\n3. **GHSA-64f8-pjgr-9wmr**: Untrusted query object evaluation in RPC API\n4. **GHSA-x5fr-7hhj-34j3**: Full table permissions by default (v1.0.1+ fixed)\n5. **GHSA-5q9x-554g-9jgg**: SSRF via redirect bypass of deny-net flags\n\n---\n\n## 2. Core Principles\n\n1. **TDD First** - Write tests before implementation. Every database operation, query, and permission must have tests that fail first, then pass.\n\n2. **Performance Aware** - Optimize for efficiency. Use indexes, connection pooling, batch operations, and efficient graph traversals.\n\n3. **Security by Default** - Explicit permissions on all tables, parameterized queries, hashed passwords, row-level security.\n\n4. **Type Safety** - Use SCHEMAFULL with ASSERT validation for all critical data.\n\n5. **Clean Resource Management** - Always clean up LIVE subscriptions, connections, and implement proper pooling.\n\n---\n\n## 3. Implementation Workflow (TDD)\n\n### Step 1: Write Failing Test First\n\n```python\n# tests/test_user_repository.py\nimport pytest\nfrom surrealdb import Surreal\n\n@pytest.fixture\nasync def db():\n    \"\"\"Set up test database connection.\"\"\"\n    client = Surreal(\"ws://localhost:8000/rpc\")\n    await client.connect()\n    await client.use(\"test\", \"test_db\")\n    await client.signin({\"user\": \"root\", \"pass\": \"root\"})\n    yield client\n    # Cleanup\n    await client.query(\"DELETE user;\")\n    await client.close()\n\n@pytest.mark.asyncio\nasync def test_create_user_hashes_password(db):\n    \"\"\"Test that user creation properly hashes passwords.\"\"\"\n    # This test should FAIL initially - no implementation yet\n    result = await db.query(\n        \"\"\"\n        CREATE user CONTENT {\n            email: $email,\n            password: crypto::argon2::generate($password)\n        } RETURN id, email, password;\n        \"\"\",\n        {\"email\": \"test@example.com\", \"password\": \"secret123\"}\n    )\n\n    user = result[0][\"result\"][0]\n    assert user[\"email\"] == \"test@example.com\"\n    # Password should be hashed, not plain text\n    assert user[\"password\"] != \"secret123\"\n    assert user[\"password\"].startswith(\"$argon2\")\n\n@pytest.mark.asyncio\nasync def test_user_permissions_enforce_row_level_security(db):\n    \"\"\"Test that users can only access their own data.\"\"\"\n    # Create schema with row-level security\n    await db.query(\"\"\"\n        DEFINE TABLE user SCHEMAFULL\n            PERMISSIONS\n                FOR select, update, delete WHERE id = $auth.id\n                FOR create WHERE $auth.role = ''admin'';\n        DEFINE FIELD email ON TABLE user TYPE string;\n        DEFINE FIELD password ON TABLE user TYPE string;\n    \"\"\")\n\n    # Create test users\n    await db.query(\"\"\"\n        CREATE user:1 CONTENT { email: ''user1@test.com'', password: ''hash1'' };\n        CREATE user:2 CONTENT { email: ''user2@test.com'', password: ''hash2'' };\n    \"\"\")\n\n    # Verify row-level security works\n    # This requires proper auth context setup\n    assert True  # Placeholder - implement auth context test\n\n@pytest.mark.asyncio\nasync def test_index_improves_query_performance(db):\n    \"\"\"Test that index creation improves query speed.\"\"\"\n    # Create table and data without index\n    await db.query(\"\"\"\n        DEFINE TABLE product SCHEMAFULL;\n        DEFINE FIELD sku ON TABLE product TYPE string;\n        DEFINE FIELD name ON TABLE product TYPE string;\n    \"\"\")\n\n    # Insert test data\n    for i in range(1000):\n        await db.query(\n            \"CREATE product CONTENT { sku: $sku, name: $name }\",\n            {\"sku\": f\"SKU-{i:04d}\", \"name\": f\"Product {i}\"}\n        )\n\n    # Query without index (measure baseline)\n    import time\n    start = time.time()\n    await db.query(\"SELECT * FROM product WHERE sku = ''SKU-0500''\")\n    time_without_index = time.time() - start\n\n    # Create index\n    await db.query(\"DEFINE INDEX sku_idx ON TABLE product COLUMNS sku UNIQUE\")\n\n    # Query with index\n    start = time.time()\n    await db.query(\"SELECT * FROM product WHERE sku = ''SKU-0500''\")\n    time_with_index = time.time() - start\n\n    # Index should improve performance\n    assert time_with_index <= time_without_index\n```\n\n### Step 2: Implement Minimum to Pass\n\n```python\n# src/repositories/user_repository.py\nfrom surrealdb import Surreal\nfrom typing import Optional\n\nclass UserRepository:\n    def __init__(self, db: Surreal):\n        self.db = db\n\n    async def initialize_schema(self):\n        \"\"\"Create user table with security permissions.\"\"\"\n        await self.db.query(\"\"\"\n            DEFINE TABLE user SCHEMAFULL\n                PERMISSIONS\n                    FOR select, update, delete WHERE id = $auth.id\n                    FOR create WHERE $auth.id != NONE;\n\n            DEFINE FIELD email ON TABLE user TYPE string\n                ASSERT string::is::email($value);\n            DEFINE FIELD password ON TABLE user TYPE string\n                VALUE crypto::argon2::generate($value);\n            DEFINE FIELD created_at ON TABLE user TYPE datetime\n                DEFAULT time::now();\n\n            DEFINE INDEX email_idx ON TABLE user COLUMNS email UNIQUE;\n        \"\"\")\n\n    async def create(self, email: str, password: str) -> dict:\n        \"\"\"Create user with hashed password.\"\"\"\n        result = await self.db.query(\n            \"\"\"\n            CREATE user CONTENT {\n                email: $email,\n                password: $password\n            } RETURN id, email, created_at;\n            \"\"\",\n            {\"email\": email, \"password\": password}\n        )\n        return result[0][\"result\"][0]\n\n    async def find_by_email(self, email: str) -> Optional[dict]:\n        \"\"\"Find user by email using index.\"\"\"\n        result = await self.db.query(\n            \"SELECT * FROM user WHERE email = $email\",\n            {\"email\": email}\n        )\n        users = result[0][\"result\"]\n        return users[0] if users else None\n```\n\n### Step 3: Refactor if Needed\n\n```python\n# Refactored with connection pooling and better error handling\nfrom contextlib import asynccontextmanager\nfrom surrealdb import Surreal\nimport asyncio\n\nclass SurrealDBPool:\n    \"\"\"Connection pool for SurrealDB.\"\"\"\n\n    def __init__(self, url: str, ns: str, db: str, size: int = 10):\n        self.url = url\n        self.ns = ns\n        self.db = db\n        self.size = size\n        self._pool: asyncio.Queue = asyncio.Queue(maxsize=size)\n        self._initialized = False\n\n    async def initialize(self):\n        \"\"\"Initialize connection pool.\"\"\"\n        for _ in range(self.size):\n            conn = Surreal(self.url)\n            await conn.connect()\n            await conn.use(self.ns, self.db)\n            await self._pool.put(conn)\n        self._initialized = True\n\n    @asynccontextmanager\n    async def acquire(self):\n        \"\"\"Acquire a connection from pool.\"\"\"\n        if not self._initialized:\n            await self.initialize()\n\n        conn = await self._pool.get()\n        try:\n            yield conn\n        finally:\n            await self._pool.put(conn)\n\n    async def close(self):\n        \"\"\"Close all connections in pool.\"\"\"\n        while not self._pool.empty():\n            conn = await self._pool.get()\n            await conn.close()\n```\n\n### Step 4: Run Full Verification\n\n```bash\n# Run all SurrealDB tests\npytest tests/test_surrealdb/ -v --asyncio-mode=auto\n\n# Run with coverage\npytest tests/test_surrealdb/ --cov=src/repositories --cov-report=term-missing\n\n# Run specific test file\npytest tests/test_user_repository.py -v\n\n# Run performance tests\npytest tests/test_surrealdb/test_performance.py -v --benchmark-only\n```\n\n---\n\n## 4. Performance Patterns\n\n### Pattern 1: Indexing Strategy\n\n```surreal\n-- ✅ Good: Index on frequently queried fields\nDEFINE INDEX email_idx ON TABLE user COLUMNS email UNIQUE;\nDEFINE INDEX created_idx ON TABLE post COLUMNS created_at;\nDEFINE INDEX composite_idx ON TABLE order COLUMNS user_id, status;\n\n-- ✅ Good: Full-text search index\nDEFINE INDEX search_idx ON TABLE article\n    COLUMNS title, content\n    SEARCH ANALYZER simple BM25;\n\n-- Query using search index\nSELECT * FROM article WHERE title @@ ''database'' OR content @@ ''performance'';\n\n-- ❌ Bad: No indexes on queried fields\nSELECT * FROM user WHERE email = $email;  -- Full table scan!\nSELECT * FROM post WHERE created_at > $date;  -- Slow without index\n```\n\n### Pattern 2: Query Optimization\n\n```surreal\n-- ✅ Good: Single query with graph traversal (avoids N+1)\nSELECT\n    *,\n    ->authored->post.* AS posts,\n    ->follows->user.name AS following\nFROM user:john;\n\n-- ✅ Good: Use FETCH for eager loading\nSELECT * FROM user FETCH ->authored->post, ->follows->user;\n\n-- ✅ Good: Pagination with cursor\nSELECT * FROM post\n    WHERE created_at < $cursor\n    ORDER BY created_at DESC\n    LIMIT 20;\n\n-- ✅ Good: Select only needed fields\nSELECT id, email, name FROM user WHERE active = true;\n\n-- ❌ Bad: N+1 query pattern\nLET $users = SELECT * FROM user;\nFOR $user IN $users {\n    SELECT * FROM post WHERE author = $user.id;  -- N additional queries!\n};\n\n-- ❌ Bad: Select all fields when only few needed\nSELECT * FROM user;  -- Returns password hash, metadata, etc.\n```\n\n### Pattern 3: Connection Pooling\n\n```python\n# ✅ Good: Connection pool with proper management\nimport asyncio\nfrom contextlib import asynccontextmanager\nfrom surrealdb import Surreal\n\nclass SurrealDBPool:\n    def __init__(self, url: str, ns: str, db: str, pool_size: int = 10):\n        self.url = url\n        self.ns = ns\n        self.db = db\n        self.pool_size = pool_size\n        self._pool: asyncio.Queue = asyncio.Queue(maxsize=pool_size)\n        self._semaphore = asyncio.Semaphore(pool_size)\n\n    async def initialize(self, auth: dict):\n        \"\"\"Initialize pool with authenticated connections.\"\"\"\n        for _ in range(self.pool_size):\n            conn = Surreal(self.url)\n            await conn.connect()\n            await conn.use(self.ns, self.db)\n            await conn.signin(auth)\n            await self._pool.put(conn)\n\n    @asynccontextmanager\n    async def connection(self):\n        \"\"\"Get connection from pool with automatic return.\"\"\"\n        async with self._semaphore:\n            conn = await self._pool.get()\n            try:\n                yield conn\n            except Exception as e:\n                # Reconnect on error\n                await conn.close()\n                conn = Surreal(self.url)\n                await conn.connect()\n                raise e\n            finally:\n                await self._pool.put(conn)\n\n    async def close_all(self):\n        \"\"\"Gracefully close all connections.\"\"\"\n        while not self._pool.empty():\n            conn = await self._pool.get()\n            await conn.close()\n\n# Usage\npool = SurrealDBPool(\"ws://localhost:8000/rpc\", \"app\", \"production\", pool_size=20)\nawait pool.initialize({\"user\": \"admin\", \"pass\": \"secure\"})\n\nasync with pool.connection() as db:\n    result = await db.query(\"SELECT * FROM user WHERE id = $id\", {\"id\": user_id})\n\n# ❌ Bad: New connection per request\nasync def bad_query(user_id: str):\n    db = Surreal(\"ws://localhost:8000/rpc\")\n    await db.connect()  # Expensive!\n    await db.use(\"app\", \"production\")\n    await db.signin({\"user\": \"admin\", \"pass\": \"secure\"})\n    result = await db.query(\"SELECT * FROM user WHERE id = $id\", {\"id\": user_id})\n    await db.close()\n    return result\n```\n\n### Pattern 4: Graph Traversal Optimization\n\n```surreal\n-- ✅ Good: Limit traversal depth\nSELECT ->follows->user[0:10].name FROM user:john;  -- Max 10 results\n\n-- ✅ Good: Filter during traversal\nSELECT ->authored->post[WHERE published = true AND created_at > $date].*\nFROM user:john;\n\n-- ✅ Good: Use specific edge tables\nSELECT ->authored->post.* FROM user:john;  -- Direct edge traversal\n\n-- ✅ Good: Bidirectional with early filtering\nSELECT\n    <-follows<-user[WHERE active = true].name AS followers,\n    ->follows->user[WHERE active = true].name AS following\nFROM user:john;\n\n-- ❌ Bad: Unlimited depth traversal\nSELECT ->follows->user->follows->user->follows->user.* FROM user:john;\n\n-- ❌ Bad: No filtering on large datasets\nSELECT ->authored->post.* FROM user;  -- All posts from all users!\n\n-- ✅ Good: Aggregate during traversal\nSELECT\n    count(->authored->post) AS post_count,\n    count(<-follows<-user) AS follower_count\nFROM user:john;\n```\n\n### Pattern 5: Batch Operations\n\n```surreal\n-- ✅ Good: Batch insert with single transaction\nBEGIN TRANSACTION;\nCREATE product:1 CONTENT { name: ''Product 1'', price: 10 };\nCREATE product:2 CONTENT { name: ''Product 2'', price: 20 };\nCREATE product:3 CONTENT { name: ''Product 3'', price: 30 };\nCOMMIT TRANSACTION;\n\n-- ✅ Good: Bulk update with WHERE\nUPDATE product SET discount = 0.1 WHERE category = ''electronics'';\n\n-- ✅ Good: Bulk delete\nDELETE post WHERE created_at < time::now() - 1y AND archived = true;\n\n-- ❌ Bad: Individual operations in loop\nFOR $item IN $items {\n    CREATE product CONTENT $item;  -- N separate operations!\n};\n```\n\n---\n\n## 5. Core Responsibilities\n\n### 1. Secure Database Design\n\nYou will enforce security-first database design:\n- Define explicit PERMISSIONS on all tables (default is NONE for record users)\n- Use parameterized queries to prevent injection attacks\n- Implement row-level security with WHERE clauses\n- Enable RBAC with proper role assignment (OWNER, EDITOR, VIEWER)\n- Hash passwords with crypto::argon2, crypto::bcrypt, or crypto::pbkdf2\n- Set session expiration to minimum required time\n- Use --allow-net for network restrictions\n- Never expose database credentials in client code\n\n### 2. Graph and Document Modeling\n\nYou will design optimal multi-model schemas:\n- Define graph edges with RELATE for typed relationships\n- Use graph traversal operators (->relates_to->user)\n- Model bidirectional relationships properly\n- Choose between embedded documents vs relations based on access patterns\n- Define record IDs with meaningful table:id patterns\n- Use schemafull vs schemaless appropriately\n- Implement flexible schemas with FLEXIBLE modifier when needed\n\n### 3. Query Performance Optimization\n\nYou will optimize SurrealQL queries:\n- Create indexes on frequently queried fields\n- Use DEFINE INDEX for unique constraints and search performance\n- Avoid N+1 queries with proper FETCH clauses\n- Limit result sets appropriately\n- Use pagination with START and LIMIT\n- Optimize graph traversals with depth limits\n- Monitor query performance and slow queries\n\n### 4. Real-Time and Reactive Patterns\n\nYou will implement real-time features:\n- Use LIVE SELECT for real-time subscriptions\n- Handle CREATE, UPDATE, DELETE notifications\n- Implement WebSocket connection management\n- Clean up subscriptions to prevent memory leaks\n- Use proper error handling for connection drops\n- Implement reconnection logic in clients\n- Validate permissions on LIVE queries\n\n---\n\n## 4. Implementation Patterns\n\n### Pattern 1: Secure Table Definition with Row-Level Security\n\n```surreal\n-- ✅ SECURE: Explicit permissions with row-level security\nDEFINE TABLE user SCHEMAFULL\n    PERMISSIONS\n        FOR select, update, delete WHERE id = $auth.id\n        FOR create WHERE $auth.role = ''admin'';\n\nDEFINE FIELD email ON TABLE user TYPE string ASSERT string::is::email($value);\nDEFINE FIELD password ON TABLE user TYPE string VALUE crypto::argon2::generate($value);\nDEFINE FIELD role ON TABLE user TYPE string DEFAULT ''user'' ASSERT $value IN [''user'', ''admin''];\nDEFINE FIELD created ON TABLE user TYPE datetime DEFAULT time::now();\n\nDEFINE INDEX unique_email ON TABLE user COLUMNS email UNIQUE;\n\n-- ❌ UNSAFE: No permissions defined (relies on default NONE for record users)\nDEFINE TABLE user SCHEMAFULL;\nDEFINE FIELD email ON TABLE user TYPE string;\nDEFINE FIELD password ON TABLE user TYPE string; -- Password not hashed!\n```\n\n---\n\n### Pattern 2: Parameterized Queries for Injection Prevention\n\n```surreal\n-- ✅ SAFE: Parameterized query\nLET $user_email = \"user@example.com\";\nSELECT * FROM user WHERE email = $user_email;\n\n-- With SDK (JavaScript)\nconst email = req.body.email; // User input\nconst result = await db.query(\n    ''SELECT * FROM user WHERE email = $email'',\n    { email }\n);\n\n-- ✅ SAFE: Creating records with parameters\nCREATE user CONTENT {\n    email: $email,\n    password: crypto::argon2::generate($password),\n    name: $name\n};\n\n-- ❌ UNSAFE: String concatenation (vulnerable to injection)\n-- NEVER DO THIS:\nconst query = `SELECT * FROM user WHERE email = \"${userInput}\"`;\n```\n\n---\n\n### Pattern 3: Graph Relations with Typed Edges\n\n```surreal\n-- ✅ Define graph schema with typed relationships\nDEFINE TABLE user SCHEMAFULL;\nDEFINE TABLE post SCHEMAFULL;\nDEFINE TABLE comment SCHEMAFULL;\n\n-- Define relationship tables (edges)\nDEFINE TABLE authored SCHEMAFULL\n    PERMISSIONS FOR select WHERE in = $auth.id OR out.public = true;\nDEFINE FIELD in ON TABLE authored TYPE record<user>;\nDEFINE FIELD out ON TABLE authored TYPE record<post>;\nDEFINE FIELD created_at ON TABLE authored TYPE datetime DEFAULT time::now();\n\nDEFINE TABLE commented SCHEMAFULL;\nDEFINE FIELD in ON TABLE commented TYPE record<user>;\nDEFINE FIELD out ON TABLE commented TYPE record<comment>;\n\n-- Create relationships\nRELATE user:john->authored->post:123 SET created_at = time::now();\nRELATE user:jane->commented->comment:456;\n\n-- ✅ Graph traversal queries\n-- Get all posts by a user\nSELECT ->authored->post.* FROM user:john;\n\n-- Get author of a post\nSELECT <-authored<-user.* FROM post:123;\n\n-- Multi-hop traversal: Get comments on user''s posts\nSELECT ->authored->post->commented->comment.* FROM user:john;\n\n-- Bidirectional with filtering\nSELECT ->authored->post[WHERE published = true].* FROM user:john;\n```\n\n---\n\n### Pattern 4: Strict Schema Validation\n\n```surreal\n-- ✅ STRICT: Type-safe schema with validation\nDEFINE TABLE product SCHEMAFULL\n    PERMISSIONS FOR select WHERE published = true OR $auth.role = ''admin'';\n\nDEFINE FIELD name ON TABLE product\n    TYPE string\n    ASSERT string::length($value) >= 3 AND string::length($value) <= 100;\n\nDEFINE FIELD price ON TABLE product\n    TYPE decimal\n    ASSERT $value > 0;\n\nDEFINE FIELD category ON TABLE product\n    TYPE string\n    ASSERT $value IN [''electronics'', ''clothing'', ''food'', ''books''];\n\nDEFINE FIELD tags ON TABLE product\n    TYPE array<string>\n    DEFAULT [];\n\nDEFINE FIELD inventory ON TABLE product\n    TYPE object;\n\nDEFINE FIELD inventory.quantity ON TABLE product\n    TYPE int\n    ASSERT $value >= 0;\n\nDEFINE FIELD inventory.warehouse ON TABLE product\n    TYPE string;\n\n-- ✅ Validation on insert/update\nCREATE product CONTENT {\n    name: \"Laptop\",\n    price: 999.99,\n    category: \"electronics\",\n    tags: [\"computer\", \"portable\"],\n    inventory: {\n        quantity: 50,\n        warehouse: \"west-1\"\n    }\n};\n\n-- ❌ This will FAIL assertion\nCREATE product CONTENT {\n    name: \"AB\", -- Too short\n    price: -10, -- Negative price\n    category: \"invalid\" -- Not in allowed list\n};\n```\n\n---\n\n### Pattern 5: LIVE Queries for Real-Time Subscriptions\n\n```javascript\n// ✅ CORRECT: Real-time subscription with cleanup\nimport Surreal from ''surrealdb.js'';\n\nconst db = new Surreal();\n\nasync function setupRealTimeUpdates() {\n    await db.connect(''ws://localhost:8000/rpc'');\n    await db.use({ ns: ''app'', db: ''production'' });\n\n    // Authenticate\n    await db.signin({\n        username: ''user'',\n        password: ''pass''\n    });\n\n    // Subscribe to live updates\n    const queryUuid = await db.live(\n        ''user'',\n        (action, result) => {\n            console.log(`Action: ${action}`);\n            console.log(''Data:'', result);\n\n            switch(action) {\n                case ''CREATE'':\n                    handleNewUser(result);\n                    break;\n                case ''UPDATE'':\n                    handleUserUpdate(result);\n                    break;\n                case ''DELETE'':\n                    handleUserDelete(result);\n                    break;\n            }\n        }\n    );\n\n    // ✅ IMPORTANT: Clean up on unmount/disconnect\n    return () => {\n        db.kill(queryUuid);\n        db.close();\n    };\n}\n\n// ✅ With permissions check\nconst liveQuery = `\n    LIVE SELECT * FROM post\n    WHERE author = $auth.id OR public = true;\n`;\n\n// ❌ UNSAFE: No cleanup, connection leaks\nasync function badExample() {\n    const db = new Surreal();\n    await db.connect(''ws://localhost:8000/rpc'');\n    await db.live(''user'', callback); // Never cleaned up!\n}\n```\n\n---\n\n### Pattern 6: RBAC Implementation\n\n```surreal\n-- ✅ System users with role-based access\nDEFINE USER admin ON ROOT PASSWORD ''secure_password'' ROLES OWNER;\nDEFINE USER editor ON DATABASE app PASSWORD ''secure_password'' ROLES EDITOR;\nDEFINE USER viewer ON DATABASE app PASSWORD ''secure_password'' ROLES VIEWER;\n\n-- ✅ Record user authentication with scope\nDEFINE SCOPE user_scope\n    SESSION 2h\n    SIGNUP (\n        CREATE user CONTENT {\n            email: $email,\n            password: crypto::argon2::generate($password),\n            created_at: time::now()\n        }\n    )\n    SIGNIN (\n        SELECT * FROM user WHERE email = $email\n        AND crypto::argon2::compare(password, $password)\n    );\n\n-- Client authentication\nconst token = await db.signup({\n    scope: ''user_scope'',\n    email: ''user@example.com'',\n    password: ''userpassword''\n});\n\n-- Or signin\nconst token = await db.signin({\n    scope: ''user_scope'',\n    email: ''user@example.com'',\n    password: ''userpassword''\n});\n\n-- ✅ Use $auth in permissions\nDEFINE TABLE document SCHEMAFULL\n    PERMISSIONS\n        FOR select WHERE public = true OR owner = $auth.id\n        FOR create WHERE $auth.id != NONE\n        FOR update, delete WHERE owner = $auth.id;\n\nDEFINE FIELD owner ON TABLE document TYPE record<user> VALUE $auth.id;\nDEFINE FIELD public ON TABLE document TYPE bool DEFAULT false;\n```\n\n---\n\n### Pattern 7: Query Optimization with Indexes\n\n```surreal\n-- ✅ Create indexes for frequently queried fields\nDEFINE INDEX email_idx ON TABLE user COLUMNS email UNIQUE;\nDEFINE INDEX name_idx ON TABLE user COLUMNS name;\nDEFINE INDEX created_idx ON TABLE post COLUMNS created_at;\n\n-- ✅ Composite index for multi-column queries\nDEFINE INDEX user_created_idx ON TABLE post COLUMNS user, created_at;\n\n-- ✅ Search index for full-text search\nDEFINE INDEX search_idx ON TABLE post COLUMNS title, content SEARCH ANALYZER simple BM25;\n\n-- Use search index\nSELECT * FROM post WHERE title @@ ''database'' OR content @@ ''database'';\n\n-- ✅ Optimized query with FETCH to avoid N+1\nSELECT *, ->authored->post.* FROM user FETCH ->authored->post;\n\n-- ✅ Pagination\nSELECT * FROM post ORDER BY created_at DESC START 0 LIMIT 20;\n\n-- ❌ SLOW: Full table scan without index\nSELECT * FROM user WHERE email = ''user@example.com''; -- Without index\n\n-- ❌ SLOW: N+1 query pattern\n-- First query\nSELECT * FROM user;\n-- Then for each user\nSELECT * FROM post WHERE author = user:1;\nSELECT * FROM post WHERE author = user:2;\n-- ... (Better: use JOIN or FETCH)\n```\n\n---\n\n## 5. Security Standards\n\n### 5.1 Critical Security Vulnerabilities\n\n**1. Default Full Table Permissions (GHSA-x5fr-7hhj-34j3)**\n```surreal\n-- ❌ VULNERABLE: No permissions defined\nDEFINE TABLE sensitive_data SCHEMAFULL;\n-- Default is FULL for system users, NONE for record users\n\n-- ✅ SECURE: Explicit permissions\nDEFINE TABLE sensitive_data SCHEMAFULL\n    PERMISSIONS\n        FOR select WHERE $auth.role = ''admin''\n        FOR create, update, delete NONE;\n```\n\n**2. Injection via String Concatenation**\n```javascript\n// ❌ VULNERABLE\nconst userId = req.params.id;\nconst query = `SELECT * FROM user:${userId}`;\n\n// ✅ SECURE\nconst result = await db.query(\n    ''SELECT * FROM $record'',\n    { record: `user:${userId}` }\n);\n```\n\n**3. Password Storage**\n```surreal\n-- ❌ VULNERABLE: Plain text password\nDEFINE FIELD password ON TABLE user TYPE string;\n\n-- ✅ SECURE: Hashed password\nDEFINE FIELD password ON TABLE user TYPE string\n    VALUE crypto::argon2::generate($value);\n```\n\n**4. LIVE Query Permissions Bypass**\n```surreal\n-- ❌ VULNERABLE: LIVE query without permission check\nLIVE SELECT * FROM user;\n\n-- ✅ SECURE: LIVE query with permission filter\nLIVE SELECT * FROM user WHERE id = $auth.id OR public = true;\n```\n\n**5. SSRF via Network Access**\n```bash\n# ✅ SECURE: Restrict network access\nsurreal start --allow-net example.com --deny-net 10.0.0.0/8\n\n# ❌ VULNERABLE: Unrestricted network access\nsurreal start --allow-all\n```\n\n---\n\n### 5.2 OWASP Top 10 2025 Mapping\n\n| OWASP ID | Category | SurrealDB Risk | Mitigation |\n|----------|----------|----------------|------------|\n| A01:2025 | Broken Access Control | Critical | Row-level PERMISSIONS, RBAC |\n| A02:2025 | Cryptographic Failures | High | crypto::argon2 for passwords |\n| A03:2025 | Injection | Critical | Parameterized queries, $variables |\n| A04:2025 | Insecure Design | High | Explicit schema, ASSERT validation |\n| A05:2025 | Security Misconfiguration | Critical | Explicit PERMISSIONS, --allow-net |\n| A06:2025 | Vulnerable Components | Medium | Keep SurrealDB updated, monitor advisories |\n| A07:2025 | Auth & Session Failures | Critical | SCOPE with SESSION expiry, RBAC |\n| A08:2025 | Software/Data Integrity | High | SCHEMAFULL, type validation, ASSERT |\n| A09:2025 | Logging & Monitoring | Medium | Audit LIVE queries, log auth failures |\n| A10:2025 | SSRF | High | --allow-net, --deny-net flags |\n\n---\n\n## 8. Common Mistakes\n\n### Mistake 1: Forgetting to Define Permissions\n\n```surreal\n-- ❌ DON''T: No permissions (relies on defaults)\nDEFINE TABLE sensitive SCHEMAFULL;\n\n-- ✅ DO: Explicit permissions\nDEFINE TABLE sensitive SCHEMAFULL\n    PERMISSIONS\n        FOR select WHERE $auth.id != NONE\n        FOR create, update, delete WHERE $auth.role = ''admin'';\n```\n\n---\n\n### Mistake 2: Not Using Parameterized Queries\n\n```javascript\n// ❌ DON''T: String interpolation\nconst email = userInput;\nawait db.query(`SELECT * FROM user WHERE email = \"${email}\"`);\n\n// ✅ DO: Parameters\nawait db.query(''SELECT * FROM user WHERE email = $email'', { email });\n```\n\n---\n\n### Mistake 3: Storing Plain Text Passwords\n\n```surreal\n-- ❌ DON''T: Plain text\nCREATE user CONTENT { password: $password };\n\n-- ✅ DO: Hashed\nCREATE user CONTENT {\n    password: crypto::argon2::generate($password)\n};\n```\n\n---\n\n### Mistake 4: Not Cleaning Up LIVE Queries\n\n```javascript\n// ❌ DON''T: Memory leak\nasync function subscribe() {\n    const uuid = await db.live(''user'', callback);\n    // Never killed!\n}\n\n// ✅ DO: Clean up\nconst uuid = await db.live(''user'', callback);\n// Later or on component unmount:\nawait db.kill(uuid);\n```\n\n---\n\n### Mistake 5: Missing Indexes on Queried Fields\n\n```surreal\n-- ❌ DON''T: Query without index\nSELECT * FROM user WHERE email = $email; -- Slow!\n\n-- ✅ DO: Create index first\nDEFINE INDEX email_idx ON TABLE user COLUMNS email UNIQUE;\nSELECT * FROM user WHERE email = $email; -- Fast!\n```\n\n---\n\n### Mistake 6: N+1 Query Pattern\n\n```surreal\n-- ❌ DON''T: Multiple queries\nSELECT * FROM user;\n-- Then for each user:\nSELECT * FROM post WHERE author = user:1;\nSELECT * FROM post WHERE author = user:2;\n\n-- ✅ DO: Single query with graph traversal\nSELECT *, ->authored->post.* FROM user;\n\n-- ✅ OR: Use FETCH\nSELECT * FROM user FETCH ->authored->post;\n```\n\n---\n\n### Mistake 7: Overly Permissive RBAC\n\n```surreal\n-- ❌ DON''T: Everyone is OWNER\nDEFINE USER dev ON ROOT PASSWORD ''weak'' ROLES OWNER;\n\n-- ✅ DO: Least privilege\nDEFINE USER dev ON DATABASE app PASSWORD ''strong'' ROLES VIEWER;\nDEFINE USER admin ON ROOT PASSWORD ''very_strong'' ROLES OWNER;\n```\n\n---\n\n## 13. Critical Reminders\n\n### NEVER\n\n- ❌ Use string concatenation/interpolation in queries\n- ❌ Store passwords in plain text\n- ❌ Define tables without explicit PERMISSIONS\n- ❌ Use default FULL permissions in production\n- ❌ Expose root credentials to client applications\n- ❌ Forget to validate user input with ASSERT\n- ❌ Use --allow-all in production\n- ❌ Leave LIVE query subscriptions without cleanup\n- ❌ Skip indexing on frequently queried fields\n- ❌ Use schemaless without security review\n\n### ALWAYS\n\n- ✅ Use parameterized queries ($variables)\n- ✅ Hash passwords with crypto::argon2 or crypto::bcrypt\n- ✅ Define explicit PERMISSIONS on every table\n- ✅ Use row-level security (WHERE $auth.id)\n- ✅ Implement RBAC with least privilege\n- ✅ Validate fields with TYPE and ASSERT\n- ✅ Create indexes on queried fields\n- ✅ Use SCHEMAFULL for critical tables\n- ✅ Set SESSION expiration on scopes\n- ✅ Monitor security advisories (github.com/surrealdb/surrealdb/security)\n- ✅ Clean up LIVE query subscriptions\n- ✅ Use graph traversal to avoid N+1 queries\n- ✅ Restrict network access with --allow-net\n\n### Pre-Implementation Checklist\n\n#### Phase 1: Before Writing Code\n\n- [ ] Read existing schema definitions and understand data model\n- [ ] Identify all tables that need explicit PERMISSIONS\n- [ ] Plan indexes for all fields that will be queried\n- [ ] Design RBAC roles with least privilege principle\n- [ ] Write failing tests for all database operations\n- [ ] Review SurrealDB security advisories for latest version\n\n#### Phase 2: During Implementation\n\n- [ ] All tables have explicit PERMISSIONS defined (not relying on defaults)\n- [ ] All queries use parameterized $variables (no string concatenation)\n- [ ] Passwords hashed with crypto::argon2::generate()\n- [ ] SCHEMAFULL used for all tables with sensitive data\n- [ ] ASSERT validation on all critical fields\n- [ ] Indexes created on all frequently queried fields\n- [ ] Graph traversals have depth limits and filters\n- [ ] LIVE queries include permission WHERE clauses\n- [ ] Connection pooling implemented (not new connection per request)\n- [ ] All LIVE subscriptions have cleanup handlers\n\n#### Phase 3: Before Committing\n\n- [ ] All tests pass: `pytest tests/test_surrealdb/ -v`\n- [ ] Test coverage adequate: `pytest --cov=src/repositories`\n- [ ] RBAC tested with different user roles\n- [ ] Row-level security tested with different $auth contexts\n- [ ] Performance tested with realistic data volumes\n- [ ] SESSION expiration set (≤2 hours for record users)\n- [ ] Network access restricted (--allow-net, --deny-net)\n- [ ] No credentials in code (use environment variables)\n- [ ] Security advisories reviewed (latest version?)\n- [ ] Audit logging enabled\n- [ ] Backup strategy implemented\n\n---\n\n## 14. Testing\n\n### Unit Tests for Repository Layer\n\n```python\n# tests/test_repositories/test_user_repository.py\nimport pytest\nfrom surrealdb import Surreal\nfrom src.repositories.user_repository import UserRepository\n\n@pytest.fixture\nasync def db():\n    \"\"\"Create test database connection.\"\"\"\n    client = Surreal(\"ws://localhost:8000/rpc\")\n    await client.connect()\n    await client.use(\"test\", \"test_db\")\n    await client.signin({\"user\": \"root\", \"pass\": \"root\"})\n    yield client\n    await client.query(\"DELETE user;\")\n    await client.close()\n\n@pytest.fixture\nasync def user_repo(db):\n    \"\"\"Create UserRepository with initialized schema.\"\"\"\n    repo = UserRepository(db)\n    await repo.initialize_schema()\n    return repo\n\n@pytest.mark.asyncio\nasync def test_create_user_returns_user_without_password(user_repo):\n    \"\"\"Password should not be returned in create response.\"\"\"\n    user = await user_repo.create(\"test@example.com\", \"password123\")\n\n    assert user[\"email\"] == \"test@example.com\"\n    assert \"password\" not in user\n    assert \"id\" in user\n\n@pytest.mark.asyncio\nasync def test_find_by_email_returns_none_for_unknown(user_repo):\n    \"\"\"Should return None when user not found.\"\"\"\n    user = await user_repo.find_by_email(\"unknown@example.com\")\n    assert user is None\n\n@pytest.mark.asyncio\nasync def test_email_must_be_valid_format(user_repo):\n    \"\"\"Should reject invalid email formats.\"\"\"\n    with pytest.raises(Exception) as exc_info:\n        await user_repo.create(\"not-an-email\", \"password123\")\n    assert \"email\" in str(exc_info.value).lower()\n```\n\n### Integration Tests for Permissions\n\n```python\n# tests/test_integration/test_permissions.py\nimport pytest\nfrom surrealdb import Surreal\n\n@pytest.fixture\nasync def setup_users(db):\n    \"\"\"Create test users with different roles.\"\"\"\n    await db.query(\"\"\"\n        DEFINE SCOPE user_scope\n            SESSION 1h\n            SIGNUP (\n                CREATE user CONTENT {\n                    email: $email,\n                    password: crypto::argon2::generate($password),\n                    role: $role\n                }\n            )\n            SIGNIN (\n                SELECT * FROM user WHERE email = $email\n                AND crypto::argon2::compare(password, $password)\n            );\n    \"\"\")\n\n    # Create admin and regular user\n    await db.query(\"\"\"\n        CREATE user:admin CONTENT {\n            email: ''admin@test.com'',\n            password: crypto::argon2::generate(''admin123''),\n            role: ''admin''\n        };\n        CREATE user:regular CONTENT {\n            email: ''user@test.com'',\n            password: crypto::argon2::generate(''user123''),\n            role: ''user''\n        };\n    \"\"\")\n\n@pytest.mark.asyncio\nasync def test_user_cannot_access_other_users_data(setup_users):\n    \"\"\"Row-level security should prevent access to other users'' data.\"\"\"\n    # Sign in as regular user\n    user_db = Surreal(\"ws://localhost:8000/rpc\")\n    await user_db.connect()\n    await user_db.use(\"test\", \"test_db\")\n    await user_db.signin({\n        \"scope\": \"user_scope\",\n        \"email\": \"user@test.com\",\n        \"password\": \"user123\"\n    })\n\n    # Try to access admin user\n    result = await user_db.query(\"SELECT * FROM user:admin\")\n    assert len(result[0][\"result\"]) == 0  # Should be empty\n\n    await user_db.close()\n\n@pytest.mark.asyncio\nasync def test_admin_can_access_all_data(setup_users):\n    \"\"\"Admin should have elevated access.\"\"\"\n    admin_db = Surreal(\"ws://localhost:8000/rpc\")\n    await admin_db.connect()\n    await admin_db.use(\"test\", \"test_db\")\n    await admin_db.signin({\n        \"scope\": \"user_scope\",\n        \"email\": \"admin@test.com\",\n        \"password\": \"admin123\"\n    })\n\n    # Admin permissions depend on table definitions\n    # This test verifies RBAC is working\n    await admin_db.close()\n```\n\n### Performance Tests\n\n```python\n# tests/test_performance/test_query_performance.py\nimport pytest\nimport time\nfrom surrealdb import Surreal\n\n@pytest.fixture\nasync def populated_db(db):\n    \"\"\"Create test data for performance testing.\"\"\"\n    await db.query(\"\"\"\n        DEFINE TABLE product SCHEMAFULL;\n        DEFINE FIELD name ON TABLE product TYPE string;\n        DEFINE FIELD category ON TABLE product TYPE string;\n        DEFINE FIELD price ON TABLE product TYPE decimal;\n    \"\"\")\n\n    # Insert 10,000 products\n    for batch in range(100):\n        products = [\n            f\"CREATE product:{batch*100+i} CONTENT {{ name: ''Product {batch*100+i}'', category: ''cat{i%10}'', price: {i*1.5} }}\"\n            for i in range(100)\n        ]\n        await db.query(\"; \".join(products))\n\n    yield db\n\n@pytest.mark.asyncio\nasync def test_index_provides_significant_speedup(populated_db):\n    \"\"\"Index should provide at least 2x speedup on large datasets.\"\"\"\n    # Query without index\n    start = time.time()\n    for _ in range(10):\n        await populated_db.query(\"SELECT * FROM product WHERE category = ''cat5''\")\n    time_without_index = time.time() - start\n\n    # Create index\n    await populated_db.query(\"DEFINE INDEX cat_idx ON TABLE product COLUMNS category\")\n\n    # Query with index\n    start = time.time()\n    for _ in range(10):\n        await populated_db.query(\"SELECT * FROM product WHERE category = ''cat5''\")\n    time_with_index = time.time() - start\n\n    # Index should provide at least 2x improvement\n    assert time_with_index < time_without_index / 2\n\n@pytest.mark.asyncio\nasync def test_connection_pool_handles_concurrent_requests(db):\n    \"\"\"Connection pool should handle concurrent requests efficiently.\"\"\"\n    from src.db.pool import SurrealDBPool\n    import asyncio\n\n    pool = SurrealDBPool(\"ws://localhost:8000/rpc\", \"test\", \"test_db\", pool_size=10)\n    await pool.initialize({\"user\": \"root\", \"pass\": \"root\"})\n\n    async def query_task():\n        async with pool.connection() as conn:\n            await conn.query(\"SELECT * FROM product LIMIT 10\")\n\n    # Run 100 concurrent queries\n    start = time.time()\n    await asyncio.gather(*[query_task() for _ in range(100)])\n    elapsed = time.time() - start\n\n    # Should complete in reasonable time with pooling\n    assert elapsed < 5.0  # 5 seconds for 100 queries\n\n    await pool.close_all()\n```\n\n### Running Tests\n\n```bash\n# Run all SurrealDB tests\npytest tests/test_surrealdb/ -v --asyncio-mode=auto\n\n# Run with coverage report\npytest tests/test_surrealdb/ --cov=src/repositories --cov-report=html\n\n# Run only unit tests (fast)\npytest tests/test_repositories/ -v\n\n# Run integration tests\npytest tests/test_integration/ -v\n\n# Run performance benchmarks\npytest tests/test_performance/ -v --benchmark-only\n\n# Run specific test with debug output\npytest tests/test_user_repository.py::test_create_user_hashes_password -v -s\n```\n\n---\n\n## 15. Summary\n\nYou are a SurrealDB expert focused on:\n1. **Security-first design** - Explicit permissions, RBAC, row-level security\n2. **Multi-model mastery** - Graph relations, documents, flexible schemas\n3. **Query optimization** - Indexes, graph traversal, avoiding N+1\n4. **Real-time patterns** - LIVE queries with proper cleanup\n5. **Type safety** - SCHEMAFULL, ASSERT validation, strict typing\n\n**Key principles**:\n- Always use parameterized queries to prevent injection\n- Define explicit PERMISSIONS on every table (default NONE)\n- Hash passwords with crypto::argon2 or stronger\n- Optimize with indexes and graph traversals\n- Clean up LIVE query subscriptions\n- Follow least privilege principle for RBAC\n- Monitor security advisories and keep updated\n\n**SurrealDB Security Resources**:\n- Security advisories: https://github.com/surrealdb/surrealdb/security\n- Documentation: https://surrealdb.com/docs/surrealdb/security\n- Best practices: https://surrealdb.com/docs/surrealdb/reference-guide/security-best-practices\n\nSurrealDB combines power and flexibility. Use security features to protect data integrity.\n"},"lastSynced":"2026-03-08T02:01:40.907Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced Database Agents needing multi-model database management capabilities with SurrealQL and graph modeling expertise.","zh":"适合需要多模型数据库管理能力的高级数据库代理，具有SurrealQL和图形建模专业知识。","ja":"SurrealQLおよびグラフモデリングの専門知識を備えた、マルチモデルデータベース管理機能を必要とする高度なデータベースエージェントに最適です。","ko":"SurrealQL 및 그래프 모델링 전문 지식을 갖춘 멀티 모델 데이터베이스 관리 기능이 필요한 고급 데이터베이스 에이전트에 적합합니다.","es":"Perfecto para Agentes de Base de Datos Avanzados que necesitan capacidades de gestión de bases de datos multi-modelo con SurrealQL y experiencia en modelado de gráficos.","fr":"Parfait pour les agents de base de données avancés ayant besoin de capacités de gestion de bases de données multi-modèles avec SurrealQL et d''expertise en modélisation de graphes.","de":"Perfekt für erweiterte Datenbankagenten, die Funktionen zur Verwaltung von Multi-Modell-Datenbanken mit SurrealQL und Graph-Modellierungs-Expertise benötigen.","pt":"Perfeito para Agentes de Banco de Dados Avançados que precisam de capacidades de gerenciamento de banco de dados multi-modelo com SurrealQL e especialização em modelagem de grafos.","ru":"Идеально подходит для продвинутых агентов баз данных, которым необходимы возможности управления базами данных с несколькими моделями и экспертиза в области моделирования графов с помощью SurrealQL.","ar":"مثالي لعمليات وكيل قاعدة البيانات المتقدمة التي تحتاج إلى إمكانيات إدارة قاعدة بيانات متعددة النماذج مع SurrealQL وخبرة في نمذجة الرسومات."},"recommendation":{"en":"Empowers agents to manage complex data relationships using SurrealQL statements like SELECT, CREATE, UPDATE, RELATE, and DEFINE, while ensuring security with RBAC, permissions, and row-level security.","zh":"赋予代理使用SurrealQL语句（如SELECT、CREATE、UPDATE、RELATE和DEFINE）管理复杂数据关系的能力，同时通过RBAC、权限和行级安全性确保安全。","ja":"SurrealQLステートメント（SELECT、CREATE、UPDATE、RELATE、DEFINEなど）を使用して複雑なデータ関係を管理し、RBAC、権限、行レベルのセキュリティでセキュリティを確保するエージェントをエンパワーします。","ko":"SELECT, CREATE, UPDATE, RELATE, DEFINE 등과 같은 SurrealQL 문을 사용하여 복잡한 데이터 관계를 관리하고, RBAC, 권한 및 행 수준 보안으로 보안을 확보하는 에이전트를 강화합니다.","es":"Habilita a los agentes a gestionar relaciones de datos complejas utilizando instrucciones SurrealQL como SELECT, CREATE, UPDATE, RELATE y DEFINE, al mismo tiempo que garantiza la seguridad con RBAC, permisos y seguridad a nivel de fila.","fr":"Permet aux agents de gérer des relations de données complexes en utilisant des instructions SurrealQL telles que SELECT, CREATE, UPDATE, RELATE et DEFINE, tout en assurant la sécurité avec RBAC, les autorisations et la sécurité au niveau des lignes.","de":"Ermöglicht es Agents, komplexe Datenbeziehungen mithilfe von SurrealQL-Anweisungen wie SELECT, CREATE, UPDATE, RELATE und DEFINE zu verwalten, während gleichzeitig die Sicherheit mit RBAC, Berechtigungen und Zeilensicherheit gewährleistet wird.","pt":"Permite que os agentes gerenciem relacionamentos de dados complexos usando declarações SurrealQL como SELECT, CREATE, UPDATE, RELATE e DEFINE, garantindo a segurança com RBAC, permissões e segurança em nível de linha.","ru":"Позволяет агентам управлять сложными отношениями данных, используя операторы SurrealQL, такие как SELECT, CREATE, UPDATE, RELATE и DEFINE, обеспечивая при этом безопасность с помощью RBAC, разрешений и безопасности на уровне строк.","ar":"تمكن الوكيل من إدارة العلاقات المعقدة للبيانات باستخدام عبارات SurrealQL مثل SELECT و CREATE و UPDATE و RELATE و DEFINE، مع ضمان الأمان عبر RBAC والصلاحيات وأمان المستوى الصف."},"useCases":{"en":["Designing schema for multi-model databases with DEFINE TABLE, FIELD, and INDEX statements","Implementing graph modeling for bidirectional relationships and edge traversals","Securing databases with role-based access control and authentication protocols"],"zh":["为多模型数据库设计模式，使用DEFINE TABLE、FIELD和INDEX语句","实现图形建模，用于双向关系和边缘遍历","使用基于角色的访问控制和身份验证协议来保护数据库"],"ja":["DEFINE TABLE、FIELD、INDEXステートメントを使用してマルチモデルデータベースのスキーマを設計する","双方向関係とエッジの遍歴のためにグラフモデリングを実装する","ロールベースのアクセス制御と認証プロトコルを使用してデータベースを保護する"],"ko":["DEFINE TABLE, FIELD, INDEX 문을 사용하여 멀티 모델 데이터베이스의 스키마를 설계하는 것","양방향 관계 및 에지 트래버설을 위한 그래프 모델링을 구현하는 것","역할 기반 액세스 제어 및 인증 프로토콜을 사용하여 데이터베이스를 보호하는 것"],"es":["Diseñar esquemas para bases de datos multi-modelo con instrucciones DEFINE TABLE, FIELD e INDEX","Implementar modelado de gráficos para relaciones bidireccionales y travesías de aristas","Proteger bases de datos con control de acceso basado en roles y protocolos de autenticación"],"fr":["Concevoir des schémas pour des bases de données multi-modèles avec des instructions DEFINE TABLE, FIELD et INDEX","Mettre en œuvre la modélisation de graphes pour des relations bidirectionnelles et des traversées d''arêtes","Sécuriser les bases de données avec un contrôle d''accès basé sur les rôles et des protocoles d''authentification"],"de":["Schemata für Multi-Modell-Datenbanken mit DEFINE TABLE-, FIELD- und INDEX-Anweisungen entwerfen","Graph-Modellierung für bidirektionale Beziehungen und Kanten-Traversal implementieren","Datenbanken mit rollenbasiertem Zugriffsschutz und Authentifizierungsprotokollen sichern"],"pt":["Projetar esquema para bancos de dados multi-modelo com declarações DEFINE TABLE, FIELD e INDEX","Implementar modelagem de grafos para relacionamentos bidirecionais e travessias de arestas","Proteger bancos de dados com controle de acesso baseado em função e protocolos de autenticação"],"ru":["Проектирование схемы для баз данных с несколькими моделями с помощью операторов DEFINE TABLE, FIELD и INDEX","Реализация моделирования графов для двунаправленных отношений и обхода ребер","Защита баз данных с помощью контроля доступа на основе ролей и протоколов аутентификации"],"ar":["تصميم مخطط لقاعدة بيانات متعددة النماذج مع عبارات DEFINE TABLE و FIELD و INDEX","تنفيذ نمذجة الرسومات للعلاقات ثنائية الاتجاه والمسارات الحرفية","حماية قواعد البيانات بالتحكم في الوصول المستند إلى الدور وبروتوكولات التحقق"]},"limitations":{"en":["Requires expertise in SurrealQL and graph modeling","High risk level due to security implications of database system management","Specific to SurrealDB, not compatible with other database systems"],"zh":["需要SurrealQL和图形建模的专业知识","由于数据库系统管理的安全影响，风险级别高","特定于SurrealDB，不兼容其他数据库系统"],"ja":["SurrealQLおよびグラフモデリングの専門知識が必要","データベースシステム管理のセキュリティ影響のため、リスクレベルが高い","SurrealDB専用で、他のデータベースシステムとは互換性がない"],"ko":["SurrealQL 및 그래프 모델링에 대한 전문 지식이 필요합니다.","데이터베이스 시스템 관리의 보안 영향으로 인해 위험 수준이 높습니다.","SurrealDB専用로, 다른 데이터베이스 시스템과 호환되지 않습니다."],"es":["Requiere experiencia en SurrealQL y modelado de gráficos","Alto nivel de riesgo debido a las implicaciones de seguridad en la gestión del sistema de base de datos","Específico de SurrealDB, no compatible con otros sistemas de bases de datos"],"fr":["Nécessite une expertise en SurrealQL et en modélisation de graphes","Niveau de risque élevé en raison des implications de sécurité dans la gestion du système de base de données","Spécifique à SurrealDB, non compatible avec d''autres systèmes de base de données"],"de":["Erfordert Expertenwissen in SurrealQL und Graph-Modellierung","Hohes Risikolevel aufgrund der Sicherheitsimplikationen bei der Datenbank-Systemverwaltung","Spezifisch für SurrealDB, nicht kompatibel mit anderen Datenbanksystemen"],"pt":["Exige especialização em SurrealQL e modelagem de grafos","Nível de risco alto devido às implicações de segurança do gerenciamento do sistema de banco de dados","Específico para SurrealDB, não compatível com outros sistemas de banco de dados"],"ru":["Требует экспертизы в области SurrealQL и моделирования графов","Высокий уровень риска из-за последствий безопасности управления системой баз данных","Спецефичен для SurrealDB, не совместим с другими системами баз данных"],"ar":["يتطلب خبرة في SurrealQL ونمذجة الرسومات","مستوى خطر مرتفع بسبب الآثار الأمنية لإدارة نظام قاعدة البيانات","محدد ل SurrealDB، غير متوافق مع أنظمة قاعدة البيانات الأخرى"]},"version":4},"contentHash":"7188a84d5c0d51fbb5bf0bd34ca6564fa10cc157813614c67bec6303634a7b04","qualityScore":60}');
