INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('twarogowski/trauma2/surrealdb-expert', 'surrealdb-expert', 'twarogowski', 'trauma2', 'community', 'surrealdb-expert twarogowski trauma2 community The SurrealDB Expert skill empowers developers to harness the power of multi-model databases, leveraging SurrealQL and graph modeling for complex data relationships. Ideal for developers seeking advanced database management capabilities. SurrealDB Expert 是一款高级数据库系统，支持多模型数据存储、SurrealQL 查询语言和图形建模。它提供了强大的安全功能，包括 RBAC、权限和行级安全 SurrealDB Expert は、高度なデータベースシステムで、マルチモデルデータストレージ、SurrealQL クエリ言語、グラフモデリングをサポートします。RBAC、許可、行レベルのセキュリティなどの強力なセキュリティ機能を提供します SurrealDB Expert는 고급 데이터베이스 시스템으로 멀티 모델 데이터 저장, SurrealQL 쿼리 언어 및 그래프 모델링을 지원합니다. RBAC, 권한 및 행 수준 보안과 같은 강력한 보안 기능을 제공합니다 SurrealDB Expert es un desarrollador de bases de datos multi-modelo con conocimientos en SurrealQL y seguridad SurrealDB Expert est un développeur de bases de données multi-modèles avec des connaissances en SurrealQL et en sécurité SurrealDB Expert ist ein Entwickler von Datenbanken mit Multi-Modell-Fähigkeiten und Kenntnissen in SurrealQL und Sicherheit O SurrealDB Expert é uma ferramenta de banco de dados multi-modelo com recursos avançados de segurança e modelagem de grafos. SurrealDB Expert - это много-модельная система базы данных с продвинутыми функциями безопасности и моделирования графов. SurrealDB Expert هو أداة قاعدة بيانات متعددة النماذج مع ميزات أمان وموديلات رسومات متقدمة. how to use SurrealDB Expert SurrealDB Expert tutorial SurrealDB vs other databases SurrealDB Expert install guide SurrealDB Expert setup tutorial what is SurrealDB Expert SurrealDB Expert alternative SurrealDB Expert security features SurrealDB Expert schema design SurrealDB Expert 多模型数据库 SurrealQL 图形建模 安全功能 模式设计 AI エージェント 数据库系统 Utilizes SurrealQL for SELECT, CREATE, UPDATE, RELATE, and DEFINE statements Supports graph modeling with edges, traversals, and bidirectional relationships Implements security features such as RBAC, permissions, and row-level security Enables schema design with DEFINE TABLE, FIELD, and INDEX statements Leverages multi-model database capabilities for graph relations, documents, key-value, and time-series data SurrealDB Expert is a high-risk, high-reward skill for elite developers, specializing in multi-model database systems, SurrealQL, graph modeling, and advanced security features.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mthangtr/groaly/issue-resolution', 'community', 'mthangtr', 'groaly', 'mthangtr/groaly', 'issue-resolution', 0, 0, 60, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:41.440Z', '14297f6531dd397ffab169c75a71c1274a7b012f4b7188116a5eb3ead50b4c52', '{"id":"mthangtr/groaly/issue-resolution","name":"issue-resolution","description":{"en":"The issue-resolution skill systematically resolves issues through iterative diagnosis and verified fixes, benefiting developers and teams. It utilizes Next.js, Supabase, and Claude AI for balanced task management.","zh":"利用Next.js、Supabase和Claude AI的AI驱动生产力伴侣，通过迭代诊断和验证的修复来解决问题","ja":"Next.js、Supabase、Claude AIを使用したAIパワーの生産性コンパニオンで、問題を解決","ko":"Next.js, Supabase, Claude AI로 구축된 AI 기반 생산성 동반자로 문제를 체계적으로 해결","es":"La resolución de problemas con AI es una herramienta de productividad que utiliza Next.js, Supabase y Claude AI para transformar notas caóticas en tareas actionables","fr":"La résolution de problèmes avec l''IA est un outil de productivité qui utilise Next.js, Supabase et Claude AI pour transformer des notes chaotiques en tâches actionables","de":"Die Problemlösung mit KI ist ein Produktivitätstool, das Next.js, Supabase und Claude AI verwendet, um chaotische Notizen in handhabbare Aufgaben umzuwandeln","pt":"O Issue Resolution é um companion de produtividade baseado em IA que transforma notas caóticas em tarefas balanceadas e ações concretas.","ru":"Issue Resolution - это ИИ Агент, который превращает хаотичные заметки в сбалансированные и действенные задачи.","ar":"Issue Resolution هو رفيق إنتاجية معتمد على الذكاء الاصطناعي يتحول الملاحظات المضطربة إلى مهام متوازنة وفعاليات ملموسة."},"seo":{"title":{"en":"issue-resolution: Setup Guide for AI Agents | AI Agent Skill","zh":"Issue Resolution Setup Guide - AIエージェント","ja":"AIエージェントによるIssue Resolutionベストプラクティス","ko":"이슈 해결 Setup Guide - AI 에이전트","es":"Guía de Configuración para Resolución de Problemas con AI","fr":"Guide de Mise en Place pour la Résolution de Problèmes av...","de":"Einrichtungsleitfaden für Problemlösung mit KI","pt":"Guia de Resolução de Problemas com IA: Técnico","ru":"Руководство по решению проблем с ИИ Агентами","ar":"دليل حل المشكلات باستخدام وكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock efficient issue resolution with our AI-powered pipeline. Learn how to transform chaotic notes into actionable tasks with Next.js, Supabase, and Claude...","zh":"使用Next.js、Supabase和Claude AI的AI驱动生产力伴侣，系统地解决问题","ja":"Next.js、Supabase、Claude AIを使用したAIパワーの生産性コンパニオンで問題を体系的に解決","ko":"Next.js, Supabase, Claude AI로 구축된 AI 기반 생산성 동반자로 문제를 체계적으로 해결","es":"Aprende a configurar y utilizar la resolución de problemas con AI para mejorar la productividad y resolver problemas de manera efectiva","fr":"Découvrez comment configurer et utiliser la résolution de problèmes avec l''IA pour améliorer la productivité et résoudre les problèmes de manière efficace","de":"Erfahren Sie, wie Sie die Problemlösung mit KI konfigurieren und nutzen können, um die Produktivität zu verbessern und Probleme effektiv zu lösen","pt":"Aprenda a resolver problemas de forma eficaz com o companion de produtividade baseado em IA, construído com Next.js, Supabase e Claude AI.","ru":"Узнайте, как эффективно решать проблемы с помощью ИИ Агентов, построенных на основе Next.js, Supabase и Claude AI.","ar":"تعلم كيفية حل المشكلات بفعالية باستخدام رفيق الإنتاجية المعتمد على الذكاء الاصطناعي، مبني على Next.js و Supabase و Claude AI."},"definition":{"en":"issue-resolution is a technical process that transforms chaotic notes into balanced, actionable tasks across multiple life goals using an AI-powered pipeline.","zh":"Issue Resolution是利用AI驱动的生产力伴侣来系统地解决问题的过程","ja":"Issue Resolutionは、AIパワーの生産性コンパニオンを使用して問題を体系的に解決するプロセス","ko":"이슈 해결은 AI 기반 생산성 동반자를 사용하여 문제를 체계적으로 해결하는 과정","es":"La resolución de problemas con AI es un proceso de diagnóstico y resolución de problemas que utiliza técnicas de inteligencia artificial","fr":"La résolution de problèmes avec l''IA est un processus de diagnostic et de résolution de problèmes qui utilise des techniques d''intelligence artificielle","de":"Die Problemlösung mit KI ist ein Prozess der Fehlerdiagnose und -behebung, der Techniken der künstlichen Intelligenz verwendet","pt":"O que é Issue Resolution? É um sistema de resolução de problemas baseado em IA que utiliza um pipeline de diagnóstico e reparo.","ru":"Что такое Issue Resolution? Это система решения проблем на основе ИИ, использующая конвейер диагностики и ремонта.","ar":"ما هو Issue Resolution؟ هو نظام حل مشكلات يعتمد على الذكاء الاصطناعي يستخدم трубة تشخيص وإصلاح."},"features":{"en":["Utilizes Next.js for robust frontend development","Leverages Supabase for scalable database management","Employs Claude AI for intelligent task analysis","Implements an iterative issue resolution pipeline","Includes phases for triage, reproduction, and root cause analysis","Supports verified fixes and iterative loops for refinement"],"zh":["使用Next.js构建","集成了Supabase和Claude AI","支持迭代诊断和验证的修复","系统地解决问题","支持多个生命周期目标"],"ja":["Next.jsで構築","SupabaseとClaude AIを統合","反復診断と検証による修正をサポート","問題を体系的に解決","複数のライフサイクル目標をサポート"],"ko":["Next.js로 구축","Supabase와 Claude AI 통합","반복적 진단 및 검증을 통한 수정 지원","문제를 체계적으로 해결","여러 라이프사이클 목표 지원"],"es":["Utiliza Next.js para la creación de interfaces de usuario","Integra Supabase para la gestión de datos","Incorpora Claude AI para el análisis y resolución de problemas","Permite la iteración y el ajuste en el proceso de resolución de problemas","Ofrece una visión general del proceso de resolución de problemas a través de una pipeline de resolución de problemas"],"fr":["Utilise Next.js pour la création d''interfaces utilisateur","Intègre Supabase pour la gestion de données","Intègre Claude AI pour l''analyse et la résolution de problèmes","Permet l''itération et l''ajustement dans le processus de résolution de problèmes","Offre une vue d''ensemble du processus de résolution de problèmes à travers une pipeline de résolution de problèmes"],"de":["Verwendet Next.js für die Erstellung von Benutzeroberflächen","Integriert Supabase für die Datenverwaltung","Integriert Claude AI für die Analyse und Lösung von Problemen","Ermöglicht die Iteration und Anpassung im Prozess der Problemlösung","Bietet eine Übersicht über den Prozess der Problemlösung durch eine Pipeline zur Problemlösung"],"pt":["Pipeline de resolução de problemas com diagnóstico e reparo","Integração com Next.js para construção de interfaces de usuário","Utilização de Supabase para gerenciamento de dados","Implementação de Claude AI para análise de linguagem natural","Técnica de triagem para identificação de problemas","Reprodução e análise de causa raiz para resolução de problemas"],"ru":["Конвейер решения проблем с диагностикой и ремонтом","Интеграция с Next.js для построения пользовательских интерфейсов","Использование Supabase для управления данными","Реализация Claude AI для анализа естественного языка","Техника триажа для выявления проблем","Репродукция и анализ коренной причины для решения проблем"],"ar":["أنبوب حل المشكلات بالتشخيص والإصلاح","التكامل مع Next.js لبناء واجهات المستخدم","استخدام Supabase لإدارة البيانات","تنفيذ Claude AI لتحليل اللغة الطبيعية","تقنية التriage لتحديد المشكلات","إعادة الإنتاج وتحليل السبب الجذري لحل المشكلات"]},"keywords":{"en":["how to use issue-resolution","issue-resolution alternative","issue-resolution setup guide","what is issue-resolution","issue-resolution vs JIRA","issue-resolution install","Next.js issue resolution","Supabase task management","Claude AI pipeline","AI-powered issue resolution"],"zh":["AIエージェント","Issue Resolution","Next.js","Supabase","Claude AI","生产力伴侣","问题解决","迭代诊断"],"ja":["AIエージェント","Issue Resolution","Next.js","Supabase","Claude AI","生産性コンパニオン","問題解決","反復診断"],"ko":["AI 에이전트","이슈 해결","Next.js","Supabase","Claude AI","생산성 동반자","문제 해결","반복적 진단"],"es":["resolución de problemas con AI","herramientas de productividad","Next.js","Supabase","Claude AI","inteligencia artificial","procesos de resolución de problemas","pipeline de resolución de problemas","desarrollo de software"],"fr":["résolution de problèmes avec l''IA","outils de productivité","Next.js","Supabase","Claude AI","intelligence artificielle","processus de résolution de problèmes","pipeline de résolution de problèmes","développement de logiciels"],"de":["Problemlösung mit KI","Produktivitätstools","Next.js","Supabase","Claude AI","künstliche Intelligenz","Prozesse der Problemlösung","Pipeline zur Problemlösung","Softwareentwicklung"],"pt":["Issue Resolution","IA para resolução de problemas","Next.js","Supabase","Claude AI","Pipeline de resolução de problemas","Diagnóstico de problemas","Reparo de problemas","Técnica de triagem","Análise de causa raiz"],"ru":["Issue Resolution","ИИ для решения проблем","Next.js","Supabase","Claude AI","Конвейер решения проблем","Диагностика проблем","Ремонт проблем","Техника триажа","Анализ коренной причины"],"ar":["Issue Resolution","الذكاء الاصطناعي لحل المشكلات","Next.js","Supabase","Claude AI","أنبوب حل المشكلات","تشخيص المشكلات","إصلاح المشكلات","تقنية التriage","تحليل السبب الجذري"]}},"owner":"mthangtr","repo":"groaly","repoPath":"mthangtr/groaly","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"issue-resolution","description":"Systematically diagnose and fix bugs through triage, reproduction, root cause analysis, and verified fixes. Use when resolving bugs, errors, failing tests, or investigating unexpected behavior.","bodyPreview":"# Issue Resolution Pipeline\n\nSystematically resolve issues through iterative diagnosis and verified fixes.\n\n## Pipeline Overview\n\n```\nINPUT → Triage → Reproduction → Root Cause Analysis → Impact → Fix → Verify\n              ◄──────────────►◄────────────────────►\n                    (Iterative loops allowed)\n```\n\n| Phase                  | Purpose                            | Output              |\n| ---------------------- | ---------------------------------- | ------------------- |\n| 0. Triage","body":"# Issue Resolution Pipeline\n\nSystematically resolve issues through iterative diagnosis and verified fixes.\n\n## Pipeline Overview\n\n```\nINPUT → Triage → Reproduction → Root Cause Analysis → Impact → Fix → Verify\n              ◄──────────────►◄────────────────────►\n                    (Iterative loops allowed)\n```\n\n| Phase                  | Purpose                            | Output              |\n| ---------------------- | ---------------------------------- | ------------------- |\n| 0. Triage              | Normalize input, classify severity | Issue Brief         |\n| 1. Reproduction        | Prove the bug, trace code path     | Repro Report + Test |\n| 2. Root Cause Analysis | Find WHY, not just WHERE           | RCA Report          |\n| 3. Impact Assessment   | Blast radius, regression risk      | Impact Report       |\n| 4. Fix Decomposition   | Break into beads                   | .beads/\\*.md        |\n| 5. Verification        | Prove fix works, no regressions    | Passing tests       |\n\n## Phase 0: Triage\n\nNormalize different input types to a structured Issue Brief.\n\n### Input Types\n\n| Type                  | Triage Strategy                       |\n| --------------------- | ------------------------------------- |\n| **Vague report**      | Clarify → Explore → Reproduce         |\n| **Error/Stack trace** | Parse trace → Locate code → Reproduce |\n| **Failing test**      | Run test → Extract assertion → Trace  |\n\n### Vague Report Triage\n\n```\nUser: \"Login is broken\"\n         │\n         ▼\nAsk clarification questions:\n• What error do you see?\n• When did it start working / stop working?\n• What steps trigger it?\n• Specific user/browser/environment?\n         │\n         ▼ (if user can''t clarify)\nExplore:\n• mcp__gkg__search_codebase_definitions: Find auth/login related code\n• git log: Recent changes in area\n• Check logs if available\n```\n\n### Error/Stack Trace Triage\n\n```\nParse the stack trace:\n• Extract file:line locations\n• mcp__gkg__get_definition on functions in trace\n• Read surrounding context\n         │\n         ▼\nIdentify reproduction conditions:\n• What input caused this?\n• Can we write a test?\n```\n\n### Failing Test Triage\n\n```\nRun test in isolation:\n• bun test <file> --filter \"<test name>\"\n• Read test file for setup/assertions\n• Check git log: was it passing before?\n         │\n         ▼\nTrace implementation:\n• What code does test exercise?\n• mcp__gkg__get_references on tested function\n• Recent changes to implementation?\n```\n\n### Severity Classification\n\nDetermines reproduction requirements:\n\n| Severity                            | Reproduction Required  |\n| ----------------------------------- | ---------------------- |\n| **CRITICAL** (production, security) | Failing test REQUIRED  |\n| **REGRESSION** (was working)        | Failing test REQUIRED  |\n| **RACE CONDITION** (timing)         | Failing test REQUIRED  |\n| **LOGIC BUG**                       | Failing test PREFERRED |\n| **UI/VISUAL**                       | Manual + screenshot OK |\n| **PERFORMANCE**                     | Benchmark/profile OK   |\n| **QUICK FIX** (obvious cause)       | Manual repro OK        |\n\n### Issue Brief Template\n\nSave to `history/issues/<id>/brief.md`:\n\n```markdown\n# Issue Brief: <Short Title>\n\n**Severity**: CRITICAL / HIGH / MEDIUM / LOW\n**Type**: Regression / Edge case / Race condition / UI / Performance / Other\n**Repro Required**: Failing test / Manual OK\n\n## Symptom\n\n<What is happening>\n\n## Expected Behavior\n\n<What should happen>\n\n## Reproduction\n\n<Steps, test command, or code path>\n\n## Evidence\n\n<Error message, stack trace, test output>\n\n## Affected Area\n\n<Files, modules, features involved>\n\n## Timeline\n\n<When started, recent changes if known>\n```\n\n## Phase 1: Reproduction\n\nProve the bug exists and trace the code path.\n\n### If Failing Test Required\n\n```bash\n# Create test file\n# packages/<area>/src/__tests__/<feature>.regression.test.ts\n\n# Test should:\n# 1. Set up conditions that trigger bug\n# 2. Assert expected behavior (currently fails)\n# 3. Be deterministic\n```\n\n### Reproduction Checklist\n\n- [ ] Bug is reproducible on demand\n- [ ] Exact error/behavior captured\n- [ ] Minimal reproduction (simplest case that fails)\n- [ ] Code path identified (stack trace or tracing)\n\n### Code Path Tracing\n\n```\nmcp__gkg__get_definition     → Find where error originates\nmcp__gkg__get_references     → Find callers\ngit blame <file>       → Who changed it, when\ngit log -p <file>      → What changed recently\n```\n\n### Repro Report Template\n\nSave to `history/issues/<id>/repro.md`:\n\n```markdown\n# Reproduction Report: <Issue Title>\n\n## Reproduction Method\n\n☐ Failing test: `<test file and name>`\n☐ Manual: <steps>\n\n## Error/Behavior Captured\n\n<Exact error message, stack trace>\n\n## Code Path\n\n1. Entry: `<file>:<line>` - <function>\n2. Calls: `<file>:<line>` - <function>\n3. Fails at: `<file>:<line>` - <reason>\n\n## Recent Changes (if relevant)\n\n- <commit>: <summary>\n```\n\n## Phase 2: Root Cause Analysis\n\nFind WHY the bug happens, not just WHERE.\n\n### RCA Framework\n\n```\nSTEP 1: Generate hypotheses (3-5)\n         │\n         ▼\nSTEP 2: Gather evidence for/against each\n         │\n         ▼\nSTEP 3: Eliminate hypotheses\n         │\n         ▼\nSTEP 4: Confirm root cause\n```\n\n### Bug Type → RCA Strategy\n\n| Bug Type            | Strategy                  | Key Tools                       |\n| ------------------- | ------------------------- | ------------------------------- |\n| **Regression**      | Find breaking change      | `git bisect`, `git blame`       |\n| **Edge case**       | Analyze boundary inputs   | Type inspection, boundary tests |\n| **Race condition**  | Trace async flow          | Timing logs, async analysis     |\n| **Data corruption** | Trace state changes       | Data flow analysis              |\n| **External dep**    | Check version/API changes | Changelogs, API docs            |\n\n### Oracle for RCA\n\n**Hypothesis Generation:**\n\n```\noracle(\n  task: \"Generate root cause hypotheses\",\n  context: \"\"\"\n    Symptom: <error>\n    Code path: <trace>\n    Recent changes: <git log>\n\n    Generate 3-5 hypotheses ranked by likelihood.\n    For each, what evidence would support/refute it?\n  \"\"\",\n  files: [\"<affected files>\"]\n)\n```\n\n**Hypothesis Validation:**\n\n```\noracle(\n  task: \"Validate root cause hypothesis\",\n  context: \"\"\"\n    Hypothesis: <proposed cause>\n    Evidence: <gathered evidence>\n\n    1. Does evidence support or refute?\n    2. Explain causal chain: cause → symptom\n    3. What would confirm this?\n  \"\"\",\n  files: [\"<relevant files>\"]\n)\n```\n\n### Iteration: RCA → Reproduction Loop\n\nIf hypothesis needs more evidence:\n\n```\nIN RCA: \"Need timing logs to confirm race condition\"\n    │\n    ▼\nBACK TO REPRO:\n• Add instrumentation\n• Run with specific conditions\n• Capture new evidence\n    │\n    ▼\nRETURN TO RCA with new evidence\n```\n\n### RCA Report Template\n\nSave to `history/issues/<id>/rca.md`:\n\n```markdown\n# Root Cause Analysis: <Issue Title>\n\n## Iteration: <N>\n\n## Hypotheses Considered\n\n### Hypothesis A: <Description>\n\n- **Likelihood**: HIGH / MEDIUM / LOW\n- **Supporting evidence**: ...\n- **Refuting evidence**: ...\n- **Verdict**: ✓ CONFIRMED / ✗ ELIMINATED\n\n### Hypothesis B: ...\n\n## Root Cause (Confirmed)\n\n**Cause**: <Clear statement>\n\n**Causal chain**:\n\n1. <Step> leads to\n2. <Step> leads to\n3. <Symptom>\n\n## Why This Happened\n\n<Underlying reason - missing validation, wrong assumption, etc.>\n\n## Fix Approach\n\n**Immediate**: <What to change>\n**Preventive**: <How to prevent similar bugs>\n```\n\n## Phase 3: Impact Assessment\n\nBefore fixing, understand blast radius.\n\n### Impact Analysis\n\n```\nmcp__gkg__get_references <affected function>\n    → Who else calls this?\n\nGrep for related patterns\n    → Similar code that might have same bug?\n\nReview test coverage\n    → What tests cover this area?\n```\n\n### Regression Risk\n\n| Factor              | Risk Level |\n| ------------------- | ---------- |\n| High usage function | HIGH       |\n| Shared utility      | HIGH       |\n| Public API change   | HIGH       |\n| Internal helper     | LOW        |\n| Isolated module     | LOW        |\n\n### Spike for Complex Fixes\n\nIf fix approach is uncertain:\n\n```bash\nbd create \"Spike: Validate fix approach for <issue>\" -t task -p 0\n```\n\nExecute via MULTI_AGENT_WORKFLOW, write to `.spikes/<issue-id>/`.\n\n### Impact Report Template\n\nSave to `history/issues/<id>/impact.md`:\n\n```markdown\n# Impact Assessment: <Issue Title>\n\n## Blast Radius\n\n### Direct Impact\n\n- <File/function directly changed>\n\n### Callers Affected\n\n- <List from mcp__gkg__get_references>\n\n### Related Code\n\n- <Similar patterns that may need same fix>\n\n## Regression Risk\n\n**Level**: HIGH / MEDIUM / LOW\n**Reason**: <Why this risk level>\n\n## Test Coverage\n\n- Existing tests: <list>\n- Tests to add: <list>\n\n## Fix Validation\n\n☐ Spike completed (if needed): `.spikes/<id>/`\n☐ Fix approach validated\n```\n\n## Phase 4: Fix Decomposition\n\nBreak fix into beads.\n\n### Simple Fix (Single Bead)\n\n```bash\nbd create \"Fix: <issue title>\" -t bug -p <priority>\n```\n\nBead includes:\n\n- Root cause reference\n- Fix implementation\n- Test (failing → passing)\n- Docs update (if behavior change)\n\n### Complex Fix (Multiple Beads)\n\n```bash\nbd create \"Epic: Fix <issue>\" -t epic -p <priority>\nbd create \"Add regression test for <issue>\" -t task --blocks <epic>\nbd create \"Fix <component A>\" -t bug --blocks <epic> --deps <test>\nbd create \"Fix <component B>\" -t bug --blocks <epic> --deps <test>\nbd create \"Update docs for <behavior change>\" -t task --blocks <epic> --deps <fix-a>,<fix-b>\n```\n\n### Fix Bead Template\n\n```markdown\n# Fix: <Issue Title>\n\n**Type**: bug\n**Priority**: <0-4>\n**Fixes**: <issue reference>\n\n## Root Cause\n\n<From RCA report>\n\n## Fix Implementation\n\n<What to change and why>\n\n## Files to Modify\n\n- `<file>`: <change description>\n\n## Acceptance Criteria\n\n- [ ] Regression test passes\n- [ ] Original symptom no longer reproducible\n- [ ] No new test failures\n- [ ] `bun run check-types` passes\n- [ ] `bun run build` passes\n```\n\n## Phase 5: Verification\n\nProve fix works and nothing else broke.\n\n### Verification Checklist\n\n```bash\n# 1. Regression test passes\nbun test <regression-test-file>\n\n# 2. Original symptom gone\n<manual verification or test>\n\n# 3. No new failures\nbun run test\n\n# 4. Types and build\nbun run check-types\nbun run build\n```\n\n### Iteration: Verify → RCA Loop\n\nIf fix doesn''t work:\n\n```\nTest still fails after fix\n    │\n    ▼\nRoot cause was wrong or incomplete\n    │\n    ▼\nBACK TO RCA:\n• Eliminate current hypothesis\n• Generate new hypotheses\n• Update RCA Report with iteration\n```\n\n### Verify → Impact Loop\n\nIf fix causes regressions:\n\n```\nNew test failures after fix\n    │\n    ▼\nFix has unintended side effects\n    │\n    ▼\nBACK TO IMPACT:\n• Reassess blast radius\n• Consider alternative fix approach\n```\n\n## Loop Limits\n\nPrevent infinite iteration:\n\n| Loop         | Soft Limit | Hard Limit | At Hard Limit               |\n| ------------ | ---------- | ---------- | --------------------------- |\n| RCA → Repro  | 2          | 4          | Escalate / pair debug       |\n| RCA → Triage | 1          | 2          | Re-evaluate original report |\n| Verify → RCA | 2          | 3          | Oracle deep review          |\n\n## Quick Reference\n\n### Tool Selection\n\n| Need                  | Tool                            |\n| --------------------- | ------------------------------- |\n| Parse stack trace     | Read + mcp**gkg**get_definition |\n| Find callers          | mcp**gkg**get_references        |\n| Recent changes        | git log, git blame              |\n| Binary search commits | git bisect                      |\n| Reasoning about cause | oracle                          |\n| Validate fix approach | Spike via MULTI_AGENT_WORKFLOW  |\n\n### Common Mistakes\n\n- **Fixing symptom, not cause** → Leads to recurrence\n- **Skipping reproduction** → Can''t verify fix\n- **No regression test** → Bug returns later\n- **Ignoring impact** → Fix breaks other things\n- **Not iterating** → Wrong diagnosis persists\n"},"lastSynced":"2026-03-08T02:01:41.440Z","agentAnalysis":{"suitability":{"en":"Ideal for Debugging Agents requiring systematic issue resolution through iterative diagnosis and verified fixes using Next.js, Supabase, and Claude AI.","zh":"适合需要通过迭代诊断和使用 Next.js、Supabase 和 Claude AI 进行系统性问题解决的调试代理。","ja":"Next.js、Supabase、Claude AI を使用した体系的な問題解決を必要とするデバッグ エージェントに最適です。","ko":"Next.js, Supabase 및 Claude AI를 사용하여 체계적인 문제 해결을 통해 반복 진단 및 확인된 수정을 요구하는 디버깅 에이전트에 적합합니다.","es":"Ideal para agentes de depuración que requieren una resolución sistemática de problemas a través de un diagnóstico iterativo y soluciones verificadas utilizando Next.js, Supabase y Claude AI.","fr":"Idéal pour les agents de débogage nécessitant une résolution systématique des problèmes par le biais d''un diagnostic itératif et de corrections vérifiées utilisant Next.js, Supabase et Claude AI.","de":"Ideal für Debugging-Agenten, die eine systematische Problemlösung durch iterative Diagnose und verifizierte Korrekturen unter Verwendung von Next.js, Supabase und Claude AI erfordern.","pt":"Ideal para agentes de depuração que exigem resolução sistemática de problemas por meio de diagnóstico iterativo e reparos verificados usando Next.js, Supabase e Claude AI.","ru":"Идеально для агентов отладки, требующих системного решения проблем посредством итеративной диагностики и верифицированных исправлений с использованием Next.js, Supabase и Claude AI.","ar":"مثالي لعمليات وكيل التصحيح التي تتطلب حلًا منهجيًا للمشكلات من خلال التشخيص المتكرر والإصلاحات المُثبَتة باستخدام Next.js و Supabase و Claude AI."},"recommendation":{"en":"Empowers agents to resolve issues efficiently by leveraging a structured pipeline that includes triage, reproduction, root cause analysis, impact assessment, and verified fixes, utilizing technologies like Next.js for task management and Claude AI for enhanced analysis.","zh":"通过利用包括分类、再现、根本原因分析、影响评估和验证修复在内的结构化流水线，赋予代理高效解决问题的能力，利用 Next.js 进行任务管理和 Claude AI 进行增强分析。","ja":"トライアジ、再現、根本原因分析、影響評価、検証された修正を含む構造化されたパイプラインを利用することで、エージェントが効率的に問題を解決できるようにし、タスク管理には Next.js、分析の強化には Claude AI を使用します。","ko":"분류, 재현, 근본 원인 분석, 영향 평가 및 검증된 수정을 포함하는 구조화된 파이프라인을 활용하여 에이전트가 효율적으로 문제를 해결할 수 있도록 하며, 작업 관리에는 Next.js, 분석 강화에는 Claude AI를 사용합니다.","es":"Permite a los agentes resolver problemas de manera eficiente mediante la explotación de una canalización estructurada que incluye triage, reproducción, análisis de causa raíz, evaluación de impacto y soluciones verificadas, utilizando tecnologías como Next.js para la gestión de tareas y Claude AI para un análisis mejorado.","fr":"Permet aux agents de résoudre les problèmes de manière efficace en exploitant une canalisation structurée qui comprend le triage, la reproduction, l''analyse de la cause profonde, l''évaluation de l''impact et les corrections vérifiées, en utilisant des technologies comme Next.js pour la gestion des tâches et Claude AI pour une analyse améliorée.","de":"Ermöglicht es Agenten, Probleme effizient zu lösen, indem sie eine strukturierte Pipeline nutzen, die Triage, Reproduktion, Root-Cause-Analyse, Auswirkungsabschätzung und verifizierte Korrekturen umfasst, unter Verwendung von Technologien wie Next.js für die Aufgabenverwaltung und Claude AI für eine verbesserte Analyse.","pt":"Habilita os agentes a resolver problemas de forma eficiente, aproveitando um pipeline estruturado que inclui triagem, reprodução, análise de causa raiz, avaliação de impacto e reparos verificados, utilizando tecnologias como Next.js para gerenciamento de tarefas e Claude AI para análise aprimorada.","ru":"Наделяет агентов возможностью эффективно решать проблемы, используя структурированный конвейер, включающий триаж, воспроизведение, анализ коренной причины, оценку воздействия и верифицированные исправления, используя технологии, такие как Next.js для управления задачами и Claude AI для расширенного анализа.","ar":"يتمكّن الوكيل من حل المشكلات بفعالية من خلال استخدام трубة مهيكلة تتضمن الفحص والاستنساخ وتحليل السبب الجذري وتقييم التأثير والإصلاحات المُثبَتة، باستخدام تقنيات مثل Next.js لإدارة المهام و Claude AI للتحليل المتقدم."},"useCases":{"en":["Automating bug reproduction for faster resolution","Generating root cause analysis reports using Supabase data","Verifying fixes through iterative testing and validation"],"zh":["自动化缺陷再现以实现更快的解决","使用 Supabase 数据生成根本原因分析报告","通过迭代测试和验证来验证修复"],"ja":["解決の高速化のためのバグの再現の自動化","Supabase データを使用した根本原因分析レポートの生成","反復テストおよび検証を通じて修正の検証"],"ko":["더 빠른 해결을 위한 버그 재현 자동화","Supabase 데이터를 사용한 근본 원인 분석 보고서 생성","반복 테스트 및 검증을 통해 수정 확인"],"es":["Automatización de la reproducción de errores para una resolución más rápida","Generación de informes de análisis de causa raíz utilizando datos de Supabase","Verificación de soluciones a través de pruebas y validación iterativas"],"fr":["Automatisation de la reproduction des bogues pour une résolution plus rapide","Génération de rapports d''analyse de cause profonde en utilisant les données de Supabase","Vérification des corrections par le biais de tests et de validations itératifs"],"de":["Automatisierung der Fehlerreproduktion für eine schnellere Lösung","Erstellung von Berichten zur Root-Cause-Analyse unter Verwendung von Supabase-Daten","Verifizierung von Korrekturen durch iterative Tests und Validierung"],"pt":["Automatizar a reprodução de bugs para resolução mais rápida","Gerar relatórios de análise de causa raiz usando dados do Supabase","Verificar reparos por meio de testes e validação iterativos"],"ru":["Автоматизировать воспроизведение ошибок для более быстрого решения","Генерировать отчеты анализа коренной причины с использованием данных Supabase","Верифицировать исправления посредством итеративного тестирования и проверки"],"ar":["تحسين إعادة إنتاج العيوب من أجل حل أسرع","توليد تقارير تحليل السبب الجذري باستخدام بيانات Supabase","التحقق من الإصلاحات من خلال اختبارات وتحقق متكرر"]},"limitations":{"en":["Requires integration with Next.js and Supabase for task management","Dependent on Claude AI for advanced diagnostic capabilities","May need iterative loops for complex issue resolution"],"zh":["需要与 Next.js 和 Supabase 集成以进行任务管理","依赖于 Claude AI 进行高级诊断功能","可能需要迭代循环以解决复杂问题"],"ja":["タスク管理のために Next.js と Supabase との統合が必要","高度な診断機能には Claude AI への依存","複雑な問題の解決には反復ループが必要になる可能性"],"ko":["작업 관리를 위한 Next.js 및 Supabaseとの 통합 필요","고급 진단 기능에는 Claude AI에 대한 의존","복잡한 문제 해결에는 반복 루프가 필요할 수 있음"],"es":["Requiere integración con Next.js y Supabase para la gestión de tareas","Depende de Claude AI para capacidades de diagnóstico avanzadas","Puede necesitar bucles iterativos para la resolución de problemas complejos"],"fr":["Nécessite une intégration avec Next.js et Supabase pour la gestion des tâches","Dépend de Claude AI pour des capacités de diagnostic avancées","Peut nécessiter des boucles itératives pour la résolution de problèmes complexes"],"de":["Benötigt Integration mit Next.js und Supabase für die Aufgabenverwaltung","Ist von Claude AI für erweiterte Diagnosefunktionen abhängig","Kann iterative Schleifen für die Lösung komplexer Probleme benötigen"],"pt":["Exige integração com Next.js e Supabase para gerenciamento de tarefas","Depende de Claude AI para capacidades de diagnóstico avançadas","Pode necessitar de loops iterativos para resolução de problemas complexos"],"ru":["Требует интеграции с Next.js и Supabase для управления задачами","Зависит от Claude AI для расширенных возможностей диагностики","Может потребовать итеративных циклов для решения сложных проблем"],"ar":["يتطلب التكامل مع Next.js و Supabase لإدارة المهام","يعتمد على Claude AI للقدرات التشخيصية المتقدمة","يمكن أن يحتاج إلى الحلقات المتكررة لحل مشكلات معقدة"]},"version":4},"contentHash":"14297f6531dd397ffab169c75a71c1274a7b012f4b7188116a5eb3ead50b4c52","qualityScore":60}');
