INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mthangtr/groaly/issue-resolution', 'issue-resolution', 'mthangtr', 'groaly', 'community', 'issue-resolution mthangtr groaly community The issue-resolution skill systematically resolves issues through iterative diagnosis and verified fixes, benefiting developers and teams. It utilizes Next.js, Supabase, and Claude AI for balanced task management. 利用Next.js、Supabase和Claude AI的AI驱动生产力伴侣，通过迭代诊断和验证的修复来解决问题 Next.js、Supabase、Claude AIを使用したAIパワーの生産性コンパニオンで、問題を解決 Next.js, Supabase, Claude AI로 구축된 AI 기반 생산성 동반자로 문제를 체계적으로 해결 La resolución de problemas con AI es una herramienta de productividad que utiliza Next.js, Supabase y Claude AI para transformar notas caóticas en tareas actionables La résolution de problèmes avec l''IA est un outil de productivité qui utilise Next.js, Supabase et Claude AI pour transformer des notes chaotiques en tâches actionables Die Problemlösung mit KI ist ein Produktivitätstool, das Next.js, Supabase und Claude AI verwendet, um chaotische Notizen in handhabbare Aufgaben umzuwandeln O Issue Resolution é um companion de produtividade baseado em IA que transforma notas caóticas em tarefas balanceadas e ações concretas. Issue Resolution - это ИИ Агент, который превращает хаотичные заметки в сбалансированные и действенные задачи. Issue Resolution هو رفيق إنتاجية معتمد على الذكاء الاصطناعي يتحول الملاحظات المضطربة إلى مهام متوازنة وفعاليات ملموسة. how to use issue-resolution issue-resolution alternative issue-resolution setup guide what is issue-resolution issue-resolution vs JIRA issue-resolution install Next.js issue resolution Supabase task management Claude AI pipeline AI-powered issue resolution AIエージェント Issue Resolution Next.js Supabase Claude AI 生产力伴侣 问题解决 迭代诊断 Utilizes Next.js for robust frontend development Leverages Supabase for scalable database management Employs Claude AI for intelligent task analysis Implements an iterative issue resolution pipeline Includes phases for triage, reproduction, and root cause analysis Supports verified fixes and iterative loops for refinement issue-resolution is a technical process that transforms chaotic notes into balanced, actionable tasks across multiple life goals using an AI-powered pipeline.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('najicham/nba-stats-scraper/validate-historical', 'community', 'najicham', 'nba-stats-scraper', 'najicham/nba-stats-scraper', 'validate-historical', 0, 0, 60, '2026-03-08T01:57:15.303Z', '2026-03-08T02:01:48.348Z', '1c2d70f90fda8e30c1f63d5596469a955368b5b0a0728b825755e48d9dd8a8e9', '{"id":"najicham/nba-stats-scraper/validate-historical","name":"validate-historical","description":{"en":"The validate-historical skill performs comprehensive historical data validation for the NBA stats scraper, identifying data gaps and assessing cascade impacts. It benefits data analysts and scientists by providing actionable remediation plans.","zh":"validate-historical AIエージェント用于历史数据验证，识别数据缺口和级联影响，提供修复计划","ja":"validate-historical AIエージェントは歴史データの検証を行い、データギャップとカスケード影響を識別し、修復計画を提供します","ko":"validate-historical AI 에이전트는 역사적 데이터의 유효성 검사를 수행하며, 데이터 격차와 캐스케이드 영향을 식별하고 修复 계획을 제공합니다","es":"El agente de AI validate-historical realiza una validación exhaustiva de los datos históricos para el raspador de estadísticas de la NBA","fr":"L''agent de validation des données historiques validate-historical effectue une validation complète des données historiques pour le scrapeur de statistiques de la NBA","de":"Der validate-historical-KI-Agent führt eine umfassende Überprüfung der historischen Daten für den NBA-Statistik-Scraper durch","pt":"O Validate-Historical é uma habilidade que valida a integridade dos dados históricos, identificando lacunas e fornecendo planos de remediação para melhorar a precisão das previsões","ru":"Validate-Historical - это навык, который проверяет целостность исторических данных, выявляет пробелы и предоставляет планы исправления для повышения точности прогнозов ИИ Агентов","ar":"Validate-Historical هو مهارة تقوم بتحقق صحة البيانات التاريخية وتحديد الفجوات وتقديم خطط تصحيحية لتحسين دقة التنبؤات للأدوات الذكية"},"seo":{"title":{"en":"validate-historical: Historical Data Validation Setup Gui...","zh":"validate-historical Setup Guide: AIエージェント用于历史数据验证","ja":"validate-historical ベストプラクティス: AIエージェントによる歴史データ検証","ko":"validate-historical 설정 가이드: AI 에이전트를 이용한 역사적 데이터 유효성 검사","es":"Guía de configuración de validate-historical para la vali...","fr":"Guide de mise en œuvre de validate-historical pour la val...","de":"Einrichtungsleitfaden für validate-historical zur Überprü...","pt":"Guia de Configuração do Validate-Historical para Análise ...","ru":"Руководство по настройке Validate-Historical для анализа ...","ar":"دليل إعداد Validate-Historical لتحليل البيانات التاريخية ..."},"description":{"en":"Discover how validate-historical identifies data gaps and provides remediation plans. Learn to audit historical data integrity and resolve cascade impacts - ...","zh":"了解validate-historical AIエージェント的功能和特点，用于历史数据验证和修复，包括数据缺口识别和级联影响评估","ja":"validate-historical AIエージェントの機能と特徴を紹介します。歴史データの検証と修復、データギャップの識別とカスケード影響の評価などを含みます","ko":"validate-historical AI 에이전트의 기능과 특징을 알아보세요. 역사적 데이터의 유효성 검사와 修复, 데이터 격차 식별 및 캐스케이드 영향 평가 등을 포함합니다","es":"Aprende a utilizar validate-historical para identificar lagunas de datos y proporcionar planes de remedio en el orden de dependencia correcto","fr":"Découvrez comment utiliser validate-historical pour identifier les lacunes de données et fournir des plans de remédiation dans l''ordre de dépendance correct","de":"Erfahren Sie, wie Sie validate-historical verwenden, um Datenlücken zu identifizieren und Wiederherstellungspläne in der richtigen Abhängigkeitsreihenfolge b...","pt":"Aprenda a validar dados históricos com o Validate-Historical e melhore a integridade dos dados para previsões mais precisas","ru":"Узнайте, как валидировать исторические данные с помощью Validate-Historical и улучшить целостность данных для более точных прогнозов ИИ Агентов","ar":"تعرف على كيفية التحقق من صحة البيانات التاريخية باستخدام Validate-Historical وتحسين سلامة البيانات لتنبؤات أكثر دقة للأدوات الذكية"},"definition":{"en":"validate-historical is a skill that audits historical data integrity across a date range, identifying gaps and providing specific remediation steps to resolve cascade effects.","zh":"validate-historical是用于历史数据验证的AIエージェント，识别数据缺口和级联影响","ja":"validate-historicalは歴史データの検証を行うAIエージェントであり、データギャップとカスケード影響を識別します","ko":"validate-historical은 역사적 데이터의 유효성 검사를 수행하는 AI 에이전트로, 데이터 격차와 캐스케이드 영향을 식별합니다","es":"validate-historical es una herramienta de AI que identifica lagunas de datos y proporciona planes de remedio para la validación de datos históricos","fr":"validate-historical est un outil d''IA qui identifie les lacunes de données et fournit des plans de remédiation pour la validation des données historiques","de":"validate-historical ist ein KI-Tool, das Datenlücken identifiziert und Wiederherstellungspläne für die Überprüfung historischer Daten bereitstellt","pt":"O Validate-Historical é uma ferramenta de validação de dados históricos que identifica lacunas e fornece planos de remediação","ru":"Validate-Historical - это инструмент проверки исторических данных, который выявляет пробелы и предоставляет планы исправления ИИ Агентов","ar":"Validate-Historical هو أداة للتحقق من البيانات التاريخية التي تحدد الفجوات وتقدم خطط تصحيحية"},"features":{"en":["Audits historical data integrity across a specified date range","Identifies data gaps that may have cascading effects on predictions","Provides actionable remediation plans in the correct dependency order","Assesses cascade impacts on historical data","Offers specific remediation steps to resolve data gaps"],"zh":["历史数据验证","数据缺口识别","级联影响评估","修复计划提供","CLI集成","Python支持"],"ja":["歴史データの検証","データギャップの識別","カスケード影響の評価","修復計画の提供","CLIの統合","Pythonのサポート"],"ko":["역사적 데이터의 유효성 검사","데이터 격차 식별","캐스케이드 영향 평가","修复 계획 제공","CLI 통합","Python 지원"],"es":["Identificación de lagunas de datos","Evaluación de impactos en cascada","Proporciona planes de remedio en el orden de dependencia correcto","Validación de la integridad de los datos históricos","Análisis de datos en un rango de fechas específico"],"fr":["Identification des lacunes de données","Évaluation des impacts en cascade","Fournit des plans de remédiation dans l''ordre de dépendance correct","Validation de l''intégrité des données historiques","Analyse des données dans une plage de dates spécifique"],"de":["Identifizierung von Datenlücken","Bewertung von Cascade-Effekten","Bereitstellung von Wiederherstellungsplänen in der richtigen Abhängigkeitsreihenfolge","Überprüfung der Integrität historischer Daten","Analyse von Daten in einem bestimmten Datumsbereich"],"pt":["Análise de dados históricos para identificar lacunas","Fornecimento de planos de remediação para melhorar a precisão das previsões","Avaliação do impacto cascata dos dados ausentes","Identificação de dependências para remediação eficaz","Suporte à auditoria de dados para garantir a integridade","Integração com ferramentas de análise de dados para melhorar a precisão"],"ru":["Анализ исторических данных для выявления пробелов","Предоставление планов исправления для повышения точности прогнозов","Оценка каскадного воздействия отсутствующих данных ИИ Агентов","Выявление зависимостей для эффективного исправления","Поддержка аудита данных для обеспечения целостности","Интеграция с инструментами анализа данных для повышения точности"],"ar":["تحليل البيانات التاريخية لتحديد الفجوات","تقديم خطط تصحيحية لتحسين دقة التنبؤات","تقييم التأثير الكاسح للبيانات الناقصة للأدوات الذكية","تحديد الارتباطات لتحقيق تصحيح فعال","دعم تدقيق البيانات لضمان سلامة البيانات","التكامل مع أدوات تحليل البيانات لتحسين الدقة"]},"keywords":{"en":["how to use validate-historical","what is validate-historical","validate-historical alternative","validate-historical vs data validation tools","validate-historical install","validate-historical setup guide","historical data validation best practices","NBA stats scraper data validation","cascade impact assessment"],"zh":["AIエージェント","历史数据验证","数据缺口识别","级联影响评估","修复计划","CLI","Python","validate-historical"],"ja":["AIエージェント","歴史データの検証","データギャップの識別","カスケード影響の評価","修復計画","CLI","Python","validate-historical"],"ko":["AI 에이전트","역사적 데이터의 유효성 검사","데이터 격차 식별","캐스케이드 영향 평가","修复 계획","CLI","Python","validate-historical"],"es":["validación de datos históricos","herramientas de AI para validación de datos","identificación de lagunas de datos","evaluación de impactos en cascada","planes de remedio para la validación de datos","validación de la integridad de los datos","análisis de datos en un rango de fechas","herramientas de inteligencia artificial para datos históricos"],"fr":["validation des données historiques","outils d''IA pour la validation des données","identification des lacunes de données","évaluation des impacts en cascade","plans de remédiation pour la validation des données","validation de l''intégrité des données","analyse des données dans une plage de dates","outils d''intelligence artificielle pour les données historiques"],"de":["Überprüfung historischer Daten","KI-Tools für die Überprüfung von Daten","Identifizierung von Datenlücken","Bewertung von Cascade-Effekten","Wiederherstellungspläne für die Überprüfung von Daten","Überprüfung der Integrität historischer Daten","Analyse von Daten in einem bestimmten Datumsbereich","KI-Tools für historische Daten"],"pt":["validação de dados históricos","análise de dados","previsões precisas","auditoria de dados","integridade de dados","ferramentas de análise de dados","validação de dados para previsões","melhoria da precisão das previsões","identificação de lacunas nos dados"],"ru":["проверка исторических данных","анализ данных","точные прогнозы","аудит данных","целостность данных","инструменты анализа данных","проверка данных для прогнозов","повышение точности прогнозов","выявление пробелов в данных ИИ Агентов"],"ar":["التحقق من البيانات التاريخية","تحليل البيانات","تنبؤات دقيقة","تدقيق البيانات","سلامة البيانات","أدوات تحليل البيانات","التحقق من البيانات للتنبؤات","تحسين دقة التنبؤات","تحديد الفجوات في البيانات للأدوات الذكية"]}},"owner":"najicham","repo":"nba-stats-scraper","repoPath":"najicham/nba-stats-scraper","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.303Z","topics":[],"category":"community","skillMd":{"name":"validate-historical","description":"Validate historical data completeness and quality over date ranges","bodyPreview":"# Historical Data Validation\n\nYou are performing comprehensive historical data validation for the NBA stats scraper. This skill identifies data gaps, assesses cascade impacts, and provides actionable remediation plans.\n\n## Your Mission\n\nAudit historical data integrity across a date range, identify gaps that may have cascading effects on predictions, and provide specific remediation steps in the correct dependency order.\n\n## Critical Concept: The Data Cascade Problem\n\n**Missing historical data co","body":"# Historical Data Validation\n\nYou are performing comprehensive historical data validation for the NBA stats scraper. This skill identifies data gaps, assesses cascade impacts, and provides actionable remediation plans.\n\n## Your Mission\n\nAudit historical data integrity across a date range, identify gaps that may have cascading effects on predictions, and provide specific remediation steps in the correct dependency order.\n\n## Critical Concept: The Data Cascade Problem\n\n**Missing historical data corrupts downstream predictions:**\n\n```\n2026-01-18: Player scores 30 points → Missing from DB (pipeline failure)\n2026-01-19: points_avg_last_5 = 20 (WRONG - should be 22 with the 30)\n2026-01-20: ML features use wrong average\n2026-01-21: Prediction degraded (wrong features)\n2026-01-22→01-28: Error propagates for 5-10 more days\n```\n\n**Cascade Window**: Missing data on date X affects rolling averages for:\n- **L5 averages**: 5 days forward\n- **L10 averages**: 10 days forward\n- **ML features using longer windows**: up to 21 days forward\n\n---\n\n## Interactive Mode (User Preference Gathering)\n\n**If the user invoked the skill without specific parameters or flags**, ask them what they want to validate:\n\nUse the AskUserQuestion tool to gather preferences:\n\n**Question 1: \"What date range would you like to validate?\"**\n```\nOptions:\n  - \"Last 7 days (Recommended)\" - Quick weekly health check\n  - \"Last 14 days\" - Bi-weekly validation\n  - \"Last 30 days\" - Monthly audit\n  - \"Full season (Oct 22 - today)\" - Comprehensive season audit (slower)\n  - \"Custom date range\" - Specify exact dates\n```\n\n**Question 2: \"What type of validation do you need?\"**\n```\nOptions:\n  - \"Standard validation (Recommended)\" - Find gaps, assess quality, get remediation plan\n  - \"Deep check\" - Recalculate rolling averages from source to verify accuracy\n  - \"Player-specific\" - Deep dive into a single player''s data history\n  - \"Game-specific\" - Validate all data for a single game\n  - \"Verify backfill\" - Confirm a recent backfill succeeded and cascade is resolved\n  - \"Quick coverage scan\" - Fast completeness check without deep analysis\n  - \"Find anomalies\" - Detect statistical outliers and suspicious data\n```\n\n**Question 3 (conditional): Follow-up questions based on mode**\n\nIf they chose:\n- **Player-specific**: Ask \"Which player?\" (free text)\n- **Verify backfill**: Ask \"What date was backfilled?\" (free text, format: YYYY-MM-DD)\n- **Custom date range**: Ask \"What date range?\" (free text, format: YYYY-MM-DD YYYY-MM-DD)\n\n**Based on their answers**, construct the effective command and proceed:\n\nExamples:\n- Q1: \"Last 7 days\", Q2: \"Standard\" → Run standard validation for last 7 days\n- Q1: \"Last 14 days\", Q2: \"Deep check\" → Run deep check for last 14 days\n- Q1: \"Last 7 days\", Q2: \"Player-specific\", Q3: \"LeBron James\" → Player validation for LeBron\n- Q1: Custom \"2026-01-18\", Q2: \"Verify backfill\" → Verify backfill for 2026-01-18\n\n**If the user already provided parameters** (e.g., `--deep-check 2026-01-18` or `--player \"LeBron James\"`), skip the questions and parse their intent directly.\n\n---\n\n## Understanding User Intent\n\nParse the command to determine mode and date range:\n\n### Date Range Parsing\n\n```\n/validate-historical              → Last 7 days\n/validate-historical 14           → Last 14 days\n/validate-historical 30           → Last 30 days\n/validate-historical season       → Full season (Oct 22 - today)\n/validate-historical 2026-01-01 2026-01-15  → Specific range\n```\n\n### Mode Detection (Flags)\n\n```\n--deep-check          → Verify calculations from source (recalculate rolling avgs)\n--player <name>       → Single player deep dive\n--game <id>           → Single game validation\n--verify-backfill     → Confirm backfill succeeded\n--coverage-only       → Quick completeness scan (no deep analysis)\n--anomalies           → Statistical outlier detection\n--compare-sources     → Cross-source reconciliation\n--export <path>       → Save results to JSON\n```\n\n**Examples**:\n- `/validate-historical --deep-check 2026-01-18` → Deep check single date\n- `/validate-historical --player \"LeBron James\"` → Player-specific validation (last 7 days)\n- `/validate-historical 14 --coverage-only` → Quick scan last 14 days\n\n---\n\n## Mode 1: Standard Validation (Default)\n\n**When**: No special flags provided\n**Purpose**: Comprehensive health check with gap detection and quality trends\n\n### Workflow\n\n#### Step 1: Data Completeness Check\n\nFor each date in range, verify all pipeline stages:\n\n```bash\n# Query for completeness\nbq query --use_legacy_sql=false \"\nWITH dates AS (\n  SELECT date\n  FROM UNNEST(GENERATE_DATE_ARRAY(''2026-01-18'', ''2026-01-25'')) AS date\n),\nraw_data AS (\n  SELECT\n    game_date,\n    COUNT(DISTINCT game_id) as games,\n    COUNT(*) as raw_records\n  FROM \\`nba-props-platform.nba_raw.nbac_gamebook_player_stats\\`\n  WHERE game_date BETWEEN ''2026-01-18'' AND ''2026-01-25''\n  GROUP BY game_date\n),\nanalytics_data AS (\n  SELECT\n    game_date,\n    COUNT(*) as analytics_records,\n    COUNTIF(minutes_played IS NOT NULL) as minutes_coverage,\n    COUNTIF(usage_rate IS NOT NULL) as usage_coverage\n  FROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\n  WHERE game_date BETWEEN ''2026-01-18'' AND ''2026-01-25''\n  GROUP BY game_date\n),\npredictions AS (\n  SELECT\n    game_date,\n    COUNT(*) as prediction_count\n  FROM \\`nba-props-platform.nba_predictions.player_prop_predictions\\`\n  WHERE game_date BETWEEN ''2026-01-18'' AND ''2026-01-25''\n    AND is_active = TRUE\n  GROUP BY game_date\n)\nSELECT\n  d.date,\n  COALESCE(r.games, 0) as games,\n  COALESCE(r.raw_records, 0) as raw_records,\n  COALESCE(a.analytics_records, 0) as analytics_records,\n  COALESCE(a.minutes_coverage, 0) as minutes_coverage,\n  COALESCE(a.usage_coverage, 0) as usage_coverage,\n  COALESCE(p.prediction_count, 0) as prediction_count,\n  CASE\n    WHEN r.raw_records > 0 AND a.analytics_records = 0 THEN ''RAW_ONLY''\n    WHEN a.analytics_records > 0 AND a.analytics_records < r.raw_records * 0.9 THEN ''INCOMPLETE''\n    WHEN a.analytics_records > 0 THEN ''COMPLETE''\n    ELSE ''NO_DATA''\n  END as status\nFROM dates d\nLEFT JOIN raw_data r ON d.date = r.game_date\nLEFT JOIN analytics_data a ON d.date = a.game_date\nLEFT JOIN predictions p ON d.date = p.game_date\nORDER BY d.date DESC\"\n```\n\n#### Step 2: Identify Gaps\n\n**Gap Types**:\n1. **NO_DATA**: No games scheduled (off-day) → Expected, not an error\n2. **RAW_ONLY**: Raw data exists but analytics missing → Phase 3 failure, backfill needed\n3. **INCOMPLETE**: Analytics < 90% of raw → Partial failure, investigate cause\n\n#### Step 3: Assess Cascade Impact\n\nFor each gap found, calculate affected dates:\n\n**Cascade Window**: Gap date + 5-21 days forward (depending on rolling avg window: L5=5 days, L10=10 days, longer features=up to 21 days)\n\n```bash\n# Find features affected by gap\nbq query --use_legacy_sql=false \"\nSELECT\n  game_date,\n  COUNT(DISTINCT player_lookup) as affected_players,\n  COUNT(*) as affected_features\nFROM \\`nba-props-platform.nba_predictions.ml_feature_store_v2\\`\nWHERE DATE(''2026-01-18'') IN UNNEST(historical_completeness.contributing_game_dates)\n  AND game_date > DATE(''2026-01-18'')\n  AND game_date <= DATE_ADD(DATE(''2026-01-18''), INTERVAL 21 DAY)\nGROUP BY game_date\nORDER BY game_date\"\n```\n\n#### Step 4: Quality Trend Analysis\n\n**Run spot checks for the date range**:\n\n```bash\npython scripts/spot_check_data_accuracy.py \\\n  --start-date 2026-01-18 \\\n  --end-date 2026-01-25 \\\n  --samples 10 \\\n  --checks rolling_avg,usage_rate\n```\n\n**Check ML feature quality trends (Session 139)**:\n\n```bash\n# Trend is_quality_ready percentage over time\nbq query --use_legacy_sql=false \"\nSELECT\n  game_date,\n  COUNT(*) as total_rows,\n  COUNTIF(is_quality_ready = TRUE) as quality_ready,\n  ROUND(100.0 * COUNTIF(is_quality_ready = TRUE) / COUNT(*), 1) as pct_quality_ready,\n  ROUND(AVG(matchup_quality_pct), 1) as avg_matchup_quality,\n  COUNTIF(quality_alert_level = ''red'') as red_alerts\nFROM \\`nba-props-platform.nba_predictions.ml_feature_store_v2\\`\nWHERE game_date BETWEEN ''2026-01-18'' AND ''2026-01-25''\nGROUP BY game_date\nORDER BY game_date DESC\"\n```\n\n**Quality trend checks**:\n- `pct_quality_ready` dropping below 60% indicates Phase 4 processor failures\n- `avg_matchup_quality` dropping below 50% catches Session 132-style degradation (all matchup features defaulted)\n- Rising `red_alerts` count signals systemic quality regression -- investigate per-feature scores\n\n**Analyze trends**:\n- Is accuracy stable or declining?\n- Are failures clustered around specific dates?\n- Do failures correlate with identified gaps?\n\n#### Step 5: Provide Remediation Plan\n\nFor each gap, provide commands in **correct dependency order**:\n\n1. **Phase 3 (Analytics)**: Regenerate player_game_summary\n2. **Phase 4 (Precompute)**: Regenerate player_daily_cache\n3. **Verification**: Run spot checks to confirm fix\n\n---\n\n## Mode 2: Deep Check (`--deep-check`)\n\n**When**: `--deep-check` flag present\n**Purpose**: Verify cached rolling averages match recalculation from source\n\n### Workflow\n\nThis mode **recalculates** rolling averages from raw data and compares to what''s stored in cache.\n\n```bash\n# For each sample, run manual recalculation\nbq query --use_legacy_sql=false \"\nWITH player_games AS (\n  SELECT\n    player_lookup,\n    game_date,\n    points,\n    ROW_NUMBER() OVER (PARTITION BY player_lookup ORDER BY game_date DESC) as game_num\n  FROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\n  WHERE player_lookup = ''lebronjames''\n    AND game_date < DATE(''2026-01-26'')\n  ORDER BY game_date DESC\n  LIMIT 5\n),\ncached_avg AS (\n  SELECT\n    points_avg_last_5\n  FROM \\`nba-props-platform.nba_precompute.player_daily_cache\\`\n  WHERE player_lookup = ''lebronjames''\n    AND cache_date = DATE(''2026-01-25'')  -- cache_date = game_date - 1\n)\nSELECT\n  (SELECT AVG(points) FROM player_games) as recalculated_avg,\n  (SELECT points_avg_last_5 FROM cached_avg) as cached_avg,\n  ABS((SELECT AVG(points) FROM player_games) - (SELECT points_avg_last_5 FROM cached_avg)) as difference\"\n```\n\n**Sample random player-dates** (10-20 samples) and compare:\n- If difference > 2% → MISMATCH (investigate)\n- If difference ≤ 2% → MATCH (floating point tolerance)\n\n**Mismatch Investigation**:\n1. Check which games were used in cache calculation\n2. Check which games SHOULD have been used\n3. Identify missing game (the gap date)\n4. Estimate cascade impact (players affected, dates affected)\n\n### Sample Size Recommendations\n\n| Date Range | Recommended Samples | Rationale |\n|------------|---------------------|-----------|\n| 1-3 days | 10-15 samples | Focused check, quick |\n| 7 days | 20 samples | Weekly health check |\n| 14 days | 30 samples | Bi-weekly audit |\n| 30+ days | 50 samples | Monthly/season audit |\n\n**Trade-off**: More samples = higher confidence but longer runtime (~2-3 seconds per sample for BigQuery queries).\n\n**Minimum**: Always check at least 10 samples for statistical relevance.\n\n---\n\n## Mode 3: Player-Specific (`--player <name>`)\n\n**When**: `--player` flag with player name\n**Purpose**: Deep dive into single player''s data history\n\n### Workflow\n\n```bash\n# Get player''s game history\nbq query --use_legacy_sql=false \"\nSELECT\n  game_date,\n  opponent_team_abbr,\n  points,\n  minutes_played,\n  usage_rate,\n  -- Check data in each stage\n  CASE WHEN game_id IN (SELECT DISTINCT game_id FROM \\`nba-props-platform.nba_raw.nbac_gamebook_player_stats\\` WHERE player_lookup = ''lebronjames'') THEN ''✅'' ELSE ''❌'' END as has_raw,\n  CASE WHEN minutes_played IS NOT NULL THEN ''✅'' ELSE ''❌'' END as has_analytics,\n  -- Note: This is simplified - real check would join to cache and predictions tables\nFROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\nWHERE player_lookup = ''lebronjames''\n  AND game_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 14 DAY)\nORDER BY game_date DESC\"\n```\n\nShow game-by-game breakdown with data stage completion for each game.\n\nRun deep check on player''s rolling averages to verify integrity.\n\n---\n\n## Mode 4: Game-Specific (`--game <id>`)\n\n**When**: `--game` flag with game ID or description\n**Purpose**: Validate all data for a single game - all players, all stats, all pipeline stages\n\n### Workflow\n\n#### Step 1: Identify the Game\n\n```bash\n# If user provided game_id directly\nGAME_ID=\"0022500123\"\n\n# If user provided description, find the game\nbq query --use_legacy_sql=false \"\nSELECT game_id, game_date, home_team_abbr, away_team_abbr\nFROM \\`nba-props-platform.nba_raw.nbac_schedule\\`\nWHERE game_date = DATE(''2026-01-25'')\n  AND (home_team_abbr = ''LAL'' OR away_team_abbr = ''LAL'')\nLIMIT 1\"\n```\n\n#### Step 2: Check All Players for Game\n\n```bash\nbq query --use_legacy_sql=false \"\nWITH raw AS (\n  SELECT player_lookup, points as raw_points, minutes as raw_minutes\n  FROM \\`nba-props-platform.nba_raw.nbac_gamebook_player_stats\\`\n  WHERE game_id = ''0022500123''\n),\nanalytics AS (\n  SELECT player_lookup, points as analytics_points, minutes_played, usage_rate\n  FROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\n  WHERE game_id = ''0022500123''\n),\npredictions AS (\n  SELECT player_lookup, COUNT(*) as prediction_count\n  FROM \\`nba-props-platform.nba_predictions.player_prop_predictions\\`\n  WHERE game_id = ''0022500123'' AND is_active = TRUE\n  GROUP BY player_lookup\n)\nSELECT\n  COALESCE(r.player_lookup, a.player_lookup) as player,\n  r.raw_points,\n  a.analytics_points,\n  a.usage_rate,\n  COALESCE(p.prediction_count, 0) as predictions,\n  CASE\n    WHEN r.player_lookup IS NULL THEN ''MISSING_RAW''\n    WHEN a.player_lookup IS NULL THEN ''MISSING_ANALYTICS''\n    WHEN a.usage_rate IS NULL THEN ''MISSING_USAGE''\n    ELSE ''COMPLETE''\n  END as status\nFROM raw r\nFULL OUTER JOIN analytics a ON r.player_lookup = a.player_lookup\nLEFT JOIN predictions p ON a.player_lookup = p.player_lookup\nORDER BY status DESC, player\"\n```\n\n#### Step 3: Verify Team Totals\n\n```bash\n# Check team stats exist and sum correctly\nbq query --use_legacy_sql=false \"\nSELECT\n  team_abbr,\n  SUM(points) as team_points,\n  (SELECT points FROM \\`nba-props-platform.nba_analytics.team_offense_game_summary\\` t\n   WHERE t.game_id = ''0022500123'' AND t.team_abbr = p.team_abbr) as recorded_team_points\nFROM \\`nba-props-platform.nba_analytics.player_game_summary\\` p\nWHERE game_id = ''0022500123''\nGROUP BY team_abbr\"\n```\n\n### Output Format\n\n```markdown\n## Game Validation: LAL vs GSW (2026-01-25)\n\n**Game ID**: 0022500123\n\n### Player Data Completeness\n\n| Player | Raw | Analytics | Usage | Predictions | Status |\n|--------|-----|-----------|-------|-------------|--------|\n| lebronjames | 28 | 28 | 32.1% | 4 | ✅ COMPLETE |\n| anthonydavis | 24 | 24 | 28.5% | 4 | ✅ COMPLETE |\n| austinreaves | 18 | 18 | NULL | 3 | ⚠️ MISSING_USAGE |\n\n### Team Totals\n\n| Team | Player Sum | Recorded | Match |\n|------|------------|----------|-------|\n| LAL | 118 | 118 | ✅ |\n| GSW | 112 | 112 | ✅ |\n\n### Issues Found\n- 2 players missing usage_rate (team stats may be incomplete)\n```\n\n---\n\n## Mode 5: Verify Backfill (`--verify-backfill`)\n\n**When**: `--verify-backfill <date>` provided\n**Purpose**: Confirm backfill succeeded and downstream data is now correct\n\n### Workflow\n\n#### Step 1: Confirm Backfilled Date Complete\n\n```bash\n# Check the backfilled date has data\nbq query --use_legacy_sql=false \"\nSELECT\n  COUNT(*) as player_records,\n  COUNT(DISTINCT game_id) as games,\n  COUNTIF(minutes_played IS NOT NULL) as minutes_coverage,\n  COUNTIF(usage_rate IS NOT NULL) as usage_coverage\nFROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\nWHERE game_date = DATE(''2026-01-18'')\"\n```\n\n**Expected**: Record count matches number of players who played that day (~180-300)\n\n#### Step 2: Verify Downstream Dates Fixed\n\nRun deep check on dates AFTER the backfill (next 5-7 days):\n\n```bash\npython scripts/spot_check_data_accuracy.py \\\n  --start-date 2026-01-19 \\\n  --end-date 2026-01-25 \\\n  --samples 20 \\\n  --checks rolling_avg\n```\n\n**Expected**: Spot check accuracy returns to ≥95% for downstream dates\n\n#### Step 3: Check Cascade Resolution\n\n```bash\n# Verify features recalculated\nbq query --use_legacy_sql=false \"\nSELECT\n  game_date,\n  COUNT(*) as features_with_backfilled_date\nFROM \\`nba-props-platform.nba_predictions.ml_feature_store_v2\\`\nWHERE DATE(''2026-01-18'') IN UNNEST(historical_completeness.contributing_game_dates)\n  AND game_date > DATE(''2026-01-18'')\nGROUP BY game_date\nORDER BY game_date\"\n```\n\n**Expected**: Features using backfilled date now exist with is_complete = true\n\n---\n\n## Mode 6: Coverage Only (`--coverage-only`)\n\n**When**: `--coverage-only` flag present\n**Purpose**: Fast completeness scan without deep analysis\n\n```bash\n# Quick completeness table\nbq query --use_legacy_sql=false --format=pretty \"\nSELECT\n  game_date,\n  COUNT(DISTINCT game_id) as games,\n  COUNT(*) as players,\n  COUNTIF(minutes_played IS NOT NULL) as has_minutes,\n  COUNTIF(usage_rate IS NOT NULL) as has_usage\nFROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\nWHERE game_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 30 DAY)\nGROUP BY game_date\nORDER BY game_date DESC\"\n```\n\nOutput: Simple table, no investigation, fast execution.\n\n---\n\n## Mode 7: Anomalies (`--anomalies`)\n\n**When**: `--anomalies` flag present\n**Purpose**: Find suspicious data that might indicate corruption\n\n### Anomalies to Flag\n\n```bash\n# Statistical outliers (Enhanced 2026-01-27 with new data quality fields)\nbq query --use_legacy_sql=false \"\nSELECT\n  game_date,\n  player_lookup,\n  points,\n  minutes_played,\n  usage_rate,\n  usage_rate_valid,\n  usage_rate_anomaly_reason,\n  is_partial_game_data,\n  game_completeness_pct,\n  CASE\n    WHEN points > 60 THEN ''Suspiciously high points (>60)''\n    WHEN points < 0 THEN ''Negative points (corruption)''\n    WHEN minutes_played = 0 AND points > 0 THEN ''Points without minutes (join issue)''\n    WHEN usage_rate > 100 THEN ''INVALID usage rate (>100%) - partial team data''\n    WHEN usage_rate > 50 THEN ''Excessive usage rate (>50%)''\n    WHEN usage_rate < 0 THEN ''Negative usage rate (corruption)''\n    WHEN is_partial_game_data = TRUE THEN ''Partial game data flag set''\n  END as anomaly_type\nFROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\nWHERE game_date >= DATE_SUB(CURRENT_DATE(), INTERVAL 14 DAY)\n  AND (\n    points > 60 OR\n    points < 0 OR\n    (minutes_played = 0 AND points > 0) OR\n    usage_rate > 50 OR\n    usage_rate < 0 OR\n    is_partial_game_data = TRUE\n  )\nORDER BY game_date DESC\"\n```\n\n### Usage Rate Anomaly Deep Dive (Added 2026-01-27)\n\nFor investigating usage_rate > 100% issues specifically:\n\n```bash\n# Find all invalid usage_rate records\nbq query --use_legacy_sql=false \"\nSELECT\n  game_date,\n  game_id,\n  player_lookup,\n  team_abbr,\n  usage_rate,\n  usage_rate_raw,\n  usage_rate_anomaly_reason,\n  -- Team data context\n  source_team_completeness_pct,\n  game_status_at_processing,\n  is_partial_game_data\nFROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\nWHERE game_date BETWEEN ''{start_date}'' AND ''{end_date}''\n  AND usage_rate > 100\nORDER BY usage_rate DESC\"\n```\n\n**Root Cause Analysis**:\n- usage_rate > 100% typically indicates team stats had incomplete data\n- Check `source_team_completeness_pct` - should be 100% for valid usage_rate\n- Check `game_status_at_processing` - should be ''Final''\n- If `is_partial_game_data = TRUE`, the record was correctly flagged\n\n### DNP (Did Not Play) Visibility (Added 2026-01-27)\n\nCheck for DNP players in historical data:\n\n```bash\nbq query --use_legacy_sql=false \"\nSELECT\n  game_date,\n  team_abbr,\n  COUNT(*) as total_roster,\n  COUNTIF(is_dnp = TRUE) as dnp_count,\n  COUNTIF(is_active = TRUE) as active_count,\n  ARRAY_AGG(CASE WHEN is_dnp = TRUE THEN CONCAT(player_lookup, '' ('', dnp_reason_category, '')'') END IGNORE NULLS) as dnp_players\nFROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\nWHERE game_date BETWEEN ''{start_date}'' AND ''{end_date}''\nGROUP BY game_date, team_abbr\nHAVING COUNTIF(is_dnp = TRUE) > 0\nORDER BY game_date DESC, dnp_count DESC\"\n```\n\n**Note**: DNPs are now visible in the data (previously filtered out). Use `is_dnp = TRUE` to identify them.\n\n---\n\n## Mode 8: Compare Sources (`--compare-sources`)\n\n**When**: `--compare-sources` flag present\n**Purpose**: Find discrepancies between data sources\n\n```bash\n# Compare NBA.com vs BallDontLie\nbq query --use_legacy_sql=false \"\nWITH nbac AS (\n  SELECT\n    game_id,\n    player_lookup,\n    points as nbac_points,\n    minutes as nbac_minutes\n  FROM \\`nba-props-platform.nba_raw.nbac_gamebook_player_stats\\`\n  WHERE game_date = DATE(''2026-01-25'')\n),\nbdl AS (\n  SELECT\n    game_id,\n    player_lookup,\n    points as bdl_points,\n    minutes as bdl_minutes\n  FROM \\`nba-props-platform.nba_raw.bdl_player_boxscores\\`\n  WHERE game_date = DATE(''2026-01-25'')\n)\nSELECT\n  COALESCE(n.game_id, b.game_id) as game_id,\n  COALESCE(n.player_lookup, b.player_lookup) as player_lookup,\n  n.nbac_points,\n  b.bdl_points,\n  n.nbac_points - b.bdl_points as points_diff,\n  CASE\n    WHEN ABS(n.nbac_points - b.bdl_points) > 2 THEN ''MISMATCH''\n    ELSE ''MATCH''\n  END as status\nFROM nbac n\nFULL OUTER JOIN bdl b\n  ON n.game_id = b.game_id AND n.player_lookup = b.player_lookup\nWHERE ABS(COALESCE(n.nbac_points, 0) - COALESCE(b.bdl_points, 0)) > 2\"\n```\n\n### Source Distribution Check (Session 128)\n\nCheck which source was used for player_game_summary records. Useful for validating same-night analytics vs morning gamebook processing.\n\n```bash\n# Check source distribution for a date range\nbq query --use_legacy_sql=false \"\nSELECT\n  game_date,\n  primary_source_used,\n  COUNT(*) as records,\n  ROUND(100.0 * COUNT(*) / SUM(COUNT(*)) OVER(PARTITION BY game_date), 1) as pct\nFROM \\`nba-props-platform.nba_analytics.player_game_summary\\`\nWHERE game_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) AND CURRENT_DATE()\nGROUP BY game_date, primary_source_used\nORDER BY game_date DESC, records DESC\"\n```\n\n**Expected Distribution**:\n- `nbac_gamebook` - Morning processing (after 6 AM ET)\n- `nbac_boxscores` - Same-night processing (before 6 AM ET)\n- Mixed sources indicate re-processing occurred\n\n**Session 128 Context**: Same-night analytics uses `nbac_boxscores` fallback when gamebook isn''t available yet. This is expected behavior during evening hours.\n\n---\n\n## Mode 9: Export Results (`--export <path>`)\n\n**When**: `--export` flag with file path\n**Purpose**: Save validation results to JSON for tracking, alerting, or dashboards\n\n### Usage\n\nCan be combined with any other mode:\n\n```bash\n/validate-historical 7 --export validation-2026-01-26.json\n/validate-historical --deep-check 2026-01-18 --export deep-check-results.json\n```\n\n### Output Format\n\n```json\n{\n  \"validation_type\": \"standard\",\n  \"date_range\": {\n    \"start\": \"2026-01-19\",\n    \"end\": \"2026-01-26\"\n  },\n  \"run_timestamp\": \"2026-01-26T17:45:00Z\",\n  \"summary\": {\n    \"status\": \"ISSUES_FOUND\",\n    \"total_dates\": 8,\n    \"complete_dates\": 7,\n    \"gap_dates\": 1,\n    \"overall_integrity\": 87.5\n  },\n  \"gaps\": [\n    {\n      \"date\": \"2026-01-23\",\n      \"type\": \"INCOMPLETE\",\n      \"raw_records\": 240,\n      \"analytics_records\": 45,\n      \"completion_pct\": 18.75,\n      \"cascade_impact\": {\n        \"affected_dates\": [\"2026-01-24\", \"2026-01-25\", \"...\"],\n        \"affected_predictions\": 150\n      },\n      \"severity\": \"P1\",\n      \"remediation\": \"python scripts/backfill_player_game_summary.py --date 2026-01-23\"\n    }\n  ],\n  \"quality_metrics\": {\n    \"spot_check_accuracy\": 72.0,\n    \"usage_coverage\": 35.0,\n    \"minutes_coverage\": 100.0\n  }\n}\n```\n\n### Use Cases\n\n1. **Automated Monitoring**: CI/CD pipeline runs validation, exports results, alerts on P1/P2 issues\n2. **Historical Tracking**: Store daily validation results, build trend dashboards\n3. **Integration**: Feed results into Slack alerts, PagerDuty, or custom dashboards\n\n---\n\n## Investigation Guidance\n\n### When Gaps Found\n\n1. **Determine gap type**:\n   - Raw data missing? → Re-scrape if source still available\n   - Analytics missing? → Regenerate Phase 3\n   - Cache missing? → Regenerate Phase 4\n\n2. **Check cascade impact**:\n   - How many downstream dates affected?\n   - How many predictions potentially degraded?\n\n3. **Provide remediation in correct order**:\n   ```bash\n   # Always: Phase 3 → Phase 4 → Verify\n\n   # Step 1: Regenerate analytics\n   python scripts/backfill_player_game_summary.py --start-date 2026-01-18 --end-date 2026-01-18\n\n   # Step 2: Regenerate cache (for cascade window)\n   python scripts/regenerate_player_daily_cache.py --start-date 2026-01-18 --end-date 2026-02-08\n\n   # Step 3: Verify fix\n   python scripts/spot_check_data_accuracy.py --start-date 2026-01-19 --end-date 2026-01-25 --samples 20\n   ```\n\n### When Deep Check Fails\n\n1. **Identify which games are missing** from the rolling average calculation\n2. **Check if those games exist** in player_game_summary\n3. **Check cache_date semantics**: cache_date = game_date - 1\n4. **Check date filter**: Should be `< cache_date` NOT `<= cache_date`\n\n### When Anomalies Found\n\n1. **High points (>60)**: Check if actual performance or double-counting\n2. **Zero minutes with stats**: Data join issue, check game_id format\n3. **Negative stats**: Data corruption, needs manual investigation\n4. **Excessive usage rate**: Team stats may be missing or wrong\n\n---\n\n## BigQuery Schema Reference\n\n**Key Tables** (use these for validation queries):\n\n### `nba_analytics.player_game_summary`\n```\nFields:\n- player_lookup (STRING) - normalized name (e.g., ''lebronjames'')\n- game_id (STRING)\n- game_date (DATE)\n- points, assists, rebounds (INT64)\n- minutes_played (INT64) - decimal format (32, not \"32:00\")\n- usage_rate (FLOAT64) - can be NULL if team stats missing\n- source_team_last_updated (TIMESTAMP) - join to team stats\n```\n\n### `nba_precompute.player_daily_cache`\n```\nFields:\n- player_lookup (STRING)\n- cache_date (DATE) - CRITICAL: cache_date = game_date - 1\n- game_date (DATE) - upcoming game date\n- points_avg_last_5, points_avg_last_10 (FLOAT64)\n- minutes_avg_last_10 (FLOAT64)\n- games_played_season (INT64)\n```\n\n### `nba_predictions.ml_feature_store_v2`\n```\nFields:\n- player_lookup (STRING)\n- game_id (STRING)\n- game_date (DATE)\n- features (ARRAY<FLOAT64>)\n- historical_completeness (STRUCT):\n    - games_found (INT64)\n    - games_expected (INT64)\n    - is_complete (BOOL)\n    - contributing_game_dates (ARRAY<DATE>) - games used in features\n```\n\n### `nba_raw.nbac_gamebook_player_stats`\n```\nFields:\n- player_lookup (STRING)\n- game_id (STRING)\n- game_date (DATE)\n- points, assists, total_rebounds (INT64)\n- minutes (STRING) - \"MM:SS\" format\n```\n\n**Schema Gotchas**:\n- cache_date = game_date - 1 (the day BEFORE the game)\n- contributing_game_dates contains dates used in rolling averages\n- minutes format differs: raw is \"MM:SS\", analytics is INT64 decimal\n\n---\n\n## Output Format\n\n### Standard Mode Output\n\n```markdown\n## Historical Data Validation - [DATE RANGE]\n\n### Summary\n[Overall assessment in one sentence]\n\n### Data Completeness\n\n| Date | Games | Players | Analytics | Predictions | Status |\n|------|-------|---------|-----------|-------------|--------|\n| 01-25 | 7 | 210 | 210 (100%) | 180 | ✅ COMPLETE |\n| 01-24 | 6 | 180 | 180 (100%) | 165 | ✅ COMPLETE |\n| 01-23 | 8 | 240 | 45 (19%) | 0 | ❌ INCOMPLETE |\n| 01-22 | 0 | 0 | 0 | 0 | ℹ️ OFF-DAY |\n\n### Gaps Detected\n\n🔴 **P1 CRITICAL**: 2026-01-23 - Analytics 19% complete (45/240 records)\n  - **Raw data**: ✅ Available (240 records)\n  - **Cascade impact**: Affects 2026-01-24 through 2026-02-13 (~21 days)\n  - **Affected predictions**: ~150 predictions potentially degraded\n  - **Root cause**: Phase 3 processor failed (check logs)\n\n### Cascade Impact Assessment\n\n| Date Range | Affected Players | Affected Predictions | Integrity |\n|------------|------------------|----------------------|-----------|\n| 01-24 → 02-13 | ~180 | ~1,500 | ❌ Compromised |\n\n**Explanation**: Missing 01-23 data means rolling averages (L5, L10) for subsequent days will have wrong game counts or skip that date entirely (L5 affected for 5 days, L10 for 10 days, longer features for up to 21 days).\n\n### Quality Trends\n\n| Week | Spot Check Accuracy | Usage Coverage | Notes |\n|------|---------------------|----------------|-------|\n| Jan 20-26 | 72% ❌ | 35% ❌ | Degraded (01-23 gap) |\n| Jan 13-19 | 95% ✅ | 88% ✅ | Healthy |\n\n### Remediation Plan\n\n#### Step 1: Regenerate Phase 3 (Analytics)\n```bash\npython scripts/backfill_player_game_summary.py \\\n  --start-date 2026-01-23 \\\n  --end-date 2026-01-23\n```\n\n#### Step 2: Regenerate Phase 4 (Cache) for Cascade Window\n```bash\npython scripts/regenerate_player_daily_cache.py \\\n  --start-date 2026-01-23 \\\n  --end-date 2026-02-13\n```\n\n#### Step 3: Verify Fix\n```bash\n# Check backfilled date\npython scripts/validate_tonight_data.py --date 2026-01-23\n\n# Spot check downstream dates\npython scripts/spot_check_data_accuracy.py \\\n  --start-date 2026-01-24 \\\n  --end-date 2026-02-05 \\\n  --samples 20 \\\n  --checks rolling_avg\n\n# Verify cascade resolution\n/validate-historical --verify-backfill 2026-01-23\n```\n```\n\n### Deep Check Output (Example)\n\n```markdown\n## Deep Check Results - 2026-01-20 to 2026-01-25\n\nSamples checked: 15 random player-game records\n\n### Results: 3 MISMATCHES FOUND (80% integrity)\n\n❌ **LeBron James** (2026-01-25)\n   - points_avg_last_5 in cache: 28.4\n   - Recalculated from raw: 26.8\n   - Difference: 1.6 points (6% error)\n   - **Root cause**: 2026-01-23 game (32 pts) missing from calculation\n   - Games used in cache: [Jan 24, 22, 21, 20, 19]\n   - Games that SHOULD be used: [Jan 24, 23, 22, 21, 20]\n\n✅ **Stephen Curry** (2026-01-24) - MATCH\n✅ **Kevin Durant** (2026-01-23) - MATCH\n... (12 more samples)\n\n### Cascade Root Cause\n\n**Gap date**: 2026-01-23 (missing from analytics)\n**Players affected**: ~180\n**Downstream dates with wrong averages**: 2026-01-24 through 2026-02-13\n**Predictions degraded**: ~150\n```\n\n---\n\n## Key Commands Reference\n\n```bash\n# Completeness check\nbq query --use_legacy_sql=false \"SELECT game_date, COUNT(*) FROM nba_analytics.player_game_summary WHERE game_date >= ''2026-01-01'' GROUP BY game_date\"\n\n# Gap detection\npython scripts/backfill_player_game_summary.py --check-only --start-date 2026-01-01 --end-date 2026-01-26\n\n# Spot checks (historical)\npython scripts/spot_check_data_accuracy.py --start-date 2026-01-18 --end-date 2026-01-25 --samples 20\n\n# Regenerate analytics (Phase 3)\npython scripts/backfill_player_game_summary.py --start-date 2026-01-23 --end-date 2026-01-23\n\n# Regenerate cache (Phase 4)\npython scripts/regenerate_player_daily_cache.py --start-date 2026-01-23 --end-date 2026-02-13\n\n# Verify backfill\npython scripts/validate_tonight_data.py --date 2026-01-23\n\n# Cascade detection\nbq query --use_legacy_sql=false \"SELECT COUNT(*) FROM nba_predictions.ml_feature_store_v2 WHERE DATE(''2026-01-23'') IN UNNEST(historical_completeness.contributing_game_dates)\"\n```\n\n---\n\n## Important Guidelines\n\n1. **Always check cascade impact**: Missing data doesn''t just affect that day\n2. **Remediate in dependency order**: Phase 3 → Phase 4 → Verify\n3. **Use cache_date semantics correctly**: cache_date = game_date - 1\n4. **Distinguish gaps from off-days**: No data on Sunday? Check if games scheduled\n5. **Provide specific commands**: Not \"regenerate data\" but exact date ranges\n6. **Classify severity appropriately**: Use P1-P5 from /validate-daily\n7. **Verify fixes**: Always run spot checks after remediation\n\n---\n\n## Severity Classification (P1-P5)\n\n**🔴 P1 CRITICAL**: Data gap affecting >100 predictions\n- Analytics missing for game day\n- Cache corrupted for multiple days\n- Cascade window includes important games\n\n**🟡 P2 HIGH**: Data gap affecting 50-100 predictions\n- Partial analytics (50-90% complete)\n- Single player''s data corrupt\n- Cascade window is short (1-5 days)\n\n**🟠 P3 MEDIUM**: Data quality issue, <50 predictions affected\n- Spot check accuracy 90-94%\n- Single game missing predictions\n- Anomaly detected but limited scope\n\n**🟢 P4 LOW**: Minor issue, no prediction impact\n- Off-day with no data (expected)\n- Very old data gap (outside prediction window)\n- Cosmetic data issues\n\n**ℹ️ P5 INFO**: Informational, no action needed\n- Data complete and healthy\n- Quality trends stable\n\n---\n\n**Remember**: This skill finds historical problems that `/validate-daily` may have missed. The goal is comprehensive data integrity audit with actionable remediation plans.\n"},"lastSynced":"2026-03-08T02:01:48.348Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing advanced historical data validation and remediation capabilities for NBA stats.","zh":"非常适合需要高级历史数据验证和修复功能的NBA数据分析代理","ja":"NBAの統計データに対する高度な歴史的データの検証および修復機能を必要とするデータ分析エージェントに最適","ko":"고급 역사적 데이터 검증 및 복구 기능이 필요한 NBA 통계 데이터 분석 에이전트에 적합","es":"Perfecto para agentes de análisis de datos que necesitan capacidades avanzadas de validación y remediación de datos históricos para estadísticas de la NBA.","fr":"Parfait pour les agents d''analyse de données nécessitant des capacités avancées de validation et de remédiation des données historiques pour les statistiques de la NBA.","de":"Perfekt für Data-Analytics-Agents, die erweiterte historische Datenvalidierungs- und Sanierungsfähigkeiten für NBA-Statistiken benötigen.","pt":"Perfeito para Agentes de Análise de Dados que precisam de capacidades avançadas de validação e remediação de dados históricos para estatísticas da NBA.","ru":"Идеально для агентов анализа данных, которым необходимы продвинутые возможности проверки и исправления исторических данных для статистики НБА.","ar":"مثالي للوكلاء تحليل البيانات الذين يحتاجون إلى قدرات متقدمة للتحقق من صحة البيانات التاريخية وإصلاحها لإحصائيات الرابطة الوطنية لكرة السلة."},"recommendation":{"en":"Empowers agents to perform comprehensive historical data validation, identifying data gaps and assessing cascade impacts using actionable remediation plans, and providing specific steps in the correct dependency order for data integrity across a date range.","zh":"能够赋予代理执行全面历史数据验证，识别数据缺口并评估级联影响，使用可行的修复计划，并为数据完整性提供特定步骤的依赖顺序","ja":"エージェントが包括的な歴史的データの検証を実行できるようにし、データギャップを特定し、連鎖的影響を評価し、行動可能な修復計画を使用し、依存順序の正しいステップでデータの完全性を提供する","ko":"에이전트가 포괄적인 역사적 데이터 검증을 수행할 수 있도록 하며 데이터 격차를 식별하고 연쇄적 영향을 평가하며 실행 가능한 복구 계획을 사용하며 데이터 무결성을 위한 올바른 종속 순서의 특정 단계를 제공","es":"Habilita a los agentes a realizar una validación de datos históricos integral, identificar lagunas de datos y evaluar impactos en cascada utilizando planes de remediación activables, y proporcionar pasos específicos en el orden de dependencia correcto para la integridad de los datos en un rango de fechas.","fr":"Permet aux agents de réaliser une validation de données historiques complète, d''identifier les lacunes de données et d''évaluer les impacts en cascade en utilisant des plans de remédiation actionnables, et de fournir des étapes spécifiques dans l''ordre de dépendance correct pour l''intégrité des données sur une plage de dates.","de":"Ermächtigt Agents, eine umfassende Validierung historischer Daten durchzuführen, Datenlücken zu identifizieren und Kaskadeneffekte zu bewerten, indem handhabbare Sanierungspläne verwendet werden, und liefert spezifische Schritte in der richtigen Abhängigkeitsreihenfolge für die Datenintegrität über einen bestimmten Zeitraum.","pt":"Habilita os agentes a realizar uma validação abrangente de dados históricos, identificando lacunas nos dados e avaliando impactos em cascata usando planos de remediação eficazes, e fornecendo etapas específicas na ordem de dependência correta para a integridade dos dados em uma faixa de datas.","ru":"Наделяет агентов возможностью проводить всестороннюю проверку исторических данных, выявлять пробелы в данных и оценивать каскадные последствия с помощью планов исправления, и предоставляет конкретные шаги в правильном порядке зависимости для целостности данных за определенный период времени.","ar":"تمكّن الوكلاء من أداء التحقق الشامل من صحة البيانات التاريخية، وتحديد فجوات في البيانات وتقييم الآثار المتسلسلة باستخدام خطط إصلاح قابلة للتنفيذ، وتقديم خطوات محددة بالترتيب الصحيح للاتكالية من أجل سلامة البيانات عبر نطاق زمني."},"useCases":{"en":["Auditing historical data integrity for NBA stats","Identifying data gaps with potential cascading effects on predictions","Generating actionable remediation plans for missing historical data"],"zh":["审核NBA统计数据的历史数据完整性","识别具有潜在级联影响的数据缺口","为缺失的历史数据生成可执行的修复计划"],"ja":["NBAの統計データの歴史的データの完全性を監査する","予測への潜在的な連鎖的影響を持つデータギャップを特定する","欠落している歴史的データに対する実行可能な修復計画を生成する"],"ko":["NBA 통계 데이터의 역사적 데이터 무결성을 감사","예측에 대한 잠재적인 연쇄적 영향을 가진 데이터 격차를 식별","누락된 역사적 데이터에 대한 실행 가능한 복구 계획을 생성"],"es":["Auditoría de la integridad de los datos históricos para estadísticas de la NBA","Identificación de lagunas de datos con efectos potenciales en cascada en las predicciones","Generación de planes de remediación activables para datos históricos perdidos"],"fr":["Audit de l''intégrité des données historiques pour les statistiques de la NBA","Identification des lacunes de données avec des effets potentiels en cascade sur les prédictions","Génération de plans de remédiation actionnables pour les données historiques manquantes"],"de":["Prüfung der Integrität historischer Daten für NBA-Statistiken","Identifizierung von Datenlücken mit potenziellen Kaskadeneffekten auf Vorhersagen","Erzeugung von handhabbaren Sanierungsplänen für fehlende historische Daten"],"pt":["Auditoria da integridade dos dados históricos para estatísticas da NBA","Identificação de lacunas nos dados com efeitos potenciais em cadeia nas previsões","Geração de planos de remediação eficazes para dados históricos ausentes"],"ru":["Аудит целостности исторических данных для статистики НБА","Определение пробелов в данных с потенциальными каскадными последствиями для прогнозов","Генерация эффективных планов исправления для отсутствующих исторических данных"],"ar":["مراجعة سلامة البيانات التاريخية لإحصائيات الرابطة الوطنية لكرة السلة","تحديد فجوات في البيانات مع آثار متسلسلة محتملة على التنبؤات","توليد خطط إصلاح قابلة للتنفيذ لبيانات تاريخية مفقودة"]},"limitations":{"en":["Requires access to historical NBA stats data","Limited to NBA stats scraper data validation"],"zh":["需要访问历史NBA统计数据","仅限于NBA统计数据抓取器数据验证"],"ja":["歴史的なNBAの統計データへのアクセスが必要","NBAの統計データスクレイパーのデータ検証に限定"],"ko":["역사적 NBA 통계 데이터에 대한 액세스가 필요","NBA 통계 데이터 스크레이퍼 데이터 유효성 검사에 한정"],"es":["Requiere acceso a datos de estadísticas históricas de la NBA","Limitado a la validación de datos del raspador de estadísticas de la NBA"],"fr":["Nécessite un accès aux données de statistiques historiques de la NBA","Limité à la validation des données du raspateur de statistiques de la NBA"],"de":["Erfordert Zugriff auf historische NBA-Statistik-Daten","Begrenzt auf die Validierung der Daten des NBA-Statistik-Scrapers"],"pt":["Exige acesso a dados históricos de estatísticas da NBA","Limitado à validação de dados do scraper de estatísticas da NBA"],"ru":["Требует доступа к историческим данным статистики НБА","Ограничен проверкой данных скрепера статистики НБА"],"ar":["يتطلب الوصول إلى بيانات إحصائيات الرابطة الوطنية لكرة السلة التاريخية","محدود بالتحقق من صحة بيانات سكريبر إحصائيات الرابطة الوطنية لكرة السلة"]},"version":4},"contentHash":"1c2d70f90fda8e30c1f63d5596469a955368b5b0a0728b825755e48d9dd8a8e9","qualityScore":60}');
