INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('najicham/nba-stats-scraper/validate-historical', 'validate-historical', 'najicham', 'nba-stats-scraper', 'community', 'validate-historical najicham nba-stats-scraper community The validate-historical skill performs comprehensive historical data validation for the NBA stats scraper, identifying data gaps and assessing cascade impacts. It benefits data analysts and scientists by providing actionable remediation plans. validate-historical AIエージェント用于历史数据验证，识别数据缺口和级联影响，提供修复计划 validate-historical AIエージェントは歴史データの検証を行い、データギャップとカスケード影響を識別し、修復計画を提供します validate-historical AI 에이전트는 역사적 데이터의 유효성 검사를 수행하며, 데이터 격차와 캐스케이드 영향을 식별하고 修复 계획을 제공합니다 El agente de AI validate-historical realiza una validación exhaustiva de los datos históricos para el raspador de estadísticas de la NBA L''agent de validation des données historiques validate-historical effectue une validation complète des données historiques pour le scrapeur de statistiques de la NBA Der validate-historical-KI-Agent führt eine umfassende Überprüfung der historischen Daten für den NBA-Statistik-Scraper durch O Validate-Historical é uma habilidade que valida a integridade dos dados históricos, identificando lacunas e fornecendo planos de remediação para melhorar a precisão das previsões Validate-Historical - это навык, который проверяет целостность исторических данных, выявляет пробелы и предоставляет планы исправления для повышения точности прогнозов ИИ Агентов Validate-Historical هو مهارة تقوم بتحقق صحة البيانات التاريخية وتحديد الفجوات وتقديم خطط تصحيحية لتحسين دقة التنبؤات للأدوات الذكية how to use validate-historical what is validate-historical validate-historical alternative validate-historical vs data validation tools validate-historical install validate-historical setup guide historical data validation best practices NBA stats scraper data validation cascade impact assessment AIエージェント 历史数据验证 数据缺口识别 级联影响评估 修复计划 CLI Python validate-historical Audits historical data integrity across a specified date range Identifies data gaps that may have cascading effects on predictions Provides actionable remediation plans in the correct dependency order Assesses cascade impacts on historical data Offers specific remediation steps to resolve data gaps validate-historical is a skill that audits historical data integrity across a date range, identifying gaps and providing specific remediation steps to resolve cascade effects.');
