INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gsmlg-app/flutter-app-template/template-mason-brick', 'template-mason-brick', 'gsmlg-app', 'flutter-app-template', 'community', 'template-mason-brick gsmlg-app flutter-app-template community The template-mason-brick skill guides the creation, modification, and removal of Mason bricks for Flutter applications, ensuring test coverage and CI workflow integration for AI coders. template-mason-brick是Flutter应用模板，用于创建、修改和删除Mason bricks template-mason-brickはFlutterアプリケーションテンプレートで、Mason bricksの作成、変更、削除をサポートします template-mason-brick는 Flutter 애플리케이션 템플릿으로, Mason bricks의 생성, 수정, 삭제를 지원합니다 La plantilla Mason Brick es una herramienta para desarrolladores de Flutter que permite crear y gestionar ladrillos de manera eficiente Le modèle Mason Brick est un outil pour les développeurs Flutter qui permet de créer et de gérer des briques de manière efficace Die Mason-Brick-Vorlage ist ein Tool für Flutter-Entwickler, das die Erstellung und Verwaltung von Bricks effizient ermöglicht O template Mason Brick é um recurso para desenvolvedores de aplicativos Flutter, permitindo a criação e gerenciamento de bricks. Шаблон Mason Brick - это функция для разработчиков приложений Flutter, позволяющая создавать и управлять кирпичами. قالب Mason Brick هو ميزة لل مطورين تطبيقات Flutter، مما يسمح بإنشاء وإدارة الطوب. how to use template-mason-brick template-mason-brick setup guide template-mason-brick vs Flutter template template-mason-brick install what is template-mason-brick template-mason-brick alternative Mason brick creation CI workflow integration Flutter application template template-mason-brick Flutter应用模板 Mason bricks AI工具 CI workflow 测试覆盖 Flutter开发 Creates new Mason brick templates for Flutter applications Updates existing brick structures and variables Removes bricks from projects with ease Ensures test coverage for Mason bricks Integrates with CI workflow for seamless development Organizes bricks in a structured project format template-mason-brick is a Flutter application template skill for AI coders, enabling the creation, modification, and removal of Mason bricks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mysticaltech/terraform-hcloud-kube-hetzner/review-pr', 'community', 'mysticaltech', 'terraform-hcloud-kube-hetzner', 'mysticaltech/terraform-hcloud-kube-hetzner', 'review-pr', 0, 0, 60, '2026-03-08T01:57:15.308Z', '2026-03-08T02:02:22.877Z', '58bf3bb29861e478cfbe5fc8ba3c9d1c2d993d0b3fa86f85daa05bbd0f74f8cc', '{"id":"mysticaltech/terraform-hcloud-kube-hetzner/review-pr","name":"review-pr","description":{"en":"The review-pr skill provides security-focused PR review following CLAUDE.md guidelines, checking for breaking changes and malicious code patterns. It benefits developers and project maintainers by ensuring code quality and backward compatibility.","zh":"Review PR是一种安全审查工具，帮助开发者优化Kubernetes安全审查和维护","ja":"Review PRは、開発者がKubernetesのセキュリティレビューを最適化し、メンテナンスを簡素化するのに役立つAIエージェントです","ko":"Review PR는 개발자가 Kubernetes 보안 리뷰를 최적화하고 유지 보수를 간소화하는 데 도움이 되는 AI 도구입니다","es":"Review-pr es una herramienta de revisión de solicitudes de extracción que sigue las pautas de CLAUDE.md para garantizar la seguridad y la calidad del código en proyectos de Kubernetes","fr":"Review-pr est un outil d''examen des demandes d''extraction qui suit les directives de CLAUDE.md pour assurer la sécurité et la qualité du code dans les projets Kubernetes","de":"Review-pr ist ein Tool zur Überprüfung von Pull-Requests, das die Richtlinien von CLAUDE.md befolgt, um die Sicherheit und Codequalität in Kubernetes-Projekten zu gewährleisten","pt":"O review-pr é uma ferramenta de análise de segurança para pull requests que verifica alterações de quebra, padrões de código maliciosos e compatibilidade backwards","ru":"Review-pr - это инструмент анализа безопасности для запросов на слияние, который проверяет нарушения, вредоносные шаблоны кода и обратную совместимость","ar":"review-pr هو أداة لتحليل الأمان لطلبات السحب التي تحقق التغييرات التي قد تسبب مشاكل、アمان ونسق ذو صلة معاكس"},"seo":{"title":{"en":"review-pr: Security-Focused PR Review Setup Guide | AI Ag...","zh":"Review PR Setup Guide: 优化Kubernetes安全审查","ja":"AIエージェント Review PR: セキュリティ重視のPRレビュー","ko":"Review PR 설정 가이드: 보안 집중 Kubernetes 리뷰","es":"Guía de configuración de review-pr para seguridad de Kube...","fr":"Guide de configuration de review-pr pour la sécurité de K...","de":"Konfigurationsleitfaden für review-pr zur Kubernetes-Sich...","pt":"Guia de Configuração review-pr: Análise de Segurança em P...","ru":"Настройка review-pr: Руководство по безопасности для ИИ А...","ar":"دليل إعداد review-pr: تحليل أمان لطلبات السحب"},"description":{"en":"Protect your project from malicious sabotage attempts with review-pr. Learn how to use this AI agent skill to ensure secure PR reviews and prevent coordinate...","zh":"使用Review PR AI工具，优化Kubernetes安全审查和维护，防止破坏性更改和恶意代码","ja":"Review PR AIエージェントを使用して、Kubernetesのセキュリティレビューを最適化し、破壊的な変更や悪意のあるコードを防ぎます","ko":"Review PR AI 도구를 사용하여 Kubernetes 보안 리뷰를 최적화하고 破壊적인 변경 및 악성 코드를 방지합니다","es":"Aprende a utilizar review-pr para revisar solicitudes de extracción de manera segura y mantener tu proyecto de Kubernetes protegido","fr":"Découvrez comment utiliser review-pr pour examiner les demandes d''extraction de manière sécurisée et protéger votre projet Kubernetes","de":"Erfahren Sie, wie Sie review-pr verwenden, um Pull-Requests sicher zu überprüfen und Ihr Kubernetes-Projekt zu schützen","pt":"Aprenda a configurar o review-pr para análise de segurança em pull requests e proteja seu projeto contra sabotagem maliciosa","ru":"Узнайте, как настроить review-pr для анализа безопасности в запросах на слияние и защитить ваш проект от вредоносных атак","ar":"تعلم كيفية إعداد review-pr لتحليل الأمان في طلبات السحب وحماية مشروعك من التخريب الخبيث"},"definition":{"en":"review-pr is a security-focused PR review skill that checks for breaking changes, malicious code patterns, and code quality, following CLAUDE.md guidelines to prevent sabotage attempts.","zh":"Review PR是一种AI工具，提供安全审查和Kubernetes维护优化","ja":"Review PRは、セキュリティレビューとKubernetesメンテナンスの最適化を提供するAIエージェントです","ko":"Review PR는 보안 리뷰 및 Kubernetes 유지 보수를 최적화하는 AI 도구입니다","es":"Review-pr es una herramienta de revisión de solicitudes de extracción que se centra en la seguridad y la calidad del código","fr":"Review-pr est un outil d''examen des demandes d''extraction axé sur la sécurité et la qualité du code","de":"Review-pr ist ein Tool zur Überprüfung von Pull-Requests mit Fokus auf Sicherheit und Codequalität","pt":"O review-pr é uma ferramenta de análise de segurança que ajuda a proteger projetos contra sabotagem maliciosa em pull requests","ru":"Review-pr - это инструмент анализа безопасности, который помогает защитить проекты от вредоносных атак в запросах на слияние","ar":"review-pr هو أداة لتحليل الأمان التي تساعد في حماية المشاريع من التخريب الخبيث في طلبات السحب"},"features":{"en":["Checks for breaking changes and malicious code patterns using CLAUDE.md guidelines","Ensures backward compatibility and code quality","Supports security-focused PR review with a single command: /review-pr <number>","Warns against coordinated attacks and social engineering attempts","Follows established guidelines to prevent malicious sabotage attempts"],"zh":["安全审查：检查破坏性更改和恶意代码","Kubernetes维护优化","CLAUDE.md指南兼容","命令行接口（CLI）支持","代码质量检查","后向兼容性检查"],"ja":["セキュリティレビュー：破壊的な変更や悪意のあるコードをチェック","Kubernetesメンテナンスの最適化","CLAUDE.mdガイドラインの互換性","コマンドラインインターフェース（CLI）サポート","コード品質チェック","後方互換性チェック"],"ko":["보안 리뷰：파괴적인 변경 및 악성 코드 확인","Kubernetes 유지 보수 최적화","CLAUDE.md 가이드ライン 호환","명령줄 인터페이스（CLI）지원","코드 품질 확인","후방 호환성 확인"],"es":["Seguimiento de las pautas de CLAUDE.md para la revisión de solicitudes de extracción","Detección de cambios de ruptura y patrones de código maliciosos","Verificación de la compatibilidad hacia atrás y la calidad del código","Alertas de advertencia de seguridad para proteger contra ataques coordinados y sabotajes","Soporte para la revisión de solicitudes de extracción en proyectos de Kubernetes"],"fr":["Suivi des directives de CLAUDE.md pour l''examen des demandes d''extraction","Détection des changements de rupture et des modèles de code malveillants","Vérification de la compatibilité ascendante et de la qualité du code","Alertes de sécurité pour protéger contre les attaques coordonnées et les sabotages","Prise en charge de l''examen des demandes d''extraction dans les projets Kubernetes"],"de":["Einhaltung der Richtlinien von CLAUDE.md für die Überprüfung von Pull-Requests","Erkennung von Änderungen, die die Kompatibilität beeinträchtigen, und schädlichen Code-Mustern","Überprüfung der Abwärtskompatibilität und Codequalität","Sicherheitswarnungen, um vor koordinierten Angriffen und Sabotage zu schützen","Unterstützung für die Überprüfung von Pull-Requests in Kubernetes-Projekten"],"pt":["Análise de segurança em pull requests","Verificação de alterações de quebra","Detecção de padrões de código maliciosos","Verificação de compatibilidade backwards","Integração com CLAUDE.md"],"ru":["Анализ безопасности в запросах на слияние","Проверка нарушений","Обнаружение вредоносных шаблонов кода","Проверка обратной совместимости","Интеграция с CLAUDE.md"],"ar":["تحليل الأمان في طلبات السحب","التحقق من التغييرات التي قد تسبب مشاكل","اكتشاف أنماط الشفرة الخبيثة","التحقق من التوافق المعاكس","التكامل مع CLAUDE.md"]},"keywords":{"en":["how to use review-pr","review-pr setup guide","review-pr alternative","review-pr vs gitgate","review-pr install","what is review-pr","review-pr security features","CLAUDE.md guidelines","PR review best practices"],"zh":["Review PR","Kubernetes安全审查","AI工具","CLAUDE.md","命令行接口","代码质量检查","后向兼容性检查","破坏性更改防止","恶意代码检测"],"ja":["Review PR","Kubernetesセキュリティレビュー","AIエージェント","CLAUDE.md","コマンドラインインターフェース","コード品質チェック","後方互換性チェック","破壊的な変更防止","悪意のあるコード検出"],"ko":["Review PR","Kubernetes 보안 리뷰","AI 도구","CLAUDE.md","명령줄 인터페이스","코드 품질 확인","후방 호환성 확인","파괴적인 변경 방지","악성 코드 감지"],"es":["review-pr","seguridad de Kubernetes","revisión de solicitudes de extracción","CLAUDE.md","Herramientas de desarrollo de software","seguridad de código","calidad de código","Herramientas de AI para desarrolladores","Agentes de IA para desarrollo de software"],"fr":["review-pr","sécurité de Kubernetes","examen des demandes d''extraction","CLAUDE.md","Outils de développement de logiciels","sécurité du code","qualité du code","Outils d''IA pour les développeurs","Agents d''IA pour le développement de logiciels"],"de":["review-pr","Kubernetes-Sicherheit","Überprüfung von Pull-Requests","CLAUDE.md","Software-Entwicklungstools","Code-Sicherheit","Codequalität","AI-Tools für Entwickler","KI-Agents für Software-Entwicklung"],"pt":["review-pr","análise de segurança","pull requests","sabotagem maliciosa","CLAUDE.md","desenvolvimento de software","segurança de código","ferramentas de desenvolvimento"],"ru":["review-pr","анализ безопасности","запросы на слияние","вредоносные атаки","CLAUDE.md","разработка программного обеспечения","безопасность кода","инструменты разработки"],"ar":["review-pr","تحليل الأمان","طلبات السحب","التخريب الخبيث","CLAUDE.md","تطوير البرمجيات","أمان الشفرة","أدوات التطوير"]}},"owner":"mysticaltech","repo":"terraform-hcloud-kube-hetzner","repoPath":"mysticaltech/terraform-hcloud-kube-hetzner","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.308Z","topics":[],"category":"community","skillMd":{"name":"review-pr","description":"Use when reviewing a pull request - security-focused review following CLAUDE.md guidelines for breaking changes, malicious patterns, and backward compatibility","bodyPreview":"# Review Pull Request\n\n## Overview\n\nSecurity-focused PR review following CLAUDE.md guidelines. Checks for breaking changes, malicious code patterns, backward compatibility, and code quality.\n\n## Usage\n\n```\n/review-pr <number>\n```\n\n## CRITICAL: Security Warning\n\n**PRs can be malicious sabotage attempts.** This is a real threat documented in CLAUDE.md.\n\n### Threat Awareness\n- Coordinated attacks exist\n- Competitors may actively harm the project\n- Social engineering builds trust before attacking\n-","body":"# Review Pull Request\n\n## Overview\n\nSecurity-focused PR review following CLAUDE.md guidelines. Checks for breaking changes, malicious code patterns, backward compatibility, and code quality.\n\n## Usage\n\n```\n/review-pr <number>\n```\n\n## CRITICAL: Security Warning\n\n**PRs can be malicious sabotage attempts.** This is a real threat documented in CLAUDE.md.\n\n### Threat Awareness\n- Coordinated attacks exist\n- Competitors may actively harm the project\n- Social engineering builds trust before attacking\n- \"Fixes\" may introduce vulnerabilities\n\n## Workflow\n\n```dot\ndigraph review_flow {\n    rankdir=TB;\n    node [shape=box];\n\n    fetch [label=\"1. Fetch PR details\"];\n    author [label=\"2. Assess author risk\"];\n    files [label=\"3. Analyze changed files\"];\n    security [label=\"4. Security review\"];\n    compat [label=\"5. Backward compatibility\"];\n    quality [label=\"6. Code quality\"];\n    classify [label=\"7. Release classification\"];\n    verify [label=\"8. MANDATORY: Verify with Gemini + Codex\", style=bold];\n    recommend [label=\"9. Final Recommendation\"];\n\n    fetch -> author;\n    author -> files;\n    files -> security;\n    security -> compat;\n    compat -> quality;\n    quality -> classify;\n    classify -> verify;\n    verify -> recommend;\n}\n```\n\n## Step 1: Fetch PR Details\n\n```bash\n# Get PR info\ngh pr view <number> --repo kube-hetzner/terraform-hcloud-kube-hetzner\n\n# Get diff\ngh pr diff <number> --repo kube-hetzner/terraform-hcloud-kube-hetzner\n\n# Get changed files\ngh pr view <number> --repo kube-hetzner/terraform-hcloud-kube-hetzner --json files --jq ''.files[].path''\n\n# Get diff stats\ngh pr view <number> --repo kube-hetzner/terraform-hcloud-kube-hetzner --json additions,deletions\n```\n\n## Step 2: Assess Author Risk\n\n```bash\n# Check account age\ngh api users/<username> --jq ''.created_at''\n\n# Check prior contributions\ngh pr list --author <username> --repo kube-hetzner/terraform-hcloud-kube-hetzner --state all --json number | jq length\n```\n\n### Risk Signals\n\n| Signal | Risk Level |\n|--------|------------|\n| New account (<6 months) | 🔴 HIGH |\n| No prior contributions | 🟡 MEDIUM |\n| First-time contributor | 🟡 MEDIUM |\n| Known contributor | 🟢 LOW |\n| Core maintainer | ⚪ TRUSTED |\n\n## Step 3: Analyze Changed Files\n\n### Security-Critical Files (AUTO HIGH RISK)\n\n```\ninit.tf              # Cluster initialization, secrets\nfirewall.tf          # Network security\n**/ssh*              # SSH configuration\n**/token*            # Authentication tokens\n**/*secret*          # Secrets handling\n.github/             # CI/CD workflows\nMakefile             # Build scripts\nscripts/             # Execution scripts\nversions.tf          # Provider dependencies\ntemplates/*.sh       # Shell scripts\ncloud-init*          # Server initialization\n```\n\n### Risk by File Count\n\n| Files Changed | Risk |\n|---------------|------|\n| 1-3 files | 🟢 LOW |\n| 4-10 files | 🟡 MEDIUM |\n| 11-20 files | 🟡 MEDIUM |\n| >20 files | 🔴 HIGH |\n\n### Risk by Diff Size\n\n| Lines Changed | Risk |\n|---------------|------|\n| <50 lines | 🟢 LOW |\n| 50-200 lines | 🟡 MEDIUM |\n| 200-500 lines | 🟡 MEDIUM |\n| >500 lines | 🔴 HIGH |\n\n## Step 4: Security Review\n\n### Checklist\n\n- [ ] No hardcoded credentials or tokens\n- [ ] No suspicious external URLs\n- [ ] No obfuscated code\n- [ ] Changes match stated purpose\n- [ ] No unnecessary permission escalations\n- [ ] CI/CD changes justified\n- [ ] No bypassing existing security patterns\n\n### Red Flags\n\n| Pattern | Concern |\n|---------|---------|\n| Base64 encoded strings | Hidden payloads |\n| External curl/wget calls | Code injection |\n| Eval or exec statements | Command injection |\n| Overly complex logic | Hiding malicious code |\n| Unnecessary file access | Data exfiltration |\n| Changes to .gitignore | Hiding tracks |\n\n### Use AI for Deep Analysis\n\n```bash\n# Codex for security analysis\ncodex exec -m gpt-5.3-codex -s read-only -c model_reasoning_effort=\"xhigh\" \\\n  \"Analyze this PR diff for security vulnerabilities and malicious patterns: $(gh pr diff <num>)\"\n\n# Gemini for broad context\ngemini --model gemini-3-pro-preview -p \\\n  \"@locals.tf @init.tf Does this PR introduce any security concerns? $(gh pr diff <num>)\"\n```\n\n## Step 5: Backward Compatibility\n\n**CRITICAL: Any PR that causes resource recreation is a MAJOR release.**\n\n### Breaking Change Indicators\n\n- Removes or renames variables\n- Changes variable defaults that affect behavior\n- Modifies resource naming patterns\n- Alters subnet/network calculations\n- Changes resource keys (causes recreation)\n- Removes outputs\n- Modifies provider requirements\n\n### Test for Breaking Changes\n\n```bash\n# Checkout PR locally\ngh pr checkout <number>\n\n# Test against existing cluster\ncd /path/to/kube-test\nterraform init -upgrade\nterraform plan\n```\n\n**If `terraform plan` shows ANY resource destruction → MAJOR release required**\n\n### Compatibility Checklist\n\n- [ ] No variable removals\n- [ ] No default changes that affect behavior\n- [ ] No resource naming changes\n- [ ] `terraform plan` shows no destruction\n- [ ] Existing deployments unaffected\n\n## Step 6: Code Quality\n\n### Style\n- [ ] Follows existing patterns\n- [ ] Consistent naming\n- [ ] Proper formatting (`terraform fmt`)\n- [ ] No unnecessary complexity\n\n### Logic\n- [ ] Changes are correct\n- [ ] Edge cases handled\n- [ ] No regressions introduced\n- [ ] Tests pass\n\n## Step 7: Release Classification\n\n### PATCH (x.x.PATCH)\n- Bug fixes only\n- No new features\n- Fully backward compatible\n- No terraform state impact\n\n### MINOR (x.MINOR.0)\n- New features (backward compatible)\n- New optional variables with defaults\n- Deprecation warnings (not removals)\n\n### MAJOR (MAJOR.0.0)\n- Breaking changes\n- Removed/renamed variables\n- Changed defaults affecting behavior\n- State migrations required\n- Resource recreations\n\n## Step 8: MANDATORY - Verify with Gemini and Codex\n\n**CRITICAL: Before making your final recommendation, you MUST run both Gemini and Codex to triple-verify the PR.**\n\nThis is not optional. External AI verification catches issues that may be missed in the initial review.\n\n### Run Both in Parallel\n\n```bash\n# Gemini - Broad context analysis (run first or in parallel)\ngemini --model gemini-3-pro-preview -p \"@control_planes.tf @locals.tf @init.tf\n\nAnalyze this PR diff for the kube-hetzner terraform module:\n\n$(gh pr diff <number> --repo kube-hetzner/terraform-hcloud-kube-hetzner)\n\nQuestions:\n1. Is this change consistent with existing patterns in the codebase?\n2. Are there any security concerns?\n3. Could this cause breaking changes or resource recreation?\n4. Is this a legitimate bug fix or could it be malicious?\"\n\n# Codex - Deep reasoning security analysis (run in parallel)\ncodex exec -m gpt-5.3-codex -s read-only -c model_reasoning_effort=\"xhigh\" \\\n\"Analyze this Terraform PR for the kube-hetzner module.\n\nDIFF:\n$(gh pr diff <number> --repo kube-hetzner/terraform-hcloud-kube-hetzner)\n\nSECURITY ANALYSIS QUESTIONS:\n1. Could this change introduce any security vulnerabilities?\n2. Could this be a malicious change disguised as a bug fix?\n3. Will this cause any Terraform state changes or resource recreation?\n4. Is this pattern safe and consistent with Terraform best practices?\n5. Any edge cases or potential issues?\"\n```\n\n### Verification Checklist\n\n- [ ] Gemini analysis completed\n- [ ] Codex analysis completed\n- [ ] Both agree the change is safe\n- [ ] No concerns raised by either tool\n- [ ] If concerns raised, they have been addressed or explained\n\n### When Reviewers Disagree\n\nIf Gemini or Codex raises concerns that you didn''t catch:\n1. **Take the concern seriously** - investigate further\n2. **Re-read the code** with the concern in mind\n3. **Request changes** if the concern is valid\n4. **Document** why the concern was dismissed if you determine it''s a false positive\n\n### Output in Final Review\n\nInclude a summary of external verification:\n\n```markdown\n### External AI Verification\n\n| Reviewer | Verdict | Key Finding |\n|----------|---------|-------------|\n| Claude | ✅/❌ | <summary> |\n| Gemini | ✅/❌ | <summary> |\n| Codex | ✅/❌ | <summary> |\n\n**Consensus:** All reviewers agree / Disagreement on X\n```\n\n---\n\n## Step 9: Final Recommendation\n\n### PR Review Output Template\n\n```markdown\n## PR Review: #<number>\n\n**Title:** <title>\n**Author:** @<username>\n**Files:** <count> files changed (+<additions>/-<deletions>)\n\n### Risk Assessment\n\n| Factor | Value | Risk |\n|--------|-------|------|\n| Author tenure | X months | 🟢/🟡/🔴 |\n| Prior contributions | N PRs | 🟢/🟡/🔴 |\n| Files changed | N files | 🟢/🟡/🔴 |\n| Lines changed | +X/-Y | 🟢/🟡/🔴 |\n| Security-critical files | Yes/No | 🟢/🔴 |\n| External dependencies | Yes/No | 🟢/🔴 |\n\n**Overall Risk:** 🔴 HIGH / 🟡 MEDIUM / 🟢 LOW\n\n### Security Review\n\n- [ ] No hardcoded credentials\n- [ ] No suspicious external URLs\n- [ ] No obfuscated code\n- [ ] Changes match stated purpose\n\n### Backward Compatibility\n\n- [ ] No breaking changes\n- [ ] terraform plan shows no destruction\n- [ ] Existing deployments unaffected\n\n### Release Classification\n\n**Type:** PATCH / MINOR / MAJOR\n**Reason:** <explanation>\n\n### External AI Verification\n\n| Reviewer | Verdict | Key Finding |\n|----------|---------|-------------|\n| Claude | ✅/❌ | <summary> |\n| Gemini | ✅/❌ | <summary> |\n| Codex | ✅/❌ | <summary> |\n\n**Consensus:** All agree / Disagreement on X\n\n### Recommendation\n\n**Action:** APPROVE / REQUEST CHANGES / CLOSE\n**Notes:** <specific concerns or required changes>\n```\n\n## Quick Commands\n\n```bash\n# Approve PR\ngh pr review <num> --approve --body \"LGTM! ...\"\n\n# Request changes\ngh pr review <num> --request-changes --body \"Please address: ...\"\n\n# Comment\ngh pr review <num> --comment --body \"...\"\n\n# Merge (after approval)\ngh pr merge <num> --squash --delete-branch\n```\n\n## Never Merge Directly to Master\n\nAll PRs go through staging branches first:\n\n1. Create staging branch\n2. Test thoroughly\n3. Get AI review (Codex + Gemini)\n4. Then merge to master\n"},"lastSynced":"2026-03-08T02:02:22.877Z","agentAnalysis":{"suitability":{"en":"Perfect for Security-Focused Agents needing advanced code review and analysis capabilities following CLAUDE.md guidelines.","zh":"非常适合需要高级代码审查和分析能力的安全焦点代理，按照CLAUDE.md指南进行。","ja":"セキュリティに重点を置いたエージェントが高度なコードレビューと分析機能を必要とする場合に最適です。CLAUDE.mdガイドラインに従っています。","ko":"고급 코드 리뷰 및 분석 기능이 필요한 보안 중심 에이전트에 적합합니다. CLAUDE.md 가이드라인을 따릅니다.","es":"Perfecto para Agentes centrados en Seguridad que necesitan capacidades de revisión y análisis de código avanzadas siguiendo las pautas de CLAUDE.md.","fr":"Parfait pour les Agents axés sur la Sécurité nécessitant des capacités de révision et d''analyse de code avancées suivant les directives CLAUDE.md.","de":"Perfekt für Sicherheitsorientierte Agenten, die erweiterte Code-Überprüfungs- und Analysefunktionen gemäß den CLAUDE.md-Richtlinien benötigen.","pt":"Perfeito para Agentes com Foco em Segurança que necessitam de capacidades avançadas de revisão e análise de código seguindo as diretrizes do CLAUDE.md.","ru":"Идеально подходит для агентов, ориентированных на безопасность, которым необходимы продвинутые возможности проверки и анализа кода в соответствии с руководством CLAUDE.md.","ar":"مثالي لعميل يركز على الأمن الذي يحتاج إلى قدرات متقدمة لاستعراض وتحليل الشفرة وفقًا لمبادئ توجيه CLAUDE.md."},"recommendation":{"en":"Empowers agents to detect breaking changes, identify malicious code patterns, and ensure backward compatibility, providing top-notch code quality and security using CLAUDE.md protocols.","zh":"赋予代理检测破坏性更改、识别恶意代码模式、确保向后兼容性，提供顶级代码质量和安全性，使用CLAUDE.md协议。","ja":"エージェントが破壊的な変更を検出して、悪意のあるコードパターンを識別し、下位互換性を確保することを可能にし、CLAUDE.mdプロトコルを使用して最高のコード品質とセキュリティを提供します。","ko":"에이전트가 破壊적인 변경을 감지하고 악의적인 코드 패턴을 식별하며 하위 호환성을 보장할 수 있도록 하여 CLAUDE.md 프로토콜을 사용하여 최상의 코드 품질과 보안을 제공합니다.","es":"Habilita a los agentes para detectar cambios que rompen la compatibilidad, identificar patrones de código maliciosos y garantizar la compatibilidad hacia atrás, proporcionando una calidad y seguridad de código de primer nivel utilizando los protocolos CLAUDE.md.","fr":"Permet aux agents de détecter les changements qui cassent la compatibilité, d''identifier les modèles de code malveillants et d''assurer la compatibilité ascendante, offrant une qualité et une sécurité de code de haute qualité en utilisant les protocoles CLAUDE.md.","de":"Ermöglicht es Agenten, Brechende Änderungen zu erkennen, bösartige Code-Muster zu identifizieren und die Abwärtskompatibilität zu gewährleisten, wodurch eine Spitzenqualität und -sicherheit des Codes unter Verwendung der CLAUDE.md-Protokolle bereitgestellt wird.","pt":"Habilita os agentes a detectar alterações quebradas, identificar padrões de código maliciosos e garantir a compatibilidade com versões anteriores, fornecendo qualidade e segurança de código de ponta usando os protocolos do CLAUDE.md.","ru":"Позволяет агентам обнаруживать изменения, нарушающие совместимость, определять вредоносные шаблоны кода и обеспечивать обратную совместимость, предоставляя код самого высокого качества и безопасность с использованием протоколов CLAUDE.md.","ar":"يمكّن الوكلاء من اكتشاف التغييرات التي تسبب انهيار الخدمة، وتحديد أنماط الشفرة الخبيثة، وضمان التوافق العكسي، مع تقديم جودة وأمان الشفرة من الدرجة الأولى باستخدام بروتوكولات CLAUDE.md."},"useCases":{"en":["Automating security audits for pull requests","Detecting malicious code patterns and sabotage attempts","Ensuring backward compatibility for new code changes"],"zh":["为拉取请求自动化安全审计","检测恶意代码模式和破坏企图","确保新代码更改的向后兼容性"],"ja":["プルリクエストのセキュリティ監査を自動化する","悪意のあるコードパターンとサボタージュの試みを検出する","新しいコード変更の下位互換性を確保する"],"ko":["풀 리퀘스트에 대한 보안 감사를 자동화하는 것","악의적인 코드 패턴 및 破壊 시도를 감지하는 것","새로운 코드 변경의 하위 호환성을 보장하는 것"],"es":["Automatización de auditorías de seguridad para solicitudes de incorporación","Detección de patrones de código maliciosos y intentos de sabotaje","Garantía de compatibilidad hacia atrás para nuevos cambios de código"],"fr":["Automatisation des audits de sécurité pour les demandes d''intégration","Détection de modèles de code malveillants et de tentatives de sabotage","Assurance de la compatibilité ascendante pour les nouveaux changements de code"],"de":["Automatisierung von Sicherheitsaudits für Pull-Requests","Erkennung bösartiger Code-Muster und Sabotageversuche","Gewährleistung der Abwärtskompatibilität für neue Code-Änderungen"],"pt":["Automatizar auditorias de segurança para solicitações de pull","Detectar padrões de código maliciosos e tentativas de sabotagem","Garantir a compatibilidade com versões anteriores para novas alterações de código"],"ru":["Автоматизировать аудиты безопасности для запросов на включение","Обнаруживать вредоносные шаблоны кода и попытки саботажа","Обеспечивать обратную совместимость для новых изменений кода"],"ar":["التحكم الآلي في عمليات التدقيق الأمني لطلبات الدمج","اكتشاف أنماط الشفرة الخبيثة ومحاولات التخريب","ضمان التوافق العكسي لتحديثات الشفرة الجديدة"]},"limitations":{"en":["Requires access to pull request data","Limited to codebases following CLAUDE.md guidelines"],"zh":["需要访问拉取请求数据","仅限于遵循CLAUDE.md指南的代码库"],"ja":["プルリクエストデータへのアクセスが必要","CLAUDE.mdガイドラインに従っているコードベースのみに限定"],"ko":["풀 리퀘스트 데이터에 대한 액세스가 필요","CLAUDE.md 가이드라인을 따르는 코드베이스에만 제한"],"es":["Requiere acceso a los datos de la solicitud de incorporación","Limitado a codebases que siguen las pautas de CLAUDE.md"],"fr":["Nécessite un accès aux données de la demande d''intégration","Limité aux bases de code suivant les directives CLAUDE.md"],"de":["Erfordert Zugriff auf Pull-Request-Daten","Begrenzt auf Codebases, die den CLAUDE.md-Richtlinien folgen"],"pt":["Requer acesso aos dados da solicitação de pull","Limitado a repositórios de código que seguem as diretrizes do CLAUDE.md"],"ru":["Требует доступа к данным запроса на включение","Ограничен кодовыми базами, следующие руководству CLAUDE.md"],"ar":["يتطلب الوصول إلى بيانات طلب الدمج","محدود بمخازن الشفرة التي تتبع إرشادات CLAUDE.md"]},"version":4},"contentHash":"58bf3bb29861e478cfbe5fc8ba3c9d1c2d993d0b3fa86f85daa05bbd0f74f8cc","qualityScore":60}');
